/// The plan's shot resolution presets.
const RESOLUTIONS: [(&str, u32, u32); 4] =
    [("HD 1920 × 1080", 1920, 1080), ("2K DCI 2048 × 1080", 2048, 1080), ("UHD 4K 3840 × 2160", 3840, 2160), ("DCI 4K 4096 × 2160", 4096, 2160)];

/// The size from which a brush file is read on a thread of its own, in bytes: a smaller one
/// is read before the window is drawn again.
const BRUSH_FILE_APART: u64 = 4 << 20;

/// A brush file that is being read apart from the window.
struct BrushReading {
    /// The file's name.
    file: String,
    /// Set to stop the reading at the next brush.
    stop: Arc<std::sync::atomic::AtomicBool>,
    /// How far the reading is, 0 to 1, as the bits of an `f32`.
    progress: Arc<std::sync::atomic::AtomicU32>,
    read: std::sync::mpsc::Receiver<Result<iskra_io::BrushImport, String>>,
}

/// A flip or a quarter turn of the Select tool's selection, about its middle.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) enum Turn {
    Across,
    Up,
    Left,
    Right,
}

impl Turn {
    /// Each with its icon, its name and what it does, in the order of the Select tool's buttons.
    const ALL: [(Turn, &'static str, &'static str, &'static str); 4] = [
        (Turn::Across, "flip-across", "Flip Horizontally", "the selection's left and right change places"),
        (Turn::Up, "flip-up", "Flip Vertically", "the selection's top and bottom change places"),
        (Turn::Left, "turn-left", "Rotate 90° Left", "the selection turns a quarter round anticlockwise"),
        (Turn::Right, "turn-right", "Rotate 90° Right", "the selection turns a quarter round clockwise"),
    ];

    /// What it does to a point about the origin, as `[a, b, c, d]` of an affine transform.
    fn linear(self) -> [f64; 4] {
        match self {
            Turn::Across => [-1.0, 0.0, 0.0, 1.0],
            Turn::Up => [1.0, 0.0, 0.0, -1.0],
            // A quarter anticlockwise on the screen, whose y is down: what was to the right goes up.
            Turn::Left => [0.0, -1.0, 1.0, 0.0],
            Turn::Right => [0.0, 1.0, -1.0, 0.0],
        }
    }

    fn command(self) -> &'static str {
        match self {
            Turn::Across => "edit.flipHorizontally",
            Turn::Up => "edit.flipVertically",
            Turn::Left => "edit.rotateLeft",
            Turn::Right => "edit.rotateRight",
        }
    }
}

/// How long a frame made for the playback cache may take, in seconds, before the log says so.
const SLOW_CACHE: f64 = 0.05;

/// The bar along the top of the window with the tool in hand's options. Hidden (the user's
/// word, 2026-10-26): the Tool Properties panel has them. Kept, as it may come back.
const TOOL_OPTIONS_BAR: bool = false;

/// The plan's frame rate presets.
const FRAME_RATES: [i64; 3] = [24, 25, 30];

/// The grey round the camera's frame where the pictures are cut to it: darker than the
/// settings' Dark Grey (the user's word, 2026-10-26).
const CLIPPED_SURROUND: u8 = 36;

/// How a palette file is brought in: as a palette of its own, into the palette in hand
/// where that lacks a swatch of a name, or so too with the colours of the swatches it has.
#[derive(Clone, Copy, PartialEq, Eq)]
enum PaletteImport {
    New,
    Into,
    Update,
}

/// Pictures being made of a rig's drawings (plan §4.17), before the rig is brought in.
struct RigJob {
    scene: std::path::PathBuf,
    /// The folder they are made in, taken away after.
    out: std::path::PathBuf,
    total: usize,
    done: Arc<AtomicUsize>,
    cancel: Arc<AtomicBool>,
    thread: Option<std::thread::JoinHandle<iskra_io::Converted>>,
}

