/// Put the window of the inner size `size` (in the interface's points) in the middle of the
/// main display, as the start window was. Its display's size is taken for the main one's,
/// whose corner is at the origin.
fn centre_window(ctx: &egui::Context, size: egui::Vec2) {
    let (inner, outer, display) = ctx.input(|i| (i.viewport().inner_rect, i.viewport().outer_rect, i.viewport().monitor_size));
    let frame = inner.zip(outer).map_or(egui::Vec2::ZERO, |(inner, outer)| outer.size() - inner.size());
    if let Some(display) = display {
        let corner = ((display - size - frame) / 2.0).max(egui::Vec2::ZERO);
        ctx.send_viewport_cmd(egui::ViewportCommand::OuterPosition(corner.to_pos2()));
    }
}

/// Draw with `draw` in `ui`, keeping inside it what egui draws of its own meanwhile over the
/// whole window, as the warning that two widgets have the same id.
fn debug_kept_inside<R>(ui: &mut egui::Ui, draw: impl FnOnce(&mut egui::Ui) -> R) -> R {
    let (area, debug) = (ui.max_rect().intersect(ui.clip_rect()), egui::LayerId::debug());
    let start = ui.ctx().graphics(|layers| layers.get(debug).map_or(0, |shapes| shapes.next_idx().0));
    let drawn = draw(ui);
    ui.ctx().graphics_mut(|layers| {
        let shapes = layers.entry(debug);
        for idx in start..shapes.next_idx().0 {
            shapes.mutate_shape(egui::layers::ShapeIdx(idx), |shape| shape.clip_rect = shape.clip_rect.intersect(area));
        }
    });
    drawn
}

