    /// Make frames on the window's graphics card: with this, a shot that plays is shown from
    /// frames the GPU compositor made and keeps (plan §4.3). `device`, `queue` and `renderer`
    /// are the window's own.
    /// Write to `log` from here on: the desktop app's, begun before there was a window.
    pub fn with_log(mut self, log: Log) -> Self {
        self.log = log;
        self
    }

    pub fn with_gpu(mut self, device: wgpu::Device, queue: wgpu::Queue, renderer: std::sync::Arc<egui::mutex::RwLock<egui_wgpu::Renderer>>) -> Self {
        let mut cache = playback::FrameCache::new(iskra_gpu::Compositor::new(device, queue), renderer);
        cache.budget = (self.prefs.playback_memory.max(1) as usize) << 20;
        self.viewport.cache = Some(cache);
        self
    }

    /// The graphics cards that were found, by name, and the one the window is drawn with, as
    /// the Settings window lists them.
    pub fn with_cards(mut self, found: Vec<String>, in_use: String) -> Self {
        self.graphics.cards = found;
        self.graphics.in_use = Some(in_use);
        self
    }

    /// Whether the window wants every key for itself: while a command in the Settings window
    /// waits for the key it is to have.
    pub fn wants_keys(&self) -> bool {
        self.shortcut_capture.is_some()
    }

    /// The player the sound output asks for samples.
    pub fn player(&self) -> std::sync::Arc<iskra_audio::Player> {
        self.player.clone()
    }

    /// What a sound input feeds while a take is recorded. It says when it wants one open.
    pub fn recorder(&self) -> std::sync::Arc<iskra_audio::Recorder> {
        self.recorder.clone()
    }

    /// Start recording sound from the playhead on. The take goes into the project's Audio
    /// folder, so the project has to have a file.
    fn start_recording(&mut self, ctx: &egui::Context, play: bool) {
        if self.session.path().is_none() {
            self.error = Some("Save the project first: a recording is kept in its Audio folder".to_string());
            return;
        }
        self.recorder.start();
        self.recording_from = Some(self.film_frame);
        if play && self.playing.is_none() {
            self.toggle_play(ctx);
        }
    }

    /// End the take: write it as a WAV file into the project's Audio folder, bring that in
    /// as a sound, and lay it under the shots from the frame the take was started on.
    fn stop_recording(&mut self) {
        let (Some(from), Some(take)) = (self.recording_from.take(), self.recorder.stop()) else { return };
        if self.playing.take().is_some() {
            self.player.stop();
        }
        let (Some(folder), Some(storyboard)) = (self.session.path().and_then(|file| file.parent()).map(|folder| folder.join("Audio")), self.storyboard) else {
            return;
        };
        if take.samples.is_empty() {
            self.error = Some("Nothing was heard: the take is empty".to_string());
            return;
        }
        // The first name that no file has.
        let path = (1u32..)
            .map(|number| folder.join(format!("Recording_{number:02}.wav")))
            .find(|path| !path.exists())
            .unwrap_or_else(|| folder.join("Recording.wav"));
        let written = std::fs::create_dir_all(&folder).and_then(|()| std::fs::write(&path, iskra_audio::write_wav16(&take.samples, take.channels, take.rate)));
        if let Err(why) = written {
            self.error = Some(format!("{}: {why}", path.display()));
            return;
        }
        let media = self.run_for("media.import", json!({ "paths": [path] })).and_then(|made| made["media"][0].as_u64());
        if let Some(media) = media {
            self.run("sound.place", json!({ "storyboard": storyboard.0, "media": media, "start": from }));
        }
    }

    /// A sound output is open and asks [`IskraApp::player`] for samples: what plays is heard.
    pub fn with_sound(mut self) -> Self {
        self.sounding = true;
        self
    }

    /// Listen to a sound item from its start, or stop listening to it.
    fn listen(&mut self, media: iskra_model::MediaId) {
        if self.listening.take() == Some(media) {
            self.player.stop();
            return;
        }
        if !self.sounding {
            self.error = Some("No sound output is open on this machine, so nothing can be heard.".to_string());
            return;
        }
        let project = self.session.project().clone();
        let folder = self.session.path().and_then(|file| file.parent()).map(std::path::Path::to_path_buf);
        let Some(item) = project.media(media) else { return };
        let Some(sound) = self.sounds.get(item, folder.as_deref()) else {
            self.error = Some(format!("{} could not be read", item.file(folder.as_deref()).display()));
            return;
        };
        (self.playing, self.heard) = (None, None);
        let length = sound.seconds();
        self.player.set_clips(vec![iskra_audio::Clip { sound, start: 0.0, offset: 0.0, length, gain: 1.0 }]);
        self.player.play(0.0);
        self.listening = Some(media);
    }

    /// Read the user's preferences from the file at `path`, and keep them saved there.
    pub fn with_preferences(mut self, path: std::path::PathBuf) -> Self {
        self.prefs = Preferences::load(&path);
        self.prefs.animate = self.prefs.animate_at_start;
        // Without workspace changes kept, each start opens the pages as they were fixed.
        if let Some(fixed) = self.prefs.fixed_layouts.clone().filter(|_| !self.prefs.keep_layouts) {
            self.prefs.layouts = fixed;
        }
        iskra_render::set_shared_budget((self.prefs.effect_memory.max(1) as usize) << 20);
        self.graphics.started = (self.prefs.graphics_backend, self.prefs.graphics_card.clone());
        self.tools.art = if self.prefs.colour_art { ArtLayerKind::ColourArt } else { ArtLayerKind::LineArt };
        self.tools.free = self.prefs.free_colour;
        self.tools.surface = self.prefs.brush_surface;
        (self.display.shown_art, self.display.shown_art_all) = (self.prefs.shown_art, self.prefs.shown_art_all);
        let onion = self.prefs.onion;
        (self.display.before, self.display.after, self.display.opacity) = (onion.before, onion.after, onion.opacity);
        (self.display.line_art_only, self.display.outline) = (onion.line_art_only, onion.outline);
        // The brushes are the user's too, in a file of their own: they can be large.
        let brushes = path.with_file_name("brushes.json");
        self.brushes = iskra_drawing::Brushes::load(&brushes);
        self.brushes_file = Some((brushes, self.brushes.clone()));
        self.prefs_file = Some((path, self.prefs.clone()));
        self.take_kept_guide();
        self.reload_scripts();
        self
    }

    /// Take in hand the drawing guide that was in hand when the open project was last worked
    /// on, as the preferences keep it. A guide the project no longer has is never in hand:
    /// [`IskraApp::guide_in_hand`] looks for it in the shot.
    fn take_kept_guide(&mut self) {
        let kept = self.prefs.guide_in_hand.as_ref().filter(|(file, _)| self.session.path() == Some(file.as_path()));
        self.viewport.guide = kept.map(|(_, guide)| iskra_model::GuideId(*guide));
    }

    /// Start on the Media page, where the project's shots and files are, and not in a shot:
    /// nothing of a shot is drawn or made ready for playing until one is gone into. Not if
    /// the user has taken that page out of the bar.
    /// Show the start window first, as when the app is opened from its icon: a new project
    /// or a recent one, before the project's window.
    pub fn with_start_window(mut self) -> Self {
        self.start = Some(start::StartWindow::new(&self.prefs.new_project));
        self
    }

    /// Open the project file at `path` first, as when the app is opened by one.
    pub fn with_file(mut self, path: &std::path::Path) -> Self {
        self.open_file(path);
        self
    }

    /// The start window's new project: made, given its resolution and frame rate, and saved
    /// in a folder of its name in `folder`. What was chosen is what the window offers next.
    fn create_project(&mut self, name: &str, folder: &std::path::Path, width: u32, height: u32, frame_rate: u32) {
        let new = &mut self.prefs.new_project;
        (new.folder, new.width, new.height, new.frame_rate) = (Some(folder.to_path_buf()), width, height, frame_rate);
        self.run("file.new", Value::Null);
        self.run("project.setResolution", json!({ "width": width, "height": height }));
        self.run("project.setFrameRate", json!({ "num": frame_rate }));
        if let Err(why) = std::fs::create_dir_all(folder) {
            self.error = Some(format!("the folder {} could not be made: {why}", folder.display()));
        } else {
            self.save_project_as(&folder.join(format!("{name}.iskra")));
        }
        self.opened();
        self.viewport.fit();
    }

    /// The start window, while it is shown: what it asks for is done, and it goes.
    fn start_window(&mut self, ui: &mut egui::Ui) -> bool {
        let Some(window) = self.start.as_mut() else { return false };
        let recent = self.prefs.recent_files.clone();
        if let Some(action) = window.show(ui, &self.prefs.new_project, &recent) {
            self.start_asked(ui.ctx(), action);
        }
        true
    }

    /// What the start window asked for: the app's window grows into the project's.
    fn start_asked(&mut self, ctx: &egui::Context, action: start::Action) {
        match action {
            start::Action::Quit => self.quit(ctx),
            // The system's dialog, which blocks: not in the tests, which say what was picked.
            start::Action::Browse => {
                #[cfg(not(test))]
                let picked = dialogs::open_project();
                #[cfg(test)]
                let picked = self.start.as_mut().and_then(|window| window.browsed.take());
                if let Some(path) = picked {
                    self.start_asked(ctx, start::Action::Open(path));
                }
            }
            start::Action::Open(path) => {
                self.start = None;
                self.grow_window(ctx);
                self.open_file(&path);
            }
            // A project of that name is in that folder already: it is not saved over.
            start::Action::Create { name, folder, .. } if folder.join(&name).join(format!("{name}.iskra")).exists() => {
                if let Some(window) = self.start.as_mut() {
                    window.problem = Some(format!("{name} is in that folder already: open it from Recent Projects, or give the new one another name"));
                }
            }
            start::Action::Create { name, folder, width, height, frame_rate } => {
                self.start = None;
                self.grow_window(ctx);
                self.create_project(&name, &folder, width, height, frame_rate);
            }
        }
    }

    /// The window, which was the start window, made the project's: as large as the
    /// preferences say, or maximised, resizable again, and where it was left.
    fn grow_window(&mut self, ctx: &egui::Context) {
        use egui::ViewportCommand as Command;
        let points = |[x, y]: [f32; 2]| egui::vec2(x, y) / ctx.zoom_factor();
        let size = points(self.prefs.opening_size());
        ctx.send_viewport_cmd(Command::Resizable(true));
        ctx.send_viewport_cmd(Command::EnableButtons { close: true, minimized: true, maximize: true });
        ctx.send_viewport_cmd(Command::MinInnerSize(points(prefs::WINDOW_SMALLEST)));
        ctx.send_viewport_cmd(Command::InnerSize(size));
        match self.prefs.opening_position() {
            Some(corner) => {
                ctx.send_viewport_cmd(Command::OuterPosition(points(corner).to_pos2()));
                self.placed_where_left();
            }
            None => centre_window(ctx, size),
        }
        if self.prefs.window_maximized {
            ctx.send_viewport_cmd(Command::Maximized(true));
        }
    }

    /// The window was opened where it was left, if that is known: see that it is there, on
    /// the display it was on. Not when it is maximised, which fills a display whatever.
    pub fn placed_where_left(&mut self) {
        let wanted = self.prefs.opening_position().is_some() && !self.prefs.window_maximized;
        self.placing = wanted.then_some(PLACING_FRAMES);
    }

    pub fn starting_on_media(mut self) -> Self {
        if !self.prefs.hidden_pages.contains(&Page::Media) {
            self.page = Page::Media;
        }
        self
    }

    /// Run an engine command and return its result, keeping its error for the status bar.
    fn run_for(&mut self, id: &str, mut params: Value) -> Option<Value> {
        if MAKES_A_DRAWING.contains(&id) {
            params["hold"] = self.prefs.new_drawing_hold.param();
        }
        // Layers made on the Storyboard page are the shot's boards (plan §7.2c).
        if id == "layer.new" && self.page == Page::Storyboard {
            params["role"] = json!("board");
        }
        // A layer whose kind is not said is of the kind the layer in hand is.
        if id == "layer.new" && params["kind"].is_null() {
            let text = self.shot().zip(self.layer).and_then(|(shot, layer)| shot.layer(layer)).is_some_and(|layer| layer.text);
            params["kind"] = json!(if text {
                "text"
            } else if self.vector_art() {
                "vector"
            } else {
                "bitmap"
            });
        }
        // A free colour that is painted is one of those used lately.
        let painted: Option<[u8; 4]> = MAKES_A_DRAWING.contains(&id).then(|| serde_json::from_value(params["color"].clone()).ok()).flatten();
        let undoing = matches!(id, "edit.undo" | "edit.redo");
        let before = undoing.then(|| self.session.project().shots.iter().find(|shot| Some(shot.id) == self.shot).cloned()).flatten();
        let timer = timings::timer(id);
        let result = self.session.execute(id, params);
        drop(timer);
        // An undo or a redo of a change to another layer or peg than the one in hand selects it.
        if let Some(before) = before {
            self.select_changed(&before);
        }
        self.error = result.as_ref().err().map(|e| e.to_string());
        if let (Some(colour), true) = (painted, result.is_ok()) {
            let recent = &mut self.prefs.recent_colours;
            recent.retain(|other| *other != colour);
            recent.insert(0, colour);
            recent.truncate(RECENT_COLOURS);
        }
        // A stroke painted is not said, unless the log is to have them: what went wrong is. Nor
        // is each change typed into a text.
        let painting = matches!(id, "drawing.stroke" | "drawing.shape" | "drawing.mix");
        match &self.error {
            Some(why) => self.log.say(format!("{id}: {why}")),
            None if painting && !self.prefs.log_strokes => {}
            None if id == "text.type" => {}
            None => self.log.say(id),
        }
        // A text laid out in Inter for a font the machine lacks (plan §4.19).
        let missing = result.as_ref().ok().and_then(|done| done["standIn"].as_array());
        for font in missing.into_iter().flatten().filter_map(Value::as_str) {
            self.log.say(format!("{id}: the font {font} is not on this machine; the text was laid out in Inter"));
        }
        self.logged_error = self.error.clone();
        if painting {
            timings::stroke_ended(|| self.timings_state());
        }
        result.ok()
    }

    /// The Preview panel (the user's of 2026-10-26): the item picked in the pool, seen. A
    /// picture whole; an image sequence a frame at a time, by its slider or played at the
    /// project's rate; a sound as its waveform, with a button to hear it.
    fn preview_panel(&mut self, ui: &mut egui::Ui) {
        let project = self.session.project().clone();
        let Some(item) = self.media.picked else {
            ui.weak("Click an item in the Media Pool to see it here.");
            return;
        };
        let iskra_model::Item::Media(id) = item else {
            let what = if matches!(item, iskra_model::Item::Shot(_)) { "A shot" } else { "A storyboard" };
            ui.weak(format!("{what}: a double click in the pool opens it."));
            return;
        };
        let Some(media) = project.media(id).cloned() else { return };
        let folder = self.session.path().and_then(|file| file.parent()).map(std::path::Path::to_path_buf);
        match media.kind {
            iskra_model::MediaKind::Sound { .. } => {
                if ui.button("Listen, or Stop").on_hover_text("Plays the sound from its start").clicked() {
                    self.listen(id);
                }
                let (rect, _) = ui.allocate_exact_size(ui.available_size().max(egui::vec2(10.0, 30.0)), egui::Sense::hover());
                let seconds = match media.kind {
                    iskra_model::MediaKind::Sound { sample_rate, frames, .. } => frames as f64 / f64::from(sample_rate.max(1)),
                    _ => 0.0,
                };
                let Some(peaks) = self.sounds.peaks(&media, folder.as_deref(), (seconds / f64::from(rect.width().max(1.0))).max(1e-4)) else {
                    ui.weak("The sound's file could not be read.");
                    return;
                };
                let theme = Theme::of(ui.ctx());
                let middle = rect.center().y;
                for (at, [low, high]) in peaks.iter().enumerate().take(rect.width() as usize) {
                    let x = rect.left() + at as f32;
                    ui.painter().vline(x, (middle - high * rect.height() / 2.0)..=(middle - low * rect.height() / 2.0), egui::Stroke::new(1.0, theme.accent));
                }
            }
            iskra_model::MediaKind::Image { .. } | iskra_model::MediaKind::ImageSequence { .. } => {
                let frames = match media.kind {
                    iskra_model::MediaKind::ImageSequence { frames, .. } => frames.max(1),
                    _ => 1,
                };
                if self.preview_frame.0 != Some(id) {
                    (self.preview_frame, self.preview_playing) = ((Some(id), 0), None);
                }
                if frames > 1 {
                    ui.horizontal(|ui| {
                        let playing = self.preview_playing.is_some();
                        if ui.button(if playing { "Stop" } else { "Play" }).clicked() {
                            self.preview_playing = if playing {
                                None
                            } else {
                                Some(ui.input(|i| i.time) - f64::from(self.preview_frame.1) / project.settings.frame_rate.as_f64())
                            };
                        }
                        let mut shown = self.preview_frame.1 + 1;
                        if ui.add(egui::Slider::new(&mut shown, 1..=frames).text("Frame")).changed() {
                            (self.preview_frame.1, self.preview_playing) = (shown - 1, None);
                        }
                    });
                    if let Some(since) = self.preview_playing {
                        let now = ui.input(|i| i.time);
                        self.preview_frame.1 = ((now - since) * project.settings.frame_rate.as_f64()) as u32 % frames;
                        ui.ctx().request_repaint();
                    }
                }
                let frame = self.preview_frame.1.min(frames - 1);
                let file = if frames > 1 {
                    if self.preview_frames.as_ref().is_none_or(|(of, _)| *of != id) {
                        let all = iskra_io::sequence_from(&media.file(folder.as_deref())).unwrap_or_default();
                        self.preview_frames = Some((id, all));
                    }
                    self.preview_frames.as_ref().and_then(|(_, all)| all.get(frame as usize).cloned().flatten())
                } else {
                    Some(media.file(folder.as_deref()))
                };
                if self.preview.as_ref().is_none_or(|(of, _)| *of != (id, frame)) {
                    let picture = file.as_deref().and_then(|file| iskra_io::read_picture(file).ok());
                    self.preview = picture.map(|(width, height, rgba)| {
                        let image = egui::ColorImage::from_rgba_unmultiplied([width as usize, height as usize], &rgba);
                        ((id, frame), ui.ctx().load_texture("media preview", image, egui::TextureOptions::LINEAR))
                    });
                }
                match &self.preview {
                    Some((_, texture)) => {
                        let room = ui.available_size();
                        let size = texture.size_vec2();
                        let scale = (room.x / size.x).min(room.y / size.y).clamp(0.01, 1.0);
                        ui.centered_and_justified(|ui| ui.image((texture.id(), size * scale)));
                    }
                    None => {
                        ui.weak("This frame's picture could not be read.");
                    }
                }
            }
        }
    }

    /// Select the layer or peg of the shot in hand that is not as it was in `before`, the shot
    /// as it was: what an undo or a redo changed. The one in hand stays if it is among them;
    /// bones changed select the layer they bend.
    fn select_changed(&mut self, before: &iskra_model::Shot) {
        let Some(now) = self.session.project().shots.iter().find(|shot| shot.id == before.id).cloned() else { return };
        let changed_layers: Vec<LayerId> = now
            .layers
            .iter()
            .filter(|layer| before.layers.iter().find(|was| was.id == layer.id).is_none_or(|was| !std::sync::Arc::ptr_eq(was, layer)))
            .map(|layer| layer.id)
            .collect();
        let bent: Vec<LayerId> = now
            .deformers
            .iter()
            .filter(|chain| before.deformers.iter().find(|was| was.id == chain.id).is_none_or(|was| !std::sync::Arc::ptr_eq(was, chain)))
            .filter_map(|chain| now.layers.iter().find(|layer| layer.deformer == Some(chain.id)).map(|layer| layer.id))
            .collect();
        let changed_pegs: Vec<PegId> = now
            .pegs
            .iter()
            .filter(|peg| before.pegs.iter().find(|was| was.id == peg.id).is_none_or(|was| !std::sync::Arc::ptr_eq(was, peg)))
            .map(|peg| peg.id)
            .collect();
        let layers: Vec<LayerId> = changed_layers.into_iter().chain(bent).collect();
        let in_hand = self.peg.map_or_else(|| self.layer.is_some_and(|layer| layers.contains(&layer)), |peg| changed_pegs.contains(&peg));
        if in_hand {
            return;
        }
        if let Some(layer) = layers.first() {
            (self.layer, self.peg, self.picked, self.released) = (Some(*layer), None, [layer.0].into(), None);
        } else if let Some(peg) = changed_pegs.first() {
            (self.peg, self.picked, self.released) = (Some(*peg), [peg.0].into(), None);
        }
    }

    /// The Select tool's selection as the parameters its commands take.
    fn selection(&self) -> Option<Value> {
        let mut selection = self.viewport.selection.as_ref()?.params();
        // Of the art layer in hand alone, if the tool is set so; and never of protected paint.
        (selection["artLayer"], selection["protect"]) = (json!(self.tools.selected_art()), json!(self.viewport.protect));
        Some(selection)
    }

    /// Flip or turn the selection a quarter round, about its middle: done by the viewport as
    /// a drag of it is, with the other drawings and layers the options take.
    pub(crate) fn turn_selection(&mut self, turn: Turn) {
        let Some(rect) = self.viewport.selection.as_ref().map(|selection| selection.rect) else { return };
        // About the middle, put on a pixel's corner or middle so that pixels land on pixels.
        let (x, y) = (f64::from(rect.x0 + rect.x1), f64::from(rect.y0 + rect.y1));
        let (e, f) = match turn {
            Turn::Across => (x, 0.0),
            Turn::Up => (0.0, y),
            Turn::Left => (((x - y) / 2.0).round(), ((x + y) / 2.0).round()),
            Turn::Right => (((x + y) / 2.0).round(), ((y - x) / 2.0).round()),
        };
        let [a, b, c, d] = turn.linear();
        self.tools.tool = Tool::Select;
        self.viewport.operation = Some(iskra_drawing::Affine { m: [a, b, c, d, e, f] });
    }

    /// Whether the selection can be merged: it is of vector art.
    pub(crate) fn can_merge(&self) -> bool {
        let layer = self.shot().zip(self.viewport.selection.as_ref()).and_then(|(shot, selection)| shot.layer(selection.layer));
        layer.is_some_and(|layer| viewport::draws_vector(layer, &self.tools))
    }

    /// The piece of a line split off for the selection, mended where it was let go, or with
    /// `now`, with nothing done to it since: the split is taken back, and the line is whole as
    /// it was. Once something is done to it, it stays a piece of its own.
    fn mend_piece(&mut self, now: bool) {
        let Some((cut, piece)) = &self.piece_cut else { return };
        let untouched = self.session.history().current() == *cut;
        if untouched && !now && self.viewport.selection.as_ref() == Some(piece) {
            return;
        }
        if untouched {
            self.session.undo();
            if self.viewport.selection.as_ref() == Some(piece) {
                self.viewport.selection = None;
            }
        }
        self.piece_cut = None;
    }

    /// Run a command on the selection, if there is one.
    fn on_selection(&mut self, id: &str) {
        if let Some(selection) = self.selection() {
            self.run(id, selection);
        }
    }

    /// The frames that are picked on the timeline, if they are what the Edit menu works on:
    /// frames of a layer of the shot that is open on the Animation page, where they are seen,
    /// with nothing selected in the viewport.
    fn picked_frames(&self) -> Option<timeline::Frames> {
        let picked = self.timeline.frames.filter(|_| self.page == Page::Animation && self.viewport.selection.is_none())?;
        self.shot()?.layer(picked.layer).map(|_| picked)
    }

    /// Whether there is something for the Edit menu to cut, copy or delete: a selection in the
    /// viewport, or frames picked on the timeline.
    fn has_selection(&self) -> bool {
        self.viewport.selection.is_some() || self.picked_frames().is_some()
    }

    /// There is something for Delete to take: what is selected, or the keyframes, shots or
    /// sound clips that are picked on the timeline of the page that is shown.
    fn can_delete(&self) -> bool {
        self.has_selection() || !self.picked_removals().is_empty() || self.joint_removal().is_some() || self.points_picked()
    }

    /// Whether the point editor is in hand with points picked, which Delete takes away.
    fn points_picked(&self) -> bool {
        self.tools.tool == Tool::Points && !self.viewport.points.picked.is_empty()
    }

    /// With the Bones tool in hand, the command that takes the selected joint of the chain of
    /// the layer drawn on out of it, or the selected point of a curve or an envelope: as the
    /// tool's bar does. `None` where none is selected, or none can go: the chain's first and
    /// last joints, and a line's points where it has as few as it can have.
    fn joint_removal(&self) -> Option<(&'static str, Value)> {
        let joint = self.viewport.bone_joint.filter(|_| self.tools.tool == Tool::Bones)?;
        let shot = self.shot()?;
        let chain = shot.deformer(shot.layer(self.layer?)?.deformer?)?;
        if !chain.is_curve() {
            let inside = (1..chain.bones.len()).contains(&joint);
            return inside.then(|| ("deformer.removeBone", json!({ "deformer": chain.id.0, "joint": joint })));
        }
        let least = if chain.is_envelope() { 3 } else { 2 };
        (joint < chain.spine.len() && chain.spine.len() > least).then(|| ("deformer.removeKnot", json!({ "deformer": chain.id.0, "knot": joint })))
    }

    /// Delete what is selected: the paint in the viewport's selection, or the picked frames,
    /// which are left as empty cells. With neither, all the keyframes that are picked on the
    /// timeline, and on the Storyboard page the shots and sound clips that are, as one step.
    fn delete_selection(&mut self) {
        // With the point editor in hand, its picked points.
        if self.points_picked() {
            let layer = self.shot().zip(self.layer).and_then(|(shot, layer)| shot.layer(layer).cloned());
            let (frame, art) = (self.tools.frame, self.tools.art);
            match layer.and_then(|layer| self.viewport.points.delete(&layer, frame, art)) {
                Some((command, params)) => self.run(command, params),
                None => self.error = Some("A line keeps two points at least: delete the shape with the Select tool".to_string()),
            }
            return;
        }
        // With the Bones tool in hand, its selected joint, or a curve's point.
        if self.viewport.selection.is_none()
            && let Some((command, params)) = self.joint_removal()
        {
            self.run(command, params);
            self.viewport.bone_joint = None;
            return;
        }
        match self.picked_frames() {
            Some(picked) => self.run("exposure.set", json!({ "layer": picked.layer.0, "frame": picked.first, "length": picked.length(), "drawing": null })),
            None if self.viewport.selection.is_some() => self.on_selection("drawing.clear"),
            None => self.run_several(self.picked_removals()),
        }
    }

    /// The commands that take away what is picked on the timeline of the page that is shown:
    /// on the Storyboard page the keyframes of the camera and the boards' pegs, the sound clips
    /// and the shots, elsewhere
    /// the keyframes of the Animation timeline.
    fn picked_removals(&self) -> Vec<Value> {
        let one = |id: &str, params: Value| json!({ "id": id, "params": params });
        if self.page != Page::Storyboard {
            // Of all a node's values on the frame, or of the one whose row the key is on.
            let key = |(of, frame): &(timeline::Keyed, u32)| one(&format!("{}.removeKey", of.kind()), of.params(json!({ "frame": frame })));
            return self.timeline.picked_keys.iter().map(key).collect();
        }
        let view = &self.storyboard_view;
        let keys = self.shot.into_iter().flat_map(|shot| {
            view.picked_keys.iter().map(move |(of, frame)| {
                let (id, params) = of.removal(shot, *frame);
                one(id, params)
            })
        });
        let sounds = view.picked_sounds.iter().map(|clip| one("sound.delete", json!({ "clip": clip.0 })));
        let shots = view.picked_shots.iter().map(|shot| one("shot.delete", json!({ "shot": shot.0 })));
        keys.chain(sounds).chain(shots).collect()
    }

    /// The commands that delete the nodes that are picked together, on the timeline's rows or
    /// in the node view.
    fn picked_deletes(&self) -> Vec<Value> {
        self.deletes_of(self.picked.clone())
    }

    /// *Animation ▸ Delete Picked Nodes*: the picked nodes deleted, but a group ungrouped, what
    /// was in it kept, as the node view's *Ungroup*. *Delete Picked Nodes with All in Them*
    /// takes a group's contents too (`picked_deletes`).
    fn picked_deletes_ungrouping(&self) -> Vec<Value> {
        let Some(shot) = self.shot() else { return Vec::new() };
        let (groups, rest): (std::collections::BTreeSet<u64>, _) = self.picked.iter().partition(|id| shot.group(iskra_model::GroupId(**id)).is_some());
        // A group's ports go with it; what else is picked inside it is deleted on its own.
        let rest = rest.into_iter().filter(|id| !(shot.is_port(*id) && shot.group_of(*id).is_some_and(|group| groups.contains(&group.id.0)))).collect();
        let ungroup = groups.iter().map(|group| json!({ "id": "group.delete", "params": { "group": group } }));
        ungroup.chain(self.deletes_of(rest)).collect()
    }

    /// The commands that delete `nodes` of the shot that is open: a group among them with all
    /// that is in it, however deep. The groups are taken away first, then what hangs on
    /// others, the bones and the effects, then the layers, the pegs and the composites. A
    /// group's ports go with the group, and are not asked for again.
    fn deletes_of(&self, mut nodes: std::collections::BTreeSet<u64>) -> Vec<Value> {
        let Some(shot) = self.shot() else { return Vec::new() };
        for group in nodes.clone() {
            nodes.extend(shot.group_nodes(iskra_model::GroupId(group)));
        }
        let gone_with = |node: &u64| shot.is_port(*node) && shot.group_of(*node).is_some_and(|group| nodes.contains(&group.id.0));
        let ports: Vec<u64> = nodes.iter().copied().filter(gone_with).collect();
        nodes.retain(|node| !ports.contains(node));
        let of = |id: &'static str, key: &'static str, has: &dyn Fn(u64) -> bool| -> Vec<Value> {
            nodes.iter().filter(|node| has(**node)).map(|node| json!({ "id": id, "params": { key: node } })).collect()
        };
        [
            of("group.delete", "group", &|id| shot.group(iskra_model::GroupId(id)).is_some()),
            of("deformer.delete", "deformer", &|id| shot.deformer(iskra_model::DeformerId(id)).is_some()),
            of("effect.delete", "effect", &|id| shot.effect(iskra_model::EffectId(id)).is_some()),
            of("layer.delete", "layer", &|id| shot.layer(LayerId(id)).is_some()),
            of("peg.delete", "peg", &|id| shot.peg(PegId(id)).is_some()),
            of("composite.delete", "composite", &|id| shot.composite(iskra_model::CompositeId(id)).is_some()),
        ]
        .concat()
    }

    /// Run several commands as one step, and let go of what was picked for them.
    fn run_several(&mut self, commands: Vec<Value>) {
        if commands.is_empty() {
            return;
        }
        self.run("edit.batch", json!({ "commands": commands }));
        if self.error.is_none() {
            self.picked.clear();
            self.timeline.picked_keys.clear();
            let view = &mut self.storyboard_view;
            (view.picked_shots, view.picked_sounds, view.picked_keys) = (Vec::new(), Vec::new(), Vec::new());
        }
    }

    /// What is asked of one thing that is picked together with others is done to them all:
    /// a keyframe removed, a row or a node, a shot or a sound clip deleted, from its menu.
    /// The commands for all of them, or none when `id` with `params` is no such thing.
    fn for_all_picked(&self, id: &str, params: &Value) -> Vec<Value> {
        let named = |key: &str| params[key].as_u64();
        let all = match id {
            "peg.removeKey" | "deformer.removeKey" | "effect.removeKey" | "sound.delete" => self.picked_removals(),
            "camera.setKey" if params["remove"] == json!(true) => self.picked_removals(),
            "shot.delete" if self.page == Page::Storyboard => self.picked_removals(),
            "layer.delete" | "peg.delete" | "effect.delete" | "composite.delete" | "deformer.delete" => self.picked_deletes(),
            _ => return Vec::new(),
        };
        // Only where what was asked is one of several that are picked.
        let key = id.split('.').next().map_or("", |kind| {
            if kind == "sound" {
                "clip"
            } else if kind == "camera" {
                "shot"
            } else {
                kind
            }
        });
        let among = all.iter().any(|one| one["id"] == id && one["params"][key].as_u64() == named(key) && one["params"]["frame"] == params["frame"]);
        if among && all.len() > 1 { all } else { Vec::new() }
    }

    /// There is something for Deselect, and Escape, to let go of.
    fn can_deselect(&self) -> bool {
        let view = &self.storyboard_view;
        let picked = !self.picked.is_empty() || !self.timeline.picked_keys.is_empty() || !view.picked_shots.is_empty() || !view.picked_sounds.is_empty();
        self.has_selection() || picked || !view.picked_keys.is_empty() || (self.tools.tool == Tool::Transform && self.target_peg().is_some())
    }

    /// Let go of what is selected: the paint in the viewport, the frames and the keyframes on
    /// the timelines, the nodes, shots and clips that are picked, and what the Transform tool
    /// has hold of, which then has nothing until something is selected again. The layer that
    /// is drawn on stays the one in hand: there is always one.
    fn deselect(&mut self) {
        (self.viewport.selection, self.timeline.frames) = (None, None);
        self.timeline.picked_keys.clear();
        self.picked.clear();
        let view = &mut self.storyboard_view;
        (view.picked_shots, view.picked_sounds, view.picked_keys) = (Vec::new(), Vec::new(), Vec::new());
        self.released = Some((self.layer, self.peg));
    }

    /// Paste the clipboard on the current frame and select what was pasted. Frames that were
    /// copied are laid on their layer from the playhead on, and are the ones picked then.
    fn paste(&mut self) {
        if let (Some(clip), Some(shot)) = (self.copied_keys.clone(), self.shot) {
            // Keyframes, from the playhead on: they are the ones picked then.
            let params = json!({ "shot": shot.0, "clip": clip, "frame": self.tools.frame, "onto": self.paste_keys_onto() });
            if let Some(pasted) = self.run_for("keys.paste", params) {
                self.pick_pasted_keys(&pasted["keys"]);
            }
            return;
        }
        if self.copied_nodes {
            // Copies of the nodes, in the shot that is open, where its node view was last
            // clicked and in the open group there, or else beside the copied ones: they are
            // the ones picked then.
            let Some(shot) = self.shot else { return };
            let params = match self.nodes.paste_at.take().filter(|(of, ..)| *of == shot) {
                Some((_, at, group)) => json!({ "shot": shot.0, "at": at, "group": group }),
                None => json!({ "shot": shot.0 }),
            };
            if let Some(made) = self.run_for("node.paste", params) {
                self.pick_made(&made);
            }
            return;
        }
        if let Some((layer, cells)) = self.copied_frames.clone() {
            let frame = self.tools.frame;
            let length = self.run_for("exposure.paste", json!({ "layer": layer.0, "frame": frame, "cells": cells })).and_then(|laid| laid["length"].as_u64());
            if let Some(length) = length {
                self.viewport.selection = None;
                self.timeline.frames = Some(timeline::Frames { layer, first: frame, last: frame + length as u32 - 1 });
            }
            return;
        }
        let Some(layer) = self.layer else { return };
        // Onto the art layer in hand, where the Select tool works on that one alone.
        let params = json!({ "layer": layer.0, "frame": self.tools.frame, "artLayer": self.tools.selected_art() });
        if let Some(pasted) = self.run_for("drawing.paste", params) {
            self.tools.tool = Tool::Select;
            self.viewport.select(layer, self.tools.frame, &pasted["rect"]);
        }
    }

    /// Pick the keyframes that were pasted, as `keys.paste` gives them, on the timeline of
    /// the page that is shown.
    fn pick_pasted_keys(&mut self, pasted: &Value) {
        let Some(shot) = self.shot().cloned() else { return };
        let keys = pasted.as_array().into_iter().flatten();
        let frame = |key: &Value| key["frame"].as_u64().map(|frame| frame as u32);
        if self.page == Page::Storyboard {
            let of = |owner: &Value| match (owner.get("camera"), owner["peg"].as_u64()) {
                (Some(_), _) => Some(items::KeyOwner::Camera),
                (None, Some(peg)) => Some(items::KeyOwner::Peg(PegId(peg))),
                _ => None,
            };
            self.storyboard_view.picked_keys = keys.filter_map(|key| Some((of(&key["owner"])?, frame(key)?))).collect();
            return;
        }
        let of = |owner: &Value| {
            let id = |name: &str| owner.get(name).and_then(Value::as_u64);
            if let Some(peg) = id("peg") {
                return Some(timeline::Keyed::Peg(PegId(peg), None));
            }
            if let Some(effect) = id("effect") {
                return Some(timeline::Keyed::Effect(iskra_model::EffectId(effect), None));
            }
            if let Some(shot) = id("camera") {
                return Some(timeline::Keyed::Lens(iskra_model::ShotId(shot)));
            }
            let bones = iskra_model::DeformerId(id("deformer")?);
            let layer = shot.layers.iter().find(|layer| layer.deformer == Some(bones))?;
            Some(timeline::Keyed::Bones(bones, layer.id, None))
        };
        self.timeline.picked_keys = keys.filter_map(|key| Some((of(&key["owner"])?, frame(key)?))).collect();
    }

    /// The nodes that Copy and Duplicate take, where no paint is selected and no frames are
    /// picked: those that are picked in the node view or on the Animation timeline, each
    /// with what goes with it, as a template takes it. A layer or a peg that was clicked is
    /// picked; the layer in hand that nothing picked is not, so that Copy does nothing by
    /// itself while drawing.
    fn nodes_to_copy(&self) -> Vec<Part> {
        match self.shot().filter(|_| self.page != Page::Storyboard && !self.has_selection()) {
            Some(shot) => timeline::parts_of(shot, &self.picked),
            None => Vec::new(),
        }
    }

    /// There is something for Copy to take: paint, frames, or nodes.
    fn can_copy(&self) -> bool {
        self.has_selection() || !self.picked_keyframes().is_empty() || !self.nodes_to_copy().is_empty()
    }

    /// There is something Cut takes: paint or frames that are selected, or keyframes.
    fn can_cut(&self) -> bool {
        self.has_selection() || !self.picked_keyframes().is_empty()
    }

    /// There is something a paste can lay, and somewhere to lay it.
    fn can_paste(&self) -> bool {
        if self.copied_nodes || self.copied_keys.is_some() { self.shot.is_some() } else { self.layer.is_some() }
    }

    /// The keyframes picked on the timeline of the page that is shown, as `keys.copy` takes
    /// them: on the Storyboard page the camera's and the boards' pegs', elsewhere those of the
    /// Animation timeline.
    fn picked_keyframes(&self) -> Vec<Value> {
        let key = |owner: Value, frame: u32| json!({ "owner": owner, "frame": frame });
        if self.page == Page::Storyboard {
            let Some(shot) = self.shot else { return Vec::new() };
            return self.storyboard_view.picked_keys.iter().map(|(of, frame)| key(of.owner(shot), *frame)).collect();
        }
        // A key on a value's own row is copied alone, by the name of its value.
        let owner = |of: &timeline::Keyed| json!({ of.kind(): of.id() });
        let picked = |(of, frame): &(timeline::Keyed, u32)| {
            let mut picked = key(owner(of), *frame);
            if let Some(name) = of.clip_name() {
                picked["value"] = json!(name);
            }
            picked
        };
        self.timeline.picked_keys.iter().map(picked).collect()
    }

    /// What keyframes that are pasted go onto, of what is in hand: the one effect node that
    /// is picked, the peg, or the bones of the layer. Keys of another kind of thing go back
    /// to where they came from.
    fn paste_keys_onto(&self) -> Option<Value> {
        let shot = self.shot()?;
        let effect = self.picked.iter().next().filter(|_| self.picked.len() == 1).copied().filter(|id| shot.effect(iskra_model::EffectId(*id)).is_some());
        if let Some(effect) = effect {
            return Some(json!({ "effect": effect }));
        }
        if let Some(peg) = self.peg {
            return Some(json!({ "peg": peg.0 }));
        }
        let bones = self.layer.and_then(|layer| shot.layer(layer)?.deformer)?;
        Some(json!({ "deformer": bones.0 }))
    }

    /// Copies of the picked nodes beside them, in one step, which are then the ones picked.
    fn duplicate(&mut self) {
        let (nodes, Some(shot)) = (self.nodes_to_copy(), self.shot) else { return };
        if let Some(made) = self.run_for("node.duplicate", json!({ "shot": shot.0, "nodes": nodes })) {
            self.pick_made(&made);
        }
    }

    /// What switches the picked nodes on, or off, as `edit.batch` takes it: `None` where none
    /// of them would change, or on the Storyboard page, where no nodes are seen.
    fn picked_switch(&self, on: bool) -> Option<Value> {
        let shot = self.shot().filter(|_| self.page != Page::Storyboard)?;
        nodes::switching(shot, self.picked.iter().copied(), on)
    }

    /// Switch the picked nodes on or off, in one step. They stay picked.
    fn switch_picked(&mut self, on: bool) {
        if let Some(batch) = self.picked_switch(on) {
            self.run("edit.batch", batch);
        }
    }

    /// Pick the nodes a paste or a duplicate made, by the ids the command gave back.
    fn pick_made(&mut self, made: &Value) {
        let ids = |kind: &str| made[kind].as_array().into_iter().flatten().filter_map(Value::as_u64).collect::<Vec<_>>();
        self.picked = ["layers", "pegs", "composites", "groups", "effects"].into_iter().flat_map(ids).collect();
    }

    /// Select everything painted on the current drawing.
    fn select_all(&mut self) {
        let Some(layer) = self.layer else { return };
        let bounds = self.session.project().layer(layer).and_then(|e| e.drawing_at(self.tools.frame)).map(|d| d.drawing.bounds());
        if let Some(b) = bounds {
            self.tools.tool = Tool::Select;
            self.viewport.select(layer, self.tools.frame, &json!([b.x0, b.y0, b.x1, b.y1]));
        }
    }

    /// Turn the selection inside out, within all that is painted on its drawing and itself.
    fn invert_selection(&mut self) {
        let Some(selection) = self.viewport.selection.as_ref() else { return };
        let drawing = self.session.project().layer(selection.layer).and_then(|layer| layer.drawing_at(selection.frame));
        let whole = drawing.map_or(selection.rect, |drawing| drawing.drawing.bounds());
        if let Some(inverted) = selection.inverted(whole) {
            self.viewport.selection = Some(inverted);
        }
    }

    /// The Animate switch: one for the app, on every page.
    fn animate(&self) -> bool {
        self.prefs.animate
    }

    fn toggle_animate(&mut self) {
        self.prefs.animate = !self.prefs.animate;
    }

    /// What a tool or a panel asks, with the Animate switch's say put into it where it moves
    /// a peg, poses bones or changes the lens, alone or as one of several: keyed on its frame, or not.
    /// What says for itself, a keyframe that is dragged, is left as it is. With Adjust on, what
    /// is keyed takes the frames of the keyframes picked on the timeline that are its own, to
    /// change alike.
    fn animated(&self, id: &str, mut params: Value) -> Value {
        let on = self.animate();
        let say = |id: &str, params: &mut Value| {
            if matches!(id, "peg.setTransform" | "camera.setLens" | "deformer.setPose") && params.get("animate").is_none() {
                params["animate"] = json!(on);
            }
            if params["animate"] != json!(false) {
                self.adjusting(id, params);
            }
        };
        say(id, &mut params);
        if id == "edit.batch" {
            for one in params["commands"].as_array_mut().into_iter().flatten() {
                let id = one["id"].as_str().unwrap_or_default().to_string();
                say(&id, &mut one["params"]);
            }
        }
        params
    }

    /// With Adjust on, a keyed command takes the frames of the keyframes picked on the
    /// timeline that are its own, to change alike, where it does not say them itself.
    fn adjusting(&self, id: &str, params: &mut Value) {
        if self.prefs.adjust && params.get("adjust").is_none() {
            let frames = self.adjusted(id, params);
            if !frames.is_empty() {
                params["adjust"] = json!(frames);
            }
        }
    }

    /// The frames of the keyframes picked on the timeline that are of what a keyed command
    /// changes: the peg's, the bones', the lens's or the effect node's.
    fn adjusted(&self, id: &str, params: &Value) -> Vec<u32> {
        let named = |key: &str| params[key].as_u64();
        let lens = named("shot").or(self.shot.map(|shot| shot.0));
        let mut frames: Vec<u32> = (self.timeline.picked_keys.iter())
            .filter(|(of, _)| match (id, of) {
                ("peg.setTransform", timeline::Keyed::Peg(peg, _)) => named("peg") == Some(peg.0),
                ("deformer.setPose", timeline::Keyed::Bones(bones, ..)) => named("deformer") == Some(bones.0),
                ("camera.setLens", timeline::Keyed::Lens(shot)) => lens == Some(shot.0),
                ("effect.set", timeline::Keyed::Effect(effect, _)) => named("effect") == Some(effect.0),
                _ => false,
            })
            .map(|(_, frame)| *frame)
            .collect();
        frames.sort_unstable();
        frames.dedup();
        frames
    }

    /// Pose a deformer (`deformer.setPose`), keyed or not as the Animate switch has it.
    fn pose(&mut self, params: Value) {
        self.run("deformer.setPose", self.animated("deformer.setPose", params));
    }

    /// Run an engine command, keeping its error for the status bar.
    fn run(&mut self, id: &str, params: Value) {
        self.run_for(id, params);
    }

    /// The project's name: its file's, or "Untitled".
    fn name(&self) -> String {
        self.session.path().and_then(|p| p.file_stem()).map_or("Untitled".to_string(), |s| s.to_string_lossy().into_owned())
    }

    /// Work that would be lost if the project were closed now: changes since the last save or
    /// autosave, or anything at all done in a project that has no file yet.
    fn would_lose_work(&self) -> bool {
        match self.session.path() {
            Some(_) => self.session.is_dirty(),
            None => self.session.history().entries().len() > 1,
        }
    }

    /// Before leaving the open project: if it has unsaved changes, ask whether to save them.
    /// Returns whether to go ahead.
    fn may_leave(&mut self) -> bool {
        if !self.would_lose_work() {
            return true;
        }
        // With autosave on, the changes of a project that has a file are simply saved.
        if self.prefs.autosave && self.session.path().is_some() {
            self.run("file.autosave", Value::Null);
            return self.error.is_none();
        }
        match dialogs::unsaved_changes(&self.name()) {
            dialogs::Unsaved::Save => {
                self.save_project(false);
                !self.would_lose_work()
            }
            dialogs::Unsaved::Discard => true,
            dialogs::Unsaved::Cancel => false,
        }
    }

    /// After another project replaced the open one: nothing of the old view applies.
    fn opened(&mut self) {
        (self.storyboard, self.shot) = (None, None);
        self.load_failed = None;
        (self.layer, self.peg, self.peg_edit) = (None, None, None);
        self.playing = None;
        self.tools.frame = 0;
        self.viewport.fit();
        self.take_kept_guide();
    }

    /// Say that the system shows the app's menus in a bar of its own, made from
    /// [`IskraApp::menu_bar`]: the window then draws none.
    pub fn set_system_menus(&mut self, shown: bool) {
        self.system_menus = shown;
    }

    /// Quit by asking the window to close, which asks about unsaved work like any close.
    fn quit(&self, ctx: &egui::Context) {
        ctx.send_viewport_cmd(egui::ViewportCommand::Close);
    }

    fn new_project(&mut self) {
        if self.may_leave() {
            self.run("file.new", Value::Null);
            self.opened();
        }
    }

    fn open_project(&mut self) {
        if !self.may_leave() {
            return;
        }
        if let Some(path) = dialogs::open_project() {
            self.open_file(&path);
        }
    }

    /// Open one of the files *Open Recent* lists, after asking about unsaved work.
    fn open_recent(&mut self, path: &std::path::Path) {
        if self.may_leave() {
            self.open_file(path);
        }
    }

    /// Open the project file at `path` in place of the open project.
    fn open_file(&mut self, path: &std::path::Path) {
        let began = std::time::Instant::now();
        let mut result = self.session.execute("file.open", json!({ "path": path }));
        if result.is_ok() {
            self.log.say(format!("opened {} in {:.0} ms", path.display(), began.elapsed().as_secs_f64() * 1000.0));
        }
        // A damaged file: offer its backup, opened as a copy so nothing is overwritten.
        if let Err(EngineError::Store(iskra_store::StoreError::Damaged { backup: Some(_), .. })) = &result
            && dialogs::confirm("Damaged Project", "This project file is damaged. Open its backup, the last saved version, as a recovered copy?", "Open Backup")
        {
            result = self.session.execute("file.recover", json!({ "path": path }));
        }
        self.error = result.err().map(|e| e.to_string());
        if self.error.is_none() {
            self.opened();
        }
    }

    /// A project opened from a file has its drawings still in the file: load those of the shot
    /// being worked on.
    fn load_shot(&mut self) {
        let Some((shot, name)) = self.shot().filter(|s| !s.loaded && self.load_failed != Some(s.id)).map(|s| (s.id, s.name.clone())) else { return };
        let began = std::time::Instant::now();
        match self.run_for("shot.load", json!({ "shot": shot.0 })) {
            Some(loaded) => {
                self.log.say(format!("loaded the drawings of `{name}` in {:.0} ms", began.elapsed().as_secs_f64() * 1000.0));
                let skipped = loaded["skipped"].as_array().map_or(0, Vec::len);
                self.error = (skipped > 0).then(|| format!("{skipped} drawing tiles could not be read and were left empty"));
            }
            None => self.load_failed = Some(shot),
        }
    }

    fn save_project(&mut self, save_as: bool) {
        if self.session.path().is_some() && !save_as {
            self.run("file.save", Value::Null);
        } else if let Some(chosen) = dialogs::save_project(&self.name()) {
            // The dialog asked about a file of that name where it was pointed; the project
            // goes into a folder there, and what is in that is asked about here.
            let file = iskra_store::in_project_folder(&chosen);
            let name = file.file_stem().map_or(String::new(), |stem| stem.to_string_lossy().into_owned());
            let question =
                format!("There is a project named {name} in a folder of that name here already. Replace it? The folder's other files are left as they are.");
            if file == chosen || !file.exists() || dialogs::confirm("Replace Project", &question, "Replace") {
                self.save_project_as(&chosen);
            }
        }
    }

    /// Save the project under the name and in the place the user chose: in a folder of that
    /// name there, which gets the folders a project starts with.
    fn save_project_as(&mut self, chosen: &std::path::Path) {
        self.run("file.saveAs", json!({ "path": chosen, "projectFolder": true }));
    }

    /// Keep the look of the interface as the preferences say: typefaces, theme and scale.
    fn style(&mut self, ctx: &egui::Context) {
        if self.styled.is_none() {
            egui_extras::install_image_loaders(ctx);
            theme::install(ctx);
        }
        let wanted = (Theme::for_appearance(self.prefs.appearance, ctx.system_theme()).with_colours(&self.prefs.colours), self.prefs.ui_scale.clamp(50, 300));
        if self.styled != Some(wanted) {
            wanted.0.apply(ctx);
            if self.styled.is_some_and(|(_, scale)| scale != wanted.1) || wanted.1 != 100 {
                ctx.set_zoom_factor(wanted.1 as f32 / 100.0);
            }
            self.styled = Some(wanted);
        }
    }

    /// Autosave, keep the preferences file and the window title current, and don't let the
    /// window close on unsaved work.
    fn housekeeping(&mut self, ui: &egui::Ui) {
        if self.keymap_name != self.prefs.keymap {
            self.keymap = Keymap::named(&self.prefs.keymap, self.keymaps_folder().as_deref());
            self.keymap_name = self.prefs.keymap.clone();
            self.keys_of = None;
        }
        if self.keys_of != Some(self.page) {
            self.keys = self.keymap.on(self.page);
            self.keys_of = Some(self.page);
        }
        // The window's size is kept, to open as large the next time: once it has stayed the
        // same for a frame, so that a window being dragged larger is not written at every step.
        // Where it is too, and how large its display is, to open there.
        let (inner, outer, display, state) = ui.input(|i| {
            let window = i.viewport();
            let state = (window.maximized.unwrap_or(false), window.fullscreen.unwrap_or(false), window.minimized.unwrap_or(false));
            (window.inner_rect, window.outer_rect, window.monitor_size, state)
        });
        // In the system's points, which the size of the interface does not change.
        let zoom = ui.ctx().zoom_factor();
        let system = |v: egui::Vec2| [(v.x * zoom).round(), (v.y * zoom).round()];
        let (corner, display) = (outer.map(|outer| system(outer.min.to_vec2())), display.map(system));
        if let Some(left) = self.placing {
            self.placing = match corner.zip(display).map(|(corner, display)| self.prefs.kept_place_holds(corner, display)) {
                Some(true) => None,
                _ if left > 0 => {
                    ui.ctx().request_repaint();
                    Some(left - 1)
                }
                // Not where it was left: centred, so that it is on a screen.
                Some(false) => {
                    centre_window(ui.ctx(), inner.map_or(egui::Vec2::ZERO, |inner| inner.size()));
                    None
                }
                // Where it is, the system does not say, as Wayland's does not.
                None => None,
            };
        }
        if let Some(inner) = inner.filter(|_| self.placing.is_none()) {
            let (size, (maximized, fullscreen, minimized)) = (system(inner.size()), state);
            if self.window_seen == Some((size, corner)) && !fullscreen && !minimized {
                self.prefs.window_maximized = maximized;
                if !maximized {
                    self.prefs.window_size = Some(size);
                    if corner.is_some() {
                        (self.prefs.window_position, self.prefs.window_display) = (corner, display);
                    }
                }
            }
            self.window_seen = Some((size, corner));
        }
        // The guide in hand, with the project it is of, to take in hand again next time.
        let guide = self.session.path().zip(self.viewport.guide).map(|(file, guide)| (file.to_path_buf(), guide.0));
        if guide != self.prefs.guide_in_hand {
            self.prefs.guide_in_hand = guide;
        }
        // Not while something is dragged: a gap between panels changes the layout every frame.
        let dragging = ui.input(|i| i.pointer.any_down());
        if let Some((path, saved)) = self.prefs_file.as_mut().filter(|(_, saved)| !dragging && *saved != self.prefs) {
            *saved = self.prefs.clone();
            if let Err(e) = self.prefs.save(path) {
                self.error = Some(format!("the preferences could not be saved: {e}"));
            }
        }
        if let Some((path, saved)) = self.brushes_file.as_mut().filter(|(_, saved)| !dragging && *saved != self.brushes) {
            *saved = self.brushes.clone();
            if let Err(e) = self.brushes.save(path) {
                self.error = Some(format!("the brushes could not be saved: {e}"));
            }
        }
        // A sound that is listened to stops at its end, and the sounds of items that are gone
        // are let go.
        if self.listening.is_some() {
            let end = self.player.clips().iter().map(|clip| clip.start + clip.length).fold(0.0, f64::max);
            if self.player.position().is_none_or(|at| at >= end) {
                self.player.stop();
                self.listening = None;
            } else {
                ui.ctx().request_repaint_after(std::time::Duration::from_millis(100));
            }
        }
        let project = self.session.project().clone();
        self.sounds.keep(|media| project.media(media).is_some());
        self.sync_sound(ui.input(|i| i.pointer.primary_down()));
        self.render_on(ui.ctx());
        // A project that was opened, or saved under a name, goes to the top of the recent files.
        let file = self.session.path().map(std::path::Path::to_path_buf);
        if file != self.last_file {
            if let Some(file) = &file {
                self.prefs.recent_files.retain(|recent| recent != file);
                self.prefs.recent_files.insert(0, file.clone());
                self.prefs.recent_files.truncate(RECENT_FILES);
            }
            self.last_file = file;
        }
        // Changes are autosaved once they have waited the interval. Saves are incremental, so
        // this is cheap (plan §4.9).
        let now = ui.input(|i| i.time);
        let unsaved = self.session.path().is_some() && self.session.is_dirty();
        self.unsaved_since = unsaved.then(|| self.unsaved_since.unwrap_or(now));
        if let Some(since) = self.unsaved_since.filter(|_| self.prefs.autosave) {
            let wait = f64::from(self.prefs.autosave_minutes.max(1)) * 60.0 - (now - since);
            if wait <= 0.0 {
                self.unsaved_since = None;
                self.run("file.autosave", Value::Null);
            } else {
                ui.ctx().request_repaint_after(std::time::Duration::from_secs_f64(wait));
            }
        }
        let title = format!("{}{} — Iskra", self.name(), if self.session.is_dirty() { " •" } else { "" });
        if title != self.title {
            ui.ctx().send_viewport_cmd(egui::ViewportCommand::Title(title.clone()));
            self.title = title;
        }
        if ui.input(|i| i.viewport().close_requested()) && !self.may_leave() {
            ui.ctx().send_viewport_cmd(egui::ViewportCommand::CancelClose);
        }
    }

    /// The shot being worked on: the project's first, until the pages bring a current shot
    /// (plan §7.8).
    fn shot(&self) -> Option<&Shot> {
        self.shot.and_then(|id| self.session.project().shot(id))
    }

    /// The layers whose onion skin shows: see `onion::onion_layers`. None while what was in
    /// hand is let go.
    fn onion_layers(&self) -> std::collections::BTreeSet<LayerId> {
        if self.released == Some((self.layer, self.peg)) {
            return Default::default();
        }
        self.shot().map_or(Default::default(), |shot| onion::onion_layers(shot, self.layer, self.peg, &self.picked))
    }

    /// The layers Hold to Here holds on to the playhead: see `timeline::layers_to_hold`.
    fn layers_to_hold(&self) -> Vec<LayerId> {
        self.shot().map_or(Vec::new(), |shot| timeline::layers_to_hold(shot, self.layer, &self.picked, self.tools.frame))
    }

    /// Make `shot` the shot being worked on. The one that was is released from memory, as far
    /// as it is saved (plan §6); the new one is loaded by the next frame.
    fn set_shot(&mut self, shot: ShotId) {
        if self.shot != Some(shot) {
            self.playing = None;
            self.switch_shot(shot);
        }
        self.film_frame = self.film_frame_of(self.tools.frame).unwrap_or(self.film_frame);
    }

    /// [`IskraApp::set_shot`] without touching playback or the storyboard's playhead: what the
    /// playhead does as it crosses from one shot into the next.
    fn switch_shot(&mut self, shot: ShotId) {
        if self.shot == Some(shot) {
            return;
        }
        // The shot that was open is let go, unless a transition under the playhead still shows it.
        if let Some(old) = self.shot.filter(|old| self.session.project().shot(*old).is_some() && !self.mixing.contains(old)) {
            self.session.unload_shot(old);
        }
        self.shot = Some(shot);
        (self.layer, self.peg, self.viewport.selection, self.timeline.frames) = (None, None, None, None);
        self.tools.frame = 0;
    }

    /// The storyboard that is open, and the current shot's clip on it.
    fn clip(&self) -> Option<iskra_model::Clip> {
        let project = self.session.project();
        project.storyboard(self.storyboard?)?.clip(self.shot?).copied()
    }

    /// Where a frame of the current shot is in the film: `None` if the shot is not on the open
    /// storyboard. A frame in the shot's handles counts as the nearest frame in the cut.
    fn film_frame_of(&self, frame: u32) -> Option<u32> {
        let clip = self.clip()?;
        Some(clip.start + frame.clamp(clip.in_point, clip.out_point - 1) - clip.in_point)
    }

    /// Whether the playhead runs along the film, from shot to shot: on the Storyboard and the
    /// Export pages. Elsewhere it is in one shot.
    fn on_film(&self) -> bool {
        matches!(self.page, Page::Storyboard | Page::Export)
    }

    /// The frame the playhead is on: of the film on the Storyboard and Export pages, of the
    /// shot elsewhere.
    fn playhead(&self) -> u32 {
        if self.on_film() { self.film_frame } else { self.tools.frame }
    }

    fn set_playhead(&mut self, frame: u32) {
        if self.on_film() {
            self.film_frame = frame;
        } else {
            self.tools.frame = frame;
        }
    }

    /// On the Storyboard and Export pages the playhead runs along the film: the shot it is on
    /// is the one being worked on, at the frame the playhead is at in it (plan §7.2b).
    fn follow_playhead(&mut self) {
        // Coming to the page, the playhead starts on the shot that was being worked on.
        let arrived = std::mem::replace(&mut self.last_page, self.page) != self.page;
        self.in_gap = false;
        if !self.on_film() {
            return;
        }
        if arrived {
            self.film_frame = self.film_frame_of(self.tools.frame).unwrap_or(self.film_frame);
        }
        let project = self.session.project().clone();
        let Some(board) = self.storyboard.and_then(|id| project.storyboard(id)) else { return };
        match board.clips().iter().find(|c| (c.start..c.end()).contains(&self.film_frame)) {
            Some(clip) => {
                self.switch_shot(clip.shot);
                self.tools.frame = clip.in_point + self.film_frame - clip.start;
            }
            None => self.in_gap = true,
        }
    }

    /// Keep the current storyboard and shot to ones the project has: an undo, or opening
    /// another project, can take them away.
    fn keep_current(&mut self) {
        let project = self.session.project().clone();
        if self.storyboard.is_none_or(|id| project.storyboard(id).is_none()) {
            self.storyboard = project.storyboards.first().map(|s| s.id);
        }
        if self.shot.is_none_or(|id| project.shot(id).is_none()) {
            let on_storyboard = self.storyboard.and_then(|id| project.storyboard(id)?.clips().first().map(|c| c.shot));
            self.shot = None;
            if let Some(shot) = on_storyboard.or(project.shots.first().map(|s| s.id)) {
                self.set_shot(shot);
            }
        }
        self.peg = self.peg.filter(|id| self.shot().is_some_and(|s| s.peg(*id).is_some()));
        // The layer in hand is one of the page's own (plan §7.2c): a board where the film is
        // boarded, and where it is animated an animation layer, if the shot has one.
        let boarding = self.page == Page::Storyboard;
        let own = |shot: &Shot| {
            let listed = shot.listed();
            let fits = listed.iter().find(|layer| shot.is_board(layer.id) == boarding).map(|layer| layer.id);
            fits.or(listed.first().map(|layer| layer.id).filter(|_| !boarding))
        };
        let gone = self.layer.is_none_or(|id| self.shot().is_none_or(|s| s.layer(id).is_none()));
        // Coming to a page with a layer of the other kind in hand, it is let go for one of this.
        let other = self.last_page != self.page && self.layer.is_some_and(|id| self.shot().is_some_and(|s| s.is_board(id) != boarding));
        // On the Storyboard page, once a board was in hand, the one of its name is.
        let named = self.board_named.clone().filter(|_| boarding);
        let by_name =
            |shot: &Shot| named.as_ref().and_then(|name| shot.layers.iter().find(|layer| shot.is_board(layer.id) && layer.name == *name).map(|layer| layer.id));
        if self.peg.is_some() {
            self.layer = None;
        } else if (gone || other) && named.is_some() {
            self.layer = self.shot().and_then(by_name);
        } else if gone || other {
            self.layer = self.shot().and_then(own).or(self.layer.filter(|_| !gone && !boarding));
        }
        let board = self.shot().and_then(|shot| shot.layer(self.layer?).filter(|layer| shot.is_board(layer.id)));
        if let (true, Some(layer)) = (boarding, board) {
            self.board_named = Some(layer.name.clone());
        }
        self.peg_edit = self.peg_edit.filter(|(id, _)| self.peg == Some(*id));
        // Another shot is looked at through its main display.
        if self.viewport.shot != self.shot {
            self.viewport.viewing = None;
        }
        self.viewport.shot = self.shot;
    }

    /// The peg the Transform tool works on: the selected one, or else the one the layer being
    /// drawn on is parented to.
    fn target_peg(&self) -> Option<PegId> {
        // The Camera tool is the Transform tool on the peg that moves the camera.
        if self.tools.tool == Tool::Camera {
            return self.shot()?.camera.parent;
        }
        // Let go of, the tool has nothing until another layer or peg is selected.
        if self.released == Some((self.layer, self.peg)) {
            return None;
        }
        self.peg.or_else(|| self.shot()?.layer(self.layer?)?.parent)
    }

    /// The peg a click of the Transform tool on a drawing of `layer` selects with *Peg
    /// Selection* on: the nearest above the drawing, or, where the peg in hand is above it,
    /// the next one up from that. `None` with the switch off, or with no peg above.
    fn clicked_peg(&self, layer: LayerId) -> Option<PegId> {
        if !(self.tools.peg_select && self.tools.tool == Tool::Transform) {
            return None;
        }
        let shot = self.shot()?;
        let above: Vec<PegId> = shot.ancestors(shot.layer(layer)?.parent).map(|peg| peg.id).collect();
        let held = self.peg.filter(|_| self.released.is_none()).and_then(|peg| above.iter().position(|one| *one == peg));
        match held {
            Some(at) => above.get(at + 1).or(above.get(at)).copied(),
            None => above.first().copied(),
        }
    }

    /// Keep where the pivot of the Transform tool's peg is seen, in the scene.
    fn copy_pivot(&mut self) {
        let (Some(shot), Some(peg)) = (self.shot(), self.target_peg()) else { return };
        self.copied_pivot = self.viewport.pivot_in_scene(shot, peg, self.panel_frame()).or(self.copied_pivot);
    }

    /// Put the pivot of the Transform tool's peg where the copied one is seen, moving the peg
    /// by as much as keeps what it carries where it is, in one step.
    fn paste_pivot(&mut self) {
        let frame = self.panel_frame();
        let (Some(shot), Some(peg), Some(at)) = (self.shot(), self.target_peg(), self.copied_pivot) else { return };
        let Some(now) = self.viewport.pivot_put(shot, peg, frame, at) else { return };
        let params = json!({ "peg": peg.0, "frame": frame, "pivot": now.pivot, "position": now.position });
        self.run("peg.setTransform", self.animated("peg.setTransform", params));
    }

    /// The other pegs the Transform tool has in hand beside the one it works on: those that
    /// are picked, and those that carry a layer that is picked. Not one that the tool's own
    /// peg carries or is carried by, nor one that another of them carries: it goes along
    /// with that one already.
    fn pegs_in_hand(&self) -> Vec<PegId> {
        let (Some(shot), Some(main), Tool::Transform) = (self.shot(), self.target_peg(), self.tools.tool) else { return Vec::new() };
        // Only where what is in hand is one of those that are picked: picked alone, or with
        // something else in hand, they are not what the tool works on.
        let in_hand = self.peg.map(|peg| peg.0).or(self.layer.map(|layer| layer.0));
        if !in_hand.is_some_and(|node| self.picked.contains(&node)) || self.picked.len() < 2 {
            return Vec::new();
        }
        let of = |node: &u64| shot.peg(PegId(*node)).map(|peg| peg.id).or_else(|| shot.layer(LayerId(*node))?.parent);
        let mut all: Vec<PegId> = self.picked.iter().filter_map(of).filter(|peg| shot.peg(*peg).is_some()).collect();
        all.sort_unstable();
        all.dedup();
        let above = |peg: PegId| shot.ancestors(shot.peg(peg).and_then(|peg| peg.parent)).map(|peg| peg.id).collect::<Vec<_>>();
        let over_main = above(main);
        all.iter()
            .copied()
            .filter(|peg| *peg != main && !over_main.contains(peg) && !above(*peg).iter().any(|over| *over == main || all.contains(over)))
            .collect()
    }

    /// Put a new peg above the selected peg, or else above the layer being drawn on, and
    /// select it. Where that one is picked with others, each of them gets a peg of its own,
    /// and what was selected stays so.
    fn add_parent_peg(&mut self) {
        // Above each of several that are picked, the one in hand among them, as one step.
        let in_hand = self.peg.map(|peg| peg.0).or(self.layer.map(|layer| layer.0));
        let several = self.shot().filter(|_| in_hand.is_some_and(|node| self.picked.contains(&node)));
        if let Some(batch) = several.and_then(|shot| timeline::parenting(shot, &self.picked, timeline::Parenting::Above)) {
            return self.run("edit.batch", batch);
        }
        let params = match (self.peg, self.layer) {
            (Some(peg), _) => json!({ "abovePeg": peg.0 }),
            (None, Some(layer)) => json!({ "aboveLayer": layer.0 }),
            (None, None) => return,
        };
        self.peg = self.run_for("peg.new", params).and_then(|made| made["id"].as_u64()).map(PegId).or(self.peg);
    }

    /// Add a peg that carries nothing yet, under the selected peg if there is one, and select it.
    fn new_peg(&mut self) {
        let Some(shot) = self.shot else { return };
        let params = json!({ "shot": shot.0, "parent": self.peg.map(|peg| peg.0) });
        self.peg = self.run_for("peg.new", params).and_then(|made| made["id"].as_u64()).map(PegId).or(self.peg);
    }

    /// The peg the keyframe commands work on, which is the Transform tool's.
    fn keyed_peg(&self) -> Option<&Peg> {
        self.shot()?.peg(self.target_peg()?)
    }

    /// The bones the keyframe commands work on in place of a peg: those that bend the layer
    /// in hand, while the Bones tool is in hand, or when there is no peg to key. It is their
    /// pose that is keyed.
    fn keyed_bones(&self) -> Option<&Deformer> {
        let shot = self.shot()?;
        let bones = shot.deformer(shot.layer(self.layer?)?.deformer?)?;
        (self.tools.tool == Tool::Bones || self.target_peg().is_none()).then_some(bones)
    }

    /// The shot whose camera the keyframe commands key, its peg and its lens together: where
    /// the peg they work on is the one that holds the camera, with the Camera tool or that
    /// peg selected.
    fn keyed_camera(&self) -> Option<&Shot> {
        let shot = self.shot()?;
        (self.keyed_bones().is_none() && shot.camera.parent.is_some() && self.target_peg() == shot.camera.parent).then_some(shot)
    }

    /// Whether the camera is in hand: the Camera tool, or the peg that holds the camera selected.
    fn camera_in_hand(&self) -> bool {
        self.shot().is_some_and(|shot| self.tools.tool == Tool::Camera || (self.peg_shown().is_some() && self.peg_shown() == shot.camera.parent))
    }

    /// The selected peg, while it is what is selected: not when another node is picked in its
    /// place, as an effect, a composite or a display is in the node view without changing it.
    fn peg_shown(&self) -> Option<PegId> {
        self.peg.filter(|peg| self.picked.is_empty() || self.picked.contains(&peg.0))
    }

    /// Put the open shot's camera in hand, from its row on the Storyboard timeline: the peg
    /// that moves it selected, made if it has none, and the Camera tool.
    fn select_camera(&mut self) {
        self.add_camera_peg();
        self.picked = self.peg.map(|peg| peg.0).into_iter().collect();
        self.released = None;
        self.take_tool(Tool::Camera);
    }

    /// The frames that what the keyframe commands work on has keyframes on: the bones' pose,
    /// the camera's peg and lens, or else the peg. `None` when there is none of them.
    pub(crate) fn keyed_frames(&self) -> Option<std::collections::BTreeSet<u32>> {
        if let Some(shot) = self.keyed_camera() {
            return Some(shot.camera_keys());
        }
        self.keyed_bones().map(Deformer::key_frames).or_else(|| self.keyed_peg().map(|peg| peg.animation.key_frames()))
    }

    /// Add a keyframe, or with `remove` take it away, on the current frame: of the camera, its
    /// peg and its lens in one step, or else of the peg or the bones' pose.
    fn add_key(&mut self, remove: bool) {
        if let Some(shot) = self.keyed_camera().map(|shot| shot.id) {
            return self.run("camera.setKey", json!({ "shot": shot.0, "frame": self.tools.frame, "withPeg": true, "remove": remove }));
        }
        self.key(if remove { "peg.removeKey" } else { "peg.setKey" }, json!({}));
    }

    /// The keyframes Key All adds on the current frame, as commands: of all that can be keyed
    /// in the tree of what is selected, the peg or layer in hand and the nodes and groups
    /// picked, with all that the pegs carry and the groups have in them; with nothing
    /// selected, of the whole shot. The pegs and the layers' bones are keyed, and of the
    /// effects those picked or already animated, so an effect left alone gets no keys.
    fn key_all_commands(&self) -> Vec<Value> {
        let Some(shot) = self.shot().filter(|_| self.page != Page::Storyboard) else { return Vec::new() };
        let roots: std::collections::BTreeSet<u64> =
            self.picked.iter().copied().chain(self.peg.map(|peg| peg.0)).chain(self.layer.map(|layer| layer.0)).collect();
        let marked = |id: u64| roots.contains(&id) || shot.groups_above(id).any(|group| roots.contains(&group.id.0));
        let under = |id: u64, parent: Option<PegId>| roots.is_empty() || marked(id) || shot.ancestors(parent).any(|peg| marked(peg.id.0));
        let frame = self.tools.frame;
        let mut commands: Vec<Value> = shot
            .pegs
            .iter()
            .filter(|peg| under(peg.id.0, peg.parent))
            .map(|peg| json!({ "id": "peg.setKey", "params": { "peg": peg.id.0, "frame": frame } }))
            .collect();
        let (mut bones, mut effects) = (std::collections::BTreeSet::new(), std::collections::BTreeSet::new());
        for layer in shot.layers.iter().filter(|layer| under(layer.id.0, layer.parent)) {
            bones.extend(layer.deformer.filter(|id| shot.deformer(*id).is_some()));
            effects.extend(timeline::effects_of(shot, layer.id).into_iter().filter(|effect| !effect.key_frames(None).is_empty()).map(|effect| effect.id));
        }
        bones.extend(shot.deformers.iter().map(|bones| bones.id).filter(|id| roots.contains(&id.0)));
        effects.extend(shot.effects.iter().map(|effect| effect.id).filter(|id| roots.contains(&id.0)));
        commands.extend(bones.into_iter().map(|bones| json!({ "id": "deformer.setKey", "params": { "deformer": bones.0, "frame": frame } })));
        commands.extend(effects.into_iter().map(|effect| json!({ "id": "effect.setKey", "params": { "effect": effect.0, "frame": frame } })));
        commands
    }

    /// Key, on the current frame, all that can be keyed in the tree of what is selected, as
    /// one step (see [`Self::key_all_commands`]).
    fn key_all(&mut self) {
        let commands = self.key_all_commands();
        if !commands.is_empty() {
            self.run("edit.batch", json!({ "commands": commands, "title": "Key All" }));
        }
    }

    /// Whether what the keyframe commands work on has a keyframe on the current frame.
    fn on_key(&self) -> bool {
        self.keyed_frames().is_some_and(|frames| frames.contains(&self.tools.frame))
    }

    /// Whether that peg's position has a keyframe on the current frame: a point of its path.
    /// A pose of bones has no path.
    fn on_path_key(&self) -> bool {
        self.keyed_bones().is_none() && self.keyed_peg().is_some_and(|peg| peg.animation.position.key(self.tools.frame).is_some())
    }

    /// Run a keyframe command on the current frame, plus `extra`: the peg's command that is
    /// named, or the same of the bones' pose where it is the bones that are keyed.
    fn key(&mut self, id: &str, extra: Value) {
        let bones = self.keyed_bones().map(|bones| bones.id).zip(id.strip_prefix("peg.").filter(|what| *what != "setBend"));
        if let Some((bones, what)) = bones {
            let mut params = json!({ "deformer": bones.0, "frame": self.tools.frame });
            if let (Some(params), Some(extra)) = (params.as_object_mut(), extra.as_object()) {
                params.extend(extra.clone());
            }
            return self.run(&format!("deformer.{what}"), params);
        }
        let Some(peg) = self.target_peg() else { return };
        let mut params = json!({ "peg": peg.0, "frame": self.tools.frame });
        if let (Some(params), Some(extra)) = (params.as_object_mut(), extra.as_object()) {
            params.extend(extra.clone());
        }
        self.run(id, params);
    }

    /// The commands that ease every keyframe picked on the Animation timeline as `ease` says,
    /// its `into`, its `out` or both: a peg's, a pose of bones' and an effect's alike. None
    /// where none is picked, or on the Storyboard page, which has keyframes of its own.
    fn picked_eases(&self, ease: &Value) -> Vec<Value> {
        use timeline::Keyed;
        if self.page == Page::Storyboard {
            return Vec::new();
        }
        let one = |(of, frame): &(Keyed, u32)| {
            let (id, mut params) = (format!("{}.setEase", of.kind()), of.params(json!({ "frame": frame })));
            for side in ["into", "out"] {
                if !ease[side].is_null() {
                    params[side] = ease[side].clone();
                }
            }
            json!({ "id": id, "params": params })
        };
        self.timeline.picked_keys.iter().map(one).collect()
    }

    /// There is a keyframe to ease: those that are picked, or the one the playhead is on.
    fn can_ease(&self) -> bool {
        self.on_key() || !self.picked_eases(&Value::Null).is_empty()
    }

    /// Ease the keyframes that are picked, all alike and as one step: they stay picked. With
    /// none picked it is the keyframe the playhead is on, and with one too where the playhead
    /// is on a keyframe, since the one that was clicked last may be far from where the
    /// playhead has gone since.
    /// Make the motion between the keyframes picked on the timeline held steps of `every`
    /// frames, as drawn animation on ones, twos or threes moves (`keys.step`).
    fn step_keys(&mut self, every: u32) {
        let (Some(shot), keys) = (self.shot, self.picked_keyframes()) else { return };
        self.run("keys.step", json!({ "shot": shot.0, "keys": keys, "every": every }));
    }

    /// There are keyframes picked to hold in steps.
    fn can_step(&self) -> bool {
        self.shot.is_some() && !self.picked_keyframes().is_empty()
    }

    /// The keyframes picked on the page's timeline, each with the cycle it is in, if any.
    fn picked_cycles(&self) -> Vec<(Value, Option<(u32, u32, iskra_model::CycleKind)>)> {
        let Some(shot) = self.shot() else { return Vec::new() };
        let cycle = |key: &Value| {
            let owner: iskra_model::KeyOwner = serde_json::from_value(key["owner"].clone()).ok()?;
            let value = key["value"].as_str();
            shot.cycle_of(owner, value.as_ref().map(std::slice::from_ref), key["frame"].as_u64()? as u32)
        };
        self.picked_keyframes().into_iter().map(|key| (cycle(&key), key)).map(|(cycle, key)| (key, cycle)).collect()
    }

    /// What *Keyframe Cycle* shows of the keyframes picked: it can cycle two or more of one
    /// thing, or change a cycle a picked one is in; the kind is shown where all are in cycles
    /// of one kind.
    fn picked_cycle(&self) -> bar::Cycled {
        let picked = self.picked_cycles();
        let mut kinds = picked.iter().map(|(_, cycle)| cycle.map(|(.., kind)| kind));
        let kind = kinds.next().flatten().filter(|first| kinds.all(|kind| kind == Some(*first)));
        let of = |key: &Value| (key["owner"].clone(), key["value"].clone());
        let two = picked.iter().any(|(key, _)| picked.iter().any(|(other, _)| of(other) == of(key) && other["frame"] != key["frame"]));
        bar::Cycled { can: two || picked.iter().any(|(_, cycle)| cycle.is_some()), kind }
    }

    /// Cycle the keyframes picked as `kind` says, or take their cycles away (`keys.cycle`).
    /// A picked keyframe of a cycle stands for the whole of it, so that one key picked
    /// changes how its cycle repeats.
    fn cycle_picked(&mut self, kind: Option<iskra_model::CycleKind>) {
        let Some(shot) = self.shot else { return };
        let mut keys = Vec::new();
        for (key, cycle) in self.picked_cycles() {
            if let Some((from, to, _)) = cycle {
                for frame in [from, to] {
                    let mut end = key.clone();
                    end["frame"] = json!(frame);
                    keys.push(end);
                }
            }
            keys.push(key);
        }
        self.run("keys.cycle", json!({ "shot": shot.0, "keys": keys, "kind": kind }));
    }

    fn ease(&mut self, ease: Value) {
        let all = self.picked_eases(&ease);
        if all.is_empty() || (all.len() == 1 && self.on_key()) {
            return self.key("peg.setEase", ease);
        }
        self.run("edit.batch", json!({ "commands": all, "title": "Set Keyframe Ease" }));
    }

    /// The keyframes the switch between held and animated works on: those picked on the
    /// timeline, or else the keyframe of the peg in hand that the playhead is on or past, which
    /// is the one the stretch under the playhead leaves from. With how each leaves: held or not.
    fn keys_to_switch(&self) -> Vec<(timeline::Keyed, u32, bool)> {
        use timeline::Keyed;
        let Some(shot) = self.shot() else { return Vec::new() };
        let before = || {
            let frame = *self.keyed_frames()?.range(..=self.tools.frame).next_back()?;
            let bones = self.keyed_bones().zip(self.layer).map(|(bones, layer)| Keyed::Bones(bones.id, layer, None));
            Some((bones.or_else(|| Some(Keyed::Peg(self.keyed_peg()?.id, None)))?, frame))
        };
        let keys = if self.timeline.picked_keys.is_empty() { before().into_iter().collect() } else { self.timeline.picked_keys.clone() };
        let eased = |of: Keyed, frame: u32| of.eases(shot, frame);
        keys.into_iter().filter_map(|(of, frame)| Some((of, frame, eased(of, frame)?.1 == Interp::Hold))).collect()
    }

    /// The boards of the shot that are locked as reference on the page that is shown: on the
    /// Animation page those whose lock is not open; none on the Storyboard page, where boards
    /// are what is drawn on.
    fn locked_boards(&self) -> std::collections::BTreeSet<LayerId> {
        let Some(shot) = self.shot().filter(|_| self.page != Page::Storyboard) else { return Default::default() };
        shot.layers.iter().map(|layer| layer.id).filter(|id| shot.is_board(*id) && !shot.unlocked.contains(id)).collect()
    }

    /// The layers that are not drawn on, picked in the viewport or given other drawings here:
    /// the boards that are locked, and on the Animation page those locked on their rows of
    /// the timeline, or by the row of what carries them or a group they are in.
    fn locked_layers(&self) -> std::collections::BTreeSet<LayerId> {
        let mut locked = self.locked_boards();
        if let Some(shot) = self.shot().filter(|_| self.page != Page::Storyboard) {
            locked.extend(shot.layers.iter().map(|layer| layer.id).filter(|id| shot.locks(*id)));
        }
        locked
    }

    /// Bring the selected node into sight: on the timeline, the pegs that carry it and the
    /// groups it is in are opened where they are folded, as one step, and the rows are
    /// scrolled to it; in the node view, the groups it is in are opened too, each fold apart,
    /// and its box is put in the middle.
    fn show_selected(&mut self) {
        let Some(shot) = self.shot() else { return };
        let Some(node) = self.peg.map(Node::Peg).or(self.layer.map(Node::Layer)) else { return };
        let id = match node {
            Node::Peg(peg) => peg.0,
            Node::Layer(layer) => layer.0,
        };
        let pegs = shot.ancestors(shot.parent_of(node)).filter(|peg| shot.folded.contains(&peg.id));
        let mut commands: Vec<Value> = pegs.map(|peg| json!({ "id": "peg.setFolded", "params": { "peg": peg.id.0, "folded": false } })).collect();
        for group in shot.groups_above(id) {
            let folds = [("folded", group.folded), ("rowsFolded", group.rows_folded)];
            for (fold, _) in folds.into_iter().filter(|(_, folded)| *folded) {
                commands.push(json!({ "id": "group.set", "params": { "group": group.id.0, fold: false } }));
            }
        }
        if !commands.is_empty() {
            self.run("edit.batch", json!({ "commands": commands, "title": "Show on the Timeline" }));
        }
        // Scrolled to again, as a row newly selected is.
        self.timeline.shown_selected = None;
        self.nodes.centre = Some(match node {
            Node::Peg(peg) => nodes::Item::Peg(peg),
            Node::Layer(layer) => nodes::Item::Layer(layer),
        });
    }

    /// Switch those keyframes between held and animated: all of them the way the first goes.
    fn switch_held(&mut self) {
        let keys = self.keys_to_switch();
        let Some(&(.., held)) = keys.first() else { return };
        let out = if held { "linear" } else { "hold" };
        let commands: Vec<Value> = keys
            .iter()
            .map(|(of, frame, _)| json!({ "id": format!("{}.setEase", of.kind()), "params": of.params(json!({ "frame": frame, "out": out })) }))
            .collect();
        self.run("edit.batch", json!({ "commands": commands, "title": if held { "Animate Keyframe" } else { "Hold Keyframe" } }));
    }

    /// Take into what a render burns in the guides and the aspect mask the viewer shows, which
    /// are what its *Guides* and *Aspect Mask* burn: they are chosen in the View menu.
    fn burn_what_is_shown(&mut self) {
        let burn = &mut self.export.settings.burn_in;
        burn.shown = prefs::Guide::ALL.map(|guide| self.prefs.guides.contains(&guide));
        let mut own =
            self.prefs.user_guides.iter().filter(|guide| guide.shown).map(|guide| iskra_export::burn::OwnGuide { kind: guide.kind, colour: guide.colour });
        burn.own = std::array::from_fn(|_| own.next());
        burn.aspect = self.prefs.aspect_mask;
        // In the colours the viewer shows them in.
        let own = |role| self.prefs.colours.get(&role).copied();
        burn.guide_colour = own(theme::Role::Guides).map_or(iskra_export::burn::GUIDE_COLOUR, |[r, g, b, _]| [r, g, b]);
        burn.mask_colour = own(theme::Role::Mask).unwrap_or([0, 0, 0, iskra_export::burn::MASK_ALPHA]);
    }

    /// Put the playhead on that peg's next keyframe, or its previous one.
    fn go_to_key(&mut self, forward: bool) {
        let Some(frames) = self.keyed_frames() else { return };
        let frame = self.tools.frame;
        let found = if forward { frames.range(frame + 1..).next() } else { frames.range(..frame).next_back() };
        if let Some(frame) = found.copied() {
            self.tools.frame = frame;
            self.film_frame = self.film_frame_of(frame).unwrap_or(self.film_frame);
            self.playing = None;
        }
    }

    fn delete_peg(&mut self) {
        if let Some(peg) = self.peg.take() {
            self.run("peg.delete", json!({ "peg": peg.0 }));
        }
    }

    fn new_storyboard(&mut self) {
        if let Some(made) = self.run_for("storyboard.new", json!({})) {
            self.storyboard = made["id"].as_u64().map(StoryboardId);
            self.page = Page::Storyboard;
        }
    }

    /// Add a shot to the storyboard and go into it, ready to draw (plan §7.2b): right after
    /// the shot that is being worked on and as long as it, with a board layer; after the last
    /// if no shot of the storyboard is in hand.
    fn new_shot(&mut self) {
        let Some(storyboard) = self.storyboard else { return };
        let params = match self.clip() {
            Some(clip) => json!({ "after": clip.shot.0, "boards": true, "ripple": self.switches.ripple }),
            None => json!({ "storyboard": storyboard.0, "boards": true }),
        };
        if let Some(shot) = self.run_for("shot.new", params).and_then(|made| made["id"].as_u64()) {
            self.set_shot(ShotId(shot));
            self.film_frame = self.film_frame_of(0).unwrap_or(self.film_frame);
        }
    }

    /// The film on the playhead's frame as a picture, where the storyboard's playhead is
    /// inside a transition (plan §7.2b): the two shots, mixed as the transition has them
    /// there. On the Storyboard page their boards on the paper; on the Export page what the
    /// export renders of them, through the pass picked in its bar, on the export's matte, as
    /// the storyboard's movie has it. While the film plays, and standing still or scrubbing
    /// too unless the View menu's switch says the shot in hand is to be seen alone. `None`
    /// anywhere else. It is made by the reference compositor at a size that can be made while
    /// playing, once for each frame of the film.
    fn mixed_picture(&mut self, ctx: &egui::Context) -> Option<egui::TextureId> {
        /// The widest a mixed picture is made, in pixels.
        const WIDEST: f64 = 640.0;
        let board = self.storyboard.and_then(|id| self.session.project().storyboards.iter().find(|board| board.id == id).cloned());
        let mixed = board.filter(|_| self.on_film() && (self.playing.is_some() || self.prefs.mix_at_rest)).and_then(|board| board.mixed_at(self.film_frame));
        let Some(mixed) = mixed else {
            // Out of the transition, what it needed in memory is let go.
            for shot in std::mem::take(&mut self.mixing) {
                if Some(shot) != self.shot && self.session.project().shot(shot).is_some() {
                    self.session.unload_shot(shot);
                }
            }
            return None;
        };
        let shots: Vec<ShotId> = [mixed.outgoing, mixed.incoming].into_iter().flatten().map(|(shot, _)| shot).collect();
        for shot in &shots {
            if self.session.project().shot(*shot).is_some_and(|shot| !shot.loaded) && self.session.load_shot(*shot).is_err() {
                return None;
            }
        }
        self.mixing = shots;
        let project = self.session.project().clone();
        let revision = |of: Option<(ShotId, u32)>| of.and_then(|(shot, _)| project.shot(shot)).map_or(0, |shot| shot.revision);
        // What of the shots is seen, and on what.
        let export = (self.page == Page::Export).then_some(&self.export.settings);
        let (work, pass) = match export {
            Some(settings) => (settings.work, self.export_pass.as_deref()),
            None => (Work::Boards, None),
        };
        let seen = format!("{work:?} {pass:?} {:?}", export.map(|settings| (settings.alpha, settings.matte)));
        let of = (revision(mixed.outgoing), revision(mixed.incoming), project.look, seen);
        if let Some((_, texture)) = self.mixes.get(&self.film_frame).filter(|(kept, _)| *kept == of) {
            return Some(texture.id());
        }
        let space = project.settings.working_space;
        let view = iskra_render::View::frame(&project.settings, (WIDEST / f64::from(project.settings.width.max(1))).min(1.0));
        // Each shot on its paper, or the export's matte, before it is mixed.
        let on_paper = |of: Option<(ShotId, u32)>| {
            let (shot, frame) = of?;
            let part = project.shot(shot)?.only(work);
            let part = pass.and_then(|pass| part.seen_as_pass(pass)).unwrap_or(part);
            let picture = iskra_render::composite(&part, &project.palette, space, frame, &view);
            Some(match export {
                Some(settings) => iskra_export::on_matte(&picture, space, settings),
                None => picture.into_iter().map(|[r, g, b, a]| [r + 1.0 - a, g + 1.0 - a, b + 1.0 - a, 1.0]).collect(),
            })
        };
        let (outgoing, incoming) = (on_paper(mixed.outgoing), on_paper(mixed.incoming));
        let pixels = view.width as usize * view.height as usize;
        let together = iskra_render::mix(mixed.kind, mixed.at, outgoing.as_deref(), incoming.as_deref(), pixels);
        let picture = iskra_render::finish(view.width, view.height, &together, space);
        let bytes: Vec<u8> = picture.pixels.iter().flatten().copied().collect();
        let image = egui::ColorImage::from_rgba_unmultiplied([picture.width as usize, picture.height as usize], &bytes);
        // Not more than a few transitions' worth of pictures are kept.
        if self.mixes.len() > 240 {
            self.mixes.clear();
        }
        let texture = ctx.load_texture("mixed", image, egui::TextureOptions::LINEAR);
        let id = texture.id();
        self.mixes.insert(self.film_frame, (of, texture));
        Some(id)
    }

    /// A new layer on top of the shot's others, which is then the one drawn on: of vector art,
    /// of pixels, or with `None` of the kind the layer in hand is.
    /// A new layer of the kind `kind` (`bitmap`, `vector` or `text`), or of the default kind.
    fn new_layer(&mut self, kind: Option<&str>) {
        let mut params = json!({ "shot": self.shot.map(|shot| shot.0) });
        if let Some(kind) = kind {
            params["kind"] = json!(kind);
        }
        if let Some(layer) = self.run_for("layer.new", params).and_then(|made| made["id"].as_u64()) {
            (self.layer, self.peg) = (Some(LayerId(layer)), None);
        }
    }

    /// Write what is spoken under the open storyboard's shots into their panels' dialogue,
    /// from the transcripts of the sounds there. What is written already is kept.
    fn fill_dialogue(&mut self) {
        let Some(storyboard) = self.storyboard else { return };
        if let Some(done) = self.run_for("storyboard.fillDialogue", json!({ "storyboard": storyboard.0 })) {
            let (filled, kept) = (done["filled"].as_u64().unwrap_or(0), done["kept"].as_u64().unwrap_or(0));
            // Not an error, but it is said where errors are: what was done is not seen at a glance.
            self.error = (kept > 0).then(|| format!("{filled} panels were given their dialogue; {kept} keep what was written in them already"));
        }
    }

    /// Whether there is a timeline to put a marker or an in or out point on: the film's on
    /// the Storyboard page, the shot's own elsewhere.
    fn has_timeline(&self) -> bool {
        if self.page == Page::Storyboard { self.storyboard.is_some() } else { self.shot.is_some() }
    }

    /// Run the command `what` of that timeline, the open storyboard's or the shot's, with
    /// `params`.
    fn on_timeline(&mut self, what: &str, mut params: Value) {
        let of = if self.page == Page::Storyboard { self.storyboard.map(|id| ("storyboard", id.0)) } else { self.shot.map(|id| ("shot", id.0)) };
        if let Some((kind, id)) = of {
            params[kind] = json!(id);
            self.run(&format!("{kind}.{what}"), params);
        }
    }

    /// Put the playhead on the next marker of that timeline, the open storyboard's or the
    /// shot's, or on the one before: the nearest after the playhead's frame, or before it.
    /// Where there is none that way, the playhead stays.
    fn go_to_marker(&mut self, next: bool) {
        let project = self.session.project().clone();
        let frames: Vec<u32> = if self.page == Page::Storyboard {
            self.storyboard.and_then(|id| project.storyboard(id)).map(|board| board.markers.iter().map(|marker| marker.frame).collect())
        } else {
            self.shot().map(|shot| shot.markers.iter().map(|marker| marker.frame).collect())
        }
        .unwrap_or_default();
        let at = self.playhead();
        let to = if next { frames.iter().copied().filter(|frame| *frame > at).min() } else { frames.iter().copied().filter(|frame| *frame < at).max() };
        if let Some(frame) = to {
            self.set_playhead(frame);
            self.playing = None;
        }
    }

    /// Run a command of that timeline with the playhead's frame under the name `key`.
    fn at_playhead(&mut self, what: &str, key: &str) {
        self.on_timeline(what, json!({ key: self.playhead() }));
    }

    /// Split the shot under the playhead in two at the playhead's frame.
    fn split_shot(&mut self) {
        if let Some(shot) = self.shot.filter(|_| !self.in_gap) {
            self.run("shot.split", json!({ "shot": shot.0, "frame": self.tools.frame }));
        }
    }

    /// Merge the shot that is being worked on with the one that follows it on the storyboard.
    /// With several shots picked, the first of them and every picked one that follows it with
    /// no gap are merged into one, in one step.
    fn merge_shot(&mut self) {
        let Some(clip) = self.clip() else { return };
        let project = self.session.project().clone();
        let Some(board) = self.storyboard.and_then(|id| project.storyboard(id)) else { return };
        let picked = self.storyboard_view.picked_shots.clone();
        let several = picked.len() > 1;
        let next_of = |clip: &iskra_model::Clip| board.clips().iter().find(|other| other.start == clip.end()).copied();
        let first = board.clips().iter().find(|clip| several && picked.contains(&clip.shot)).copied().unwrap_or(clip);
        let mut merged = vec![first];
        while let Some(next) = merged.last().and_then(next_of) {
            if several && !picked.contains(&next.shot) {
                break;
            }
            merged.push(next);
            if !several {
                break;
            }
        }
        // The others' drawings have to be in memory to come over.
        for clip in &merged {
            if let Err(problem) = self.session.load_shot(clip.shot) {
                self.error = Some(problem.to_string());
                return;
            }
        }
        let commands: Vec<Value> = merged.iter().skip(1).map(|_| json!({ "id": "shot.merge", "params": { "shot": first.shot.0 } })).collect();
        match commands.len() {
            0 | 1 => self.run("shot.merge", json!({ "shot": first.shot.0 })),
            _ => self.run("edit.batch", json!({ "commands": commands, "title": "Merge Shots" })),
        }
    }

    /// Move the shot that is being worked on before the one before it on the storyboard, or
    /// after the one after it: the two change places, and a gap between them stays.
    fn move_shot(&mut self, later: bool) {
        let Some(clip) = self.clip() else { return };
        let project = self.session.project().clone();
        let Some(board) = self.storyboard.and_then(|id| project.storyboard(id)) else { return };
        let Some(at) = board.clips().iter().position(|other| other.shot == clip.shot) else { return };
        let place = if later { at + 1 } else { at.saturating_sub(1) };
        self.reorder_shot(clip.shot, place, if later { "Move Shot Later" } else { "Move Shot Earlier" });
    }

    /// Put `shot` at `place` among the storyboard's shots, as [`boards::reorder`] does, in one
    /// step called `title`.
    fn reorder_shot(&mut self, shot: ShotId, place: usize, title: &str) {
        let project = self.session.project().clone();
        let Some(board) = self.storyboard.and_then(|id| project.storyboard(id)) else { return };
        let Some((commands, starts)) = boards::reorder(board, shot, place) else { return };
        let open = self.clip();
        self.run("edit.batch", json!({ "commands": commands, "title": title }));
        // The playhead stays on the same frame of the shot that is open, if that moved.
        if let Some(clip) = open
            && let Some((_, start)) = starts.iter().find(|(moved, _)| *moved == clip.shot)
        {
            self.film_frame = start + self.tools.frame.saturating_sub(clip.in_point);
        }
    }

    /// A panel at the playhead, with a new empty drawing on each of the shot's board layers
    /// held until the next panel, to draw it on: one step.
    fn new_panel(&mut self) {
        let Some(shot) = self.shot().filter(|_| !self.in_gap).cloned() else { return };
        let frame = self.tools.frame;
        let next = shot.panels().iter().map(|panel| panel.frame).find(|start| *start > frame).unwrap_or(shot.duration);
        let mut commands = vec![json!({ "id": "panel.add", "params": { "shot": shot.id.0, "frame": frame } })];
        let boards = shot.layers.iter().filter(|layer| shot.is_board(layer.id));
        commands.extend(
            boards.map(
                |layer| json!({ "id": "drawing.newDrawing", "params": { "layer": layer.id.0, "frame": frame, "hold": next.saturating_sub(frame).max(1) } }),
            ),
        );
        self.run("edit.batch", json!({ "commands": commands, "title": "New Panel" }));
    }

    fn duplicate_shot(&mut self) {
        let Some(shot) = self.shot else { return };
        let params = json!({ "shot": shot.0, "ripple": self.switches.ripple });
        if let Some(copy) = self.run_for("shot.duplicate", params).and_then(|made| made["id"].as_u64()) {
            self.set_shot(ShotId(copy));
        }
    }

    fn delete_shot(&mut self) {
        if let Some(shot) = self.shot {
            self.run("shot.delete", json!({ "shot": shot.0 }));
        }
    }

    /// Carry out what was asked for in the project bin or on the storyboard timeline.
    fn item_actions(&mut self, ctx: &egui::Context, actions: Vec<items::Action>) {
        let ctx = ctx.clone();
        for action in actions {
            match action {
                items::Action::SelectShot(shot) => self.set_shot(shot),
                items::Action::Seek(frame) => {
                    self.film_frame = frame;
                    self.playing = None;
                    // Elsewhere than on the Storyboard page, whose playhead is of the film, it
                    // is the shot under that frame of the film that is opened, on that frame.
                    let project = self.session.project().clone();
                    let under = self
                        .storyboard
                        .and_then(|id| project.storyboard(id))
                        .and_then(|board| board.clips().iter().find(|c| (c.start..c.end()).contains(&frame)).copied());
                    if let (true, Some(clip)) = (self.page != Page::Storyboard, under) {
                        self.set_shot(clip.shot);
                        (self.tools.frame, self.film_frame) = (clip.in_point + frame - clip.start, frame);
                    }
                }
                items::Action::SelectLayer(layer) => {
                    // A board taken in hand puts the Camera tool down, as another node does in
                    // the node view.
                    if self.tools.tool == Tool::Camera {
                        self.tools.tool = self.before_camera.take().unwrap_or(Tool::Transform);
                    }
                    (self.layer, self.peg) = (Some(layer), None);
                    // Properties shows the board, not the shots that were picked.
                    self.storyboard_view.picked_shots.clear();
                }
                items::Action::SelectCamera => self.select_camera(),
                // The razor's cut: the shot is in memory first, as a split needs.
                items::Action::Split(shot, frame) => match self.session.load_shot(shot) {
                    Ok(_) => self.run("shot.split", json!({ "shot": shot.0, "frame": frame })),
                    Err(problem) => self.error = Some(problem.to_string()),
                },
                items::Action::Bar(asked) => self.answer_bar(&ctx, asked),
                items::Action::Command(id) => {
                    if let Some(command) = commands::command(id).filter(|command| (command.enabled)(self)) {
                        (command.run)(self, &ctx);
                    }
                }
                items::Action::OpenShot(shot) => {
                    self.set_shot(shot);
                    self.page = Page::Animation;
                }
                items::Action::Reorder(shot, place) => self.reorder_shot(shot, place, "Move Shot"),
                items::Action::OpenStoryboard(storyboard) => {
                    self.storyboard = Some(storyboard);
                    self.page = Page::Storyboard;
                }
                items::Action::Drag(dragged) => self.item_drag = Some(dragged),
                items::Action::Place(media) => self.place_media(media),
                items::Action::Listen(media) => self.listen(media),
                items::Action::Relink(media) => {
                    let sound = self.session.project().media(media).is_some_and(|media| matches!(media.kind, iskra_model::MediaKind::Sound { .. }));
                    if let Some(path) = dialogs::relink_media(sound) {
                        self.run("media.relink", json!({ "media": media.0, "path": path }));
                    }
                }
                items::Action::Record(play) => self.start_recording(&ctx, play),
                items::Action::StopRecording => self.stop_recording(),
                items::Action::Transcript(media) => {
                    if let Some(path) = dialogs::import_transcript() {
                        self.run("media.setTranscript", json!({ "media": media.0, "path": path }));
                    }
                }
                items::Action::SendOut(shots) => self.ask_send_out(shots),
                items::Action::RenameShots(shots) => self.renaming_shots = Some(shots),
                items::Action::BringBack(shot) => self.ask_bring_back(shot),
                // A shot made or copied here becomes the current one.
                items::Action::Run(id, params) => {
                    let all = self.for_all_picked(id, &params);
                    if !all.is_empty() {
                        self.run_several(all);
                        continue;
                    }
                    // A shot deleted from the pool may not be loaded, and undo wants its drawings.
                    let unloaded = params["shot"].as_u64().map(ShotId).filter(|shot| self.session.project().shot(*shot).is_some_and(|shot| !shot.loaded));
                    if let (true, Some(shot)) = (id == "shot.delete", unloaded) {
                        self.run("shot.load", json!({ "shot": shot.0 }));
                    }
                    let on_storyboard = !params["storyboard"].is_null() || !params["after"].is_null() || id == "shot.duplicate";
                    let made = self.run_for(id, params).and_then(|made| made["id"].as_u64());
                    if let (true, Some(shot)) = (on_storyboard && id.starts_with("shot."), made) {
                        self.set_shot(ShotId(shot));
                    } else if let (true, Some(layer)) = (id == "layer.new", made) {
                        (self.layer, self.peg) = (Some(LayerId(layer)), None);
                    }
                    // A shot that was moved or trimmed keeps the playhead on the frame it was on.
                    if id.starts_with("storyboard.") && !self.in_gap {
                        self.film_frame = self.film_frame_of(self.tools.frame).unwrap_or(self.film_frame);
                    }
                }
            }
        }
    }

    /// Draw one frame of the whole window.
    pub fn ui(&mut self, ui: &mut egui::Ui) {
        timings::set(self.prefs.log_timings, &self.log);
        let began = std::time::Instant::now();
        self.frame_ui(ui);
        timings::frame(began, || self.timings_state());
    }

    /// What the project and the window hold, for the timings in the log: what grows as the
    /// work does.
    fn timings_state(&self) -> String {
        let project = self.session.project();
        let shots = project.shots.iter();
        let layers: usize = shots.clone().map(|shot| shot.layers.len()).sum();
        let drawings: usize = shots.flat_map(|shot| &shot.layers).map(|layer| layer.drawings.len()).sum();
        let mut system = sysinfo::System::new();
        let memory = sysinfo::get_current_pid().ok().and_then(|pid| {
            system.refresh_processes(sysinfo::ProcessesToUpdate::Some(&[pid]), false);
            system.process(pid).map(|process| process.memory())
        });
        format!(
            "{} shots, {layers} layers, {drawings} drawings, {} undo steps, {} tile textures kept, {}",
            project.shots.len(),
            self.session.history().entries().len(),
            self.viewport.tiles_kept(),
            memory.map_or("the memory used unknown".to_string(), |bytes| format!("{} MB of memory used", bytes / 1_000_000)),
        )
    }

    fn frame_ui(&mut self, ui: &mut egui::Ui) {
        // The typefaces installed on the first frame are only there from the next: the start
        // window, the first thing drawn, waits for them, as its heading is in one of them.
        let first = self.styled.is_none();
        self.style(ui.ctx());
        if first && self.start.is_some() {
            ui.ctx().request_repaint();
            return;
        }
        if self.start_window(ui) {
            return;
        }
        ui.input(|i| {
            self.stylus.update(&i.events);
            if self.prefs.log_strokes {
                self.pen_log.watch(&self.log, &i.events, self.stylus.sample());
            }
        });
        self.keep_current();
        // A take that could not be heard is over, and why is said.
        if let Some(problem) = self.recorder.problem() {
            (self.recording_from, self.error) = (None, Some(problem));
        }
        if self.recording_from.is_some() {
            ui.ctx().request_repaint();
        }
        self.hold_panels(ui);
        self.play(ui);
        self.tally_playback(ui);
        self.follow_playhead();
        self.load_shot();
        self.housekeeping(ui);
        self.tools.frame = self.tools.frame.min(self.shot().map_or(0, |s| s.duration.saturating_sub(1)));
        self.shortcuts(ui.ctx());

        // A frame made for the playback cache that kept the window waiting is said in the
        // log, the slowest of a few seconds at a time, so that it can be told from other waits.
        let now = ui.input(|i| i.time);
        self.slow_cache = match (self.slow_cache, self.viewport.cache_took.take().filter(|took| *took >= SLOW_CACHE)) {
            (None, Some(took)) => Some((now, took)),
            (Some((since, slowest)), took) => Some((since, slowest.max(took.unwrap_or(0.0)))),
            (None, None) => None,
        };
        if let Some((_, slowest)) = self.slow_cache.take_if(|(since, _)| now - *since >= 3.0) {
            self.log.say(format!("playback cache: a frame took {:.0} ms to make, and the window waited that long", slowest * 1000.0));
        }
        // The menus read from the disk only now and then.
        let listed_at = ui.input(|i| i.time);
        let keymaps = self.keymaps_folder();
        self.listed.refresh(listed_at, &self.prefs.recent_files, keymaps.as_deref());
        // Where the system has the app's menus in a bar of its own, the window has none.
        if !self.system_menus {
            egui::Panel::top("menu").show(ui, |ui| egui::MenuBar::new().ui(ui, |ui| self.menus(ui)));
        }
        egui::Panel::bottom("pages").show(ui, |ui| self.page_bar(ui));
        if self.page.draws() {
            if self.options_bar {
                egui::Panel::top("options").show(ui, |ui| self.tool_options(ui));
            }
            egui::Panel::left("tools").resizable(false).exact_size(46.0).show(ui, |ui| self.tools_strip(ui));
        }
        self.viewport.look_only = self.page == Page::Export;
        if self.page == Page::Export {
            self.export_page(ui);
        } else {
            let gaps = Theme::of(ui.ctx()).border;
            egui::CentralPanel::default().frame(egui::Frame::NONE.fill(gaps)).show(ui, |ui| self.dock(ui));
        }
        self.detached_windows(ui.ctx());
        self.workspace_name(ui.ctx());
        self.about(ui.ctx());
        self.print_window(ui.ctx());
        self.trace_window(ui.ctx());
        self.rename_shots_window(ui.ctx());
        self.rig_window(ui.ctx());
        self.day_skin_window(ui.ctx());
        self.skins_window(ui.ctx());
        self.rig_progress(ui.ctx());
        self.settings_window(ui.ctx());
        self.template_window(ui.ctx());
        self.apply_window(ui.ctx());
        self.send_out_window(ui.ctx());
        self.bring_back_window(ui.ctx());
        self.brush_report_window(ui.ctx());
        self.brush_reading_window(ui.ctx());
        self.guides_window(ui.ctx());
        // Files let go on the window.
        let dropped: Vec<std::path::PathBuf> =
            ui.input(|i| i.raw.dropped_files.iter().map(|file| file.path().to_path_buf()).filter(|path| !path.as_os_str().is_empty()).collect());
        if !dropped.is_empty() {
            self.files_dropped(&dropped);
        }
        self.script_dialog_window(ui.ctx());
        let mut palette = std::mem::take(&mut self.palette);
        let chosen = palette.show(ui.ctx(), self);
        self.palette = palette;
        match chosen {
            Some(commands::Picked::Command(command)) => (command.run)(self, ui.ctx()),
            Some(commands::Picked::Script(id)) => self.run_script_command(id),
            Some(commands::Picked::Brush(group, name)) => self.take_brush(&group, &name),
            None => {}
        }
        // What the status bar says of a problem, the log says too, once.
        if self.error != self.logged_error {
            if let Some(problem) = &self.error {
                self.log.say(problem.as_str());
            }
            self.logged_error = self.error.clone();
        }
    }

    /// Start playing from the current frame, or stop on it.
    fn toggle_play(&mut self, ctx: &egui::Context) {
        // Outside the stretch that plays, the film starts from its in point.
        if self.playing.is_none() && self.on_film() {
            let played = self.storyboard.and_then(|id| self.session.project().storyboard(id).map(|board| self.film_played(board)));
            if let Some((first, after)) = played.filter(|(first, after)| !(*first..*after).contains(&self.film_frame)) {
                self.film_frame = first.min(after.saturating_sub(1));
            }
        } else if self.playing.is_none()
            && let Some((first, after)) = self.shot().map(Shot::played).filter(|(first, after)| !(*first..*after).contains(&self.tools.frame))
        {
            // And so does a shot from its own.
            self.tools.frame = first.min(after.saturating_sub(1));
        }
        self.playing = match self.playing {
            Some(_) => None,
            None => Some((ctx.input(|i| i.time), self.playhead())),
        };
        self.sound_waits = false;
        if self.playing.is_some() {
            self.start_sound(self.playhead());
        }
    }

    /// The storyboard whose sound is heard: the one the Storyboard page shows, or elsewhere
    /// the one the shot that is worked on lies on.
    fn sounding_board(&self) -> Option<std::sync::Arc<iskra_model::Storyboard>> {
        let project = self.session.project();
        let on = match self.on_film() {
            true => self.storyboard,
            false => self.shot.and_then(|shot| project.storyboard_of(shot)).map(|board| board.id),
        };
        project.storyboards.iter().find(|board| Some(board.id) == on).cloned()
    }

    /// When in the film, in seconds, a frame of this page's playhead is: on the Storyboard
    /// page it is a frame of the film; elsewhere a frame of the shot, which the shot's clip
    /// places in the film. `None` for a shot that is on no storyboard, which has no sound.
    fn film_time(&self, frame: u32) -> Option<f64> {
        let project = self.session.project();
        let fps = project.settings.frame_rate.as_f64();
        if self.on_film() {
            return Some(f64::from(frame) / fps);
        }
        let clip = *project.storyboard_of(self.shot?)?.clip(self.shot?)?;
        Some((f64::from(clip.start) + f64::from(frame) - f64::from(clip.in_point)) / fps)
    }

    /// Whether playing goes round again at the end: the Export page has a Loop of its own, the
    /// other pages the timelines'.
    fn looping(&self) -> bool {
        if self.page == Page::Export { self.export_looping } else { self.switches.looping }
    }

    /// The stretch of the film that plays, its first frame and the one after its last: on
    /// the Storyboard page between its in and out points, if it has them; on the Export page
    /// all of it, as it is rendered.
    fn film_played(&self, board: &iskra_model::Storyboard) -> (u32, u32) {
        match self.page {
            Page::Export => (0, board.end().max(1)),
            _ => board.played(),
        }
    }

    /// Put the playhead on the first frame of the shot before or after the one it is on, in
    /// the film's cut; playing, the film plays on from there.
    fn step_shot(&mut self, ctx: &egui::Context, later: bool) {
        let Some(board) = self.storyboard.and_then(|id| self.session.project().storyboard(id).cloned()) else { return };
        let starts: Vec<u32> = board.clips().iter().map(|clip| clip.start).collect();
        let at = self.film_frame;
        let to = if later { starts.iter().copied().find(|start| *start > at) } else { starts.iter().copied().rev().find(|start| *start < at) };
        let Some(to) = to else { return };
        let playing = self.playing.is_some();
        if playing {
            self.toggle_play(ctx);
        }
        self.film_frame = to;
        self.follow_playhead();
        if playing {
            self.toggle_play(ctx);
        }
    }

    /// Start the sound with the picture, from a frame of this page's playhead.
    fn start_sound(&mut self, frame: u32) {
        self.listening = None;
        self.sync_sound(false);
        match self.film_time(frame).filter(|_| self.sounding) {
            Some(from) => {
                self.player.play(from);
                self.sound_from = Some(from);
            }
            None => {
                self.player.stop();
                self.sound_from = None;
            }
        }
    }

    /// The sound a shot hears, for its timeline: a row for each sound track of its storyboard
    /// that has sound under the shot, with what a waveform draws on each of the shot's frames.
    fn shot_sound(&mut self, shot: &Shot) -> Vec<timeline::SoundRow> {
        let project = self.session.project().clone();
        let Some((board, clip)) = project.storyboard_of(shot.id).and_then(|board| Some((board, *board.clip(shot.id)?))) else { return Vec::new() };
        let folder = self.session.path().and_then(|file| file.parent()).map(std::path::Path::to_path_buf);
        let frame = 1.0 / project.settings.frame_rate.as_f64();
        // The frame of the film that a frame of the shot is, if the film has got that far.
        let film = |at: u32| (i64::from(clip.start) + i64::from(at) - i64::from(clip.in_point)).try_into().ok();
        let mut rows = Vec::new();
        for (index, track) in board.sound.iter().enumerate() {
            let (mut peaks, mut clips) = (vec![None; shot.duration as usize], Vec::new());
            for sound in &track.clips {
                // Under the shot, it is among those whose volume the row's menu sets.
                let (first, after) = (film(0).unwrap_or(0), film(shot.duration).unwrap_or(0));
                if sound.start < after && sound.end() > first {
                    clips.push((sound.id.0, project.media(sound.media).map_or("?".to_string(), |media| media.name.clone()), sound.gain));
                }
                let Some(wave) = project.media(sound.media).and_then(|media| self.sounds.peaks(media, folder.as_deref(), frame)) else { continue };
                for (at, peak) in peaks.iter_mut().enumerate() {
                    let Some(on): Option<u32> = film(at as u32) else { continue };
                    if on >= sound.start && on < sound.end() {
                        *peak = wave.get((sound.offset + on - sound.start) as usize).map(|[low, high]| [low * sound.gain.min(1.0), high * sound.gain.min(1.0)]);
                    }
                }
            }
            if peaks.iter().any(Option::is_some) {
                rows.push(timeline::SoundRow { name: track.name.clone(), storyboard: board.id.0, track: index, mute: track.mute, clips, peaks });
            }
        }
        rows
    }

    /// Keep the player in step with the app: it has the clips of the storyboard that is
    /// heard here, it is silent when nothing plays, and a playhead that is dragged lets what is
    /// under it be heard for a moment. `dragging` says whether the pointer is held down: a
    /// playhead that jumps, by a click, a key or a change of page, is not heard.
    fn sync_sound(&mut self, dragging: bool) {
        if self.listening.is_some() {
            return;
        }
        let project = self.session.project().clone();
        let board = self.sounding_board();
        // The Export page's Mute is heard on that page alone.
        let volume = if self.muted && self.page == Page::Export { 0.0 } else { project.settings.volume };
        let same = volume == self.heard_volume
            && match (&self.heard, &board) {
                (Some((heard, media)), Some(board)) => std::sync::Arc::ptr_eq(heard, board) && *media == project.media,
                (None, None) => true,
                _ => false,
            };
        if !same {
            let (folder, fps) = (self.session.path().and_then(|file| file.parent()).map(std::path::Path::to_path_buf), project.settings.frame_rate.as_f64());
            let mut clips = Vec::new();
            for track in board.iter().flat_map(|board| &board.sound).filter(|track| !track.mute) {
                for clip in &track.clips {
                    let Some(sound) = project.media(clip.media).and_then(|media| self.sounds.get(media, folder.as_deref())) else { continue };
                    let seconds = |frames: u32| f64::from(frames) / fps;
                    clips.push(iskra_audio::Clip {
                        sound,
                        start: seconds(clip.start),
                        offset: seconds(clip.offset),
                        length: seconds(clip.length),
                        gain: clip.gain * volume,
                    });
                }
            }
            self.player.set_clips(clips);
            self.heard = board.map(|board| (board, project.media.clone()));
            self.heard_volume = volume;
        }
        if self.playing.is_none() {
            self.sound_from = None;
            if self.player.position().is_some() {
                self.player.stop();
            }
            // A playhead that is dragged along: what is under it is heard for a moment. Coming
            // to another page, or jumping to a frame, is silent.
            let now = (self.page, self.playhead());
            if dragging
                && self.heard_frame.is_some_and(|heard| heard.0 == now.0 && heard.1 != now.1)
                && self.sounding
                && let Some(at) = self.film_time(now.1)
            {
                self.player.scrub(at);
            }
            self.heard_frame = Some(now);
        } else {
            self.heard_frame = None;
        }
    }

    /// Hold what the bars and Properties show while the shot plays, or while a press moves the
    /// playhead: at the frame from before, until playing stops and the button is let go.
    fn hold_panels(&mut self, ui: &egui::Ui) {
        let now = (self.playhead(), self.tools.frame);
        let (pressed, down) = ui.input(|i| (i.pointer.any_pressed(), i.pointer.any_down()));
        if pressed {
            self.pressed_at = Some(now);
        }
        if !down {
            self.pressed_at = None;
        }
        // The frame of the shot that is seen has to change: a shot moved or trimmed on the
        // storyboard timeline takes the film's playhead along, on the same frame of the shot,
        // and that holds nothing.
        let dragged = self.pressed_at.filter(|at| at.1 != now.1);
        self.held = match (self.playing.is_some(), dragged) {
            (false, None) => None,
            (true, _) => self.held.or(dragged).or(Some(now)),
            (false, Some(at)) => self.held.or(Some(at)),
        };
        // Let go, the panels show the frame it stopped on, without waiting for another event.
        if self.held.is_none() && self.was_held {
            ui.ctx().request_repaint();
        }
        self.was_held = self.held.is_some();
    }

    /// The shot's frame that Properties and the bars show: the playhead's, but while it plays
    /// or is dragged the one it was on before.
    fn panel_frame(&self) -> u32 {
        self.held.map_or(self.tools.frame, |(_, frame)| frame)
    }

    /// While playing, show the frame the clock says; or, playing every frame, the next one
    /// where the picture is behind, so that none is skipped.
    fn play(&mut self, ui: &egui::Ui) {
        let Some((started, from)) = self.playing else { return };
        let project = self.session.project().clone();
        // On the Storyboard page it is the film that plays, from shot to shot: the stretch
        // between its in and out points, if it has them, else all of it.
        let (first, after) = match self.on_film() {
            true => self.storyboard.and_then(|id| project.storyboard(id)).map_or((0, 1), |board| self.film_played(board)),
            false => self.shot().map_or((0, 1), Shot::played),
        };
        let duration = after - first;
        // With sound playing, the picture follows the sound's clock: what is seen is what is heard.
        let now = ui.input(|i| i.time);
        let elapsed = match (self.sound_from, self.player.position()) {
            (Some(from), Some(heard)) => heard - from,
            _ => now - started,
        };
        // Within the stretch, frames are counted from its first.
        let looping = self.looping();
        let mut within = playback_frame(from.saturating_sub(first), elapsed, project.settings.frame_rate.as_f64(), duration, looping);
        // Playing every frame, a picture that is behind its time goes on to the next frame
        // alone, and the clock starts again from there: the playhead waits for a frame that
        // is slow to make. The sound can't wait: it stops while the picture is behind, and
        // goes on from the frame that is seen once the picture keeps time again.
        let shown = self.playhead().checked_sub(first).filter(|shown| *shown < duration);
        if let (true, Some(target), Some(shown)) = (self.prefs.play_every_frame, within, shown) {
            // With sound heard, its clock goes on in steps as the sound card asks for more: the
            // picture is behind only when it is more than a quarter of a second late.
            let late = if self.sound_from.is_some() { (project.settings.frame_rate.as_f64() / 4.0).ceil() as u32 } else { 1 };
            let behind = (target + duration - shown) % duration > late;
            if behind {
                let next = shown + 1;
                within = if next < duration {
                    Some(next)
                } else if looping {
                    Some(0)
                } else {
                    None
                };
                if let Some(next) = within {
                    self.playing = Some((now, next + first));
                }
                if self.sound_from.is_some() {
                    self.player.stop();
                    (self.sound_from, self.sound_waits) = (None, true);
                }
            } else if std::mem::take(&mut self.sound_waits) {
                self.start_sound(target + first);
            }
        }
        match within.map(|frame| frame + first) {
            Some(frame) => {
                // Round the loop, the sound starts again with the picture.
                if frame < self.playhead() && self.sound_from.is_some() {
                    self.playing = Some((now, frame));
                    self.start_sound(frame);
                }
                self.set_playhead(frame);
                ui.ctx().request_repaint();
            }
            None => {
                self.set_playhead(after.saturating_sub(1));
                self.playing = None;
            }
        }
    }

    /// Keep count of how the playback goes, and say it in the log when it stops.
    fn tally_playback(&mut self, ui: &egui::Ui) {
        let now = ui.input(|i| i.time);
        let playhead = self.playhead();
        match (&mut self.played, self.playing.is_some()) {
            (Some(played), true) => played.frame(now, playhead),
            (None, true) => self.played = Some(log::Playback::new(now, playhead, self.prefs.viewport_on_card)),
            (Some(_), false) => {
                let what = match self.on_film() {
                    true => self.storyboard.and_then(|id| self.session.project().storyboard(id)).map(|board| format!("the storyboard `{}`", board.name)),
                    false => self.shot().map(|shot| format!("`{}`", shot.name)),
                };
                let rate = self.session.project().settings.frame_rate.as_f64();
                if let Some(said) = self.played.take().and_then(|played| played.said(what.as_deref().unwrap_or("the shot"), rate)) {
                    self.log.say(said);
                }
            }
            (None, false) => {}
        }
    }

    /// Cut or copy the selection. The system clipboard gets a line of text as well: without
    /// any text on it, the system's paste shortcut would not reach the app.
    fn copy(&mut self, ctx: &egui::Context, id: &str) {
        if self.viewport.selection.is_some() {
            self.on_selection(id);
            (self.copied_frames, self.copied_nodes, self.copied_keys) = (None, false, None);
            ctx.copy_text("Iskra drawing selection".to_string());
        } else if let Some(picked) = self.picked_frames() {
            // Frames picked on the timeline: what they show is kept here, to be laid on the
            // same layer again; cut, they are left as empty cells.
            let span = json!({ "layer": picked.layer.0, "frame": picked.first, "length": picked.length() });
            let Some(copied) = self.run_for("exposure.copy", span) else { return };
            (self.copied_frames, self.copied_nodes, self.copied_keys) = (Some((picked.layer, copied["cells"].clone())), false, None);
            if id == "drawing.cut" {
                self.delete_selection();
            }
            ctx.copy_text("Iskra frames".to_string());
        } else if let (false, Some(shot)) = (self.picked_keyframes().is_empty(), self.shot) {
            // Keyframes picked on the timeline: their values, eases and handles are kept, to
            // be pasted on the playhead; cut, they are taken away.
            let Some(copied) = self.run_for("keys.copy", json!({ "shot": shot.0, "keys": self.picked_keyframes() })) else { return };
            (self.copied_frames, self.copied_nodes, self.copied_keys) = (None, false, Some(copied["clip"].clone()));
            if id == "drawing.cut" {
                self.delete_selection();
            }
            ctx.copy_text("Iskra keyframes".to_string());
        } else if let (false, Some(shot), "drawing.copy") = (self.nodes_to_copy().is_empty(), self.shot, id) {
            // Nodes that are picked: the session keeps a copy of them, for a paste here or
            // in another shot. They are not cut: Delete takes them away.
            let nodes = self.nodes_to_copy();
            if self.run_for("node.copy", json!({ "shot": shot.0, "nodes": nodes })).is_some() {
                (self.copied_frames, self.copied_nodes, self.copied_keys) = (None, true, None);
                // Pasted beside them, until the node view is clicked where they are to go.
                self.nodes.paste_at = None;
                ctx.copy_text("Iskra nodes".to_string());
            }
        }
    }

    /// Run the commands whose shortcuts were pressed, as the keymap says.
    fn shortcuts(&mut self, ctx: &egui::Context) {
        // While a script's dialog is open, the keys are the dialog's.
        if self.script_dialog.is_some() {
            return;
        }
        // Keys are text only while a text field has the focus, or had it as the frame began:
        // the Escape or Enter that let it go is the field's too, not a Deselect. egui also
        // walks the focus from widget to widget on Tab; here Tab is a shortcut like any other,
        // so that is undone.
        let typing = std::mem::replace(&mut self.was_typing, ctx.text_edit_focused()) || ctx.text_edit_focused();
        if !typing && let Some(focused) = ctx.memory(|m| m.focused()) {
            ctx.memory_mut(|m| m.surrender_focus(focused));
        }
        // The system's cut, copy and paste shortcuts arrive as events, not as keys.
        for event in ctx.input(|i| i.events.clone()).into_iter().filter(|_| !typing) {
            match event {
                egui::Event::Copy => self.copy(ctx, "drawing.copy"),
                egui::Event::Cut => self.copy(ctx, "drawing.cut"),
                egui::Event::Paste(_) => self.paste(),
                _ => {}
            }
        }
        // A key pressed for a command in the Settings window is its new key, and runs nothing.
        if self.shortcut_capture.is_some() {
            return;
        }
        for (chord, id) in self.keys.clone().in_order() {
            // A key that types a character belongs to the text field while one has the focus.
            if typing && chord.is_typing() {
                continue;
            }
            // While a polyline is clicked out, Enter finishes it and Backspace takes a corner back.
            if self.viewport.polyline_open() && [egui::Key::Enter, egui::Key::Backspace, egui::Key::Delete].contains(&chord.key) {
                continue;
            }
            // A command that can't run now leaves its key for whoever else wants it.
            if let Some(command) = commands::command(id)
                && (command.enabled)(self)
                && ctx.input_mut(|i| chord.consume(i))
            {
                (command.run)(self, ctx);
            } else if let Some(script) = self.scripts.iter().find(|script| script.id == id).map(|script| script.id)
                && ctx.input_mut(|i| chord.consume(i))
            {
                self.run_script_command(script);
            }
        }
    }

    /// The folder of the user's own keymap files: `keymaps` beside the preferences file.
    fn keymaps_folder(&self) -> Option<std::path::PathBuf> {
        Some(self.prefs_file.as_ref()?.0.parent()?.join("keymaps"))
    }

