    #[test]
    fn colours_painted_on_free_colour_lately_are_taken_again() {
        let mut h = Harness::new();
        let (green, blue) = ([10, 200, 150, 255], [20, 40, 230, 255]);
        h.app.tools.free = Some(green);
        h.drag_between(Pos2::new(300.0, 300.0), Pos2::new(600.0, 300.0));
        h.app.tools.free = Some(blue);
        h.drag_between(Pos2::new(300.0, 330.0), Pos2::new(600.0, 330.0));
        assert_eq!((h.app.prefs.recent_colours.clone(), &h.app.error), (vec![blue, green], &None), "the last first");
        // Painted again, a colour goes to the front and is there once.
        h.app.tools.free = Some(green);
        h.drag_between(Pos2::new(300.0, 360.0), Pos2::new(600.0, 360.0));
        assert_eq!(h.app.prefs.recent_colours, [green, blue]);
        // The colour in hand is the preferences' too.
        h.frame(vec![]);
        assert_eq!(h.app.prefs.free_colour, Some(green));
        // A click on one in the brush's bar takes it.
        h.app.tools.tool = Tool::Brush;
        h.frame(vec![]);
        let chip = *h.app.recent_chips.get(1).expect("two chips in the bar");
        click(&mut h, chip.center());
        assert_eq!(h.app.tools.free, Some(blue));
    }

    #[test]
    fn the_tool_properties_panel_has_the_bars_settings_in_two_columns() {
        let mut h = Harness::new();
        let (green, blue) = ([10, 200, 150, 255], [20, 40, 230, 255]);
        h.app.prefs.recent_colours = vec![green, blue];
        run(&mut h, "panel.toolProperties");
        h.frame(vec![]);
        h.frame(vec![]);
        let group = h.app.dock_drawn.1.iter().find(|group| group.showing() == Some(Panel::ToolProperties)).expect("the panel is shown").clone();
        // The chips are below what the panel shows: it is scrolled to them.
        h.frame(vec![Event::PointerMoved(group.content.center())]);
        let (unit, delta) = (egui::MouseWheelUnit::Point, egui::vec2(0.0, -100.0));
        h.frame(vec![Event::MouseWheel { unit, delta, phase: egui::TouchPhase::Move, modifiers: Modifiers::NONE }]);
        for _ in 0..40 {
            h.frame(vec![]);
        }
        // The bar is drawn first, then the panel: the chips last recorded are the panel's.
        let chip = *h.app.recent_chips.get(1).expect("two chips in the panel");
        assert!(group.content.contains_rect(chip), "{chip:?} in {:?}", group.content);
        assert!(chip.top() > group.content.top() + 20.0, "the art layers, what is shown and the colour are rows of their own: {chip:?}");
        assert!(chip.left() > group.content.left() + form::NAME_WIDTH, "after the column of names, as in Properties: {chip:?}");
        click(&mut h, chip.center());
        assert_eq!((h.app.tools.free, &h.app.error), (Some(blue), &None));
        // The bar over the viewport stays.
        h.app.close_panel(Panel::ToolProperties);
        h.frame(vec![]);
        let chip = *h.app.recent_chips.first().expect("the chips in the bar");
        assert!(!group.content.contains_rect(chip) && chip.top() < 80.0, "{chip:?}");
    }

