    /// A converter standing in for the user's: a script that writes a picture, 4 by 2 with one
    /// red pixel, wherever it is told to, and says a small box.
    #[cfg(unix)]
    #[test]
    fn import_rig_makes_pictures_of_the_drawings_with_the_converter_first() {
        use std::os::unix::fs::PermissionsExt;
        let dir = tempfile::tempdir().unwrap();
        let picture = dir.path().join("red.png");
        let mut pixels = vec![[0u8; 4]; 8];
        pixels[2] = [255, 0, 0, 255];
        std::fs::write(&picture, iskra_io::encode_png(4, 2, &pixels).unwrap()).unwrap();
        let script = dir.path().join("convert");
        let body = format!(
            "#!/bin/sh\nout=\"\"; prev=\"\"\nfor arg in \"$@\"; do [ \"$prev\" = \"-outfile\" ] && out=\"$arg\"; prev=\"$arg\"; done\n[ -n \"$out\" ] && cp \"{}\" \"$out\"\necho \"-10 -10 10 10\"\n",
            picture.display()
        );
        std::fs::write(&script, body).unwrap();
        std::fs::set_permissions(&script, std::fs::Permissions::from_mode(0o755)).unwrap();
        std::fs::create_dir_all(dir.path().join("elements/ARM")).unwrap();
        std::fs::write(dir.path().join("elements/ARM/ARM-1.tvg"), "drawing").unwrap();
        let scene = dir.path().join("hero.xstage");
        std::fs::write(
            &scene,
            r#"<project><elements><element id="2" elementName="ARM" elementFolder="ARM"><drawings><dwg name="1"/></drawings></element></elements>
               <options><resolution size="1920,1080"/></options>
               <scenes><scene startFrame="1"><columns><column type="0" name="C"><elementSeq exposures="1" val="1" id="2"/></column></columns>
               <rootgroup name="Top"><nodeslist><module type="READ" name="ARM"><attrs><drawing><element col="C"/></drawing></attrs></module></nodeslist></rootgroup>
               </scene></scenes></project>"#,
        )
        .unwrap();
        let mut h = Harness::new();
        h.app.convert_rig(&scene, script);
        let folder = h.app.rig_job.as_ref().expect("converting").out.clone();
        for _ in 0..200 {
            h.frame(vec![]);
            if h.app.rig_job.is_none() {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        assert!(h.app.rig_job.is_none(), "the pictures were made, and the rig brought in");
        let shot = h.app.shot().unwrap().clone();
        let arm = shot.layers.iter().find(|layer| layer.name == "ARM").expect("the layer");
        let drawing = &arm.drawings[0].drawing;
        let ArtContent::Indexed(line) = &drawing.layer(ArtLayerKind::LineArt).unwrap().content else { panic!("indexed") };
        assert_eq!(line.pixel(0, -1).coverage, 65535, "the red pixel, with the picture's middle at the origin");
        let log = h.app.log.text();
        assert!(log.contains("converter -debug -printbox") && log.contains("3 pictures made of 1 drawings"), "{log}");
        assert!(!folder.exists(), "the folder of pictures is taken away");
    }

