    #[test]
    fn a_changed_preference_is_written_to_the_users_file() {
        use crate::prefs::NewDrawingHold;
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("preferences.json");
        let mut h = Harness::new();
        h.app = IskraApp::new(Session::new()).with_preferences(path.clone());
        h.frame(vec![]);
        assert!(!path.exists(), "nothing changed, nothing written");
        h.app.prefs.new_drawing_hold = NewDrawingHold::Frames(1);
        h.frame(vec![]);
        assert_eq!(Preferences::load(&path), h.app.prefs);
        assert_eq!(
            IskraApp::new(Session::new()).with_preferences(path.clone()).prefs.new_drawing_hold,
            NewDrawingHold::Frames(1),
            "and read at the next start"
        );

        // The art layer in hand is the user's too, and is in hand at the next start.
        run(&mut h, "art.colourArt");
        h.frame(vec![]);
        assert_eq!(IskraApp::new(Session::new()).with_preferences(path.clone()).tools.art, ArtLayerKind::ColourArt);
        h.app.tools.free = Some([1, 2, 3, 255]);
        // Taken into the preferences on one frame, and written on the next.
        h.frame(vec![]);
        h.frame(vec![]);
        assert_eq!(IskraApp::new(Session::new()).with_preferences(path.clone()).tools.free, Some([1, 2, 3, 255]), "and the free colour in hand");

        // So is the drawing guide in hand, with its project: in hand when that is opened, and
        // not in another one.
        let file = dir.path().join("Ruled.iskra");
        h.app.run("file.saveAs", json!({ "path": file }));
        run(&mut h, "guide.addRuler");
        let ruler = h.app.viewport.guide.expect("the new ruler is in hand");
        run(&mut h, "file.save");
        h.frame(vec![]);
        let mut again = Harness::new();
        again.app = IskraApp::new(Session::new()).with_preferences(path.clone());
        assert_eq!(again.app.viewport.guide, None, "another project");
        again.app.open_file(&file);
        again.frame(vec![]);
        assert_eq!((again.app.viewport.guide, again.app.guide_in_hand().map(|guide| guide.id), &again.app.error), (Some(ruler), Some(ruler), &None));
        // Put away, it is not taken in hand again.
        run(&mut again, "guide.putAway");
        again.frame(vec![]);
        assert_eq!(Preferences::load(&path).guide_in_hand, None);
    }

