        // The column's edge dragged 100 points to the right: the frames begin as far to the
        // right, and the preferences keep the width.
        let (edge, was) = (h.app.storyboard_view.names_edge.expect("the column has its edge"), h.app.storyboard_view.origin.x);
        h.drag_between(edge.center(), edge.center() + egui::vec2(100.0, 0.0));
