        let composite = h.app.session.project().shots[0].composite(mixed).unwrap().clone();
        assert_eq!(nodes::ordering_title(&composite), "2D, Right on Top");
        // Picked alone, Properties is the composite's, and draws without a fault.
        h.app.picked = [mixed.0].into();
