    #[test]
    fn sends_that_have_one_tag_say_which_is_read() {
        use crate::nodes::Item;
        use iskra_model::EffectId;
        let mut h = Harness::new();
        let send =
            |h: &mut Harness, name: &str| EffectId(h.app.run_for("effect.new", json!({ "kind": "send", "name": name })).unwrap()["id"].as_u64().unwrap());
        let (first, second) = (send(&mut h, "Arm"), send(&mut h, "Leg"));
        run(&mut h, "panel.nodeView");
        h.frame(vec![]);
        h.frame(vec![]);
        let said = |h: &Harness, id: EffectId| h.app.nodes.tags_said.iter().find(|(item, _)| *item == Item::Effect(id)).map(|(_, said)| said.clone());
        assert_eq!((said(&h, first).as_deref(), said(&h, second).as_deref()), (Some("tag: Arm"), Some("tag: Leg")));
        h.app.run("effect.set", json!({ "effect": second.0, "param": "tag", "value": "Arm" }));
        h.frame(vec![]);
        assert_eq!(said(&h, first).as_deref(), Some("tag: Arm, read here; another Send has it too"));
        assert_eq!(said(&h, second).as_deref(), Some("tag: Arm, not read: Arm has it first"));
        let shot = h.app.session.project().shots[0].clone();
        assert_eq!(shot.tag_shared(shot.effect(second).unwrap()).map(|send| send.id), Some(first));
    }

    #[test]
    fn a_wires_end_is_taken_from_one_composite_to_another() {
        use crate::nodes::Item;
        use iskra_model::{CompositeId, Source};
        let mut h = Harness::new();
        let first = h.app.layer.unwrap();
        let other = CompositeId(h.app.run_for("composite.new", json!({})).unwrap()["id"].as_u64().unwrap());
        run(&mut h, "panel.nodeView");
        h.frame(vec![]);
        h.frame(vec![]);
        let shot = |h: &Harness| h.app.session.project().shots[0].clone();
        let main = shot(&h).main_composite().unwrap();
        let at = |h: &Harness, item: Item| h.app.nodes.boxes.iter().find(|(other, _)| *other == item).expect("the node has a box").1;
        let end = |h: &Harness, from: Item, to: Item| h.app.nodes.wire_ends.iter().find(|(a, b, ..)| (*a, *b) == (from, to)).expect("the wire is there").3;
        let stacked = |h: &Harness, composite: CompositeId| shot(h).composite(composite).unwrap().inputs.clone();
        // The one layer of the main composite, taken to the other composite.
        let (from, onto) = (end(&h, Item::Layer(first), Item::Composite(main)), at(&h, Item::Composite(other)).center());
        h.drag_between(from, onto);
        assert_eq!((stacked(&h, main), stacked(&h, other), &h.app.error), (vec![], vec![Source::Layer(first)], &None));
        // Back, and with a second layer beside it in the main composite: one of two taken over.
        h.app.session.undo();
        run(&mut h, "layer.new");
        let second = h.app.layer.unwrap();
        h.frame(vec![]);
        h.frame(vec![]);
        assert_eq!(stacked(&h, main).len(), 2);
        let (from, onto) = (end(&h, Item::Layer(second), Item::Composite(main)), at(&h, Item::Composite(other)).center());
        h.drag_between(from, onto);
        assert_eq!((stacked(&h, main), stacked(&h, other), &h.app.error), (vec![Source::Layer(first)], vec![Source::Layer(second)], &None));
        // A composite's own wire: the other composite goes into the main one, and is taken
        // from there to a third.
        h.app.run("node.connect", json!({ "node": { "composite": other.0 }, "to": main.0 }));
        let third = CompositeId(h.app.run_for("composite.new", json!({})).unwrap()["id"].as_u64().unwrap());
        h.frame(vec![]);
        h.frame(vec![]);
        let (from, onto) = (end(&h, Item::Composite(other), Item::Composite(main)), at(&h, Item::Composite(third)).center());
        h.drag_between(from, onto);
        assert_eq!((stacked(&h, main), stacked(&h, third), &h.app.error), (vec![Source::Layer(first)], vec![Source::Composite(other)], &None));
    }

    #[test]
    fn nodes_stay_where_they_were_laid_out_unless_the_view_arranges_them() {
        use crate::nodes::Item;
        let mut h = Harness::new();
        let layer = h.app.layer.unwrap();
        run(&mut h, "panel.nodeView");
        h.frame(vec![]);
        let at = |h: &Harness, item: Item| h.app.nodes.boxes.iter().find(|(other, _)| *other == item).expect("the node has a box").1.center();
        let was = at(&h, Item::Layer(layer));
        // A second layer beside it in the composite: the layout would move the first aside,
        // and by hand it stays.
        run(&mut h, "layer.new");
        h.frame(vec![]);
        h.frame(vec![]);
        assert_eq!(at(&h, Item::Layer(layer)), was);
        // Arranged by the view, it is where the layout has it, and goes back to moving.
        h.app.nodes.arrange = true;
        h.frame(vec![]);
        h.frame(vec![]);
        let arranged = at(&h, Item::Layer(layer));
        assert!((arranged.x - was.x).abs() > 20.0, "{was:?} {arranged:?}");
        // By hand again, all stay where they are now.
        h.app.nodes.arrange = false;
        h.frame(vec![]);
        run(&mut h, "layer.new");
        h.frame(vec![]);
        h.frame(vec![]);
        assert_eq!(at(&h, Item::Layer(layer)), arranged);
        assert_eq!(h.app.error, None);
    }

