        let one = h.app.run_for("group.new", json!({ "nodes": [layer.0], "name": "One" })).unwrap()["id"].as_u64().unwrap();
        let two = h.app.run_for("group.new", json!({ "nodes": [peg.0], "name": "Two" })).unwrap()["id"].as_u64().unwrap();
        run(&mut h, "panel.nodeView");
        h.frame(vec![]);
