    #[test]
    fn a_node_added_over_an_open_group_goes_into_it() {
        let mut h = Harness::new();
        let layer = h.app.layer.unwrap();
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        let group = h.app.run_for("group.new", json!({ "nodes": [peg.0, layer.0], "name": "Rig" })).unwrap()["id"].as_u64().unwrap();
        run(&mut h, "panel.nodeView");
        h.frame(vec![]);
        h.frame(vec![]);
        let frame = h.app.nodes.frames[0].1;
        // Between the peg's box and the layer's, off to the side, the frame is bare.
        let bare = egui::pos2(frame.left() + 8.0, frame.center().y);
        click(&mut h, bare);
        assert!(h.app.picked.is_empty());
        h.frame(vec![Event::PointerMoved(bare)]);
        press(&mut h, Modifiers::NONE, Key::Enter);
        h.frame(vec![Event::Text("transp".to_string())]);
        press(&mut h, Modifiers::NONE, Key::Enter);
        h.frame(vec![]);
        let shot = h.app.session.project().shots[0].clone();
        let [made] = &shot.effects[..] else { panic!("one node was added: {:?} {:?}", shot.effects, h.app.error) };
        assert!(shot.group(iskra_model::GroupId(group)).unwrap().members.contains(&made.id.0), "{:?}", shot.groups);
        // So does a layer, a peg or a composite that the view's menu makes there.
        let ctx = h.ctx.clone();
        for id in ["layer.new", "peg.new", "composite.new"] {
            let before = h.app.session.project().shots[0].group(iskra_model::GroupId(group)).unwrap().members.len();
            h.app.timeline_actions(&ctx, vec![timeline::Action::Run(id, json!({ "shot": shot.id.0, "group": group }))]);
            let after = h.app.session.project().shots[0].group(iskra_model::GroupId(group)).unwrap().members.len();
            assert_eq!((after, &h.app.error), (before + 1, &None), "{id}");
        }
    }

    #[test]
    fn a_groups_own_composite_is_put_under_what_it_gathers() {
        use crate::nodes::Item;
        let mut h = Harness::new();
        run(&mut h, "panel.nodeView");
        let first = h.app.layer.unwrap();
        run(&mut h, "layer.new");
        let second = h.app.layer.unwrap();
        h.frame(vec![]);
        let shot = |h: &Harness| h.app.session.project().shots[0].clone();
        let at = |h: &Harness, item: Item| h.app.nodes.boxes.iter().find(|(other, _)| *other == item).expect("the node has a box").1;
        let (a, b) = (at(&h, Item::Layer(first)), at(&h, Item::Layer(second)));
        let ctx = h.ctx.clone();
        h.app.timeline_actions(&ctx, vec![timeline::Action::Run("group.new", json!({ "nodes": [first.0, second.0], "composite": true, "ports": true }))]);
        h.frame(vec![]);
        let own = shot(&h).groups[0].members.iter().copied().find(|member| shot(&h).composite(iskra_model::CompositeId(*member)).is_some());
        let own = iskra_model::CompositeId(own.expect("the group has a composite of its own"));
        assert_eq!(h.app.error, None);
        let put = at(&h, Item::Composite(own));
        assert!(put.top() > a.bottom().max(b.bottom()), "below both: {put:?} {a:?} {b:?}");
        assert!((put.center().x - (a.center().x + b.center().x) / 2.0).abs() < 2.0, "between them across: {put:?} {a:?} {b:?}");
    }

    #[test]
    fn a_group_is_deleted_with_all_that_is_in_it_as_one_step() {
        let mut h = Harness::new();
        bare_camera(&mut h);
        let layer = h.app.layer.unwrap();
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        run(&mut h, "layer.new");
        let other = h.app.layer.unwrap();
        let group = h.app.run_for("group.new", json!({ "nodes": [peg.0, layer.0], "name": "Rig" })).unwrap()["id"].as_u64().unwrap();
        let left = |h: &Harness| {
            let shot = &h.app.session.project().shots[0];
            (shot.layers.iter().map(|layer| layer.id).collect::<Vec<_>>(), shot.pegs.len(), shot.groups.len())
        };
        // From its own menu, the group goes with the peg and the layer in it.
        let ctx = h.ctx.clone();
        h.app.timeline_actions(&ctx, vec![timeline::Action::Run("group.delete", json!({ "group": group, "contents": true }))]);
        h.frame(vec![]);
        assert_eq!((left(&h), &h.app.error), ((vec![other], 0, 0), &None));
        h.app.session.undo();
        assert_eq!(left(&h).1, 1, "one step");
        assert_eq!((left(&h).0.len(), left(&h).2), (2, 1));
        // Picked with a layer outside it, a Delete on that layer takes the group and all in it.
        run(&mut h, "layer.new");
        let third = h.app.layer.unwrap();
        h.app.picked = [group, other.0].into();
        h.app.timeline_actions(&ctx, vec![timeline::Action::Run("layer.delete", json!({ "layer": other.0 }))]);
        h.frame(vec![]);
        assert_eq!((left(&h), &h.app.error), ((vec![third], 0, 0), &None));
        // A group with its ports: they go with the group, and are not deleted again after.
        h.app.session.undo();
        h.app.run("group.delete", json!({ "group": group }));
        let made = h.app.run_for("group.new", json!({ "nodes": [peg.0, layer.0, third.0], "name": "Prop", "ports": true })).unwrap();
        let prop = made["id"].as_u64().unwrap();
        assert!(h.app.session.project().shots[0].effects.iter().any(|effect| h.app.session.project().shots[0].is_port(effect.id.0)), "it has ports");
        h.app.timeline_actions(&ctx, vec![timeline::Action::Run("group.delete", json!({ "group": prop, "contents": true }))]);
        let shot = h.app.session.project().shots[0].clone();
        assert_eq!((h.app.error.clone(), shot.layer(third).is_none(), shot.effects.len()), (None, true, 0));
        h.app.session.undo();
        // Ungrouping is as it was: what is in the group stays.
        h.app.session.undo();
        h.app.timeline_actions(&ctx, vec![timeline::Action::Run("group.delete", json!({ "group": group }))]);
        assert_eq!((left(&h).0.len(), left(&h).1, left(&h).2), (3, 1, 0));
    }

    #[test]
    fn properties_shows_the_camera_only_when_it_is_in_hand() {
        let mut h = Harness::new();
        h.frame(vec![]);
        assert!(h.app.layer.is_some() && !h.app.camera_shown, "a layer is in hand: the panel is the layer's");
        // With the Camera tool the panel is the camera's.
        h.app.tools.tool = Tool::Camera;
        h.frame(vec![]);
        assert!(h.app.camera_shown);
        h.app.tools.tool = Tool::Brush;
        h.frame(vec![]);
        assert!(!h.app.camera_shown);
        // The peg that moves the camera has the camera under its own values; another peg has not.
        h.app.add_camera_peg();
        h.frame(vec![]);
        assert!(h.app.camera_shown && !h.app.property_fields.is_empty());
        run(&mut h, "peg.new");
        h.frame(vec![]);
        assert!(!h.app.camera_shown);
    }

