    #[test]
    fn the_timelines_zoom_fits_the_shot_and_the_film() {
        let mut h = Harness::new();
        // The parts before the zoom are hidden, for it to be in the harness's narrow window.
        let hidden = |panel: Panel| bar::of(panel).iter().map(|part| part.id).filter(|id| *id != "zoom").map(str::to_string).collect();
        h.app.prefs.set_bar(Panel::Timeline, bar::BarLayout { hidden: hidden(Panel::Timeline), ..Default::default() });
        h.app.prefs.set_bar(Panel::Storyboard, bar::BarLayout { hidden: hidden(Panel::Storyboard), ..Default::default() });
        h.app.prefs.timeline_zoom = Some(60.0);
        h.frame(vec![]);
        let shot = h.app.session.project().shots[0].duration as f32;
        // The frames are seen beside the column of names.
        let seen = h.app.timeline.rows_seen.expect("the timeline is shown").width() - h.app.timeline.names_width();
        assert!(60.0 * shot > seen, "zoomed in, the shot is wider than the timeline");
        let fit = h.app.timeline.fit_button.expect("the zoom has Fit").center();
        click(&mut h, fit);
        h.frame(vec![]);
        let width = h.app.timeline.frame_width();
        assert!(width * shot <= seen + 1.0 && width * shot > seen * 0.9, "{width} × {shot} in {seen}");
        // The storyboard's fits the whole film.
        run(&mut h, "page.storyboard");
        h.app.prefs.storyboard_zoom = Some(24.0);
        h.frame(vec![]);
        let fit = h.app.storyboard_view.fit_button.expect("the zoom has Fit").center();
        click(&mut h, fit);
        h.frame(vec![]);
        let (width, film) = (h.app.prefs.storyboard_zoom.expect("zoomed to fit"), h.app.session.project().storyboards[0].end() as f32);
        assert!(width < 24.0 && width * film < 800.0, "{width} × {film}");
    }

