    #[test]
    fn the_animate_switch_is_one_on_every_page() {
        let mut h = Harness::new();
        h.frame(vec![]);
        let checked = |h: &Harness| (commands::command("animate.toggle").unwrap().checked.unwrap())(&h.app);
        assert!(checked(&h), "on at the start");
        run(&mut h, "page.storyboard");
        h.frame(vec![]);
        assert!(checked(&h) && h.app.storyboard_view.animate, "the Storyboard page's is the same");
        run(&mut h, "animate.toggle");
        h.frame(vec![]);
        assert!(!checked(&h) && !h.app.prefs.animate);
        run(&mut h, "page.animation");
        h.frame(vec![]);
        assert!(!checked(&h) && !h.app.timeline.animate, "switched off there, it is off here");
        // At the next start it is as the settings say, whatever it was left at.
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("preferences.json");
        let mut prefs = Preferences { animate: false, ..Preferences::default() };
        prefs.save(&path).unwrap();
        let app = IskraApp::new(Session::new()).with_preferences(path.clone());
        assert!(app.prefs.animate);
        prefs.animate_at_start = false;
        prefs.animate = true;
        prefs.save(&path).unwrap();
        assert!(!IskraApp::new(Session::new()).with_preferences(path).prefs.animate);
    }

