    #[test]
    fn the_animate_switch_keys_a_first_move_and_off_takes_the_keys_along() {
        let mut h = Harness::new();
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        let keys = |h: &Harness| h.app.session.project().shots[0].peg(peg).unwrap().animation.key_frames().into_iter().collect::<Vec<_>>();
        let at = |h: &Harness, frame: u32| h.app.session.project().shots[0].peg(peg).unwrap().transform_at(frame).position[0];
        let checked = |h: &Harness| (commands::command("animate.toggle").unwrap().checked.unwrap())(&h.app);
        run(&mut h, "tool.transform");
        let step = 50.0 / f64::from(h.app.viewport.view.zoom);
        // On, as it is at first: a move of what has no keys is keyed where it is done, and a
        // move on another frame is a second key, so it goes from the one to the other.
        assert!(checked(&h));
        h.drag_between(Pos2::new(300.0, 350.0), Pos2::new(350.0, 350.0));
        assert_eq!((keys(&h), h.app.session.history().undo_label()), (vec![0], Some("Move Peg")));
        h.app.tools.frame = 10;
        h.drag_between(Pos2::new(350.0, 350.0), Pos2::new(400.0, 350.0));
        assert_eq!((keys(&h), &h.app.error), (vec![0, 10], &None));
        assert!((at(&h, 0) - step).abs() < 0.5 && (at(&h, 10) - 2.0 * step).abs() < 0.5, "{} {}", at(&h, 0), at(&h, 10));
        // Off, a move between the keys makes none: both keys go as far as the drag.
        run(&mut h, "animate.toggle");
        assert!(!checked(&h));
        h.app.tools.frame = 5;
        h.drag_between(Pos2::new(375.0, 350.0), Pos2::new(425.0, 350.0));
        assert_eq!((keys(&h), h.app.session.history().undo_label(), &h.app.error), (vec![0, 10], Some("Move Peg"), &None));
        assert!((at(&h, 0) - 2.0 * step).abs() < 0.5 && (at(&h, 10) - 3.0 * step).abs() < 0.5, "{} {}", at(&h, 0), at(&h, 10));
    }

    #[test]
    fn a_peg_is_keyed_moved_on_another_frame_and_its_keys_dragged_in_the_timeline() {
        let mut h = Harness::new();
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        let keys = |h: &Harness| h.app.session.project().shots[0].peg(peg).unwrap().animation.key_frames().into_iter().collect::<Vec<_>>();
        let at = |h: &Harness, frame: u32| h.app.session.project().shots[0].peg(peg).unwrap().transform_at(frame).position[0];
        let enabled = |h: &Harness, id: &str| (commands::command(id).unwrap().enabled)(&h.app);

        // With the Animate switch off, moving the peg on a later frame moves it on every
        // frame, and makes no key.
        run(&mut h, "tool.transform");
        assert!(h.app.prefs.animate, "it is on in a new window");
        run(&mut h, "animate.toggle");
        h.app.tools.frame = 10;
        h.drag_between(Pos2::new(300.0, 350.0), Pos2::new(350.0, 350.0));
        let step = 50.0 / f64::from(h.app.viewport.view.zoom);
        assert!((at(&h, 0) - step).abs() < 0.5 && keys(&h).is_empty());

        // Keyed on the first frame, the same drag on frame 10 with the switch on makes a key
        // there.
        h.app.tools.frame = 0;
        assert!(enabled(&h, "key.add") && !enabled(&h, "key.remove"));
        run(&mut h, "key.add");
        assert!((keys(&h), enabled(&h, "key.add"), enabled(&h, "key.remove")) == (vec![0], false, true));
        h.app.tools.frame = 10;
        run(&mut h, "animate.toggle");
        h.drag_between(Pos2::new(300.0, 350.0), Pos2::new(350.0, 350.0));
        assert_eq!((keys(&h), h.app.session.history().undo_label(), &h.app.error), (vec![0, 10], Some("Move Peg"), &None));
        assert!(
            (at(&h, 0) - step).abs() < 0.5 && (at(&h, 5) - 1.5 * step).abs() < 0.5 && (at(&h, 10) - 2.0 * step).abs() < 0.5,
            "it goes there over ten frames"
        );

        // The keys are marks on the peg's row. Dragging one four frames along moves it.
        let mark = |h: &Harness, frame: u32| h.app.timeline.key_marks.iter().find(|(id, at, _)| (*id, *at) == (peg, frame)).expect("the key has a mark").2;
        let from = mark(&h, 10).center();
        h.drag_between(from, from + egui::vec2(64.0, 0.0));
        assert_eq!((keys(&h), h.app.session.history().undo_label()), (vec![0, 14], Some("Move Keyframe")));
        assert_eq!(h.app.tools.frame, 10, "dragging a key doesn't move the playhead");
        // Clicking one goes to its frame, and the keyframe keys step from one to the next.
        let on = mark(&h, 14).center();
        click(&mut h, on);
        assert_eq!((h.app.tools.frame, h.app.peg), (14, Some(peg)));
        run(&mut h, "key.previous");
        assert_eq!(h.app.tools.frame, 0);
        run(&mut h, "key.previous");
        run(&mut h, "key.next");
        assert_eq!(h.app.tools.frame, 14);

        // Held, the first key's pose stays until the next key.
        h.app.tools.frame = 0;
        run(&mut h, "key.hold");
        assert!((at(&h, 13) - step).abs() < 0.5 && (at(&h, 14) - 2.0 * step).abs() < 0.5);
        assert_eq!(h.app.session.history().undo_label(), Some("Set Keyframe Ease"));
        run(&mut h, "key.remove");
        assert_eq!((keys(&h), &h.app.error), (vec![14], &None));
    }

    #[test]
    fn an_in_between_slid_along_the_motion_path_times_the_way_and_the_others_follow() {
        let mut h = Harness::new();
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        run(&mut h, "tool.transform");
        // Two keys: at the middle on frame 0, 120 points right on frame 6.
        run(&mut h, "key.add");
        h.app.tools.frame = 6;
        h.frame(vec![]);
        h.drag_between(Pos2::new(300.0, 300.0), Pos2::new(420.0, 300.0));
        let across = |h: &Harness, frame: u32| h.app.session.project().shots[0].peg(peg).unwrap().transform_at(frame).position[0];
        let start = across(&h, 0);
        let way = across(&h, 6) - start;
        assert!(way > 50.0 && (across(&h, 3) - start - way / 2.0).abs() < 1e-6, "{way}");
        let dot = |h: &Harness, frame: u32| h.app.viewport.path_dots.iter().find(|(at, _)| *at == frame).expect("the in-between is on the path").1;
        let key = |h: &Harness, frame: u32| h.app.viewport.path_keys.iter().find(|(at, _)| *at == frame).expect("the keyframe is on the path").1;
        assert_eq!(h.app.viewport.path_dots.len(), 5);
        // The third in-between slid back to three tenths of the way, by thirds with the other
        // side left: the first two follow evenly, along the path, as one undo step; the frame
        // shown stays.
        h.app.prefs.breakdowns = crate::breakdown::Breakdowns { shown: true, rule: iskra_model::Spacing::Thirds, other_side: false };
        let (first, last) = (key(&h, 0), key(&h, 6));
        let steps = h.app.session.history().entries().len();
        h.drag_between(dot(&h, 3), first + (last - first) * 0.3 + egui::vec2(0.0, 6.0));
        assert_eq!(
            (h.app.session.history().entries().len(), h.app.session.history().undo_label(), h.app.tools.frame, &h.app.error),
            (steps + 1, Some("Space In-betweens"), 6, &None)
        );
        let moved: Vec<f64> = (1..6).map(|frame| (across(&h, frame) - start) / way).collect();
        assert!((moved[2] - 0.3).abs() < 0.02, "{moved:?}");
        assert!((moved[0] - moved[2] / 3.0).abs() < 1e-6 && (moved[1] - moved[2] * 2.0 / 3.0).abs() < 1e-6, "{moved:?}");
        assert!((moved[3] - 4.0 / 6.0).abs() < 1e-6 && (moved[4] - 5.0 / 6.0).abs() < 1e-6, "the other side stays: {moved:?}");
        // The keys did not move, and the path is where it was.
        assert!((across(&h, 6) - start - way).abs() < 1e-6);
        assert!((dot(&h, 3).y - first.y).abs() < 1.0);
    }

    #[test]
    fn the_motion_path_shows_in_the_viewport_and_its_keys_and_handles_drag() {
        let mut h = Harness::new();
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        run(&mut h, "tool.transform");
        assert!(h.app.viewport.path_keys.is_empty(), "a peg that is not animated has no path");
        // Three keys: at the middle, 100 points right and down on frame 10, 200 right on frame 20.
        run(&mut h, "key.add");
        for (frame, from, to) in [(10, Pos2::new(300.0, 300.0), Pos2::new(400.0, 400.0)), (20, Pos2::new(400.0, 400.0), Pos2::new(500.0, 300.0))] {
            h.app.tools.frame = frame;
            h.frame(vec![]);
            h.drag_between(from, to);
        }
        let position = |h: &Harness, frame: u32| h.app.session.project().shots[0].peg(peg).unwrap().transform_at(frame).position;
        let key = |h: &Harness, frame: u32| h.app.viewport.path_keys.iter().find(|(at, _)| *at == frame).expect("the keyframe is on the path").1;
        let origin = key(&h, 0);
        assert_eq!(h.app.viewport.path_keys.len(), 3);
        assert!((key(&h, 10) - origin - egui::vec2(100.0, 100.0)).length() < 1.0 && (key(&h, 20) - origin - egui::vec2(200.0, 0.0)).length() < 1.0);

        // Clicking a keyframe's square goes to its frame, where the path's handles show: level,
        // since the keys before and after are level with each other.
        let steps = h.app.session.history().entries().len();
        let middle = key(&h, 10);
        click(&mut h, middle);
        assert_eq!((h.app.tools.frame, h.app.session.history().entries().len()), (10, steps));
        let (into, out) = h.app.viewport.bend_dots.expect("the keyframe under the playhead has handles");
        assert!(out.x > middle.x + 10.0 && (out.y - middle.y).abs() < 1.0 && into.x < middle.x - 10.0, "{into:?} {middle:?} {out:?}");

        // Dragging the leaving handle to straight under the key bends the path: the other
        // handle swings to straight above, and the peg now dips below the key after it.
        h.drag_between(out, middle + egui::vec2(0.0, 50.0));
        assert_eq!((h.app.session.history().undo_label(), &h.app.error), (Some("Bend Motion Path"), &None));
        let (into, out) = h.app.viewport.bend_dots.unwrap();
        assert!((out - middle - egui::vec2(0.0, 50.0)).length() < 1.5 && (into.x - middle.x).abs() < 1.5 && into.y < middle.y - 10.0, "{into:?} {out:?}");
        assert!(position(&h, 11)[1] > position(&h, 10)[1]);
        // At a corner the peg goes straight from key to key; smooth curves it again.
        run(&mut h, "key.corner");
        let halfway = |h: &Harness| (position(h, 5)[1] - (position(h, 0)[1] + position(h, 10)[1]) / 2.0).abs();
        assert!(halfway(&h) < 1e-6);
        // Its handles lie along the straight ways, to pull it into a curve by; pulling one
        // leaves the other side straight.
        let (_, out) = h.app.viewport.bend_dots.unwrap();
        h.drag_between(out, middle + egui::vec2(0.0, 50.0));
        assert!(halfway(&h) < 1e-6 && position(&h, 11)[1] > position(&h, 10)[1], "bent on the way out only");
        run(&mut h, "key.smooth");
        assert!(halfway(&h) > 1.0);
        assert!((h.app.viewport.bend_dots.unwrap().1.y - middle.y).abs() < 1.0);

        // Dragging the square of another frame's keyframe moves that keyframe, from here.
        let last = key(&h, 20);
        h.drag_between(last, last + egui::vec2(0.0, 80.0));
        assert_eq!((h.app.session.history().undo_label(), h.app.tools.frame), (Some("Move Peg"), 10));
        assert!((key(&h, 20) - last - egui::vec2(0.0, 80.0)).length() < 1.0 && (key(&h, 10) - middle).length() < 0.5);
    }

    #[test]
    fn the_function_curves_show_a_value_over_time_and_shape_how_it_gets_there() {
        let mut h = Harness::new();
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        // The rotation goes from 0 on frame 0 to 90 on frame 20.
        run(&mut h, "key.add");
        h.app.run("peg.setTransform", json!({ "peg": peg.0, "frame": 20, "rotation": 90.0 }));
        run(&mut h, "panel.curves");
        h.app.curves.curve = curves::Curve::Rotation;
        h.frame(vec![]);
        let rotation = |h: &Harness, frame: u32| peg_transform_at(h, peg, frame).rotation;
        let key = |h: &Harness, frame: u32| h.app.curves.keys.iter().find(|(at, _)| *at == frame).expect("the keyframe is on the curve").1;
        let handle = |h: &Harness, frame: u32, out: bool| h.app.curves.handles.iter().find(|(at, side, _)| (*at, *side) == (frame, out)).expect("a handle").2;
        let (first, last) = (key(&h, 0), key(&h, 20));
        assert!(last.x > first.x + 100.0 && last.y < first.y - 20.0, "later is to the right, more is up: {first:?} {last:?}");
        // Linear, the handles lie on the straight line between the keys, a third of the way in.
        let out = handle(&h, 0, true);
        assert!((out - (first + (last - first) / 3.0)).length() < 1.0, "{out:?}");
        assert!((rotation(&h, 5) - 22.5).abs() < 1e-6);

        // Pulling the first handle down to the level of its key: a slow start.
        let steps = h.app.session.history().entries().len();
        h.drag_between(out, Pos2::new(out.x, first.y));
        assert_eq!(
            (h.app.session.history().undo_label(), h.app.session.history().entries().len(), &h.app.error),
            (Some("Set Keyframe Ease"), steps + 1, &None)
        );
        assert!(rotation(&h, 5) < 15.0 && (rotation(&h, 20) - 90.0).abs() < 1e-9, "{}", rotation(&h, 5));
        assert!((handle(&h, 0, true).y - first.y).abs() < 1.0, "the handle is where it was left");
        // Only the rotation's key was eased; the position's on the same frame is as it was.
        let sides = |channel| h.app.session.project().shots[0].peg(peg).unwrap().animation.interp_of(0, Some(channel)).unwrap();
        assert!(matches!(sides(iskra_model::Channel::Rotation).1, Interp::Curve(_)) && sides(iskra_model::Channel::Position).1 == Interp::Linear);

        // Dragging a keyframe up raises its value; the frame stays.
        let last = key(&h, 20);
        h.drag_between(last, last - egui::vec2(0.0, 30.0));
        assert!(rotation(&h, 20) > 100.0 && h.app.session.history().undo_label() == Some("Rotate Peg"), "{}", rotation(&h, 20));
        // Anywhere else, the pointer puts the playhead on its frame.
        let on = key(&h, 20);
        click(&mut h, Pos2::new(on.x, on.y + 40.0));
        assert_eq!(h.app.tools.frame, 20);

        // The position's curve is the way along its path: its keys show, and don't drag here.
        h.app.run("peg.setTransform", json!({ "peg": peg.0, "frame": 20, "position": [300.0, 0.0] }));
        h.app.curves.curve = curves::Curve::Position;
        h.frame(vec![]);
        let (first, last) = (key(&h, 0), key(&h, 20));
        assert!(last.y < first.y - 20.0);
        let steps = h.app.session.history().entries().len();
        h.drag_between(last, last + egui::vec2(0.0, 30.0));
        assert_eq!(h.app.session.history().entries().len(), steps);
        let into = handle(&h, 20, false);
        h.drag_between(into, Pos2::new(into.x, last.y));
        let x = |h: &Harness, frame: u32| peg_transform_at(h, peg, frame).position[0];
        assert!(x(&h, 15) > 240.0 && h.app.session.history().undo_label() == Some("Set Keyframe Ease"), "a slow arrival: {}", x(&h, 15));
    }

    #[test]
    fn a_keys_value_dragged_on_the_curves_with_adjust_moves_the_picked_keys_alike() {
        let mut h = Harness::new();
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        // The rotation keyed on 0, 10 and 20.
        run(&mut h, "key.add");
        for (frame, rotation) in [(10, 40.0), (20, 10.0)] {
            h.app.run("peg.setTransform", json!({ "peg": peg.0, "frame": frame, "rotation": rotation }));
        }
        run(&mut h, "panel.curves");
        h.app.curves.curve = curves::Curve::Rotation;
        h.frame(vec![]);
        let rotation = |h: &Harness, frame: u32| peg_transform_at(h, peg, frame).rotation;
        // With Adjust on and the key on 20 picked, the key on 10 dragged up takes it as far.
        h.app.prefs.adjust = true;
        h.app.timeline.picked_keys = vec![(timeline::Keyed::Peg(peg, None), 20)];
        let key = h.app.curves.keys.iter().find(|(at, _)| *at == 10).expect("the keyframe is on the curve").1;
        h.drag_between(key, key - egui::vec2(0.0, 30.0));
        let by = rotation(&h, 10) - 40.0;
        assert!(by > 1.0, "{by}");
        assert!((rotation(&h, 20) - 10.0 - by).abs() < 1e-9 && rotation(&h, 0) == 0.0, "{} {}", rotation(&h, 20), rotation(&h, 0));
        assert_eq!(h.app.error, None);
    }

    #[test]
    fn a_charted_way_shows_its_in_betweens_on_the_curve_and_they_are_dragged() {
        let mut h = Harness::new();
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        // The rotation goes from 0 on frame 0 to 60 on frame 6, timed by a chart.
        run(&mut h, "key.add");
        h.app.run("peg.setTransform", json!({ "peg": peg.0, "frame": 6, "rotation": 60.0 }));
        let chart = json!({ "owner": { "peg": peg.0 }, "value": "rotation", "from": 0, "to": 6, "spacing": [0.1, 0.2, 0.3, 0.6, 0.9] });
        h.app.run("keys.chart", chart);
        run(&mut h, "panel.curves");
        h.app.curves.curve = curves::Curve::Rotation;
        h.frame(vec![]);
        // Its five in-betweens are points on the curve, and the eases have no handles there.
        let points = |h: &Harness| h.app.curves.chart_points.iter().filter(|(from, ..)| *from == 0).map(|(.., at)| *at).collect::<Vec<_>>();
        assert_eq!((points(&h).len(), h.app.curves.handles.iter().filter(|(frame, ..)| *frame == 0).count()), (5, 0));
        let rotation = |h: &Harness, frame: u32| peg_transform_at(h, peg, frame).rotation;
        // The third dragged down to a tenth of the way, by thirds with the other side left: the
        // two before it spaced evenly under it, as one undo step.
        h.app.prefs.breakdowns = crate::breakdown::Breakdowns { shown: true, rule: iskra_model::Spacing::Thirds, other_side: false };
        let (third, key) = (points(&h)[2], h.app.curves.keys[0].1);
        let steps = h.app.session.history().entries().len();
        h.drag_between(third, Pos2::new(third.x, key.y + (h.app.curves.keys[1].1.y - key.y) * 0.15));
        assert_eq!(
            (h.app.session.history().undo_label(), h.app.session.history().entries().len(), &h.app.error),
            (Some("Space In-betweens"), steps + 1, &None)
        );
        let third = rotation(&h, 3);
        assert!((third - 9.0).abs() < 0.5 && (rotation(&h, 1) - third / 3.0).abs() < 1e-6 && (rotation(&h, 2) - third * 2.0 / 3.0).abs() < 1e-6, "{third}");
        assert!((rotation(&h, 4) - 36.0).abs() < 1e-6 && (rotation(&h, 5) - 54.0).abs() < 1e-6, "the other side stays");
        // The position, not charted, keeps its handles.
        h.app.run("peg.setTransform", json!({ "peg": peg.0, "frame": 6, "position": [300.0, 0.0] }));
        h.app.curves.curve = curves::Curve::Position;
        h.frame(vec![]);
        assert!(points(&h).is_empty() && !h.app.curves.handles.is_empty());
    }

    #[test]
    fn the_function_curves_show_a_pose_of_bones_and_its_keys_are_dragged() {
        let mut h = Harness::new();
        h.app.run("shot.setDuration", json!({ "frames": 24 }));
        h.drag();
        let layer = h.app.layer.unwrap();
        let bones = json!([{ "angle": 0, "length": 100 }, { "angle": 0, "length": 100 }]);
        let made = h.app.run_for("deformer.new", json!({ "layer": layer.0, "origin": [-100, 0], "bones": bones })).unwrap()["id"].as_u64().unwrap();
        h.app.run("deformer.setKey", json!({ "deformer": made, "frame": 0 }));
        h.app.run("deformer.setPose", json!({ "deformer": made, "frame": 20, "bone": 1, "turn": 60 }));
        run(&mut h, "panel.curves");
        h.frame(vec![]);
        h.frame(vec![]);
        assert_eq!(h.app.error, None);
        let turn = |h: &Harness, frame: u32| h.app.session.project().shots[0].deformer(iskra_model::DeformerId(made)).unwrap().bones[1].turn_at(frame);
        let key = |h: &Harness, frame: u32| h.app.curves.keys.iter().find(|(at, _)| *at == frame).map(|(_, at)| *at);
        // With no peg, the curves are of the pose: the first bone's turn to begin with, which
        // has the one key that keyed the whole pose; the second bone's rises to a second.
        assert!(key(&h, 0).is_some() && key(&h, 20).is_none(), "{:?}", h.app.curves.keys);
        h.app.curves.pose = Some(curves::Pose::Turn(1));
        h.frame(vec![]);
        let (first, last) = (key(&h, 0).unwrap(), key(&h, 20).unwrap());
        assert!(last.x > first.x + 100.0 && last.y < first.y - 20.0, "later is to the right, more is up: {first:?} {last:?}");
        // The handle out of the first key pulled down to its level: a slow start, of all the
        // pose's values together, as one step.
        let out = h.app.curves.handles.iter().find(|(at, side, _)| (*at, *side) == (0, true)).expect("a pose's way is shaped by its handles").2;
        let linear = turn(&h, 5);
        h.drag_between(out, Pos2::new(out.x, first.y));
        assert_eq!((h.app.session.history().undo_label(), &h.app.error), (Some("Set Keyframe Ease"), &None));
        assert!(turn(&h, 5) < linear - 2.0, "{} against {linear}", turn(&h, 5));
        let shot = h.app.session.project().shots[0].clone();
        let eased = shot.deformer(iskra_model::DeformerId(made)).unwrap().interp(0);
        assert!(matches!(eased, Some((_, iskra_model::Interp::Curve(_)))), "{eased:?}");
        h.frame(vec![]);
        let (first, last) = (key(&h, 0).unwrap(), key(&h, 20).unwrap());
        // Its last key dragged down to the level of the first: the bone turns less there, as one step.
        let steps = h.app.session.history().entries().len();
        h.drag_between(last, Pos2::new(last.x, first.y + (last.y - first.y) / 2.0));
        assert!((turn(&h, 20) - 30.0).abs() < 3.0 && turn(&h, 0) == 0.0, "{}", turn(&h, 20));
        assert_eq!((h.app.session.history().entries().len(), h.app.session.history().undo_label(), &h.app.error), (steps + 1, Some("Pose Bones"), &None));
    }

    #[test]
    fn the_function_curves_show_an_effect_nodes_number_and_shape_it() {
        let mut h = Harness::new();
        let layer = h.app.layer.unwrap();
        h.app.run("shot.setDuration", json!({ "frames": 24 }));
        let node = h.app.run_for("effect.new", json!({ "kind": "transparency", "on": { "layer": layer.0 } })).unwrap()["id"].as_u64().unwrap();
        h.app.run("effect.set", json!({ "effect": node, "param": "amount", "value": 0 }));
        h.app.run("effect.setKey", json!({ "effect": node, "frame": 0 }));
        h.app.run("effect.set", json!({ "effect": node, "param": "amount", "value": 100, "frame": 20 }));
        run(&mut h, "panel.curves");
        // Picked alone, the node is what the curves are of.
        h.app.picked = [node].into();
        h.frame(vec![]);
        h.frame(vec![]);
        let key = |h: &Harness, frame: u32| h.app.curves.keys.iter().find(|(at, _)| *at == frame).expect("the keyframe is on the curve").1;
        let handle = |h: &Harness, frame: u32, out: bool| h.app.curves.handles.iter().find(|(at, side, _)| (*at, *side) == (frame, out)).expect("a handle").2;
        let amount = |h: &Harness, frame: u32| h.app.session.project().shots[0].effect(iskra_model::EffectId(node)).unwrap().number("amount", frame);
        assert!(key(&h, 20).y < key(&h, 0).y - 20.0, "the number rises: {:?}", h.app.curves.keys);
        assert_eq!(amount(&h, 10), 50.0);
        // A keyframe dragged down lowers the number there, within its range.
        let last = key(&h, 20);
        h.drag_between(last, Pos2::new(last.x, (last.y + key(&h, 0).y) / 2.0));
        assert!(
            (amount(&h, 20) - 50.0).abs() < 8.0 && h.app.session.history().undo_label() == Some("Set Effect") && h.app.error.is_none(),
            "{}",
            amount(&h, 20)
        );
        // The handle out of the first keyframe, laid level, starts the number slowly.
        let (first, out) = (key(&h, 0), handle(&h, 0, true));
        let before = amount(&h, 5);
        h.drag_between(out, Pos2::new(out.x, first.y));
        assert!(amount(&h, 5) < before - 1.0 && h.app.session.history().undo_label() == Some("Set Keyframe Ease"), "{} then {}", before, amount(&h, 5));
        assert_eq!(&h.app.error, &None);
    }

    #[test]
    fn a_group_of_the_brushes_panel_folds_by_a_click_on_its_name() {
        let mut h = Harness::new();
        run(&mut h, "panel.brushes");
        h.frame(vec![]);
        let all = h.app.brushes_panel.drawn.len();
        let (group, name) = h.app.brushes_panel.headers.first().cloned().expect("a group");
        click(&mut h, name.center());
        // Once it has folded away.
        for _ in 0..30 {
            h.frame(vec![]);
        }
        let folded = h.app.brushes_panel.drawn.len();
        assert!(folded < all, "{group} folds: {folded} of {all} drawn");
        click(&mut h, name.center());
        for _ in 0..30 {
            h.frame(vec![]);
        }
        assert_eq!(h.app.brushes_panel.drawn.len(), all, "and unfolds");
    }

    #[test]
    fn the_interfaces_colours_are_listed_in_settings_and_kept_with_the_preferences() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("preferences.json");
        let mut h = Harness::new();
        h.app = IskraApp::new(Session::new()).with_preferences(path.clone());
        h.app.settings = Some(settings::Section::Interface);
        h.frame(vec![]);
        h.frame(vec![]);
        let listed: Vec<theme::Role> = h.app.colour_rows.iter().map(|(role, _)| *role).collect();
        assert_eq!(listed, theme::Role::ALL, "every colour has its row");
        // One set is what the interface is drawn with, in either appearance, and what is burned in.
        let green = Color32::from_rgb(20, 200, 90);
        h.app.prefs.colours.insert(theme::Role::Animate, green.to_srgba_unmultiplied());
        h.app.prefs.colours.insert(theme::Role::Guides, [200, 0, 200, 255]);
        h.app.prefs.colours.insert(theme::Role::Accent, [0, 120, 255, 255]);
        h.frame(vec![]);
        let theme = Theme::of(&h.ctx);
        assert_eq!((theme.colour(theme::Role::Animate), theme.accent), (green, Color32::from_rgb(0, 120, 255)));
        h.app.prefs.appearance = theme::Appearance::Light;
        h.frame(vec![]);
        assert_eq!((Theme::of(&h.ctx).dark, Theme::of(&h.ctx).colour(theme::Role::Animate)), (false, green));
        h.app.burn_what_is_shown();
        assert_eq!(h.app.export.settings.burn_in.guide_colour, [200, 0, 200]);
        // Kept in the preferences file; one taken back to its default is the theme's again.
        h.frame(vec![]);
        let read = IskraApp::new(Session::new()).with_preferences(path);
        assert_eq!(read.prefs.colours, h.app.prefs.colours);
        h.app.prefs.colours.remove(&theme::Role::Accent);
        h.frame(vec![]);
        assert_eq!(Theme::of(&h.ctx).accent, Theme::light().accent);
    }

    #[test]
    fn the_settings_window_has_its_sections_and_keeps_or_fixes_the_workspace() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("preferences.json");
        let mut h = Harness::new();
        h.app = IskraApp::new(Session::new()).with_preferences(path.clone());
        h.frame(vec![]);
        // Cmd+, opens it at General; a click on a section's name shows that one.
        assert_eq!(h.app.keymap.chords(SETTINGS).first().map(|chord| String::from(*chord)), Some("Cmd+Comma".to_string()));
        run(&mut h, SETTINGS);
        h.frame(vec![]);
        assert_eq!(h.app.settings, Some(settings::Section::General));
        let interface = h.app.settings_sections.iter().find(|(section, _)| *section == settings::Section::Interface).expect("listed").1;
        click(&mut h, interface.center());
        assert_eq!(h.app.settings, Some(settings::Section::Interface));
        // Memory and GPU reads the machine's memory.
        let memory = h.app.settings_sections.iter().find(|(section, _)| *section == settings::Section::Memory).expect("listed").1;
        click(&mut h, memory.center());
        h.frame(vec![]);
        assert_eq!(h.app.settings, Some(settings::Section::Memory));
        assert!(h.app.system_memory.is_some_and(|(_, total, free)| total > 0 && free <= total), "{:?}", h.app.system_memory);
        // The project's Format is listed apart, under the project, and shown.
        let format = h.app.settings_sections.iter().find(|(section, _)| *section == settings::Section::Format).expect("listed").1;
        assert!(format.top() > memory.bottom());
        click(&mut h, format.center());
        assert_eq!((h.app.settings, &h.app.error), (Some(settings::Section::Format), &None));
        press(&mut h, Modifiers::NONE, Key::Escape);
        assert_eq!(h.app.settings, None);
        // Workspace changes not kept: the next start opens the pages as they were when that
        // was switched off, whatever was moved since.
        h.app.prefs.keep_layouts = false;
        h.app.prefs.fixed_layouts = Some(h.app.prefs.layouts.clone());
        let fixed = h.app.prefs.layouts.clone();
        h.app.close_panel(Panel::Properties);
        h.frame(vec![]);
        h.frame(vec![]);
        assert!(h.app.prefs.layouts != fixed);
        let read = IskraApp::new(Session::new()).with_preferences(path.clone());
        assert_eq!(read.prefs.layouts, fixed);
        // Kept, it opens as it was left.
        h.app.prefs.keep_layouts = true;
        h.frame(vec![]);
        h.frame(vec![]);
        let read = IskraApp::new(Session::new()).with_preferences(path);
        assert_eq!(read.prefs.layouts, h.app.prefs.layouts);
    }

    #[test]
    fn a_key_pressed_in_shortcuts_binds_it_takes_it_and_is_kept_as_the_users_keymap() {
        let dir = tempfile::tempdir().unwrap();
        let mut h = Harness::new();
        h.app = IskraApp::new(Session::new()).with_preferences(dir.path().join("preferences.json"));
        h.frame(vec![]);
        run(&mut h, SETTINGS);
        h.frame(vec![]);
        let shortcuts = h.app.settings_sections.iter().find(|(section, _)| *section == settings::Section::Shortcuts).expect("listed").1;
        click(&mut h, shortcuts.center());
        h.frame(vec![]);
        // Searched, the table shows the tools alone.
        h.app.shortcut_search = "eraser".to_string();
        for _ in 0..3 {
            h.frame(vec![]);
        }
        assert!(h.app.shortcut_rows.iter().all(|(id, _)| id.contains("eraser")), "{:?}", h.app.shortcut_rows);
        let eraser = h.app.shortcut_rows.iter().find(|(id, _)| *id == "tool.eraser").expect("the Eraser is listed").1;
        // A click, and the key pressed: the Eraser has the Brush's key, which runs nothing now.
        let tool = h.app.tools.tool;
        click(&mut h, eraser.center());
        assert_eq!(h.app.shortcut_capture, Some("tool.eraser"));
        press(&mut h, Modifiers::ALT, Key::B);
        h.frame(vec![]);
        assert_eq!((h.app.shortcut_capture, h.app.tools.tool), (None, tool));
        let key = |text| keymap::Chord::parse(text).unwrap();
        assert_eq!((h.app.keymap.chords("tool.eraser"), h.app.keymap.chords("tool.brush")), (&[key("Alt+B")][..], &[][..]));
        assert_eq!(h.app.shortcut_note.as_deref(), Some("Alt+B was taken from Brush"));
        // The preset is kept as the user's own, which is the keymap from now on.
        assert_eq!(h.app.prefs.keymap, "Harmony (mine)");
        assert!(dir.path().join("keymaps").join("Harmony (mine).json").is_file());
        // Escape while a key is waited for leaves the key, and the window, as they were.
        let eraser = h.app.shortcut_rows.iter().find(|(id, _)| *id == "tool.eraser").expect("the Eraser is listed").1;
        click(&mut h, eraser.center());
        assert_eq!(h.app.shortcut_capture, Some("tool.eraser"));
        press(&mut h, Modifiers::NONE, Key::Escape);
        h.frame(vec![]);
        assert_eq!((h.app.shortcut_capture, h.app.settings), (None, Some(settings::Section::Shortcuts)));
        assert_eq!(h.app.keymap.chords("tool.eraser"), [key("Alt+B")]);
        // On the Storyboard page alone, the Eraser has another key.
        h.app.shortcut_page = Some(Page::Storyboard);
        for _ in 0..3 {
            h.frame(vec![]);
        }
        let eraser = h.app.shortcut_rows.iter().find(|(id, _)| *id == "tool.eraser").expect("the Eraser is listed").1;
        click(&mut h, eraser.center());
        press(&mut h, Modifiers::ALT, Key::X);
        h.frame(vec![]);
        assert_eq!(h.app.keymap.on(Page::Storyboard).chords("tool.eraser"), [key("Alt+X")]);
        assert_eq!(h.app.keymap.on(Page::Animation).chords("tool.eraser"), [key("Alt+B")]);
        // Closed, the new key runs the Eraser on the Animation page.
        press(&mut h, Modifiers::NONE, Key::Escape);
        h.app.page = Page::Animation;
        h.frame(vec![]);
        press(&mut h, Modifiers::ALT, Key::B);
        h.frame(vec![]);
        assert_eq!(h.app.tools.tool, Tool::Eraser);
        // What was changed is in the user's file.
        let read = keymap::Keymap::named("Harmony (mine)", Some(&dir.path().join("keymaps")));
        assert_eq!(read, h.app.keymap);
    }

    fn peg_transform_at(h: &Harness, peg: PegId, frame: u32) -> Transform {
        h.app.session.project().shots[0].peg(peg).expect("the peg is in the shot").transform_at(frame)
    }

    #[test]
    fn the_brushes_panel_lists_presets_and_a_click_takes_one_as_the_brush_in_hand() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("preferences.json");
        let mut h = Harness::swatches();
        h.app = IskraApp::new(Session::new()).with_preferences(path.clone());
        h.frame(vec![]);
        h.frame(vec![]);
        assert_eq!((h.app.brushes.in_hand.raster.name.as_str(), h.app.brushes.in_hand.raster.brush.size), ("Pen", 8.0));
        run(&mut h, "panel.brushes");
        h.frame(vec![]);
        let at = |h: &Harness, name: &str| h.app.brushes_panel.drawn.iter().find(|(preset, _)| preset == name).map(|(_, rect)| rect.center());
        let raster = |brushes: &iskra_drawing::Brushes| brushes.listed_of(iskra_drawing::BrushKind::Raster).count();
        assert_eq!(h.app.brushes_panel.drawn.len(), raster(&h.app.brushes), "every raster preset of the engine is listed, the vector ones folded away");

        // A preset brings its size; the smoothing is the tool's and stays.
        h.app.brushes.in_hand.raster.brush.smoothing.amount = 0.5;
        h.app.tools.tool = Tool::Select;
        let soft = at(&h, "Soft Round").expect("listed");
        click(&mut h, soft);
        let held = h.app.brushes.in_hand.raster.clone();
        assert_eq!((held.name.as_str(), held.brush.size, held.brush.hardness, held.brush.smoothing.amount), ("Soft Round", 45.0, 0.0, 0.5));
        assert_eq!(h.app.tools.tool, Tool::Brush, "a brush is taken to draw with");

        // The stroke is drawn by the brush in hand: as wide as the preset is.
        h.app.brushes.in_hand.raster.brush.smoothing.amount = 0.0;
        h.drag();
        let (_, height) = h.painted().expect("painted");
        assert!((height as f32 - across(90.0, 0.0)).abs() < 8.0, "{height} pixels high for a soft brush of 45, at two pixels a unit");

        // Strokes alone, without names, are the same presets.
        h.app.prefs.brush_strokes_only = true;
        h.frame(vec![]);
        assert_eq!(h.app.brushes_panel.drawn.len(), raster(&h.app.brushes));
        h.app.prefs.brush_strokes_only = false;

        // The brush in hand is kept for the next start, beside the preferences.
        let read = IskraApp::new(Session::new()).with_preferences(path.clone());
        assert_eq!(read.brushes.in_hand.raster.name, "Soft Round");
        assert!(dir.path().join("brushes.json").exists());
    }

    #[test]
    fn the_brush_in_hand_is_tried_on_a_stroke_and_saved_as_a_preset() {
        let mut h = Harness::new();
        run(&mut h, "panel.brushes");
        h.frame(vec![]);
        assert_eq!(h.app.brushes_panel.trials, 0, "folded away, the settings draw nothing");
        // Unfolded, the brush in hand has a stroke that tries it, drawn again when it changes.
        h.app.prefs.brush_settings = true;
        h.frame(vec![]);
        h.frame(vec![]);
        assert_eq!(h.app.brushes_panel.trials, 1);
        h.app.brushes.in_hand.raster.brush.scattering.enabled = true;
        h.app.brushes.in_hand.raster.brush.scattering.scatter.jitter = 2.0;
        h.frame(vec![]);
        h.frame(vec![]);
        assert_eq!(h.app.brushes_panel.trials, 2);

        // Saved under a name, it is a preset of the user's, listed after the engine's and in hand.
        let engines = h.app.brushes.listed_of(iskra_drawing::BrushKind::Raster).count();
        run(&mut h, "brush.saveAsPreset");
        h.frame(vec![Event::Text("Spatter Pen".to_string())]);
        press(&mut h, Modifiers::NONE, Key::Enter);
        h.frame(vec![]);
        let own: Vec<(&str, &str)> = h.app.brushes.presets.iter().map(|preset| (preset.listed_group(), preset.name.as_str())).collect();
        assert_eq!(own, [(iskra_drawing::OWN_GROUP, "Spatter Pen")]);
        assert_eq!(h.app.brushes.in_hand.raster.name, "Spatter Pen");
        assert_eq!(h.app.brushes_panel.drawn.len(), engines + 1);
        assert_eq!(h.app.brushes_panel.drawn.last().map(|(name, _)| name.as_str()), Some("Spatter Pen"));

        // Escape gives the name up; a deleted brush of the engine's comes back by its command.
        run(&mut h, "brush.saveAsPreset");
        h.frame(vec![Event::Text("Other".to_string())]);
        press(&mut h, Modifiers::NONE, Key::Escape);
        assert_eq!(h.app.brushes.presets.len(), 1);
        assert!(!(commands::command("brush.restore").unwrap().enabled)(&h.app));
        assert!(h.app.brushes.delete("General", "Soft Round"));
        h.frame(vec![]);
        assert_eq!(h.app.brushes_panel.drawn.len(), engines);
        run(&mut h, "brush.restore");
        assert_eq!(h.app.brushes_panel.drawn.len(), engines + 1);
    }

    #[test]
    fn a_brush_is_taken_by_a_command_from_its_slot_or_by_its_name_in_the_palette() {
        let mut h = Harness::new();
        h.frame(vec![]);
        let listed: Vec<String> = h.app.brushes.listed().map(|preset| preset.name.clone()).collect();
        let in_hand = |h: &Harness| h.app.brushes.in_hand.raster.name.clone();
        // Next and Previous go through the list, round at its ends; a brush is taken to draw with.
        h.app.tools.tool = Tool::Select;
        run(&mut h, "brush.next");
        assert_eq!((in_hand(&h), h.app.tools.tool), (listed[0].clone(), Tool::Brush));
        run(&mut h, "brush.next");
        run(&mut h, "brush.next");
        run(&mut h, "brush.previous");
        assert_eq!(in_hand(&h), listed[1]);
        // A slot's command can run once a brush has the slot, and takes that brush.
        let slot = commands::command("brush.slot2").unwrap();
        assert!(!(slot.enabled)(&h.app));
        let last = h.app.brushes.listed_of(iskra_drawing::BrushKind::Raster).last().cloned().unwrap();
        h.app.brushes.set_slot(last.listed_group(), &last.name, Some(1));
        assert!((slot.enabled)(&h.app) && !(commands::command("brush.slot1").unwrap().enabled)(&h.app));
        run(&mut h, "brush.slot2");
        assert_eq!(in_hand(&h), last.name);
        // The palette finds brushes by their names, after the commands, once something is typed.
        assert!(commands::Palette::brushes("", &h.app.brushes).is_empty());
        let found = commands::Palette::brushes("soft round", &h.app.brushes);
        assert!(found.contains(&("General".to_string(), "Soft Round".to_string())), "{found:?}");
        assert!(
            commands::Palette::brushes("brush general", &h.app.brushes).len() > 1 && commands::Palette::brushes("no such thing", &h.app.brushes).is_empty()
        );
        h.app.take_brush("General", "Soft Round");
        assert_eq!((in_hand(&h), &h.app.error), ("Soft Round".to_string(), &None));
        // The Storyboard page has the Brushes panel in its sidebar from the start.
        assert!(dock::DockNode::for_page(Page::Storyboard).contains(Panel::Brushes));
    }

    #[test]
    fn a_brush_file_is_dropped_on_the_window_and_a_large_one_is_read_apart_and_can_be_stopped() {
        let dir = tempfile::tempdir().unwrap();
        let mut h = Harness::new();
        h.app.brushes.save_in_hand("Inker", "", iskra_drawing::BrushKind::Raster);
        let file = dir.path().join("Kit.iskrabrushes");
        let own = h.app.brushes.presets.clone();
        h.app.export_brushes(&file, &own, false);
        h.app.brushes.presets.clear();
        // Let go on the window, a brush file's brushes come in; another kind of file is said
        // to be brought in from its menu.
        h.app.files_dropped(std::slice::from_ref(&file));
        h.frame(vec![]);
        assert_eq!((h.app.brushes.presets.len(), &h.app.error), (1, &None));
        h.app.files_dropped(&[dir.path().join("picture.png")]);
        assert!(h.app.error.as_ref().is_some_and(|said| said.contains("only brush files")) && h.app.brushes.presets.len() == 1);
        h.app.error = None;
        // Read apart from the window, the file's brushes come in once it is read: the
        // window is drawn meanwhile, and says so.
        h.app.brushes.presets.clear();
        h.app.import_brushes_apart(&file);
        assert!(h.app.brush_reading.is_some());
        for _ in 0..200 {
            h.frame(vec![]);
            if h.app.brush_reading.is_none() {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
        assert_eq!((h.app.brush_reading.is_none(), h.app.brushes.presets.len(), &h.app.error), (true, 1, &None));
        // Stopped, it brings nothing in and is no error; and one file is read at a time.
        h.app.brushes.presets.clear();
        h.app.import_brushes_apart(&file);
        h.app.import_brushes_apart(&file);
        assert!(h.app.error.take().is_some_and(|said| said.contains("another file")));
        h.app.brush_reading.as_ref().unwrap().stop.store(true, std::sync::atomic::Ordering::Relaxed);
        for _ in 0..200 {
            h.frame(vec![]);
            if h.app.brush_reading.is_none() {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
        assert_eq!((h.app.brush_reading.is_none(), h.app.brushes.presets.len(), &h.app.error), (true, 0, &None));
        // A file that is not there says so.
        h.app.import_brushes_apart(&dir.path().join("none.abr"));
        for _ in 0..200 {
            h.frame(vec![]);
            if h.app.brush_reading.is_none() {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
        assert!(h.app.error.as_ref().is_some_and(|said| said.contains("could not be read")), "{:?}", h.app.error);
    }

    #[test]
    fn the_users_brushes_are_dragged_to_another_place_and_onto_a_groups_name() {
        let mut h = Harness::new();
        for (name, group) in [("One", "Inks"), ("Two", "Inks"), ("Three", "Paints")] {
            h.app.brushes.save_in_hand(name, group, iskra_drawing::BrushKind::Raster);
        }
        run(&mut h, "panel.brushes");
        h.frame(vec![]);
        // With the engine's brushes out of the list, the user's are all in view.
        h.app.brushes.hidden = iskra_drawing::builtin_brushes().iter().map(|preset| preset.name.clone()).collect();
        h.frame(vec![]);
        h.frame(vec![]);
        let at = |h: &Harness, name: &str| h.app.brushes_panel.drawn.iter().find(|(preset, _)| preset == name).map(|(_, rect)| rect.center()).unwrap();
        let header = |h: &Harness, group: &str| h.app.brushes_panel.headers.iter().find(|(name, _)| name == group).map(|(_, rect)| *rect).unwrap();
        let own = |h: &Harness| h.app.brushes.presets.iter().map(|preset| format!("{}/{}", preset.listed_group(), preset.name)).collect::<Vec<_>>();
        assert_eq!(own(&h), ["Inks/One", "Inks/Two", "Paints/Three"]);
        // One let go on another goes before it.
        h.drag_between(at(&h, "Two"), at(&h, "One"));
        assert_eq!(own(&h), ["Inks/Two", "Inks/One", "Paints/Three"]);
        // Let go on a group's name, it goes to the end of that group.
        let name = header(&h, "Paints");
        h.drag_between(at(&h, "Two"), name.center());
        assert_eq!(own(&h), ["Inks/One", "Paints/Three", "Paints/Two"]);
        // Let go on one of another group, it goes into that group, before it.
        h.drag_between(at(&h, "Three"), at(&h, "One"));
        assert_eq!(own(&h), ["Inks/Three", "Inks/One", "Paints/Two"]);
        // A group is dragged by its name before another.
        let (paints, inks) = (header(&h, "Paints"), header(&h, "Inks"));
        h.drag_between(paints.center(), inks.center());
        assert_eq!(own(&h), ["Paints/Two", "Inks/Three", "Inks/One"]);
        // A click still takes a brush.
        let one = at(&h, "One");
        click(&mut h, one);
        assert_eq!(h.app.brushes.in_hand.raster.name, "One");
    }

    #[test]
    fn brushes_go_out_to_files_and_come_in_as_presets_in_a_group_of_the_files_name() {
        let dir = tempfile::tempdir().unwrap();
        let mut h = Harness::new();
        assert!(!(commands::command("brush.export").unwrap().enabled)(&h.app), "there is nothing of the user's to export yet");
        // Two presets of the user's: a pen that pressure sizes, and one with a sampled tip.
        h.app.brushes.save_in_hand("Inker", "", iskra_drawing::BrushKind::Raster);
        let sampled =
            iskra_drawing::builtin_brushes().iter().find(|p| matches!(&p.brush, iskra_drawing::Brush::Raster(b) if b.tip != iskra_drawing::TipShape::Round));
        h.app.brushes.take(sampled.expect("the engine has sampled tips"));
        h.app.brushes.save_in_hand("Chalky", "", iskra_drawing::BrushKind::Raster);
        let own = h.app.brushes.presets.clone();

        // The app's own file carries them whole; they come in under the file's name.
        let file = dir.path().join("Kit.iskrabrushes");
        h.app.export_brushes(&file, &own, false);
        assert_eq!((&h.app.error, &h.app.brush_report), (&None, &None));
        h.app.brushes.presets.clear();
        h.app.import_brushes(&file);
        h.frame(vec![]);
        assert_eq!(h.app.brushes.presets, own, "they said their group, so they are back in it");
        assert!(h.app.brush_report.is_none() && h.app.brushes_panel.drawn.iter().any(|(name, _)| name == "Chalky"));

        // Photoshop's old kind holds the tips; the window says what was left behind, and Escape closes it.
        let abr = dir.path().join("Old.abr");
        h.app.export_brushes(&abr, &own, true);
        assert!(h.app.brush_report.as_ref().is_some_and(|(_, notes)| notes.iter().any(|note| note.contains("Inker"))), "{:?}", h.app.brush_report);
        h.frame(vec![]);
        press(&mut h, Modifiers::NONE, Key::Escape);
        assert!(h.app.brush_report.is_none());
        h.app.import_brushes(&abr);
        h.frame(vec![]);
        let groups: Vec<&str> = h.app.brushes.presets.iter().map(|preset| preset.listed_group()).collect();
        assert_eq!(groups, [iskra_drawing::OWN_GROUP, iskra_drawing::OWN_GROUP, "Old", "Old"]);
        assert_eq!(h.app.brushes.presets[3].name, "Chalky", "a sampled tip keeps its name");

        // Photoshop's new kind holds a brush with all that shapes its stroke: both come
        // back with their names and as they were.
        let new = dir.path().join("New.abr");
        h.app.export_brushes(&new, &own, false);
        // All it says is that a made pattern went as a picture of it.
        let said = h.app.brush_report.take().map(|(_, notes)| notes).unwrap_or_default();
        assert!(h.app.error.is_none() && said.len() == 1 && said[0].contains("made pattern"), "{said:?}");
        h.app.import_brushes(&new);
        h.frame(vec![]);
        let came: Vec<&iskra_drawing::BrushPreset> = h.app.brushes.presets.iter().filter(|preset| preset.listed_group() == "New").collect();
        assert_eq!(came.iter().map(|preset| preset.name.as_str()).collect::<Vec<_>>(), ["Inker", "Chalky"]);
        let (iskra_drawing::Brush::Raster(was), iskra_drawing::Brush::Raster(is)) = (&own[0].brush, &came[0].brush) else { panic!("raster brushes") };
        assert_eq!((is.pressure_size, is.size, is.shape_dynamics.enabled), (was.pressure_size, was.size, was.shape_dynamics.enabled));
        assert!(h.app.brush_report.is_none(), "{:?}", h.app.brush_report);

        // A file that is no brush file says so in the status bar, and adds nothing.
        std::fs::write(dir.path().join("Bad.abr"), b"nothing of the kind").unwrap();
        h.app.import_brushes(&dir.path().join("Bad.abr"));
        assert!(h.app.error.is_some() && h.app.brushes.presets.len() == 6);
    }

    #[test]
    fn skins_are_imported_onto_the_character_of_the_peg_in_hand_from_a_window() {
        use photocraft_psd::{LayerSpec, PixelData, PsdBuilder};
        let dir = tempfile::tempdir().unwrap();
        let file = |name: &str, color: [u8; 4]| {
            let mut builder = PsdBuilder::new(200, 100);
            builder.push_layer(LayerSpec::new("body", 90, 40, 20, 20, PixelData::Rgba8(color.repeat(400))));
            let path = dir.path().join(name);
            std::fs::write(&path, builder.to_bytes().unwrap()).unwrap();
            path
        };
        let mut h = Harness::new();
        h.app.import_character(&file("hero.psd", [255, 0, 0, 255]));
        let peg = h.app.peg.expect("the character's peg is in hand");
        h.app.open_skins_import(&file("night.psd", [0, 0, 90, 255]));
        assert!(h.app.importing_skins.as_ref().is_some_and(|import| import.untagged && import.tagged.is_empty()));
        h.frame(vec![]);
        // Not until the untagged parts' skin is named.
        let button = h.app.skins_import_button.unwrap();
        click(&mut h, button.center());
        assert!(h.app.importing_skins.is_some() && h.app.session.project().skins().is_empty());
        h.app.importing_skins.as_mut().unwrap().name = "Night".to_string();
        h.frame(vec![]);
        let button = h.app.skins_import_button.unwrap();
        click(&mut h, button.center());
        let project = h.app.session.project().clone();
        let body = project.shots[0].layers.iter().find(|layer| layer.name == "body").unwrap();
        assert!(h.app.importing_skins.is_none() && body.variant(project.skin_named("Night").unwrap().id, body.drawings[0].id).is_some());
        assert_eq!(h.app.peg, Some(peg));
    }

    #[test]
    fn a_character_file_all_in_skins_asks_which_is_the_day_one() {
        use photocraft_psd::{LayerSpec, PixelData, PsdBuilder};
        let dir = tempfile::tempdir().unwrap();
        let part = |name: &str| LayerSpec::new(name, 90, 40, 20, 20, PixelData::Rgba8([200, 0, 0, 255].repeat(400)));
        let mut builder = PsdBuilder::new(200, 100);
        builder.push_layer(part("[skin Day] body"));
        builder.push_layer(part("[skin Night] body"));
        let path = dir.path().join("skins.psd");
        std::fs::write(&path, builder.to_bytes().unwrap()).unwrap();
        let mut h = Harness::new();
        let before = h.app.session.project().shots[0].layers.len();
        h.app.import_character(&path);
        assert_eq!(h.app.day_skin, Some((path.clone(), vec!["Day".to_string(), "Night".to_string()])), "it is asked, and nothing is brought in yet");
        assert_eq!(h.app.session.project().shots[0].layers.len(), before);
        h.frame(vec![]);
        // Night picked as the day one: Day's parts are its variants.
        h.app.day_skin = None;
        h.app.import_character_with(&path, Some("Night"));
        let project = h.app.session.project().clone();
        let body = project.shots[0].layers.iter().find(|layer| layer.name == "body").unwrap();
        assert!(body.variant(project.skin_named("Day").unwrap().id, body.drawings[0].id).is_some() && h.app.error.is_none());
    }

    #[test]
    fn the_picker_shows_the_drawings_as_the_skin_has_them_under_the_day_ids() {
        let mut h = Harness::new();
        h.drag();
        let (shot, layer) = (h.app.shot.unwrap(), h.app.layer.unwrap());
        h.app.run("skin.add", json!({ "name": "Night", "shot": shot.0 }));
        h.frame(vec![]);
        // A stroke makes the first drawing's variant; a second drawing has none.
        h.drag_between(Pos2::new(300.0, 250.0), Pos2::new(700.0, 250.0));
        h.app.run("drawing.newDrawing", json!({ "layer": layer.0, "frame": 2 }));
        run(&mut h, "panel.substitution");
        h.frame(vec![]);
        let days: Vec<_> = h.app.session.project().layer(layer).unwrap().drawings.iter().map(|d| d.id).collect();
        let listed: Vec<_> = h.app.substitution.drawn.iter().map(|(id, _)| *id).collect();
        assert_eq!((listed, h.app.substitution.day_marked.clone()), (days.clone(), vec![days[1]]), "the day ids, the one with no variant marked");
        // With the day drawings shown, none is marked.
        h.app.run("shot.setSkin", json!({ "shot": shot.0 }));
        h.frame(vec![]);
        assert!(h.app.substitution.day_marked.is_empty());
    }

    #[test]
    fn the_substitution_picker_shows_a_layers_drawings_and_swaps_the_one_on_the_frame() {
        let mut h = Harness::new();
        h.app.run("shot.setDuration", json!({ "frames": 8 }));
        let layer = h.app.layer.unwrap();
        // Three mouths; the first is held for the whole shot.
        h.drag();
        for frame in [1, 2] {
            h.app.prefs.new_drawing_hold = crate::prefs::NewDrawingHold::Frames(1);
            h.app.run("drawing.newDrawing", json!({ "layer": layer.0, "frame": frame }));
        }
        h.app.run("exposure.set", json!({ "layer": layer.0, "frame": 0, "length": 8, "drawing": h.app.session.project().shots[0].layers[0].drawings[0].id.0 }));
        assert_eq!(cells(&h, 8), "1 1 1 1 1 1 1 1");
        run(&mut h, "panel.substitution");
        h.frame(vec![]);
        let ids: Vec<_> = h.app.session.project().shots[0].layers[0].drawings.iter().map(|d| d.id).collect();
        let thumb =
            |h: &Harness, index: usize| h.app.substitution.drawn.iter().find(|(id, _)| *id == ids[index]).expect("every drawing has a thumbnail").1.center();
        assert_eq!(h.app.substitution.drawn.len(), 3);

        // A click swaps the drawing held here, from this frame to the end of the hold.
        h.app.tools.frame = 4;
        let second = thumb(&h, 1);
        click(&mut h, second);
        assert_eq!((cells(&h, 8).as_str(), h.app.tools.frame, &h.app.error), ("1 1 1 1 2 2 2 2", 4, &None));
        assert_eq!(h.app.session.history().undo_label(), Some("Set Exposure"));
        // Set to move on by two, each click is a mouth for two frames: one click a shape.
        h.app.prefs.substitution_advance = 2;
        h.app.tools.frame = 0;
        for index in [2, 1, 0] {
            let at = thumb(&h, index);
            click(&mut h, at);
        }
        assert_eq!((cells(&h, 8).as_str(), h.app.tools.frame), ("3 3 2 2 1 1 2 2", 6));
        // The keys go round the layer's drawings on the frame.
        h.app.prefs.substitution_advance = 0;
        run(&mut h, "substitution.next");
        assert_eq!(cells(&h, 8), "3 3 2 2 1 1 3 3");
        run(&mut h, "substitution.next");
        run(&mut h, "substitution.previous");
        assert_eq!(cells(&h, 8), "3 3 2 2 1 1 3 3");
        // The tile after the drawings puts a new empty one on the frame.
        h.app.tools.frame = 6;
        let new = h.app.substitution.new_tile.expect("a tile for a new drawing").center();
        click(&mut h, new);
        let layer = &h.app.session.project().shots[0].layers[0];
        assert_eq!((layer.drawings.len(), &h.app.error), (4, &None));
        assert!(layer.drawing_at(6).is_some_and(|drawing| drawing.id == layer.drawings[3].id && drawing.drawing.bounds().is_empty()));
        h.frame(vec![]);
        assert_eq!(h.app.substitution.drawn.len(), 4);
        // A thumbnail's menu renames the drawing, the name typed under it, and deletes it,
        // leaving the frames that showed it empty.
        let menu = |h: &mut Harness, index: usize, item: &str| {
            let at = thumb(h, index);
            let secondary = |pos, pressed| Event::PointerButton { pos, button: PointerButton::Secondary, pressed, modifiers: Modifiers::NONE };
            h.frame(vec![Event::PointerMoved(at)]);
            h.frame(vec![secondary(at, true)]);
            h.frame(vec![secondary(at, false)]);
            h.frame(vec![]);
            let button = h.app.substitution.menu.iter().find(|(name, _)| *name == item).unwrap_or_else(|| panic!("the menu has {item}")).1;
            click(h, button.center());
            h.frame(vec![]);
        };
        menu(&mut h, 1, "Rename");
        h.frame(vec![Event::Text("mouth-O".to_string())]);
        h.frame(vec![Event::Key { key: Key::Enter, physical_key: None, pressed: true, repeat: false, modifiers: Modifiers::NONE }]);
        h.frame(vec![]);
        let names = |h: &Harness| h.app.session.project().shots[0].layers[0].drawings.iter().map(|d| d.name.clone()).collect::<Vec<_>>().join(" ");
        assert_eq!((names(&h).as_str(), h.app.session.history().undo_label(), &h.app.error), ("1 mouth-O 3 4", Some("Rename Drawing"), &None));
        menu(&mut h, 1, "Delete");
        assert_eq!((names(&h).as_str(), cells(&h, 8).as_str(), &h.app.error), ("1 3 4", "3 3 - - 1 1 4 3", &None));
        // With a peg selected there is no layer to show.
        run(&mut h, "peg.new");
        h.frame(vec![]);
        assert!(h.app.substitution.drawn.len() == 3 && !(commands::command("substitution.next").unwrap().enabled)(&h.app));
    }

    #[test]
    fn dragging_along_the_ruler_moves_the_playhead_and_along_a_layer_picks_its_frames() {
        let mut h = Harness::new();
        h.app.prefs.new_drawing_hold = crate::prefs::NewDrawingHold::Frames(1);
        let layer = h.app.layer.unwrap();
        h.app.run("drawing.newDrawing", json!({ "layer": layer.0, "frame": 0 }));
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        h.frame(vec![]);
        // The peg's row is over the layer's. The handle of the drawing on frame 0 says where the
        // layer's cells are: sixteen points a frame.
        let handle = h.app.timeline.hold_handles[0].2;
        let cell = |frame: f32, row: f32| Pos2::new(handle.right() + 1.5 + 16.0 * (frame - 0.5), handle.center().y + 22.0 * row);
        let picked = |h: &Harness| h.app.timeline.frames.map(|picked| (picked.layer, picked.first, picked.last));

        // Pressed on the layer's row and dragged along it, and up across the peg's: the press
        // selects the layer and puts the playhead there, and the drag picks the layer's frames.
        h.drag_between(cell(3.0, 0.0), cell(7.0, -2.0));
        assert_eq!((h.app.tools.frame, h.app.layer, h.app.peg, picked(&h)), (3, Some(layer), None, Some((layer, 3, 7))));
        let mark = h.app.timeline.frames_mark.expect("the picked frames are marked");
        assert!((mark.left() - (cell(3.0, 0.0).x - 8.0)).abs() < 1.0 && (mark.width() - 5.0 * 16.0).abs() < 2.0, "{mark:?}");
        // Backwards picks as well.
        h.drag_between(cell(9.0, 0.0), cell(8.0, 0.0));
        assert_eq!((h.app.tools.frame, picked(&h)), (9, Some((layer, 8, 9))));
        // Pressed on the ruler and dragged down across both rows: the playhead goes along, and
        // nothing is selected or picked by it.
        h.drag_between(cell(7.0, -2.0), cell(2.0, 0.0));
        assert_eq!((h.app.tools.frame, h.app.layer, h.app.peg, picked(&h)), (2, Some(layer), None, Some((layer, 8, 9))));
        // Pressed on the peg's row and dragged down over the layer's: the peg, and it stays.
        // On a row of keyframes the drag pulls out the box that picks them, so the playhead
        // stays too.
        h.drag_between(cell(4.0, -1.0), cell(9.0, 0.0));
        assert_eq!((h.app.tools.frame, h.app.layer, h.app.peg), (2, None, Some(peg)));
        // A click still selects the row it is on, and picks the frame it is on alone; with
        // Shift, from the frame picked to the one clicked. On the ruler it lets them go.
        click(&mut h, cell(5.0, 0.0));
        assert_eq!((h.app.tools.frame, h.app.layer, h.app.peg, picked(&h)), (5, Some(layer), None, Some((layer, 5, 5))));
        let shift = Modifiers { shift: true, ..Modifiers::NONE };
        let at = cell(8.0, 0.0);
        h.frame(vec![Event::ModifiersChanged(shift), Event::PointerMoved(at)]);
        h.frame(vec![Event::PointerButton { pos: at, button: PointerButton::Primary, pressed: true, modifiers: shift }]);
        h.frame(vec![Event::PointerButton { pos: at, button: PointerButton::Primary, pressed: false, modifiers: shift }]);
        h.frame(vec![Event::ModifiersChanged(Modifiers::NONE)]);
        assert_eq!(picked(&h), Some((layer, 5, 8)));
        click(&mut h, cell(5.0, -2.0));
        assert_eq!(picked(&h), None);
    }

    #[test]
    fn frames_picked_on_a_layers_row_are_moved_copied_pasted_and_deleted() {
        let mut h = Harness::new();
        h.app.prefs.new_drawing_hold = crate::prefs::NewDrawingHold::Frames(1);
        let layer = h.app.layer.unwrap();
        for frame in [0, 1, 2] {
            h.app.run("drawing.newDrawing", json!({ "layer": layer.0, "frame": frame }));
        }
        h.frame(vec![]);
        assert_eq!(cells(&h, 10), "1 2 3 - - - - - - -");
        let handle = h.app.timeline.hold_handles.iter().find(|(_, start, _)| *start == 0).unwrap().2;
        let cell = |frame: f32| Pos2::new(handle.right() + 1.5 + 16.0 * (frame - 0.5), handle.center().y);
        let picked = |h: &Harness| h.app.timeline.frames.map(|picked| (picked.first, picked.last));
        let enabled = |h: &Harness, id: &str| (commands::command(id).unwrap().enabled)(&h.app);
        assert!(!enabled(&h, "edit.copy") && !enabled(&h, "edit.delete"));

        // Two frames are picked by a drag, and dragged four frames along by a second: what
        // they showed goes with them and leaves empty cells, in one step. The playhead stays.
        h.drag_between(cell(1.0), cell(2.0));
        assert_eq!((picked(&h), h.app.tools.frame), (Some((1, 2)), 1));
        let steps = h.app.session.history().entries().len();
        h.drag_between(cell(2.0), cell(6.0));
        assert_eq!((cells(&h, 10).as_str(), picked(&h), h.app.tools.frame, &h.app.error), ("1 - - - - 2 3 - - -", Some((5, 6)), 1, &None));
        assert_eq!((h.app.session.history().entries().len(), h.app.session.history().undo_label()), (steps + 1, Some("Move Frames")));
        // They can't be dragged off the front of the shot.
        h.drag_between(cell(5.0), cell(5.0) - egui::vec2(200.0, 0.0));
        assert_eq!((cells(&h, 10).as_str(), picked(&h)), ("2 3 - - - - - - - -", Some((0, 1))));
        h.app.session.undo();
        h.frame(vec![]);
        h.app.timeline.frames = Some(timeline::Frames { layer, first: 5, last: 6 });

        // Copied, and pasted at the playhead: the pasted frames are the ones picked then.
        assert!(enabled(&h, "edit.copy"));
        run(&mut h, "edit.copy");
        h.app.tools.frame = 8;
        run(&mut h, "edit.paste");
        assert_eq!((cells(&h, 10).as_str(), picked(&h), h.app.session.history().undo_label()), ("1 - - - - 2 3 - 2 3", Some((8, 9)), Some("Paste Frames")));
        // Cut, they leave empty cells, and are pasted elsewhere.
        run(&mut h, "edit.cut");
        assert_eq!(cells(&h, 10), "1 - - - - 2 3 - - -");
        h.app.tools.frame = 3;
        run(&mut h, "edit.paste");
        assert_eq!((cells(&h, 10).as_str(), picked(&h)), ("1 - - 2 3 2 3 - - -", Some((3, 4))));
        // Deleted by the key, they are empty cells; Escape lets them go.
        press(&mut h, Modifiers::NONE, Key::Delete);
        assert_eq!((cells(&h, 10).as_str(), picked(&h), &h.app.error), ("1 - - - - 2 3 - - -", Some((3, 4)), &None));
        press(&mut h, Modifiers::NONE, Key::Escape);
        assert_eq!(picked(&h), None);
        // On another layer there are none of these drawings: the paste says so.
        run(&mut h, "layer.new");
        h.app.copied_frames = h.app.copied_frames.take().map(|(_, cells)| (h.app.layer.unwrap(), cells));
        run(&mut h, "edit.paste");
        assert!(h.app.error.as_deref().is_some_and(|error| error.contains("the layer they were copied from")), "{:?}", h.app.error);
    }

    #[test]
    fn an_effect_node_is_seen_in_the_viewport_and_set_in_properties() {
        let mut h = Harness::new();
        h.drag();
        let layer = h.app.layer.unwrap();
        let tiles = h.app.viewport.tiles_shown();
        assert!(tiles > 0 && h.app.viewport.through_shown == (0, 0));
        // Added as the node view's menu adds it: on the wire that leaves the layer.
        let ctx = h.ctx.clone();
        h.app.timeline_actions(&ctx, vec![Action::Run("effect.new", json!({ "kind": "transparency", "on": { "layer": layer.0 } }))]);
        h.frame(vec![]);
        let shot = |h: &Harness| h.app.session.project().shots[0].clone();
        let node = shot(&h).effects[0].id;
        // What goes through it is shown as the one picture the node makes, not from tiles;
        // the picture is made once and shown again while the shot stays the same.
        assert_eq!((h.app.viewport.through_shown, h.app.viewport.tiles_shown(), &h.app.error), ((1, 1), 0, &None));
        h.frame(vec![]);
        assert_eq!(h.app.viewport.through_shown, (1, 0));
        // In the node view it lies between the layer and the composite.
        let places = nodes::layout(&shot(&h));
        let (above, at, below) =
            (places[&nodes::Item::Layer(layer)], places[&nodes::Item::Effect(node)], places[&nodes::Item::Composite(shot(&h).composites[0].id)]);
        assert!(above.y < at.y && at.y < below.y, "{above:?} {at:?} {below:?}");

        // Picked alone, Properties shows its parameters; a number let go is the project's.
        h.app.picked = [node.0].into();
        h.frame(vec![]);
        h.app.effect_edit = Some((node, "amount".to_string(), 80.0));
        h.frame(vec![]);
        let amount = |h: &Harness, frame: u32| shot(h).effect(node).unwrap().number("amount", frame);
        assert_eq!((amount(&h, 0), h.app.session.history().undo_label(), &h.app.error, &h.app.effect_edit), (80.0, Some("Set Effect"), &None, &None));
        assert_eq!(h.app.viewport.live_effect, Some((node, "amount".to_string(), iskra_model::Value::Number(80.0))), "shown while in hand");
        h.frame(vec![]);
        assert_eq!((h.app.viewport.through_shown.0, &h.app.viewport.live_effect), (1, &None), "and the picture is of the node as it is now");
        // Keyed, a number that is changed on another frame is keyed there.
        h.app.run("effect.setKey", json!({ "effect": node.0, "frame": 0 }));
        h.app.tools.frame = 10;
        h.frame(vec![]);
        h.app.effect_edit = Some((node, "amount".to_string(), 20.0));
        h.frame(vec![]);
        assert_eq!((amount(&h, 0), amount(&h, 10), &h.app.error), (80.0, 20.0, &None));
        // A number in hand is what the viewport shows, on every frame, before the project has it.
        h.app.viewport.live_effect = Some((node, "amount".to_string(), iskra_model::Value::Number(50.0)));
        let posed = h.app.viewport.posed(&h.app.session.project().shots[0]).into_owned();
        assert_eq!((posed.effect(node).unwrap().number("amount", 0), posed.effect(node).unwrap().number("amount", 10), amount(&h, 10)), (50.0, 50.0, 20.0));
        h.app.viewport.live_effect = None;
        // Switched off, the layer is drawn from its tiles again.
        h.app.run("effect.setEnabled", json!({ "effect": node.0, "enabled": false }));
        h.frame(vec![]);
        assert!(h.app.viewport.through_shown == (0, 0) && h.app.viewport.tiles_shown() > 0);
        // A Visible node shows what comes into it from its tiles, as it came; switched to
        // hidden on a frame, nothing of it is in the viewport there. Its switch has a row in
        // Properties as any parameter has.
        let visible = h.app.run_for("effect.new", json!({ "kind": "visible", "on": { "layer": layer.0 } })).unwrap()["id"].as_u64().unwrap();
        h.app.picked = [visible].into();
        h.frame(vec![]);
        assert!(h.app.viewport.through_shown == (0, 0) && h.app.viewport.tiles_shown() > 0 && h.app.error.is_none());
        h.app.run("effect.setKey", json!({ "effect": visible, "frame": 0 }));
        h.app.run("effect.set", json!({ "effect": visible, "param": "shown", "frame": 10, "value": false }));
        h.frame(vec![]);
        assert_eq!((h.app.viewport.tiles_shown(), &h.app.error), (0, &None), "hidden on the frame that is showing");
        h.app.tools.frame = 5;
        h.frame(vec![]);
        assert!(h.app.viewport.tiles_shown() > 0, "and shown on one before");
    }

    #[test]
    fn a_style_node_is_seen_in_the_viewport_and_lists_the_palettes_and_styles_in_properties() {
        let mut h = Harness::new();
        h.drag();
        let layer = h.app.layer.unwrap();
        h.app.run("palette.addStyle", json!({ "name": "Night" }));
        let ctx = h.ctx.clone();
        h.app.timeline_actions(&ctx, vec![Action::Run("effect.new", json!({ "kind": "style", "on": { "layer": layer.0 } }))]);
        h.frame(vec![]);
        let node = h.app.session.project().shots[0].effects[0].id;
        assert_eq!((h.app.viewport.through_shown.0, &h.app.error), (1, &None), "what goes through is the node's one picture");
        // Picked, Properties offers the styles by name, with one of a name no palette has
        // marked; neither is refused.
        assert_eq!(h.app.session.project().palette.style_names(""), ["Night"]);
        h.app.picked = [node.0].into();
        for style in ["Night", "Dusk", ""] {
            h.app.run("effect.set", json!({ "effect": node.0, "param": "style", "value": style }));
            h.frame(vec![]);
            assert_eq!((h.app.session.project().shots[0].effect(node).unwrap().text("style"), &h.app.error), (style.to_string(), &None));
        }
        // And the palettes by name, with the styles of the one picked.
        h.app.run("palette.new", json!({ "name": "Hero" }));
        for palette in ["Hero", "Sky", ""] {
            h.app.run("effect.set", json!({ "effect": node.0, "param": "palette", "value": palette }));
            h.frame(vec![]);
            assert_eq!((h.app.session.project().shots[0].effect(node).unwrap().text("palette"), &h.app.error), (palette.to_string(), &None));
        }
        assert!(h.app.session.project().palette.style_names("Hero").is_empty());
    }

    #[test]
    fn an_effect_node_that_can_be_keyed_has_a_row_on_the_timeline() {
        let mut h = Harness::new();
        h.app.prefs.new_drawing_hold = crate::prefs::NewDrawingHold::Frames(1);
        let layer = h.app.layer.unwrap();
        h.app.run("drawing.newDrawing", json!({ "layer": layer.0, "frame": 0 }));
        let node = h.app.run_for("effect.new", json!({ "kind": "transparency", "on": { "layer": layer.0 } })).unwrap()["id"].as_u64().unwrap();
        let node = iskra_model::EffectId(node);
        h.frame(vec![]);
        // It can be keyed, so it has a row before it has a key.
        assert!(matches!(h.app.timeline.effect_names[..], [(named, _)] if named == node), "{:?}", h.app.timeline.effect_names);
        h.app.run("effect.setKey", json!({ "effect": node.0, "frame": 0 }));
        h.app.run("effect.set", json!({ "effect": node.0, "param": "amount", "value": 100, "frame": 10 }));
        h.frame(vec![]);
        // Keyed, its row is under its layer's, with its keys and the line between them.
        let [(named, name)] = h.app.timeline.effect_names[..] else { panic!("one effect row: {:?}", h.app.timeline.effect_names) };
        let layer_name = h.app.timeline.names.iter().find(|(of, _)| *of == Node::Layer(layer)).unwrap().1;
        assert!(named == node && name.top() > layer_name.top() && name.left() > layer_name.left());
        let mark =
            |h: &Harness, frame: u32| h.app.timeline.effect_key_marks.iter().find(|(of, at, _)| (*of, *at) == (node, frame)).expect("the key has a mark").2;
        assert!((mark(&h, 0).center().y - name.center().y).abs() < 2.0, "{:?} beside {name:?}", mark(&h, 0));
        assert!(h.app.timeline.tweens.contains(&(node.0, 0, 10)));
        // A key is dragged along its row, as a peg's is.
        let keys = |h: &Harness| h.app.session.project().shots[0].effect(node).unwrap().key_frames(None).into_iter().collect::<Vec<_>>();
        let from = mark(&h, 10).center();
        h.drag_between(from, from + egui::vec2(64.0, 0.0));
        assert_eq!((keys(&h), h.app.session.history().undo_label(), &h.app.error), (vec![0, 14], Some("Move Keyframe"), &None));
        // A click on a key goes to it and picks the node, which Properties then shows; the
        // switch between held and animated works on it.
        let on = mark(&h, 0).center();
        click(&mut h, on);
        assert_eq!((h.app.tools.frame, h.app.picked.iter().copied().collect::<Vec<_>>(), h.app.layer), (0, vec![node.0], Some(layer)));
        run(&mut h, "key.switchHeld");
        let out = h.app.session.project().shots[0].effect(node).unwrap().interp(0, None).unwrap().1;
        assert_eq!((out, &h.app.error), (Interp::Hold, &None));
        assert!(!h.app.timeline.tweens.contains(&(node.0, 0, 14)));
        // Its last key gone, its row stays, as it can be keyed again.
        h.app.run("effect.removeKey", json!({ "effect": node.0, "frame": 0 }));
        h.app.run("effect.removeKey", json!({ "effect": node.0, "frame": 14 }));
        h.frame(vec![]);
        assert!(h.app.timeline.effect_names.len() == 1 && h.app.error.is_none());
    }

    #[test]
    fn a_colour_corrections_curves_are_drawn_in_properties() {
        let mut h = Harness::new();
        h.drag();
        let layer = h.app.layer.unwrap();
        let ctx = h.ctx.clone();
        h.app.timeline_actions(&ctx, vec![Action::Run("effect.new", json!({ "kind": "colourCorrection", "on": { "layer": layer.0 } }))]);
        let node = h.app.session.project().shots[0].effects[0].id;
        let curves = |h: &Harness| h.app.session.project().shots[0].effect(node).unwrap().curves("curves");
        // Picked alone, Properties shows the node, and under its numbers the square.
        h.app.picked = [node.0].into();
        h.frame(vec![]);
        h.frame(vec![]);
        // The panel is longer than its place: scrolled down, the square is all in the window.
        let below = h.app.tone_curves.area.expect("the curves have their square");
        let (unit, delta) = (egui::MouseWheelUnit::Point, egui::vec2(0.0, -400.0));
        h.frame(vec![Event::PointerMoved(egui::pos2(below.center().x, 500.0))]);
        h.frame(vec![Event::MouseWheel { unit, delta, phase: egui::TouchPhase::Move, modifiers: Modifiers::NONE }]);
        for _ in 0..30 {
            h.frame(vec![]);
        }
        let area = h.app.tone_curves.area.unwrap();
        assert!(area.bottom() < 690.0 && area.top() < below.top(), "{area:?}");
        let steps = h.app.session.history().entries().len();
        // A drag from the middle of the straight line, up: a point is made there and lifted,
        // and it is the project's when it is let go, in one step.
        h.drag_between(area.center(), area.center() - egui::vec2(0.0, area.height() / 4.0));
        let master = curves(&h).master;
        assert_eq!((master.len(), h.app.session.history().entries().len(), &h.app.error), (3, steps + 1, &None), "{master:?}");
        assert!((master[1][0] - 0.5).abs() < 0.02 && (master[1][1] - 0.75).abs() < 0.02, "{master:?}");
        assert_eq!((h.app.session.history().undo_label(), &h.app.curves_edit), (Some("Set Effect"), &None));
        // The point is taken hold of again where it is, and moved: still three points.
        let point = egui::pos2(area.center().x, area.center().y - area.height() / 4.0);
        h.drag_between(point, point + egui::vec2(area.width() / 8.0, 0.0));
        let master = curves(&h).master;
        assert!(master.len() == 3 && (master[1][0] - 0.625).abs() < 0.02, "{master:?}");
        // It is picked, and its numbers are typed: the tone it gives out set to 64 of 255, as
        // one step.
        assert_eq!(h.app.tone_curves.picked, Some(1));
        assert!(h.app.tone_curves.fields.is_some(), "the picked point's numbers are shown");
        let steps = h.app.session.history().entries().len();
        // Scrolled further, so that they are well inside the panel.
        h.frame(vec![Event::PointerMoved(area.center())]);
        h.frame(vec![Event::MouseWheel { unit, delta, phase: egui::TouchPhase::Move, modifiers: Modifiers::NONE }]);
        for _ in 0..30 {
            h.frame(vec![]);
        }
        let (_, out) = h.app.tone_curves.fields.unwrap();
        click(&mut h, out.center());
        h.frame(vec![Event::Key { key: Key::A, physical_key: None, pressed: true, repeat: false, modifiers: Modifiers::COMMAND }]);
        h.frame(vec![Event::Text("64".to_string())]);
        h.frame(vec![Event::Key { key: Key::Enter, physical_key: None, pressed: true, repeat: false, modifiers: Modifiers::NONE }]);
        h.frame(vec![]);
        h.frame(vec![]);
        let master = curves(&h).master;
        assert!((master[1][1] - 64.0 / 255.0).abs() < 1e-6 && (master[1][0] - 0.625).abs() < 0.02, "{master:?}");
        assert_eq!((h.app.session.history().entries().len(), &h.app.error), (steps + 1, &None));
        // Another of the four is shown, and drawn on alone.
        let area = h.app.tone_curves.area.unwrap();
        h.app.tone_curves.channel = 3;
        h.frame(vec![]);
        h.drag_between(area.center(), area.center() + egui::vec2(0.0, area.height() / 4.0));
        let all = curves(&h);
        assert!(all.master.len() == 3 && all.blue.len() == 3 && all.red.is_empty() && (all.blue[1][1] - 0.25).abs() < 0.02, "{all:?}");
    }

    #[test]
    fn a_pegs_row_folds_what_it_carries_away() {
        let mut h = Harness::new();
        bare_camera(&mut h);
        let layer = h.app.layer.unwrap();
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        h.app.run("peg.new", json!({}));
        h.frame(vec![]);
        let rows = |h: &Harness| h.app.timeline.names.iter().map(|(node, _)| *node).collect::<Vec<_>>();
        assert_eq!(rows(&h).len(), 3);
        // Only the peg that carries something has the arrow. A click on it puts the layer's
        // row away, and another brings it back.
        let [(folds, arrow)] = h.app.timeline.peg_arrows[..] else { panic!("one arrow: {:?}", h.app.timeline.peg_arrows) };
        assert_eq!(folds, peg);
        click(&mut h, arrow.center());
        assert!(!rows(&h).contains(&Node::Layer(layer)) && rows(&h).len() == 2 && h.app.error.is_none(), "{:?}", rows(&h));
        assert!(h.app.timeline.hold_handles.is_empty() || h.app.timeline.hold_handles.iter().all(|(of, ..)| *of != layer));
        let arrow = h.app.timeline.peg_arrows[0].1;
        click(&mut h, arrow.center());
        assert_eq!(rows(&h).len(), 3);
    }

    #[test]
    fn a_rows_eye_hides_a_layer_or_all_that_a_peg_carries_or_a_group_has_in_it() {
        let mut h = Harness::new();
        let layer = h.app.layer.unwrap();
        h.drag();
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        h.app.run("group.new", json!({ "nodes": [peg.0] }));
        let group = h.app.session.project().shots[0].groups[0].id;
        h.app.timeline_actions(&h.ctx.clone(), vec![Action::Select { node: Some(Node::Layer(layer)), frame: 0 }]);
        h.frame(vec![]);
        let eye = |h: &Harness, id: u64| h.app.timeline.eyes.iter().find(|(of, _)| *of == id).unwrap_or_else(|| panic!("no eye of {id}")).1.center();
        let shot = |h: &Harness| h.app.session.project().shots[0].clone();
        let steps = |h: &Harness| h.app.session.history().entries().len();
        assert!(h.app.viewport.tiles_shown() > 0);
        // Each hides the layer: its own row, the peg that carries it, the group the peg is in.
        for id in [layer.0, peg.0, group.0] {
            let at = eye(&h, id);
            click(&mut h, at);
            h.frame(vec![]);
            assert!(shot(&h).hidden.contains(&id) && shot(&h).hides(layer) && h.app.error.is_none(), "{id}: {:?}", h.app.error);
            assert_eq!((h.app.viewport.tiles_shown(), iskra_eval::evaluate(&shot(&h), 0).layers.len()), (0, 0), "{id}");
            // Hidden, the pen leaves it alone.
            let before = steps(&h);
            h.drag();
            assert_eq!(steps(&h), before, "{id}");
            let at = eye(&h, id);
            click(&mut h, at);
            h.frame(vec![]);
            assert!(shot(&h).hidden.is_empty() && h.app.viewport.tiles_shown() > 0, "{id}");
        }
    }

    #[test]
    fn a_rows_lock_keeps_a_layer_or_all_that_a_peg_carries_or_a_group_has_in_it_from_the_pen_and_the_pick() {
        let mut h = Harness::new();
        let layer = h.app.layer.unwrap();
        h.drag();
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        h.app.run("group.new", json!({ "nodes": [peg.0] }));
        let group = h.app.session.project().shots[0].groups[0].id;
        let other = LayerId(h.app.run_for("layer.new", json!({ "name": "Other" })).unwrap()["id"].as_u64().unwrap());
        let select = |h: &mut Harness, layer: LayerId| {
            h.app.timeline_actions(&h.ctx.clone(), vec![Action::Select { node: Some(Node::Layer(layer)), frame: 0 }]);
            h.frame(vec![]);
        };
        select(&mut h, layer);
        let lock = |h: &Harness, id: u64| h.app.timeline.row_locks.iter().find(|(of, _)| *of == id).unwrap_or_else(|| panic!("no lock of {id}")).1.center();
        let shot = |h: &Harness| h.app.session.project().shots[0].clone();
        let steps = |h: &Harness| h.app.session.history().entries().len();
        // Each locks the layer: its own row, the peg that carries it, the group the peg is in.
        for id in [layer.0, peg.0, group.0] {
            let at = lock(&h, id);
            click(&mut h, at);
            h.frame(vec![]);
            assert!(shot(&h).locked.contains(&id) && shot(&h).locks(layer) && !shot(&h).locks(other), "{id}: {:?}", h.app.error);
            assert_eq!(h.app.session.history().undo_label(), Some("Lock or Unlock Row"));
            // Still seen, and rendered.
            assert!(h.app.viewport.tiles_shown() > 0 && iskra_eval::evaluate(&shot(&h), 0).layers.len() == 2, "{id}");
            // Locked, the pen leaves it alone, and says why.
            let before = steps(&h);
            h.drag();
            assert_eq!(steps(&h), before, "{id}");
            assert!(h.app.viewport.locked.is_some_and(|why| why.contains("locked")), "{id}: {:?}", h.app.viewport.locked);
            // Nor is it picked by a click on its drawing from the other layer.
            select(&mut h, other);
            h.app.tools.tool = Tool::Transform;
            click(&mut h, Pos2::new(500.0, 350.0));
            assert_eq!(h.app.layer, Some(other), "{id}");
            let at = lock(&h, id);
            click(&mut h, at);
            h.frame(vec![]);
            assert!(shot(&h).locked.is_empty(), "{id}");
            click(&mut h, Pos2::new(500.0, 350.0));
            assert_eq!(h.app.layer, Some(layer), "{id}: unlocked, a click picks it");
            h.app.tools.tool = Tool::Brush;
            h.frame(vec![]);
        }
    }

    #[test]
    fn key_all_keys_the_tree_of_what_is_selected_or_all_of_the_shot() {
        let mut h = Harness::new();
        let layer = h.app.layer.unwrap();
        run(&mut h, "peg.addParent");
        let inner = h.app.peg.unwrap();
        run(&mut h, "peg.addParent");
        let outer = h.app.peg.unwrap();
        let bones = json!([{ "angle": 0, "length": 100 }]);
        h.app.run("deformer.new", json!({ "layer": layer.0, "origin": [-100, 0], "bones": bones }));
        let other = LayerId(h.app.run_for("layer.new", json!({ "name": "Other" })).unwrap()["id"].as_u64().unwrap());
        (h.app.layer, h.app.peg) = (Some(other), None);
        run(&mut h, "peg.addParent");
        let aside = h.app.peg.unwrap();
        let shot = |h: &Harness| h.app.session.project().shots[0].clone();
        let keyed = |h: &Harness, peg: PegId| shot(h).peg(peg).unwrap().animation.key_frames().contains(&5);
        let bones_keyed = |h: &Harness| shot(h).deformers[0].key_frames().contains(&5);
        // The outer peg selected: it, the peg it carries and the bones of the layer under
        // that are keyed, in one step; the peg aside is not.
        (h.app.layer, h.app.peg, h.app.tools.frame) = (None, Some(outer), 5);
        h.frame(vec![]);
        let button = h.app.timeline.key_all_button.expect("the Animate part has Key All");
        click(&mut h, button.center());
        assert_eq!((h.app.session.history().undo_label(), &h.app.error), (Some("Key All"), &None));
        assert!(keyed(&h, outer) && keyed(&h, inner) && bones_keyed(&h) && !keyed(&h, aside));
        // With nothing selected, all of the shot.
        h.app.session.undo();
        (h.app.layer, h.app.peg) = (None, None);
        run(&mut h, "key.all");
        assert!(keyed(&h, outer) && keyed(&h, inner) && bones_keyed(&h) && keyed(&h, aside));
    }

    #[test]
    fn a_folded_row_marks_the_frames_that_have_something_on_the_rows_it_puts_away() {
        let mut h = Harness::new();
        let layer = h.app.layer.unwrap();
        run(&mut h, "peg.addParent");
        let inner = h.app.peg.unwrap();
        run(&mut h, "peg.addParent");
        let outer = h.app.peg.unwrap();
        // A drawing on frames 2 and 9, which are no keyframes; a key of the peg between on
        // frame 5, and one of the outer peg's own on 20.
        h.app.run("drawing.newDrawing", json!({ "layer": layer.0, "frame": 2 }));
        h.app.run("drawing.newDrawing", json!({ "layer": layer.0, "frame": 9 }));
        h.app.run("peg.setKey", json!({ "peg": inner.0, "frame": 5 }));
        h.app.run("peg.setKey", json!({ "peg": outer.0, "frame": 20 }));
        h.frame(vec![]);
        assert!(h.app.timeline.put_away_marks.is_empty() && h.app.error.is_none(), "open, a peg's row has no marks: {:?}", h.app.error);
        // Folded, the outer peg's row marks what is under it, and not its own key.
        h.app.run("peg.setFolded", json!({ "peg": outer.0, "folded": true }));
        h.frame(vec![]);
        assert_eq!(h.app.timeline.put_away_marks, [(outer.0, 5)]);
        // The inner one folded alone carries a layer with drawings and no keyframes: no marks.
        // A folded group of the inner peg marks the peg's key.
        h.app.run("peg.setFolded", json!({ "peg": outer.0, "folded": false }));
        h.app.run("peg.setFolded", json!({ "peg": inner.0, "folded": true }));
        h.frame(vec![]);
        assert!(h.app.timeline.put_away_marks.is_empty(), "{:?}", h.app.timeline.put_away_marks);
        h.app.run("peg.setFolded", json!({ "peg": inner.0, "folded": false }));
        h.app.run("group.new", json!({ "nodes": [inner.0] }));
        let group = h.app.session.project().shots[0].groups[0].id;
        h.app.run("group.set", json!({ "group": group.0, "rowsFolded": true }));
        h.frame(vec![]);
        assert_eq!((&h.app.timeline.put_away_marks[..], &h.app.error), (&[(group.0, 5)][..], &None));
    }

    #[test]
    fn the_timelines_rows_scroll_up_and_down_under_a_ruler_that_stays() {
        let mut h = Harness::new();
        let shot = h.app.shot.unwrap();
        h.app.run("drawing.newDrawing", json!({ "layer": h.app.layer.unwrap().0, "frame": 0 }));
        h.app.run("shot.setMarker", json!({ "shot": shot.0, "frame": 3 }));
        for _ in 0..40 {
            h.app.run("layer.new", json!({ "shot": shot.0 }));
        }
        h.frame(vec![]);
        h.frame(vec![]);
        assert_eq!(h.app.error, None);
        let names = |h: &Harness| h.app.timeline.names.clone();
        let name_of = |h: &Harness, node: Node| names(h).iter().find(|(of, _)| *of == node).unwrap().1;
        let (first, last) = (names(&h)[0], names(&h)[40]);
        let seen = h.app.timeline.rows_seen.unwrap();
        let (marker, handle) = (h.app.timeline.markers[0].1, h.app.timeline.hold_handles[0]);
        // More rows than the panel is high: the last is below what is seen.
        assert!(seen.contains(first.1.center()) && last.1.top() > seen.bottom(), "{seen:?} {first:?} {last:?}");
        // The wheel over the cells takes the names and the cells up together. The ruler stays.
        let wheel = |h: &mut Harness, at: Pos2| {
            let (unit, delta) = (egui::MouseWheelUnit::Point, egui::vec2(0.0, -110.0));
            h.frame(vec![Event::PointerMoved(at)]);
            h.frame(vec![Event::MouseWheel { unit, delta, phase: egui::TouchPhase::Move, modifiers: Modifiers::NONE }]);
            for _ in 0..40 {
                h.frame(vec![]);
            }
        };
        wheel(&mut h, Pos2::new(seen.left() + 250.0, seen.center().y));
        let by = first.1.top() - names(&h)[0].1.top();
        let handle_by = handle.2.top() - h.app.timeline.hold_handles.iter().find(|(layer, ..)| *layer == handle.0).unwrap().2.top();
        assert!(by > 60.0 && (by - handle_by).abs() < 0.01, "{by} {handle_by}");
        assert_eq!(h.app.timeline.markers[0].1, marker);
        // And over the names.
        wheel(&mut h, Pos2::new(seen.left() + 40.0, seen.center().y));
        let further = first.1.top() - names(&h)[0].1.top();
        assert!(further > by + 60.0, "{further} {by}");
        // Sideways the frames scroll, the ruler with them, and the names stay: however short
        // the shot is, since there is room after its last frame.
        let (unit, delta) = (egui::MouseWheelUnit::Point, egui::vec2(-90.0, 0.0));
        let (flag, name) = (h.app.timeline.markers[0].1, names(&h)[0].1);
        h.frame(vec![Event::PointerMoved(Pos2::new(seen.left() + 250.0, seen.center().y))]);
        h.frame(vec![Event::MouseWheel { unit, delta, phase: egui::TouchPhase::Move, modifiers: Modifiers::NONE }]);
        for _ in 0..40 {
            h.frame(vec![]);
        }
        let sideways = flag.left() - h.app.timeline.markers[0].1.left();
        assert!(sideways > 60.0 && names(&h)[0].1 == name && h.app.timeline.markers[0].1.top() == flag.top(), "{sideways}");
        // A press on the ruler is on the ruler, not on the row that is scrolled under it.
        let (layer, on_ruler) = (h.app.layer, Pos2::new(marker.center().x + 16.0 * 4.0, marker.center().y));
        click(&mut h, on_ruler);
        assert_eq!((h.app.layer, h.app.tools.frame > 0), (layer, true));
        // A row that is selected from elsewhere is scrolled into sight: one in the middle, the
        // last, the first.
        let ctx = h.ctx.clone();
        for node in [names(&h)[20].0, last.0, first.0] {
            h.app.timeline_actions(&ctx, vec![Action::Select { node: Some(node), frame: 0 }]);
            h.frame(vec![]);
            h.frame(vec![]);
            let (name, seen) = (name_of(&h, node), h.app.timeline.rows_seen.unwrap());
            assert!(name.top() >= seen.top() - 1.0 && name.bottom() <= seen.bottom() + 1.0, "{node:?} {name:?} {seen:?}");
        }
        assert_eq!(h.app.error, None);
    }

    #[test]
    fn a_shot_has_markers_on_its_ruler_and_plays_round_between_its_in_and_out_points() {
        let mut h = Harness::new();
        let layer = h.app.layer.unwrap();
        h.app.run("drawing.newDrawing", json!({ "layer": layer.0, "frame": 0 }));
        h.frame(vec![]);
        let shot = |h: &Harness| h.app.session.project().shots[0].clone();
        // A marker goes on the playhead's frame, by its key, and is dragged along the ruler.
        h.app.tools.frame = 12;
        press(&mut h, Modifiers { command: true, shift: true, ..Modifiers::NONE }, Key::M);
        h.frame(vec![]);
        let [(12, flag)] = h.app.timeline.markers[..] else { panic!("one marker: {:?} {:?}", h.app.timeline.markers, h.app.error) };
        // The handle of the drawing, which holds for all of the shot, says where the cells are.
        let cells_left = h.app.timeline.hold_handles[0].2.right() + 1.5 - 16.0 * shot(&h).duration as f32;
        assert!((flag.center().x - 0.5 - (cells_left + 12.0 * 16.0 + 8.0)).abs() < 1.0, "{flag:?} {cells_left}");
        h.drag_between(flag.center(), flag.center() + egui::vec2(48.0, 0.0));
        assert_eq!((shot(&h).markers.iter().map(|marker| marker.frame).collect::<Vec<_>>(), &h.app.error), (vec![15], &None));
        assert!(h.app.session.project().storyboards[0].markers.is_empty(), "the film's ruler has none");
        // A click on it goes to its frame.
        let flag = h.app.timeline.markers[0].1;
        click(&mut h, flag.center());
        assert_eq!(h.app.tools.frame, 15);

        // In and out points are set at the playhead, and shown on the ruler.
        h.app.tools.frame = 10;
        run(&mut h, "range.in");
        h.app.tools.frame = 15;
        run(&mut h, "range.out");
        h.frame(vec![]);
        assert_eq!((shot(&h).range, h.app.timeline.range_ends), (Some((10, 16)), Some((cells_left + 160.0, cells_left + 256.0))));
        // Played with the loop on, the shot goes round between them, from the in point if the
        // playhead was outside.
        h.app.switches.looping = true;
        h.app.tools.frame = 40;
        run(&mut h, "playback.toggle");
        let mut seen = std::collections::BTreeSet::new();
        for _ in 0..60 {
            h.frame(vec![]);
            seen.insert(h.app.tools.frame);
        }
        assert_eq!(seen.into_iter().collect::<Vec<_>>(), [10, 11, 12, 13, 14, 15]);
        // Without the loop it stops on the out point; cleared, all of the shot plays again.
        run(&mut h, "playback.toggle");
        h.app.switches.looping = false;
        h.app.tools.frame = 12;
        run(&mut h, "playback.toggle");
        for _ in 0..40 {
            h.frame(vec![]);
        }
        assert_eq!((h.app.tools.frame, h.app.playing.is_some()), (15, false));
        run(&mut h, "range.clear");
        h.frame(vec![]);
        assert_eq!((shot(&h).range, h.app.timeline.range_ends), (None, None));
    }

    #[test]
    fn the_viewer_shows_what_the_display_shows() {
        let mut h = Harness::new();
        bare_camera(&mut h);
        let bottom = h.app.layer.unwrap();
        h.app.run("layer.rename", json!({ "layer": bottom.0, "name": "Sky" }));
        run(&mut h, "layer.new");
        h.frame(vec![]);
        // The rows of the timeline are in stacking order, the new layer on top.
        let rows = |h: &Harness| h.app.timeline.names.iter().map(|(node, _)| *node).collect::<Vec<_>>();
        let top = h.app.session.project().shots[0].stack()[0];
        assert_eq!(rows(&h), [Node::Layer(top), Node::Layer(bottom)]);
        // Moved under the sky in its composite, it is under it in the timeline too.
        h.app.run("layer.move", json!({ "layer": top.0, "index": 1 }));
        h.frame(vec![]);
        assert_eq!(rows(&h), [Node::Layer(bottom), Node::Layer(top)]);

        // A layer that is connected to nothing is not seen: no tile of it is drawn, though it
        // can still be selected and is still in the shot.
        h.app.layer = Some(bottom);
        h.drag();
        h.frame(vec![]);
        assert!(h.app.viewport.tiles_shown() > 0);
        h.app.run("node.disconnect", json!({ "node": { "layer": bottom.0 } }));
        h.frame(vec![]);
        assert_eq!((h.app.viewport.tiles_shown(), rows(&h), &h.app.error), (0, vec![Node::Layer(top), Node::Layer(bottom)], &None));
        // With the display on that layer alone, it is all that is seen.
        h.app.run("display.set", json!({ "node": { "layer": bottom.0 } }));
        h.frame(vec![]);
        assert!(h.app.viewport.tiles_shown() > 0 && h.app.session.project().shots[0].stack() == [bottom]);
    }

    #[test]
    fn a_node_is_found_by_search_dropped_on_a_wire_and_coloured_in_the_node_view() {
        use crate::nodes::Item;
        use iskra_model::Source;
        let mut h = Harness::new();
        let layer = h.app.layer.unwrap();
        run(&mut h, "panel.nodeView");
        h.frame(vec![]);
        let shot = |h: &Harness| h.app.session.project().shots[0].clone();
        let composite = shot(&h).composites[0].id;
        let at = |h: &Harness, item: Item| h.app.nodes.boxes.iter().find(|(other, _)| *other == item).expect("the node has a box").1;
        // The search finds kinds by any words of their category and name.
        assert_eq!(nodes::found("colour transp").iter().map(|kind| kind.id).collect::<Vec<_>>(), ["transparency"]);
        assert!(nodes::found("zzz").is_empty() && !nodes::found("").is_empty());

        // With nothing picked, Enter over the view opens the search; what is typed is found,
        // and Enter adds it where the search was opened, wired to nothing.
        let free = at(&h, Item::Display(main_display(&h))).center() + egui::vec2(170.0, -30.0);
        click(&mut h, free);
        assert!(h.app.picked.is_empty());
        h.frame(vec![Event::PointerMoved(free)]);
        press(&mut h, Modifiers::NONE, Key::Enter);
        h.frame(vec![Event::Text("transp".to_string())]);
        press(&mut h, Modifiers::NONE, Key::Enter);
        h.frame(vec![]);
        let [made] = &shot(&h).effects[..] else { panic!("one node was added: {:?} {:?}", shot(&h).effects, h.app.error) };
        let node = made.id;
        assert_eq!((made.picture(), made.kind.as_str(), &h.app.error), (None, "transparency", &None));
        let put = at(&h, Item::Effect(node));
        assert!((put.center() - free).length() < 2.0, "{put:?} {free:?}");

        // Its box let go on the wire from the layer to the composite puts it on that wire.
        let (from, to) = (at(&h, Item::Layer(layer)).center_bottom(), at(&h, Item::Composite(composite)).center_top());
        let on_wire = from + (to - from) * 0.5;
        h.drag_between(put.center(), on_wire);
        let wired = shot(&h);
        assert_eq!(
            (wired.effect(node).unwrap().picture(), wired.composites[0].inputs.clone(), &h.app.error),
            (Some(Source::Layer(layer)), vec![Source::Effect(node)], &None)
        );
        // With the layer picked, the search adds below it, on the wire that leaves it: between
        // it and the first node, and under its box.
        let on_layer = at(&h, Item::Layer(layer)).center();
        click(&mut h, on_layer);
        assert_eq!(h.app.picked, [layer.0].into());
        h.frame(vec![Event::PointerMoved(free)]);
        press(&mut h, Modifiers::NONE, Key::Enter);
        h.frame(vec![Event::Text("blur".to_string())]);
        press(&mut h, Modifiers::NONE, Key::Enter);
        h.frame(vec![]);
        let added = shot(&h).effects.iter().find(|effect| effect.kind == "blur").map(|effect| effect.id).expect("a blur was added");
        assert_eq!(
            (shot(&h).effect(added).unwrap().picture(), shot(&h).effect(node).unwrap().picture(), &h.app.error),
            (Some(Source::Layer(layer)), Some(Source::Effect(added)), &None)
        );
        let (above, put) = (at(&h, Item::Layer(layer)), at(&h, Item::Effect(added)));
        assert!((put.center().x - above.center().x).abs() < 1.0 && put.top() > above.bottom(), "{above:?} {put:?}");
        // The node that was under the layer, where the new one goes, made room: it and what
        // its picture goes on to are moved down, and the new one is not under it.
        let (first, composite_now) = (at(&h, Item::Effect(node)), at(&h, Item::Composite(composite)));
        assert!(first.top() > put.bottom() && composite_now.top() > first.bottom(), "{put:?} {first:?} {composite_now:?}");
        assert_eq!(h.app.session.history().undo_label(), Some("Add Blur"));
        h.app.session.undo();
        h.frame(vec![]);
        assert!((at(&h, Item::Effect(node)).center() - on_wire).length() < 2.0, "one step: the room made goes too");
        let wired = shot(&h);
        // The user's colour for a node is the shot's, and changes nothing that is rendered.
        let revision = wired.revision;
        h.app.run("node.setColour", json!({ "node": node.0, "colour": [219, 68, 55] }));
        assert_eq!((shot(&h).colours.get(&node.0), shot(&h).revision, &h.app.error), (Some(&[219, 68, 55]), revision, &None));
        h.app.run("node.setColour", json!({ "nodes": [node.0] }));
        assert!(shot(&h).colours.is_empty());
        h.frame(vec![]);
    }

    #[test]
    fn the_top_view_shows_a_line_for_each_plane_of_rain_and_a_click_picks_it() {
        let mut h = Harness::new();
        bare_camera(&mut h);
        h.drag();
        let made = h.app.run_for("effect.new", json!({ "kind": "particles", "stack": "over" })).unwrap()["id"].as_u64().unwrap();
        for (param, value) in [("depth", 50.0), ("depthRange", 100.0), ("planes", 2.0)] {
            h.app.run("effect.set", json!({ "effect": made, "param": param, "value": value }));
        }
        run(&mut h, "panel.topView");
        h.frame(vec![]);
        let sheets = h.app.top_view.sheets.clone();
        let depths: Vec<f64> = sheets.iter().map(|(_, depth, _)| *depth).collect();
        assert_eq!(depths, [-50.0, 50.0], "{sheets:?}");
        let (far, near) = (sheets[0].2, sheets[1].2);
        assert!(near[0].y > far[0].y + 10.0, "the near one is nearer the camera, down the screen: {far:?} {near:?}");
        assert!((near[1].x - near[0].x) < (far[1].x - far[0].x), "the camera sees less of the scene nearer it");
        // A click on one picks the node.
        assert!(h.app.picked.is_empty() || !h.app.picked.contains(&made));
        (0..30).for_each(|_| h.frame(vec![]));
        click(&mut h, near[0] + (near[1] - near[0]) * 0.25);
        assert_eq!(h.app.picked, [made].into());
    }

