    #[test]
    fn the_emitter_of_the_particles_picked_is_drawn_in_the_viewport() {
        let mut h = Harness::new();
        let made = h.app.run_for("effect.new", json!({ "kind": "particles", "stack": "over" })).unwrap()["id"].as_u64().unwrap();
        let set = |h: &mut Harness, param: &str, value: Value| h.app.run("effect.set", json!({ "effect": made, "param": param, "value": value }));
        set(&mut h, "emitter", json!("Line"));
        set(&mut h, "emitterY", json!(-100.0));
        set(&mut h, "emitterWidth", json!(300.0));
        h.frame(vec![]);
        assert!(h.app.viewport.emitter_outline.is_empty(), "not picked, not drawn");
        h.app.picked = [made].into();
        h.frame(vec![]);
        let line = h.app.viewport.emitter_outline.clone();
        assert_eq!(line.len(), 2, "a line: {line:?}");
        assert!((line[0].y - line[1].y).abs() < 0.5 && line[1].x > line[0].x, "{line:?}");
        // An area is a box round, and the whole frame nothing.
        set(&mut h, "emitter", json!("Area"));
        h.frame(vec![]);
        assert_eq!(h.app.viewport.emitter_outline.len(), 5);
        set(&mut h, "emitter", json!("Whole Frame"));
        h.frame(vec![]);
        assert!(h.app.viewport.emitter_outline.is_empty());
        assert_eq!(h.app.error, None);
    }

    #[test]
    fn a_colour_card_added_by_the_search_is_stacked_under_the_layers_whatever_is_picked() {
        use crate::nodes::Item;
        use iskra_model::Source;
        let mut h = Harness::new();
        let layer = h.app.layer.unwrap();
        run(&mut h, "panel.nodeView");
        h.frame(vec![]);
        let shot = |h: &Harness| h.app.session.project().shots[0].clone();
        let at = |h: &Harness, item: Item| h.app.nodes.boxes.iter().find(|(other, _)| *other == item).expect("the node has a box").1;
        assert_eq!(nodes::found("colour card").iter().map(|kind| kind.id).collect::<Vec<_>>(), [iskra_model::COLOUR_CARD]);
        // With the layer picked, a Colour Card does not go on its wire, as it takes no picture:
        // it is under the layer in the main composite.
        let on_layer = at(&h, Item::Layer(layer)).center();
        click(&mut h, on_layer);
        let free = at(&h, Item::Display(main_display(&h))).center() + egui::vec2(170.0, -30.0);
        h.frame(vec![Event::PointerMoved(free)]);
        press(&mut h, Modifiers::NONE, Key::Enter);
        h.frame(vec![Event::Text("colour card".to_string())]);
        press(&mut h, Modifiers::NONE, Key::Enter);
        h.frame(vec![]);
        let [card] = &shot(&h).effects[..] else { panic!("one node was added: {:?} {:?}", shot(&h).effects, h.app.error) };
        let card = card.id;
        assert_eq!((shot(&h).composites[0].inputs.clone(), &h.app.error), (vec![Source::Layer(layer), Source::Effect(card)], &None));
        // Picked, its colour is set as any parameter is.
        h.app.picked = [card.0].into();
        h.frame(vec![]);
        h.app.run("effect.set", json!({ "effect": card.0, "param": "colour", "value": [0.2, 0.6, 0.3] }));
        assert_eq!((shot(&h).effect(card).unwrap().colour("colour", 0), &h.app.error), ([0.2, 0.6, 0.3, 1.0], &None));
        h.frame(vec![]);
        // Particles, rain to begin with, go over everything instead. Opened elsewhere than on
        // the card's box, where the search was opened before.
        let right = h.app.nodes.boxes.iter().map(|(_, rect)| rect.right()).fold(f32::MIN, f32::max);
        let elsewhere = egui::pos2(right + 60.0, free.y);
        (0..30).for_each(|_| h.frame(vec![]));
        click(&mut h, elsewhere);
        assert!(h.app.picked.is_empty());
        h.frame(vec![Event::PointerMoved(elsewhere)]);
        press(&mut h, Modifiers::NONE, Key::Enter);
        h.frame(vec![Event::Text("particles".to_string())]);
        press(&mut h, Modifiers::NONE, Key::Enter);
        h.frame(vec![]);
        let rain = shot(&h).effects.iter().find(|effect| effect.kind == iskra_model::PARTICLES).map(|effect| effect.id).expect("particles were added");
        assert_eq!((shot(&h).composites[0].inputs.first(), &h.app.error), (Some(&Source::Effect(rain)), &None));
        assert_eq!(shot(&h).effect(rain).unwrap().choice("kind", 0), "Rain");
        // A wire from the layer let go on its box goes into its sprite port: it has no other.
        h.frame(vec![]);
        h.drag_between(at(&h, Item::Layer(layer)).center_bottom(), at(&h, Item::Effect(rain)).center());
        assert_eq!((shot(&h).effect(rain).unwrap().inputs.get(iskra_model::SPRITE), &h.app.error), (Some(&Source::Layer(layer)), &None));
        // Let go on its second input along the top, rain's, into its splash's port.
        h.frame(vec![]);
        let onto = at(&h, Item::Effect(rain));
        let splash = onto.left_top() + egui::vec2(onto.width() * 0.24, 4.0);
        h.drag_between(at(&h, Item::Layer(layer)).center_bottom(), splash);
        assert_eq!((shot(&h).effect(rain).unwrap().inputs.get(iskra_model::SPLASH_SPRITE), &h.app.error), (Some(&Source::Layer(layer)), &None));
        // Made a burst, it has a third, its collider's, which the layer is wired into and stays
        // where it was besides.
        h.app.run("effect.set", json!({ "effect": rain.0, "param": "kind", "value": "Burst" }));
        h.frame(vec![]);
        let onto = at(&h, Item::Effect(rain));
        let collider = onto.left_top() + egui::vec2(onto.width() * 0.36, 4.0);
        h.drag_between(at(&h, Item::Layer(layer)).center_bottom(), collider);
        assert_eq!((shot(&h).effect(rain).unwrap().inputs.get(iskra_model::COLLIDER), &h.app.error), (Some(&Source::Layer(layer)), &None));
        assert_eq!(shot(&h).effect(rain).unwrap().inputs.get(iskra_model::SPLASH_SPRITE), Some(&Source::Layer(layer)));
        assert!(shot(&h).effect(rain).unwrap().applies("bounce", 0));
    }

    #[test]
    fn a_matte_is_wired_into_the_side_of_a_cutter_and_cut_again() {
        use crate::nodes::Item;
        use iskra_model::{MATTE, Source};
        let mut h = Harness::new();
        // The clicks below are on wires where the layout puts them: the view arranges the nodes.
        h.app.nodes.arrange = true;
        let layer = h.app.layer.unwrap();
        run(&mut h, "layer.new");
        let shape = h.app.layer.unwrap();
        let node = h.app.run_for("effect.new", json!({ "kind": "cutter", "on": { "layer": layer.0 } })).unwrap()["id"].as_u64().unwrap();
        let node = iskra_model::EffectId(node);
        run(&mut h, "panel.nodeView");
        h.frame(vec![]);
        let shot = |h: &Harness| h.app.session.project().shots[0].clone();
        let at = |h: &Harness, item: Item| h.app.nodes.boxes.iter().find(|(other, _)| *other == item).expect("the node has a box").1;
        // A wire dragged from under the other layer onto the left end of the cutter's box is
        // its matte; the picture that goes through stays.
        let onto = at(&h, Item::Effect(node));
        h.drag_between(at(&h, Item::Layer(shape)).center_bottom(), onto.left_center() + egui::vec2(8.0, 0.0));
        let wired = shot(&h).effect(node).unwrap().clone();
        assert_eq!((wired.inputs.get(MATTE), wired.picture(), &h.app.error), (Some(&Source::Layer(shape)), Some(Source::Layer(layer)), &None));
        // Picked, Properties shows what a cutter has, and a number let go is the project's.
        h.app.picked = [node.0].into();
        h.frame(vec![]);
        h.app.effect_edit = Some((node, "blur".to_string(), 12.0));
        h.frame(vec![]);
        assert_eq!((shot(&h).effect(node).unwrap().number("blur", 0), &h.app.error), (12.0, &None));
        h.app.run("effect.set", json!({ "effect": node.0, "param": "inverted", "value": true }));
        assert!(shot(&h).effect(node).unwrap().switch("inverted", 0) && h.app.error.is_none());
        // A colour that was picked is the project's when the pointer is let go.
        let glow = h.app.run_for("effect.new", json!({ "kind": "glow", "on": { "layer": layer.0 } })).unwrap()["id"].as_u64().unwrap();
        let glow = iskra_model::EffectId(glow);
        h.app.picked = [glow.0].into();
        h.frame(vec![]);
        h.app.colour_edit = Some((glow, "colour".to_string(), [255, 0, 51, 255]));
        h.frame(vec![]);
        assert_eq!((shot(&h).effect(glow).unwrap().colour("colour", 0), &h.app.error, &h.app.colour_edit), ([1.0, 0.0, 0.2, 1.0], &None, &None));
        h.app.picked = [node.0].into();
        // Alt-click on the matte's wire takes it away again.
        h.frame(vec![]);
        let (from, to) = (at(&h, Item::Layer(shape)).center_bottom(), at(&h, Item::Effect(node)).left_center());
        let alt = Modifiers { alt: true, ..Modifiers::NONE };
        let button = |pos: Pos2, pressed| Event::PointerButton { pos, button: PointerButton::Primary, pressed, modifiers: alt };
        // Half way along, the wire is half way between its ends: it bends as much out of the
        // one as into the other. The layer's wire to the composite is nowhere near there.
        let on_wire = from + (to - from) * 0.5;
        h.frame(vec![Event::ModifiersChanged(alt), Event::PointerMoved(on_wire)]);
        h.frame(vec![button(on_wire, true)]);
        h.frame(vec![button(on_wire, false)]);
        h.frame(vec![Event::ModifiersChanged(Modifiers::NONE)]);
        assert_eq!((shot(&h).effect(node).unwrap().inputs.get(MATTE), &h.app.error), (None, &None));
    }

    #[test]
    fn the_node_view_shows_the_graph_and_wires_are_dragged_and_cut_in_it() {
        use crate::nodes::Item;
        let mut h = Harness::new();
        let layer = h.app.layer.unwrap();
        run(&mut h, "panel.nodeView");
        // Once more, for the panel's bar to have its height.
        h.frame(vec![]);
        h.frame(vec![]);
        let composite = h.app.session.project().shots[0].composites[0].id;
        let at = |h: &Harness, item: Item| h.app.nodes.boxes.iter().find(|(other, _)| *other == item).expect("the node has a box").1;
        let (display, stacker, drawing) = (at(&h, Item::Display(main_display(&h))), at(&h, Item::Composite(composite)), at(&h, Item::Layer(layer)));
        assert!(drawing.center().y < stacker.center().y && stacker.center().y < display.center().y, "pictures flow down to the display");
        let shot = |h: &Harness| h.app.session.project().shots[0].clone();

        // A wire dragged from under a peg onto the layer parents the layer to the peg, as the
        // timeline then shows; clicking the peg's box selects it there too.
        run(&mut h, "peg.new");
        let peg = h.app.peg.unwrap();
        h.app.peg = None;
        h.frame(vec![]);
        h.drag_between(at(&h, Item::Peg(peg)).center_bottom(), at(&h, Item::Layer(layer)).center());
        assert_eq!((shot(&h).layer(layer).unwrap().parent, h.app.session.history().undo_label(), &h.app.error), (Some(peg), Some("Parent Layer"), &None));
        let on = at(&h, Item::Peg(peg)).center();
        click(&mut h, on);
        assert_eq!((h.app.peg, h.app.layer), (Some(peg), None));

        // Alt-click on the wire into the composite cuts it: the layer is no longer seen.
        let alt = Modifiers { alt: true, ..Modifiers::NONE };
        let alt_click = |h: &mut Harness, pos: Pos2| {
            let button = |pressed| Event::PointerButton { pos, button: PointerButton::Primary, pressed, modifiers: alt };
            h.frame(vec![Event::ModifiersChanged(alt), Event::PointerMoved(pos)]);
            h.frame(vec![button(true)]);
            h.frame(vec![button(false)]);
            h.frame(vec![Event::ModifiersChanged(Modifiers::NONE)]);
        };
        let into = at(&h, Item::Composite(composite)).center_top() - egui::vec2(0.0, 8.0);
        alt_click(&mut h, into);
        assert_eq!((shot(&h).stack(), h.app.session.history().undo_label()), (vec![], Some("Disconnect Node")));
        // Dragged from under the layer onto the composite, it is connected again.
        h.drag_between(at(&h, Item::Layer(layer)).center_bottom(), at(&h, Item::Composite(composite)).center());
        assert_eq!((shot(&h).stack(), h.app.session.history().undo_label()), (vec![layer], Some("Connect Node")));
        // Onto the display, the layer is shown alone; the composite's wire brings the rest back.
        h.drag_between(at(&h, Item::Layer(layer)).center_bottom(), at(&h, Item::Display(main_display(&h))).center());
        assert_eq!(shot(&h).display, Some(iskra_model::Source::Layer(layer)));
        h.drag_between(at(&h, Item::Composite(composite)).center_bottom(), at(&h, Item::Display(main_display(&h))).center());
        assert_eq!(shot(&h).display, Some(iskra_model::Source::Composite(composite)));
        // A wire dropped on nothing, or where it makes no sense, changes nothing.
        let steps = h.app.session.history().entries().len();
        h.drag_between(at(&h, Item::Layer(layer)).center_bottom(), at(&h, Item::Peg(peg)).center());
        // Let go on nothing, well inside the view: its edges take the view along.
        let nothing = h.app.nodes.shown_in().expect("the node view is shown").left_center() + egui::vec2(80.0, 0.0);
        h.drag_between(at(&h, Item::Composite(composite)).center_bottom(), nothing);
        assert_eq!((h.app.session.history().entries().len(), &h.app.error), (steps, &None));

        // Dragging a box moves the node, and its place is kept with the shot.
        let before = at(&h, Item::Composite(composite));
        h.drag_between(before.center(), before.center() + egui::vec2(60.0, 20.0));
        let after = at(&h, Item::Composite(composite));
        assert!((after.center() - before.center() - egui::vec2(60.0, 20.0)).length() < 8.0, "{before:?} {after:?}");
        assert_eq!((h.app.session.history().undo_label(), shot(&h).places.len()), (Some("Move Node"), 1));
        assert!((at(&h, Item::Display(main_display(&h))).center() - display.center()).length() < 0.5, "the others stay");

        // The end of a wire is dragged along the composite's ports to another place among
        // them: the layer that was on top goes under the other.
        let sky = LayerId(h.app.run_for("layer.new", json!({})).unwrap()["id"].as_u64().unwrap());
        h.frame(vec![]);
        let inputs = |h: &Harness| shot(h).composite(composite).unwrap().inputs.clone();
        let (top, under) = (iskra_model::Source::Layer(sky), iskra_model::Source::Layer(layer));
        assert_eq!(inputs(&h), [top, under]);
        let onto = at(&h, Item::Composite(composite));
        let end = |index: f32| Pos2::new(onto.left() + onto.width() * index / 3.0, onto.top());
        h.drag_between(end(1.0), end(2.0) + egui::vec2(12.0, 0.0));
        assert_eq!((inputs(&h), h.app.session.history().undo_label(), &h.app.error), (vec![under, top], Some("Connect Node"), &None));
        // Let go where it was, it changes nothing.
        let steps = h.app.session.history().entries().len();
        h.drag_between(end(1.0), end(1.0) + egui::vec2(8.0, 0.0));
        assert_eq!((inputs(&h), h.app.session.history().entries().len()), (vec![under, top], steps));
        h.drag_between(end(2.0), end(1.0) - egui::vec2(12.0, 0.0));
        assert_eq!(inputs(&h), [top, under]);
    }

    #[test]
    fn a_transform_is_wired_through_a_send_and_a_receive_in_the_node_view() {
        use crate::nodes::Item;
        let mut h = Harness::new();
        let layer = h.app.layer.unwrap();
        run(&mut h, "peg.new");
        let peg = h.app.peg.unwrap();
        let new = |h: &mut Harness, kind: &str, at: [f64; 2]| {
            iskra_model::EffectId(h.app.run_for("effect.new", json!({ "kind": kind, "at": at })).unwrap()["id"].as_u64().unwrap())
        };
        let (send, receive) = (new(&mut h, "send", [150.0, -150.0]), new(&mut h, "receive", [150.0, -300.0]));
        h.app.run("effect.set", json!({ "effect": receive.0, "param": "tag", "value": "Send" }));
        h.app.run("node.place", json!({ "moves": [{ "node": peg.0, "at": [-150.0, -300.0] }] }));
        run(&mut h, "panel.nodeView");
        h.frame(vec![]);
        let at = |h: &Harness, item: Item| h.app.nodes.boxes.iter().find(|(other, _)| *other == item).expect("the node has a box").1;
        let shot = |h: &Harness| h.app.session.project().shots[0].clone();
        // From under the peg onto the Send: the peg's transform goes into it.
        h.drag_between(at(&h, Item::Peg(peg)).center_bottom(), at(&h, Item::Effect(send)).center());
        assert_eq!(
            (shot(&h).effect(send).unwrap().parent, h.app.session.history().undo_label(), &h.app.error),
            (Some(peg), Some("Wire a Transform into a Port"), &None)
        );
        // From under the Receive onto the layer: the layer is carried by what the Send is given.
        h.drag_between(at(&h, Item::Effect(receive)).center_bottom(), at(&h, Item::Layer(layer)).center());
        assert_eq!((shot(&h).layer(layer).unwrap().parent, &h.app.error), (Some(PegId(receive.0)), &None));
        assert_eq!(shot(&h).peg_above(Some(PegId(receive.0))).map(|above| above.id), Some(peg));
        // Both wires are drawn, as a peg's are.
        let wired = |h: &Harness, from: Item, to: Item| h.app.nodes.wire_ends.iter().any(|(a, b, ..)| *a == from && *b == to);
        assert!(wired(&h, Item::Peg(peg), Item::Effect(send)) && wired(&h, Item::Effect(receive), Item::Layer(layer)));
    }

    #[test]
    fn an_effect_node_comes_off_its_wire_with_alt_and_goes_onto_one_it_is_let_go_on() {
        use crate::nodes::Item;
        use iskra_model::{EffectId, Source};
        let mut h = Harness::new();
        let composite = h.app.session.project().shots[0].composites[0].id;
        let made = h.app.run_for("effect.new", json!({ "kind": "transparency", "on": { "composite": composite.0 } })).unwrap()["id"].as_u64().unwrap();
        let effect = EffectId(made);
        run(&mut h, "panel.nodeView");
        h.frame(vec![]);
        let at = |h: &Harness, item: Item| h.app.nodes.boxes.iter().find(|(other, _)| *other == item).map(|(_, rect)| *rect).unwrap();
        let shot = |h: &Harness| h.app.session.project().shots[0].clone();
        assert_eq!(shot(&h).display, Some(Source::Effect(effect)));
        // Dragged with Alt held, the node comes off its wire. While it is dragged the wire
        // that is joined behind it, from the composite to the display, is drawn in red.
        let alt = Modifiers { alt: true, ..Modifiers::NONE };
        let (from, to) = (at(&h, Item::Effect(effect)).center(), at(&h, Item::Effect(effect)).center() + egui::vec2(170.0, -10.0));
        let button = |pos, pressed, modifiers| Event::PointerButton { pos, button: PointerButton::Primary, pressed, modifiers };
        h.frame(vec![Event::ModifiersChanged(alt), Event::PointerMoved(from)]);
        h.frame(vec![button(from, true, alt)]);
        h.frame(vec![Event::PointerMoved(from + (to - from) * 0.5)]);
        h.frame(vec![Event::PointerMoved(to)]);
        h.frame(vec![]);
        assert_eq!(h.app.nodes.lit, [(Item::Composite(composite), Item::Display(main_display(&h)), true)]);
        assert_eq!(shot(&h).display, Some(Source::Effect(effect)), "nothing is changed until it is let go");
        h.frame(vec![button(to, false, alt)]);
        h.frame(vec![Event::ModifiersChanged(Modifiers::NONE)]);
        h.frame(vec![]);
        assert_eq!((shot(&h).display, shot(&h).effect(effect).unwrap().picture()), (Some(Source::Composite(composite)), None));
        assert_eq!((h.app.session.history().undo_label(), &h.app.error, h.app.nodes.lit.len()), (Some("Take Effect off Its Wire"), &None, 0));
        assert!((at(&h, Item::Effect(effect)).center() - to).length() < 8.0, "it lies where it was let go");
        // Dragged over a wire, without Alt, that wire is lit; let go there, the node is on it.
        let wire = h
            .app
            .nodes
            .wire_ends
            .iter()
            .find(|(a, b, ..)| *a == Item::Composite(composite) && *b == Item::Display(main_display(&h)))
            .map(|(.., a, b)| (*a, *b))
            .unwrap();
        let (from, middle) = (at(&h, Item::Effect(effect)).center(), wire.0 + (wire.1 - wire.0) * 0.5);
        h.frame(vec![Event::PointerMoved(from)]);
        h.frame(vec![button(from, true, Modifiers::NONE)]);
        h.frame(vec![Event::PointerMoved(from + (middle - from) * 0.5)]);
        h.frame(vec![Event::PointerMoved(middle)]);
        h.frame(vec![]);
        assert_eq!(h.app.nodes.lit, [(Item::Composite(composite), Item::Display(main_display(&h)), false)]);
        h.frame(vec![button(middle, false, Modifiers::NONE)]);
        h.frame(vec![]);
        assert_eq!(
            (shot(&h).display, shot(&h).effect(effect).unwrap().picture(), &h.app.error),
            (Some(Source::Effect(effect)), Some(Source::Composite(composite)), &None)
        );
        // A node that is out of what the shot shows is drawn darker: an effect that is
        // switched off, and a layer whose row is hidden on the timeline, with the peg over it
        // when it is the peg that is hidden.
        let layer = h.app.layer.unwrap();
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        h.frame(vec![]);
        assert!(h.app.nodes.dimmed.is_empty());
        h.app.run("effect.setEnabled", json!({ "effect": made, "enabled": false }));
        h.app.run("shot.setHidden", json!({ "node": layer.0, "hidden": true }));
        h.frame(vec![]);
        assert_eq!(
            (h.app.nodes.dimmed.len(), h.app.nodes.dimmed.contains(&Item::Layer(layer)), h.app.nodes.dimmed.contains(&Item::Effect(effect))),
            (2, true, true)
        );
        h.app.run("shot.setHidden", json!({ "node": layer.0, "hidden": false }));
        h.app.run("shot.setHidden", json!({ "node": peg.0, "hidden": true }));
        h.app.run("effect.setEnabled", json!({ "effect": made, "enabled": true }));
        h.frame(vec![]);
        assert_eq!(
            (h.app.nodes.dimmed.len(), h.app.nodes.dimmed.contains(&Item::Layer(layer)), h.app.nodes.dimmed.contains(&Item::Peg(peg)), &h.app.error),
            (2, true, true, &None)
        );
        h.app.run("shot.setHidden", json!({ "node": peg.0, "hidden": false }));
        h.frame(vec![]);
        // Dragged without Alt, a node that is on a wire stays on it.
        let from = at(&h, Item::Effect(effect)).center();
        h.drag_between(from, from + egui::vec2(-160.0, 0.0));
        assert_eq!((shot(&h).display, h.app.session.history().undo_label()), (Some(Source::Effect(effect)), Some("Move Node")));
    }

    #[test]
    fn the_bottom_strip_has_a_menu_of_the_shots_and_the_app_can_start_on_the_media_page() {
        let mut h = Harness::new();
        h.frame(vec![]);
        let first = h.app.shot.unwrap();
        let second = ShotId(h.app.run_for("shot.new", json!({ "name": "Second" })).unwrap()["id"].as_u64().unwrap());
        h.app.set_shot(first);
        h.frame(vec![]);
        // The strip names the shot in hand, and lists the project's shots in their order.
        let listed = h.app.shot_names();
        assert_eq!(listed.iter().map(|(id, name, in_hand)| (*id, name.as_str(), *in_hand)).collect::<Vec<_>>()[1], (second, "Second", false));
        assert!(listed[0].0 == first && listed[0].2 && listed.len() == 2);
        // Its name is a button at the right of the strip, which opens the list.
        let button = h.app.shot_menu.expect("the shot's name is drawn");
        let strip = h.app.page_icons[0].1;
        assert!(button.center().x > strip.right() && (button.center().y - strip.center().y).abs() < 12.0, "{button:?}");
        click(&mut h, button.center());
        assert!(egui::Popup::is_any_open(&h.ctx), "the list of shots is open");
        h.frame(vec![Event::Key { key: egui::Key::Escape, physical_key: None, pressed: true, repeat: false, modifiers: Modifiers::NONE }]);
        // Going to another is what choosing it there does.
        h.app.set_shot(second);
        h.frame(vec![]);
        assert!(h.app.shot_names()[1].2 && h.app.error.is_none());

        // The app starts in a shot unless it is told to start on the Media page; and there
        // only if the user has not taken that page out of the bar.
        assert_eq!(IskraApp::new(Session::new()).page, Page::Animation);
        assert_eq!(IskraApp::new(Session::new()).starting_on_media().page, Page::Media);
        let mut without = IskraApp::new(Session::new());
        without.prefs.hidden_pages.push(Page::Media);
        assert_eq!(without.starting_on_media().page, Page::Animation);
    }

    #[test]
    fn the_drawing_menu_keeps_its_tools_rulers_palettes_brushes_and_drawings_in_menus_of_their_own() {
        let mut h = Harness::new();
        h.frame(vec![]);
        let bar = h.app.menu_bar();
        let drawing = &bar.iter().find(|(title, _)| title == "Drawing").expect("a Drawing menu").1;
        let within: Vec<(&str, Vec<String>)> = drawing
            .iter()
            .filter_map(|node| match node {
                MenuNode::Menu { title, items, .. } => Some((
                    title.as_str(),
                    items
                        .iter()
                        .filter_map(|item| match item {
                            MenuNode::Item(entry) => Some(entry.id.clone()),
                            _ => None,
                        })
                        .collect(),
                )),
                _ => None,
            })
            .collect();
        let titles: Vec<&str> = within.iter().map(|(title, _)| *title).collect();
        assert_eq!(&titles[..5], ["Tools", "Ruler", "Palette", "Brush", "Drawing"]);
        let has = |title: &str, id: &str| within.iter().any(|(t, ids)| *t == title && ids.iter().any(|i| i == id));
        assert!(has("Tools", "tool.brush") && has("Ruler", "guide.addRuler") && has("Palette", "palette.add") && has("Brush", "brush.next"));
        assert!(has("Drawing", "drawing.newDrawing") && has("Drawing", "exposure.insert") && has("Drawing", "substitution.next"));
        // What is of the art layer stays in the menu itself, and is short.
        let top: Vec<&str> = drawing.iter().filter_map(|node| if let MenuNode::Item(entry) = node { Some(entry.id.as_str()) } else { None }).collect();
        assert!(top.contains(&"art.lineArt") && top.contains(&"drawing.makeVector") && top.len() < 15, "{top:?}");
        // A command in a menu within the menu is run by its id as before.
        h.app.run_menu_command("tool.eraser", &h.ctx.clone());
        assert_eq!(h.app.tools.tool, Tool::Eraser);
    }

    #[test]
    fn the_file_menu_keeps_its_imports_in_an_import_menu() {
        let mut h = Harness::new();
        h.frame(vec![]);
        let bar = h.app.menu_bar();
        let file = &bar.iter().find(|(title, _)| title == "File").expect("a File menu").1;
        let Some(MenuNode::Menu { items, .. }) = file.iter().find(|node| matches!(node, MenuNode::Menu { title, .. } if title == "Import")) else {
            panic!("an Import menu in {file:?}")
        };
        // The imports, named without the menu's own word, then a line and their options.
        let shown: Vec<String> = items
            .iter()
            .map(|item| match item {
                MenuNode::Item(entry) => entry.title.clone(),
                MenuNode::Separator => "-".to_string(),
                other => panic!("{other:?}"),
            })
            .collect();
        assert_eq!(shown, ["Media…", "Character…", "Skins…", "Rig…", "-", "Read the Layer's Pictures Again", "Add Skin From Folder…"]);
        let top: Vec<&str> = file.iter().filter_map(|node| if let MenuNode::Item(entry) = node { Some(entry.id.as_str()) } else { None }).collect();
        assert!(!top.iter().any(|id| id.ends_with(".import")), "{top:?}");
        // The command keeps its whole name elsewhere.
        assert_eq!(crate::commands::command("rig.import").unwrap().title(), "Import Rig…");
    }

    #[test]
    fn the_menus_are_listed_for_a_menu_bar_outside_the_window_and_run_by_id() {
        let mut h = Harness::new();
        h.frame(vec![]);
        let bar = h.app.menu_bar();
        let titles: Vec<&str> = bar.iter().map(|(title, _)| title.as_str()).collect();
        assert_eq!(titles, ["File", "Edit", "Drawing", "Animation", "View", "Play", "Storyboard", "Scripts", "Workspace"]);
        // Everything that can be chosen, in the menus and in the menus within them.
        fn entries(nodes: &[MenuNode]) -> Vec<MenuEntry> {
            let of = |node: &MenuNode| match node {
                MenuNode::Item(entry) => vec![entry.clone()],
                MenuNode::Menu { items, .. } => entries(items),
                MenuNode::Separator | MenuNode::Note(_) => Vec::new(),
            };
            nodes.iter().flat_map(of).collect()
        }
        let all = |h: &Harness| h.app.menu_bar().iter().flat_map(|(_, nodes)| entries(nodes)).collect::<Vec<_>>();
        let entry = |h: &Harness, id: &str| all(h).into_iter().find(|entry| entry.id == id).unwrap_or_else(|| panic!("no {id}"));
        // A line is between two groups: never first, never last, never two together. Every
        // entry has a name and an id, and no two the same id, which is what it is run by.
        for (title, nodes) in &bar {
            let line = |node: &MenuNode| *node == MenuNode::Separator;
            assert!(!nodes.first().is_some_and(line) && !nodes.last().is_some_and(line), "{title}");
            assert!(nodes.windows(2).all(|pair| !line(&pair[0]) || !line(&pair[1])), "{title}");
        }
        let ids: Vec<String> = all(&h).into_iter().map(|entry| entry.id).collect();
        let distinct: std::collections::BTreeSet<&String> = ids.iter().collect();
        assert!(ids.len() == distinct.len() && all(&h).iter().all(|entry| !entry.id.is_empty() && !entry.title.is_empty()));
        assert_eq!(entry(&h, QUIT).title, "Quit");
        // About Iskra opens a window of its own, which Escape closes.
        assert!(entry(&h, ABOUT).enabled);
        run(&mut h, ABOUT);
        h.frame(vec![]);
        assert!(h.app.about_open);
        press(&mut h, Modifiers::NONE, Key::Escape);
        assert!(!h.app.about_open);
        // Each says how it is now: with nothing done yet Undo can't run and says only Undo;
        // a command with a shortcut has it.
        let undo = entry(&h, "edit.undo");
        assert_eq!((undo.title.as_str(), undo.enabled, undo.checked, undo.shortcut.is_some()), ("Undo", false, None, true));
        h.drag();
        let undo = entry(&h, "edit.undo");
        assert!(undo.enabled && undo.title.starts_with("Undo ") && undo.title.len() > 5, "{undo:?}");
        // A command chosen there is run as the window's menus run it; one that can't run
        // now, or that is not known, does nothing.
        let layers = |h: &Harness| h.app.session.project().shots[0].layers.len();
        let before = layers(&h);
        h.app.run_menu_command("layer.new", &h.ctx.clone());
        assert_eq!((layers(&h), &h.app.error), (before + 1, &None));
        h.app.run_menu_command("edit.redo", &h.ctx.clone());
        h.app.run_menu_command("no.such", &h.ctx.clone());
        assert_eq!((layers(&h), &h.app.error), (before + 1, &None));
        // The settings that are picked from a list are in menus within the menus, each
        // marked where it is the one that is on, and are chosen the same way: a page out of
        // the bar and in again.
        let page = entry(&h, "page.Media");
        assert_eq!(page.checked, Some(true));
        h.app.run_menu_command("page.Media", &h.ctx.clone());
        assert!(entry(&h, "page.Media").checked == Some(false) && h.app.prefs.hidden_pages.len() == 1);
        h.app.run_menu_command("page.Media", &h.ctx.clone());
        assert!(h.app.prefs.hidden_pages.is_empty());
        // What the Settings window has is in no menu; with no recent files that menu can't
        // be opened.
        assert!(all(&h).iter().all(|entry| !["autosave", "scale.", "appearance.", "surround.", "project."].iter().any(|moved| entry.id.starts_with(moved))));
        let recent = bar[0].1.iter().find_map(|node| match node {
            MenuNode::Menu { title, enabled, .. } if title == "Open Recent" => Some(*enabled),
            _ => None,
        });
        assert_eq!(recent, Some(false));
        // Where the system shows the menus in a bar of its own, the window draws none.
        let top = |h: &mut Harness| {
            h.frame(vec![]);
            h.app.viewport.shown_in.map_or(0.0, |shown| shown.top())
        };
        let with = top(&mut h);
        h.app.set_system_menus(true);
        let without = top(&mut h);
        assert!(without < with - 10.0, "{without} against {with}");
    }

    #[test]
    fn groups_side_by_side_are_stacked_and_the_one_taken_hold_of_comes_on_top() {
        use crate::nodes::Item;
        let mut h = Harness::new();
        h.frame(vec![]);
        let made = |h: &mut Harness| LayerId(h.app.run_for("layer.new", json!({})).unwrap()["id"].as_u64().unwrap());
        let (first, second) = (made(&mut h), made(&mut h));
        let group = |h: &mut Harness, layer: LayerId| h.app.run_for("group.new", json!({ "nodes": [layer.0] })).unwrap()["id"].as_u64().unwrap();
        let (one, two) = (group(&mut h, first), group(&mut h, second));
        for group in [one, two] {
            h.app.run("group.set", json!({ "group": group, "folded": false }));
        }
        // The two frames lap over each other.
        let moves = json!([{ "node": first.0, "at": [0.0, 0.0] }, { "node": second.0, "at": [60.0, 30.0] }]);
        h.app.run("node.place", json!({ "moves": moves }));
        run(&mut h, "panel.nodeView");
        h.frame(vec![]);
        h.frame(vec![]);
        let order = |h: &Harness| h.app.nodes.floating.iter().filter_map(|item| if let Item::Layer(id) = item { Some(*id) } else { None }).collect::<Vec<_>>();
        let strip = |h: &Harness, group: u64| h.app.nodes.frames.iter().find(|(id, ..)| id.0 == group).expect("the group's frame").2;
        let at = |h: &Harness, layer: LayerId| h.app.nodes.boxes.iter().find(|(item, _)| *item == Item::Layer(layer)).expect("a box").1;
        // Taken hold of by its strip, the first is on top: its frame and its layer after the
        // second's.
        let by = strip(&h, one).left_center() + egui::vec2(20.0, 0.0);
        click(&mut h, by);
        h.frame(vec![]);
        assert_eq!(order(&h), [second, first]);
        // Then the second's layer clicked: the second is on top, and the first's layer, where
        // the second's frame is over it, is out of reach.
        for _ in 0..30 {
            h.frame(vec![]);
        }
        // By its right end: its left end is under the first group's frame, out of reach.
        let first_frame = h.app.nodes.frames.iter().find(|(id, ..)| id.0 == one).unwrap().1;
        let on = at(&h, second).right_center() - egui::vec2(6.0, 0.0);
        assert!(!first_frame.contains(on), "{first_frame:?} {:?}", at(&h, second));
        click(&mut h, on);
        h.frame(vec![]);
        assert_eq!((order(&h), h.app.layer), (vec![first, second], Some(second)));
        let frame = h.app.nodes.frames.iter().find(|(id, ..)| id.0 == two).unwrap().1;
        let under = at(&h, first);
        let pos = [under.right_bottom() - egui::vec2(4.0, 4.0), under.center()].into_iter().find(|pos| frame.contains(*pos) && !at(&h, second).contains(*pos));
        let pos = pos.unwrap_or_else(|| panic!("the second frame laps over the first layer: {frame:?} {under:?}"));
        for _ in 0..30 {
            h.frame(vec![]);
        }
        click(&mut h, pos);
        assert_eq!(h.app.layer, Some(second), "under the second group's frame");
    }

    #[test]
    fn a_group_in_an_open_group_is_drawn_over_what_is_in_the_outer_one() {
        use crate::nodes::Item;
        let mut h = Harness::new();
        h.frame(vec![]);
        let made = |h: &mut Harness| LayerId(h.app.run_for("layer.new", json!({})).unwrap()["id"].as_u64().unwrap());
        let (outer_layer, inner_layer) = (made(&mut h), made(&mut h));
        let inner = h.app.run_for("group.new", json!({ "nodes": [inner_layer.0] })).unwrap()["id"].as_u64().unwrap();
        let outer = h.app.run_for("group.new", json!({ "nodes": [outer_layer.0, inner] })).unwrap()["id"].as_u64().unwrap();
        for group in [inner, outer] {
            h.app.run("group.set", json!({ "group": group, "folded": false }));
        }
        run(&mut h, "panel.nodeView");
        h.frame(vec![]);
        h.frame(vec![]);
        assert_eq!((h.app.nodes.frames.len(), &h.app.error), (2, &None));
        // What is in the inner group is drawn after what is only in the outer one.
        let order = |h: &Harness, item: Item| h.app.nodes.floating.iter().position(|other| *other == item);
        assert!(order(&h, Item::Layer(outer_layer)) < order(&h, Item::Layer(inner_layer)), "{:?}", h.app.nodes.floating);
        // The outer group's layer put just under the inner one's, where the inner frame lies
        // over it: there the frame is over it, and a click does not take it.
        let moves = json!([{ "node": inner_layer.0, "at": [0.0, 0.0] }, { "node": outer_layer.0, "at": [0.0, 40.0] }]);
        h.app.run("node.place", json!({ "moves": moves }));
        h.frame(vec![]);
        h.frame(vec![]);
        let at = |h: &Harness, item: Item| h.app.nodes.boxes.iter().find(|(other, _)| *other == item).expect("the node has a box").1;
        let inner_frame = h.app.nodes.frames.iter().find(|(group, ..)| group.0 == inner).expect("the inner frame").1;
        let outer_box = at(&h, Item::Layer(outer_layer));
        let pos = egui::pos2(outer_box.center().x, outer_box.top() + 4.0);
        assert!(inner_frame.contains(pos) && !at(&h, Item::Layer(inner_layer)).contains(pos), "{inner_frame:?} {outer_box:?}");
        h.app.layer = Some(inner_layer);
        click(&mut h, pos);
        assert_eq!(h.app.layer, Some(inner_layer), "under the inner frame the outer group's layer is out of reach");
        // Clear of the inner frame it is taken (a while later, not as a double click).
        for _ in 0..30 {
            h.frame(vec![]);
        }
        // At its left end: the inner group's way out laps over the middle of the frame's bottom.
        let clear = egui::pos2(outer_box.left() + 10.0, outer_box.bottom() - 3.0);
        assert!(!inner_frame.contains(clear), "{inner_frame:?} {outer_box:?}");
        click(&mut h, clear);
        assert_eq!(h.app.layer, Some(outer_layer));
    }

    #[test]
    fn a_group_is_a_frame_in_the_node_view_and_a_row_on_the_timeline_and_folds_into_one_in_each_apart() {
        use crate::nodes::Item;
        let mut h = Harness::new();
        bare_camera(&mut h);
        let layer = h.app.layer.unwrap();
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        let sky = LayerId(h.app.run_for("layer.new", json!({})).unwrap()["id"].as_u64().unwrap());
        let made = h.app.run_for("group.new", json!({ "nodes": [peg.0, layer.0], "name": "Rig" })).unwrap()["id"].as_u64().unwrap();
        let rig = iskra_model::GroupId(made);
        run(&mut h, "panel.nodeView");
        h.frame(vec![]);
        let at = |h: &Harness, item: Item| h.app.nodes.boxes.iter().find(|(other, _)| *other == item).map(|(_, rect)| *rect);
        let group = |h: &Harness| h.app.session.project().shots[0].group(rig).cloned().unwrap();
        let rows = |h: &Harness| h.app.timeline.names.iter().map(|(node, _)| *node).collect::<Vec<_>>();

        // What is in the open group is drawn over its frame, and what is in none under it.
        assert_eq!(h.app.nodes.floating, [Item::Peg(peg), Item::Layer(layer)]);
        assert!(
            h.app.nodes.boxes.iter().position(|(item, _)| *item == Item::Layer(sky)) < h.app.nodes.boxes.iter().position(|(item, _)| *item == Item::Peg(peg))
        );
        // Open, the group is a frame round what is in it, and has a row over their rows.
        let [(framed, frame, _)] = h.app.nodes.frames[..] else { panic!("one frame: {:?}", h.app.nodes.frames) };
        let (peg_box, layer_box, sky_box) = (at(&h, Item::Peg(peg)).unwrap(), at(&h, Item::Layer(layer)).unwrap(), at(&h, Item::Layer(sky)).unwrap());
        assert!(framed == rig && frame.contains_rect(peg_box) && frame.contains_rect(layer_box) && !frame.contains_rect(sky_box), "{frame:?}");
        assert!(at(&h, Item::Group(rig)).is_none() && rows(&h).contains(&Node::Layer(layer)) && rows(&h).contains(&Node::Peg(peg)));
        let [(named, arrow)] = h.app.timeline.group_names[..] else { panic!("one group row: {:?}", h.app.timeline.group_names) };
        let peg_row = h.app.timeline.names.iter().find(|(node, _)| *node == Node::Peg(peg)).unwrap().1;
        assert!(named == rig && arrow.center().y < peg_row.center().y, "the group's row is over the rows of what is in it");

        // Its arrow folds its rows: they are put away, and the node view keeps it open.
        click(&mut h, arrow.center());
        assert_eq!((group(&h).rows_folded, h.app.session.history().undo_label(), &h.app.error), (true, Some("Set Group"), &None));
        assert_eq!((rows(&h), h.app.timeline.group_names.len()), (vec![Node::Layer(sky)], 1));
        assert!(!group(&h).folded && at(&h, Item::Group(rig)).is_none() && h.app.nodes.frames.len() == 1);
        // Opened on the timeline, and folded in the node view: it is one box, with the wire
        // that went from the layer into the composite going from the box, and its rows stay.
        h.app.run("group.set", json!({ "group": rig.0, "rowsFolded": false }));
        h.app.run("group.set", json!({ "group": rig.0, "folded": true }));
        h.frame(vec![]);
        assert_eq!((group(&h).folded, group(&h).rows_folded, rows(&h).len(), &h.app.error), (true, false, 3, &None));
        let folded = at(&h, Item::Group(rig)).expect("a folded group is a box");
        assert!(
            at(&h, Item::Peg(peg)).is_none() && at(&h, Item::Layer(layer)).is_none() && at(&h, Item::Layer(sky)).is_some() && h.app.nodes.frames.is_empty()
        );
        // The box is dragged, and its place kept with the shot.
        h.drag_between(folded.center(), folded.center() + egui::vec2(-50.0, 30.0));
        assert_eq!((h.app.session.history().undo_label(), &h.app.error), (Some("Move Node"), &None));
        assert!((at(&h, Item::Group(rig)).unwrap().center() - folded.center() - egui::vec2(-50.0, 30.0)).length() < 8.0);
        // Folded, the box has the group's ports: a wire that leaves a Port Out leaves the box
        // at that port's place along its bottom, the first of two a third of the way along.
        let composite = h.app.session.project().shots[0].composites[0].id;
        h.app.run("effect.new", json!({ "kind": "portOut", "on": { "layer": layer.0 }, "group": rig.0 }));
        h.app.run("effect.new", json!({ "kind": "portOut", "group": rig.0 }));
        h.frame(vec![]);
        assert_eq!((group(&h).members.len(), &h.app.error), (4, &None));
        let onto = at(&h, Item::Group(rig)).unwrap();
        let leaves: Vec<Pos2> = h
            .app
            .nodes
            .wire_ends
            .iter()
            .filter(|(from, to, ..)| *from == Item::Group(rig) && *to == Item::Composite(composite))
            .map(|(.., from, _)| *from)
            .collect();
        let [left] = leaves[..] else { panic!("one wire from the box to the composite: {leaves:?}") };
        assert!((left.x - (onto.left() + onto.width() / 3.0)).abs() < 1.0 && (left.y - onto.bottom()).abs() < 1.0, "{left:?} of {onto:?}");
        // Opened again in the node view, all is as it was.
        h.app.run("group.set", json!({ "group": rig.0, "folded": false }));
        h.frame(vec![]);
        assert!(!group(&h).folded && at(&h, Item::Layer(layer)).is_some() && rows(&h).len() == 3);
        // What was put away went along with the box when it was dragged.
        let went = at(&h, Item::Layer(layer)).unwrap().center() - layer_box.center();
        assert!((went - egui::vec2(-50.0, 30.0)).length() < 8.0, "{went:?}");
        // Open, the ports are on the frame, not in it: the ports out side by side on its
        // bottom edge, smaller than a box, and a port in on its top edge.
        h.app.run("effect.new", json!({ "kind": "portIn", "group": rig.0 }));
        h.frame(vec![]);
        let frame = h.app.nodes.frames[0].1;
        let kind = |h: &Harness, id: iskra_model::EffectId| h.app.session.project().shots[0].effect(id).unwrap().kind.clone();
        let ports: Vec<(iskra_model::EffectId, egui::Rect)> =
            h.app.nodes.boxes.iter().filter_map(|(item, rect)| if let Item::Effect(id) = item { Some((*id, *rect)) } else { None }).collect();
        let outs: Vec<&(iskra_model::EffectId, egui::Rect)> = ports.iter().filter(|(id, _)| kind(&h, *id) == "portOut").collect();
        let ins: Vec<&(iskra_model::EffectId, egui::Rect)> = ports.iter().filter(|(id, _)| kind(&h, *id) == "portIn").collect();
        assert_eq!((outs.len(), ins.len()), (2, 1));
        let layer_now = at(&h, Item::Layer(layer)).unwrap();
        for (_, tab) in &outs {
            assert!(tab.top() < frame.bottom() && tab.bottom() > frame.bottom() && tab.height() < layer_now.height() && !tab.intersects(layer_now), "{tab:?}");
        }
        assert!(ins[0].1.bottom() > frame.top() && ins[0].1.top() < frame.top() && (outs[0].1.center().x - outs[1].1.center().x).abs() > outs[0].1.width());
        // The wire from the layer runs inside the frame to the port, and from the port on
        // outside to the composite.
        let wired = outs.iter().find(|(id, _)| h.app.session.project().shots[0].effect(*id).unwrap().picture().is_some()).unwrap();
        let ends =
            |h: &Harness, from: Item, to: Item| h.app.nodes.wire_ends.iter().find(|(a, b, ..)| *a == from && *b == to).map(|(.., from, to)| (*from, *to));
        let (_, arrives) = ends(&h, Item::Layer(layer), Item::Effect(wired.0)).expect("a wire from the layer to the port");
        let (leaves, _) = ends(&h, Item::Effect(wired.0), Item::Composite(composite)).expect("a wire from the port to the composite");
        assert!((arrives - wired.1.center_top()).length() < 1.0 && (leaves - wired.1.center_bottom()).length() < 1.0, "{arrives:?} {leaves:?}");
        // Dragged by its name, the open group moves with all that is in it.
        let (name, peg_now) = (h.app.nodes.frames[0].2, at(&h, Item::Peg(peg)).unwrap());
        h.drag_between(name.center(), name.center() + egui::vec2(60.0, 40.0));
        assert_eq!((h.app.session.history().undo_label(), &h.app.error), (Some("Move Node"), &None));
        let moved = [(Item::Layer(layer), layer_now), (Item::Peg(peg), peg_now), (Item::Effect(wired.0), wired.1)];
        for (item, was) in moved {
            let by = at(&h, item).unwrap().center() - was.center();
            assert!((by - egui::vec2(60.0, 40.0)).length() < 8.0, "{item:?} by {by:?}");
        }
        assert!((h.app.nodes.frames[0].1.center() - frame.center() - egui::vec2(60.0, 40.0)).length() < 8.0 && at(&h, Item::Layer(sky)) == Some(sky_box));
        // By the strip along its top anywhere, out to its right end, as well as by its name.
        let (moved, strip) = (h.app.nodes.frames[0].1, h.app.nodes.frames[0].2);
        assert!((strip.right() - moved.right()).abs() < 8.0 && (strip.left() - moved.left()).abs() < 8.0, "{strip:?} across {moved:?}");
        let end = strip.right_center() - egui::vec2(6.0, 0.0);
        h.drag_between(end, end + egui::vec2(-30.0, 20.0));
        assert_eq!((h.app.session.history().undo_label(), &h.app.error), (Some("Move Node"), &None));
        assert!((h.app.nodes.frames[0].1.center() - moved.center() - egui::vec2(-30.0, 20.0)).length() < 8.0, "{:?}", h.app.nodes.frames[0].1);
        h.app.session.undo();
        h.frame(vec![]);
        // A wire let go on a port that carries something already makes another port beside
        // it, as a composite makes room for another input: the peg's transform goes out by
        // a third port, and the layer's picture still by the first.
        let of_kind = |h: &Harness, kind: &str| {
            let shot = &h.app.session.project().shots[0];
            shot.effects.iter().filter(|effect| effect.kind == kind).map(|effect| (effect.id, effect.picture(), effect.parent)).collect::<Vec<_>>()
        };
        let taken = at(&h, Item::Effect(wired.0)).unwrap();
        h.drag_between(at(&h, Item::Peg(peg)).unwrap().center_bottom(), taken.center());
        let outs = of_kind(&h, "portOut");
        assert_eq!((outs.len(), h.app.session.history().undo_label(), &h.app.error), (3, Some("Add Effect"), &None));
        assert!(
            outs.iter().any(|(id, picture, _)| *id == wired.0 && picture.is_some())
                && outs.iter().any(|(_, picture, parent)| picture.is_none() && *parent == Some(peg))
        );
        let beside = outs.iter().find(|(_, _, parent)| *parent == Some(peg)).unwrap().0;
        let (first, new) = (at(&h, Item::Effect(wired.0)).unwrap(), at(&h, Item::Effect(beside)).unwrap());
        assert!(new.center().x > first.center().x && (new.center().y - first.center().y).abs() < 1.0 && group(&h).members.contains(&beside.0));
        // Let go on the frame's top edge, where no port is, a wire makes a port in there.
        let frame = h.app.nodes.frames[0].1;
        h.drag_between(at(&h, Item::Layer(sky)).unwrap().center_bottom(), egui::pos2(frame.left() + 6.0, frame.top()));
        let ins = of_kind(&h, "portIn");
        assert_eq!((ins.len(), &h.app.error), (2, &None));
        assert!(ins.iter().any(|(_, picture, _)| *picture == Some(iskra_model::Source::Layer(sky))), "{ins:?}");
        // The frame leaves room round what is in it.
        let (frame, inside) = (h.app.nodes.frames[0].1, at(&h, Item::Layer(layer)).unwrap());
        assert!(inside.left() - frame.left() >= 25.0 && frame.bottom() - inside.bottom() >= 25.0, "{frame:?} round {inside:?}");
        // Taken apart, what was in it stays.
        h.app.run("group.delete", json!({ "group": rig.0 }));
        h.frame(vec![]);
        assert!(h.app.nodes.frames.is_empty() && h.app.timeline.group_names.is_empty() && rows(&h).len() == 3 && h.app.error.is_none());
    }

    #[test]
    fn a_template_is_applied_onto_the_selected_peg_from_a_window_that_says_what_goes_where() {
        let dir = tempfile::tempdir().unwrap();
        let mut h = Harness::new();
        h.drag();
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        // The peg's pose is saved, and then it is put back to where it was drawn.
        h.app.run("peg.setTransform", json!({ "peg": peg.0, "rotation": 25 }));
        let saved = h.app.run_for("library.save", json!({ "folder": dir.path(), "name": "Pose", "nodes": [{ "peg": peg.0 }] })).unwrap();
        let path = std::path::PathBuf::from(saved["path"].as_str().unwrap());
        h.app.run("peg.setTransform", json!({ "peg": peg.0, "rotation": 0 }));
        let rotation = |h: &Harness| peg_transform(h, peg).rotation;
        let (pegs, steps) = (h.app.session.project().shots[0].pegs.len(), h.app.session.history().entries().len());

        // Asked for from the library, a window says what would go where and changes nothing.
        h.app.library_actions(vec![library::Action::Apply(path)]);
        h.frame(vec![]);
        h.frame(vec![]);
        let would = h.app.applying_template.as_ref().and_then(|applying| applying.would.clone()).expect("the window has asked what would happen");
        assert_eq!((&would["applied"], &would["skipped"], &would["matches"][0]["found"]), (&json!(2), &json!(0), &json!("matched")));
        assert_eq!((rotation(&h), h.app.session.history().entries().len(), h.app.layer), (0.0, steps, None));
        // Escape closes it; asked again and applied, the shot's own peg has the pose, in one step.
        press(&mut h, Modifiers::NONE, Key::Escape);
        assert!(h.app.applying_template.is_none() && rotation(&h) == 0.0);
        let applying = ApplyTemplate {
            path: dir.path().join("Pose.iskratpl"),
            onto_selected: true,
            mirror: false,
            merge: false,
            at_playhead: false,
            replace_drawings: false,
            make_missing: false,
            drawings: Default::default(),
            map: Default::default(),
            would: None,
            problem: None,
        };
        let applying = ApplyTemplate { map: [("Hand".to_string(), "Drawing".to_string())].into(), ..applying };
        let params = h.app.apply_params(&applying, false);
        assert_eq!((&params["peg"], &params["preview"], params.get("frame"), &params["keepMatches"]), (&json!(peg.0), &json!(false), None, &json!(true)));
        assert_eq!(h.app.apply_params(&applying, true)["keepMatches"], json!(false), "a preview keeps nothing");
        let chosen = ApplyTemplate { drawings: [("Hand".to_string(), [("1".to_string(), true)].into())].into(), ..applying };
        assert_eq!(h.app.apply_params(&chosen, true)["drawings"], json!({ "Hand": { "1": true } }), "drawings chosen one at a time go along");
        h.app.run("library.apply", params);
        assert_eq!((rotation(&h), h.app.session.history().undo_label(), &h.app.error), (25.0, Some("Apply Template"), &None));
        assert_eq!((h.app.session.project().shots[0].pegs.len(), h.app.session.project().shots[0].layers.len()), (pegs, 1), "nothing was copied");
        // The match made by hand is kept with the peg, and the window has it again next time.
        h.app.library_actions(vec![library::Action::Apply(dir.path().join("Pose.iskratpl"))]);
        let map = h.app.applying_template.as_ref().map(|applying| applying.map.clone());
        assert_eq!(map, Some([("Hand".to_string(), "Drawing".to_string())].into()));
    }

    #[test]
    fn several_nodes_are_picked_together_and_moved_grouped_and_saved_as_one() {
        use crate::nodes::Item;
        let dir = tempfile::tempdir().unwrap();
        let mut h = Harness::new();
        bare_camera(&mut h);
        h.drag();
        let layer = h.app.layer.unwrap();
        h.app.prefs.library_folders = vec![dir.path().to_path_buf()];
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        let sky = LayerId(h.app.run_for("layer.new", json!({})).unwrap()["id"].as_u64().unwrap());
        run(&mut h, "panel.nodeView");
        h.frame(vec![]);
        let at = |h: &Harness, item: Item| h.app.nodes.boxes.iter().find(|(other, _)| *other == item).expect("the node has a box").1;
        let picked = |h: &Harness| h.app.picked.iter().copied().collect::<Vec<_>>();
        let (peg_box, layer_box, sky_box) = (at(&h, Item::Peg(peg)), at(&h, Item::Layer(layer)), at(&h, Item::Layer(sky)));

        // A box dragged out on the background round the peg and its layer picks the two, and
        // not the layer beside them.
        let around = peg_box.union(layer_box).expand(10.0);
        assert!(!around.intersects(sky_box), "{around:?} {sky_box:?}");
        h.drag_between(around.left_top(), around.right_bottom());
        assert_eq!(picked(&h), {
            let mut both = vec![layer.0, peg.0];
            both.sort_unstable();
            both
        });
        // One of them dragged takes the other along, in one step.
        let steps = h.app.session.history().entries().len();
        h.drag_between(layer_box.center(), layer_box.center() + egui::vec2(-30.0, 25.0));
        assert_eq!((h.app.session.history().entries().len(), h.app.session.history().undo_label(), &h.app.error), (steps + 1, Some("Move Node"), &None));
        for (item, was) in [(Item::Peg(peg), peg_box), (Item::Layer(layer), layer_box)] {
            assert!((at(&h, item).center() - was.center() - egui::vec2(-30.0, 25.0)).length() < 8.0, "{item:?}");
        }
        assert!((at(&h, Item::Layer(sky)).center() - sky_box.center()).length() < 0.5, "what is not picked stays");
        // With Shift held, a click picks another beside them, and a second lets it go.
        let shift = Modifiers { shift: true, ..Modifiers::NONE };
        let shift_click = |h: &mut Harness, pos: Pos2| {
            let button = |pressed| Event::PointerButton { pos, button: PointerButton::Primary, pressed, modifiers: shift };
            h.frame(vec![Event::ModifiersChanged(shift), Event::PointerMoved(pos)]);
            h.frame(vec![button(true)]);
            h.frame(vec![button(false)]);
            h.frame(vec![Event::ModifiersChanged(Modifiers::NONE)]);
        };
        let on = at(&h, Item::Layer(sky)).center();
        shift_click(&mut h, on);
        assert_eq!(picked(&h).len(), 3);
        shift_click(&mut h, on);
        assert_eq!(picked(&h).len(), 2);
        // Dragged onto the Library panel, the two are one template.
        h.app.open_panel(Panel::Library);
        h.frame(vec![]);
        let area = h.app.library_area.expect("the Library panel is shown");
        h.drag_between(at(&h, Item::Peg(peg)).center(), area.center());
        let parts = h.app.saving_template.as_ref().map(|saving| saving.parts.clone()).expect("the window asks for a name");
        assert!(parts.len() == 2 && parts.contains(&Part::Peg(peg)) && parts.contains(&Part::Layer(layer)), "{parts:?}");
        press(&mut h, Modifiers::NONE, Key::Escape);
        // A plain click on a node selects it alone again; one on the background lets all go.
        let on = at(&h, Item::Layer(sky)).center();
        click(&mut h, on);
        assert_eq!((picked(&h), h.app.layer), (vec![sky.0], Some(sky)));

        // On the timeline, a click with Shift picks the rows from the one clicked last to
        // that one, and a dragged row takes them to the library with it.
        let name = |h: &Harness, node: Node| h.app.timeline.names.iter().find(|(other, _)| *other == node).expect("the node has a row").1.center();
        let (first, last) = (h.app.timeline.names[0], *h.app.timeline.names.last().unwrap());
        click(&mut h, first.1.center());
        shift_click(&mut h, last.1.center());
        assert_eq!(picked(&h).len(), 3, "all three rows");
        let grip = name(&h, Node::Layer(layer));
        h.drag_between(grip, area.center());
        assert_eq!(h.app.saving_template.as_ref().map(|saving| saving.parts.len()), Some(3));
        press(&mut h, Modifiers::NONE, Key::Escape);
        // A plain click on a row selects it alone.
        click(&mut h, grip);
        assert_eq!((picked(&h), h.app.layer), (vec![layer.0], Some(layer)));
    }

    #[test]
    fn nodes_are_dragged_onto_the_library_to_save_them_and_templates_out_of_it_into_the_shot() {
        use crate::nodes::Item;
        let dir = tempfile::tempdir().unwrap();
        let mut h = Harness::new();
        bare_camera(&mut h);
        // A stroke, so that the template has something to show.
        h.drag();
        let layer = h.app.layer.unwrap();
        h.app.prefs.library_folders = vec![dir.path().to_path_buf()];
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        run(&mut h, "panel.nodeView");
        run(&mut h, "panel.library");
        h.frame(vec![]);
        let at = |h: &Harness, item: Item| h.app.nodes.boxes.iter().find(|(other, _)| *other == item).expect("the node has a box").1;
        let showing = |h: &Harness, panel: Panel| h.app.dock_drawn.1.iter().find(|group| group.showing() == Some(panel)).expect("the panel is showing").content;
        let area = h.app.library_area.expect("the Library panel is showing");
        let steps = h.app.session.history().entries().len();

        // A peg's box dragged onto the Library panel: a window asks what to call the template,
        // and Enter saves it into the folder the panel shows. The box stays where it was.
        h.drag_between(at(&h, Item::Peg(peg)).center(), area.center());
        let asked = h.app.saving_template.as_ref().map(|saving| (saving.name.clone(), saving.folder.clone(), saving.parts.clone()));
        assert_eq!(asked, Some(("Drawing-P".to_string(), dir.path().to_path_buf(), vec![Part::Peg(peg)])));
        h.frame(vec![]);
        press(&mut h, Modifiers::NONE, Key::Enter);
        let file = dir.path().join("Drawing-P.iskratpl");
        assert!(file.is_file() && h.app.saving_template.is_none(), "{:?}", h.app.error);
        assert_eq!(h.app.session.history().entries().len(), steps, "nothing of the project changed, nor was the node moved in the view");
        h.frame(vec![]);
        let [(path, tile)] = &h.app.library.tiles[..] else { panic!("one template in the panel: {:?}", h.app.library.tiles) };
        assert_eq!(path, &file);
        let tile = *tile;

        // The template dragged out onto the node view: copies of the peg and its layer, in one
        // step, with free names; what was put in is selected.
        let free = showing(&h, Panel::NodeView).left_top() + egui::vec2(60.0, 60.0);
        h.drag_between(tile.center(), free);
        let shot = h.app.session.project().shots[0].clone();
        assert_eq!((h.app.session.history().undo_label(), &h.app.error), (Some("Place Template"), &None));
        assert_eq!(shot.node_names().collect::<Vec<_>>(), ["Drawing 2", "Drawing", "Drawing-P", "Drawing-P 2", "Composite"]);
        assert_eq!((h.app.peg, h.app.layer, shot.layers[0].parent), (Some(shot.pegs[1].id), None, Some(shot.pegs[1].id)));
        assert_eq!(shot.layers[0].template.as_deref(), Some("Drawing-P"));
        assert!(!shot.layers[0].drawings[0].drawing.bounds().is_empty() && shot.stack() == [shot.layers[0].id, layer]);
        // Let go onto a peg's box, it is to be applied onto that peg: the window that says what
        // would change opens for it, and nothing is changed yet.
        let steps = h.app.session.history().entries().len();
        h.frame(vec![]);
        h.drag_between(tile.center(), at(&h, Item::Peg(peg)).center());
        let asked = h.app.applying_template.as_ref().map(|applying| (applying.path.clone(), applying.onto_selected));
        assert_eq!((asked, h.app.peg, h.app.session.history().entries().len(), &h.app.error), (Some((file.clone(), true)), Some(peg), steps, &None));
        h.app.applying_template = None;
        // Let go over a panel that doesn't show the shot, it is put nowhere.
        h.drag_between(tile.center(), showing(&h, Panel::Palette).center());
        assert_eq!((h.app.session.history().entries().len(), h.app.library_drag.is_some()), (steps, false));

        // A row of the timeline is dragged there by its name. Escape leaves without saving.
        let name = h.app.timeline.names.iter().find(|(node, _)| *node == Node::Layer(layer)).expect("the layer has a row").1;
        h.drag_between(name.center(), area.center());
        assert_eq!(h.app.saving_template.as_ref().map(|saving| (saving.name.as_str(), saving.parts.clone())), Some(("Drawing", vec![Part::Layer(layer)])));
        press(&mut h, Modifiers::NONE, Key::Escape);
        assert!(h.app.saving_template.is_none() && !dir.path().join("Drawing.iskratpl").exists());
        // Let go anywhere else, a row or a box is on its way to no library.
        h.drag_between(name.center(), free);
        h.drag_between(at(&h, Item::Peg(peg)).center(), showing(&h, Panel::Palette).center());
        assert!(h.app.saving_template.is_none() && h.app.session.history().entries().len() == steps);
    }

    #[test]
    fn the_library_panel_goes_through_folders_and_a_drop_on_a_folder_saves_into_it() {
        let dir = tempfile::tempdir().unwrap();
        let props = dir.path().join("Props");
        std::fs::create_dir(&props).unwrap();
        let mut h = Harness::new();
        let layer = h.app.layer.unwrap();
        run(&mut h, "panel.library");
        assert!(h.app.library.folder().is_none(), "with no folder in the library, the panel asks for one");
        // Without a folder there is nowhere to save: the status bar says how to add one.
        run(&mut h, "library.save");
        assert!(h.app.saving_template.is_none() && h.app.error.as_ref().is_some_and(|why| why.contains("no folder yet")));
        h.app.prefs.library_folders = vec![dir.path().to_path_buf()];
        h.frame(vec![]);
        h.frame(vec![]);
        assert_eq!(h.app.library.folder(), Some(dir.path()));
        let [(folder, tile)] = &h.app.library.folder_tiles[..] else { panic!("one folder in the panel") };
        assert_eq!(folder, &props);
        let tile = *tile;

        // A row let go on the folder's tile is saved into that folder, under the name typed.
        let name = h.app.timeline.names.iter().find(|(node, _)| *node == Node::Layer(layer)).expect("the layer has a row").1;
        h.drag_between(name.center(), tile.center());
        assert_eq!(h.app.saving_template.as_ref().map(|saving| saving.folder.clone()), Some(props.clone()));
        h.app.saving_template.as_mut().unwrap().name = "Ball".to_string();
        h.app.saving_template.as_mut().unwrap().tags = "prop, round".to_string();
        h.frame(vec![]);
        press(&mut h, Modifiers::NONE, Key::Enter);
        let saved = iskra_store::read_template_info(&props.join("Ball.iskratpl")).expect("the template is in the folder");
        assert_eq!((saved.tags, saved.source.as_str()), (vec!["prop".to_string(), "round".to_string()], "Untitled"));
        // The panel shows the folder it was saved into; saving the same name again offers to
        // replace it, and does.
        h.frame(vec![]);
        assert_eq!((h.app.library.folder(), h.app.library.tiles.len()), (Some(props.as_path()), 1));
        run(&mut h, "library.save");
        h.app.saving_template.as_mut().unwrap().name = "Ball".to_string();
        h.frame(vec![]);
        press(&mut h, Modifiers::NONE, Key::Enter);
        assert!(h.app.saving_template.is_none() && h.app.error.is_none(), "{:?}", h.app.error);
        assert!(iskra_store::read_template_info(&props.join("Ball.iskratpl")).unwrap().tags.is_empty());
        // A name that can be no file's keeps the window open, which says why.
        run(&mut h, "library.save");
        h.app.saving_template.as_mut().unwrap().name = "a/b".to_string();
        h.frame(vec![]);
        press(&mut h, Modifiers::NONE, Key::Enter);
        assert!(h.app.saving_template.as_ref().is_some_and(|saving| saving.problem.as_ref().is_some_and(|why| why.contains("can't contain"))));
    }

    #[test]
    fn a_shot_is_sent_out_and_brought_back_through_a_window_that_says_what_changed() {
        let dir = tempfile::tempdir().unwrap();
        let mut h = Harness::new();
        h.drag();
        let shot = h.app.shot.unwrap();
        let status = |h: &Harness| h.app.session.project().shot(shot).map(|shot| (shot.status, shot.out_to.clone())).unwrap();

        // Sent out to a folder: the window asks whom to, and Enter sends.
        h.app.send_out(vec![shot], dir.path().to_path_buf());
        h.frame(vec![]);
        h.frame(vec![Event::Text("Ana".to_string())]);
        press(&mut h, Modifiers::NONE, Key::Enter);
        let file = dir.path().join("Shot_01.iskra");
        assert!(file.is_file() && h.app.sending_out.is_none(), "{:?}", h.app.error);
        assert_eq!((status(&h), h.app.session.history().undo_label()), ((Status::Out, Some("Ana".to_string())), Some("Send Shots Out")));
        // The bin and the storyboard show its status, and every page still draws.
        for page in ["page.media", "page.storyboard", "page.animation"] {
            run(&mut h, page);
            h.frame(vec![]);
        }

        // Whoever has it adds a layer and saves.
        let mut theirs = Session::new();
        theirs.execute("file.open", json!({ "path": file })).unwrap();
        theirs.execute("shot.load", Value::Null).unwrap();
        theirs.execute("layer.new", json!({ "name": "Shadow" })).unwrap();
        theirs.execute("file.save", Value::Null).unwrap();
        drop(theirs);

        // Brought back: the window says what would change. Escape leaves the shot as it is.
        let steps = h.app.session.history().entries().len();
        h.app.bring_back(file.clone(), None);
        let asked = h.app.bringing_back.as_ref().map(|back| (back.shot, back.name.clone(), back.to.clone(), back.differences.clone()));
        let said = vec!["A new layer, “Shadow”, with 0 drawings.".to_string(), "What is seen, or which layer is over which, has changed.".to_string()];
        assert_eq!(asked, Some((shot, "Shot_01".to_string(), "Ana".to_string(), said)), "{:?}", h.app.error);
        h.frame(vec![]);
        press(&mut h, Modifiers::NONE, Key::Escape);
        assert!(h.app.bringing_back.is_none() && h.app.session.history().entries().len() == steps && status(&h).0 == Status::Out);
        // Enter replaces the shot, in one step, and a layer of the new one is drawn on.
        h.app.bring_back(file, None);
        h.frame(vec![]);
        press(&mut h, Modifiers::NONE, Key::Enter);
        h.frame(vec![]);
        let back = h.app.session.project().shot(shot).unwrap().clone();
        assert_eq!((status(&h), back.layers.len(), h.app.session.history().undo_label()), ((Status::Animation, None), 2, Some("Bring Shot Back")));
        assert!(h.app.bringing_back.is_none() && h.app.layer.is_some_and(|layer| back.layer(layer).is_some()), "{:?}", h.app.error);
        let drawn = back.layers[1].drawing_at(0).map(|entry| entry.drawing.bounds().width());
        assert!(drawn.is_some_and(|width| width > 300), "with the drawing it went out with: {drawn:?}");
        // A file that is no shot's opens no window; the status bar says why.
        h.app.bring_back(dir.path().join("none.iskra"), None);
        assert!(h.app.bringing_back.is_none() && h.app.error.is_some());
    }

    #[test]
    fn a_shot_with_a_blend_is_drawn_on_the_card_whatever_the_switch_says() {
        let Some(compositor) = iskra_gpu::Compositor::headless() else {
            eprintln!("no graphics card here: the viewport on the card is not tried");
            return;
        };
        let renderer = egui_wgpu::Renderer::new(compositor.device(), wgpu::TextureFormat::Rgba8Unorm, egui_wgpu::RendererOptions::default());
        let mut h = Harness::new();
        h.app.viewport.cache = Some(playback::FrameCache::new(compositor, std::sync::Arc::new(egui::mutex::RwLock::new(renderer))));
        h.drag();
        let layer = h.app.layer.unwrap();
        h.frame(vec![]);
        assert!(!h.app.viewport.from_card, "from its tiles, as the switch is off");
        let node = h.app.run_for("effect.new", json!({ "kind": "blend", "on": { "layer": layer.0 } })).unwrap()["id"].as_u64().unwrap();
        h.frame(vec![]);
        assert!(!h.app.viewport.from_card, "a Normal Blend is laid over, as the tiles have it");
        h.app.run("effect.set", json!({ "effect": node, "param": "mode", "value": "Add" }));
        h.frame(vec![]);
        assert!(h.app.viewport.from_card && h.app.error.is_none(), "{:?}", h.app.error);
    }

    #[test]
    fn on_the_card_the_drawings_follow_a_colour_while_it_is_picked() {
        let Some(compositor) = iskra_gpu::Compositor::headless() else {
            eprintln!("no graphics card here: the viewport on the card is not tried");
            return;
        };
        let renderer = egui_wgpu::Renderer::new(compositor.device(), wgpu::TextureFormat::Rgba8Unorm, egui_wgpu::RendererOptions::default());
        let mut h = Harness::swatches();
        h.app.viewport.cache = Some(playback::FrameCache::new(compositor, std::sync::Arc::new(egui::mutex::RwLock::new(renderer))));
        h.drag();
        run(&mut h, "view.onCard");
        h.frame(vec![]);
        let shown = h.app.viewport.shown_in.expect("the viewport is shown");
        let at = |h: &Harness| {
            let pixels = h.app.viewport.cache.as_ref().and_then(playback::FrameCache::window_pixels).expect("the picture is read back");
            pixels[(350.0 - shown.min.y) as usize * shown.width().round() as usize + (500.0 - shown.min.x) as usize]
        };
        let black = at(&h);
        assert!(h.app.viewport.from_card && black[3] > 200 && black[0] < 40, "{black:?}");
        // The stroke's swatch picked white, not yet let go: the picture follows.
        h.app.swatch_edit = Some((SwatchId(1), [255, 255, 255, 255]));
        h.frame(vec![]);
        let white = at(&h);
        assert!(h.app.viewport.from_card && white[0] > 200 && white[3] > 200, "{white:?}");
        assert_eq!(h.app.session.project().palette.color(SwatchId(1)), [0, 0, 0, 255], "the palette itself is as it was");
        h.app.swatch_edit = None;
        h.frame(vec![]);
        assert!(at(&h)[0] < 40);
    }

    #[test]
    fn standing_still_the_viewport_is_the_cards_picture_when_asked_with_the_stroke_as_it_is_drawn() {
        let Some(compositor) = iskra_gpu::Compositor::headless() else {
            eprintln!("no graphics card here: the viewport on the card is not tried");
            return;
        };
        let renderer = egui_wgpu::Renderer::new(compositor.device(), wgpu::TextureFormat::Rgba8Unorm, egui_wgpu::RendererOptions::default());
        let mut h = Harness::new();
        h.app.viewport.cache = Some(playback::FrameCache::new(compositor, std::sync::Arc::new(egui::mutex::RwLock::new(renderer))));
        h.drag();
        h.frame(vec![]);
        assert!(!h.app.viewport.from_card && h.app.viewport.tiles_shown() > 0, "unasked, the shot is drawn from its tiles");
        // Asked for, it is one picture made on the card, and no tile is drawn.
        run(&mut h, "view.onCard");
        h.frame(vec![]);
        assert!(h.app.viewport.from_card && h.app.viewport.tiles_shown() == 0 && h.app.error.is_none(), "{:?}", h.app.error);
        let painted = |h: &Harness| {
            let pixels = h.app.viewport.cache.as_ref().and_then(playback::FrameCache::window_pixels).expect("the picture is read back");
            pixels.iter().filter(|pixel| pixel[3] > 0).count()
        };
        let sent = |h: &Harness| h.app.viewport.cache.as_ref().map_or(0, playback::FrameCache::tiles_sent);
        let one = painted(&h);
        assert!(one > 400, "the stroke is in the picture: {one}");
        // While nothing it shows changes, the picture is shown again, not made again.
        let made = |h: &Harness| h.app.viewport.cache.as_ref().map_or(0, |cache| cache.windows_made);
        let pictures = made(&h);
        for _ in 0..5 {
            h.frame(vec![]);
        }
        assert_eq!(made(&h), pictures, "standing still, no picture is made");
        // And where it was drawn: along the line the pen took, and not well above it.
        let shown = h.app.viewport.shown_in.expect("the viewport is shown");
        let at = |h: &Harness, on: Pos2| {
            let pixels = h.app.viewport.cache.as_ref().and_then(playback::FrameCache::window_pixels).unwrap();
            pixels[(on.y - shown.min.y) as usize * shown.width().round() as usize + (on.x - shown.min.x) as usize][3]
        };
        assert!(at(&h, Pos2::new(500.0, 350.0)) > 200 && at(&h, Pos2::new(500.0, 300.0)) == 0, "{shown:?}");
        // A second stroke is in the picture while it is drawn, before the project has it, and
        // only the tiles it touches go to the card.
        let (steps, before) = (h.app.session.history().entries().len(), sent(&h));
        let button = |pos, pressed| Event::PointerButton { pos, button: PointerButton::Primary, pressed, modifiers: Modifiers::NONE };
        let (from, to) = (Pos2::new(300.0, 420.0), Pos2::new(700.0, 420.0));
        h.frame(vec![Event::PointerMoved(from)]);
        h.frame(vec![button(from, true)]);
        for step in 1..=10 {
            h.frame(vec![Event::PointerMoved(from + (to - from) * (step as f32 / 10.0))]);
        }
        let (two, during) = (painted(&h), sent(&h));
        assert!(made(&h) > pictures, "the stroke being drawn makes it anew");
        assert!(two > one + 400 && h.app.session.history().entries().len() == steps, "{one} {two}");
        assert!(during > before && during - before < 60, "{before} {during}");
        // On the frame the pen lifts the stroke is still there, though the project has it
        // only after: it does not go for a frame and come back.
        h.frame(vec![button(to, false)]);
        assert!(painted(&h) >= two, "the frame the pen lifts: {} of {two}", painted(&h));
        h.frame(vec![]);
        h.frame(vec![]);
        assert!(painted(&h) >= two && h.app.session.history().entries().len() == steps + 1 && h.app.viewport.from_card);
        // The light table fades the layers that are not in hand; here there is none, and the
        // onion skin has nothing to show: the picture is the same.
        run(&mut h, "view.lightTable");
        run(&mut h, "view.onionSkin");
        h.frame(vec![]);
        assert!(h.app.viewport.from_card && painted(&h) >= two);
        // One art layer shown alone is drawn on the card too: the strokes are line art, so the
        // colour art alone is nothing, and the line art alone all of them.
        run(&mut h, "view.colourArtAlone");
        h.frame(vec![]);
        assert!(h.app.viewport.from_card && h.app.viewport.tiles_shown() == 0 && painted(&h) == 0, "{}", painted(&h));
        run(&mut h, "view.lineArtAlone");
        h.frame(vec![]);
        assert!(h.app.viewport.from_card && painted(&h) >= two);
        run(&mut h, "view.allArt");
        // Switched off, the tiles again.
        run(&mut h, "view.onCard");
        h.frame(vec![]);
        assert!(!h.app.viewport.from_card && h.app.viewport.tiles_shown() > 0);
    }

    #[test]
    fn a_shot_left_alone_has_its_frames_made_ahead_and_the_ruler_marks_them() {
        let Some(compositor) = iskra_gpu::Compositor::headless() else {
            eprintln!("no graphics card here: the playback cache is not tried");
            return;
        };
        let renderer = egui_wgpu::Renderer::new(compositor.device(), wgpu::TextureFormat::Rgba8Unorm, egui_wgpu::RendererOptions::default());
        let mut h = Harness::new();
        h.app.viewport.cache = Some(playback::FrameCache::new(compositor, std::sync::Arc::new(egui::mutex::RwLock::new(renderer))));
        h.app.run("shot.setDuration", json!({ "frames": 12 }));
        h.drag();
        h.frame(vec![]);
        let cache = |h: &Harness| h.app.viewport.cache.as_ref().map(|cache| (cache.made, cache.kept())).unwrap();
        assert!(cache(&h) == (0, 0) && h.app.timeline.cache_marks.is_empty(), "just drawn on, nothing is made yet");
        // While the window is in use nothing is made, however long: the pointer moving
        // over it is enough, since the window would answer late while a frame is made.
        for step in 0..60 {
            h.frame(vec![Event::PointerMoved(Pos2::new(400.0 + step as f32, 300.0))]);
        }
        assert_eq!(cache(&h), (0, 0));
        // Left alone for half a second and more, all of its frames are made, a few on each
        // frame of the screen, and the ruler has a line over them.
        for _ in 0..60 {
            h.frame(vec![]);
        }
        assert_eq!((cache(&h), &h.app.timeline.cache_marks[..]), ((12, 12), &[(0, 12)][..]));
        // The playhead moved, the frame that is kept is shown at once, and none is made; once
        // it rests, the frame is drawn as it stands.
        assert!(!h.app.viewport.from_cache);
        h.app.tools.frame = 7;
        h.frame(vec![]);
        assert!(h.app.viewport.from_cache && h.app.viewport.tiles_shown() == 0 && cache(&h) == (12, 12), "{:?}", cache(&h));
        for _ in 0..12 {
            h.frame(vec![]);
        }
        assert!(!h.app.viewport.from_cache && cache(&h) == (12, 12));
        // While a rest is edited the drawings are shown as they were drawn, also while the
        // playhead is moved: a frame that is kept would show them posed.
        let tool = h.app.tools.tool;
        (h.app.tools.tool, h.app.tools.frame) = (Tool::Bones, 3);
        h.frame(vec![]);
        assert!(!h.app.viewport.from_cache && h.app.viewport.tiles_shown() > 0);
        h.app.tools.tool = tool;
        for _ in 0..12 {
            h.frame(vec![]);
        }
        // Playing then makes none: every frame is there.
        h.app.switches.looping = true;
        run(&mut h, "playback.toggle");
        for _ in 0..30 {
            h.frame(vec![]);
        }
        assert!(h.app.viewport.from_cache && cache(&h) == (12, 12), "{:?}", cache(&h));
        run(&mut h, "playback.toggle");
        // Drawn on, the frames are others: the line goes, and comes back once it is left alone.
        h.frame(vec![]);
        h.drag_between(Pos2::new(300.0, 420.0), Pos2::new(700.0, 420.0));
        h.frame(vec![]);
        assert!(h.app.timeline.cache_marks.is_empty(), "{:?}", h.app.timeline.cache_marks);
        for _ in 0..60 {
            h.frame(vec![]);
        }
        assert_eq!((cache(&h).1, &h.app.timeline.cache_marks[..]), (12, &[(0, 12)][..]));
        // The storyboard timeline has the line too, over the shot's clip in the film, once
        // the frames of the shot as that page plays it, its boards, are made.
        run(&mut h, "page.storyboard");
        for _ in 0..60 {
            h.frame(vec![]);
        }
        let clip = h.app.session.project().storyboards[0].clips()[0];
        let film = |frame: u32| clip.start + frame - clip.in_point;
        assert_eq!(h.app.storyboard_view.cache_marks, [(film(clip.in_point), film(clip.out_point.min(12)))], "{clip:?}");
        run(&mut h, "page.animation");
        for _ in 0..60 {
            h.frame(vec![]);
        }
        // With a budget for five frames, five are made, from the playhead on, and no more.
        h.app.viewport.cache.as_mut().unwrap().clear();
        let each = {
            let settings = &h.app.session.project().settings;
            settings.width as usize * settings.height as usize * 4
        };
        h.app.viewport.cache.as_mut().unwrap().budget = 5 * each;
        h.app.viewport.view.zoom = 1.0;
        h.app.tools.frame = 4;
        for _ in 0..90 {
            h.frame(vec![]);
        }
        assert_eq!((cache(&h).1, &h.app.timeline.cache_marks[..]), (5, &[(4, 9)][..]));
    }

    #[test]
    fn a_shot_that_plays_is_shown_from_frames_made_once_on_the_card() {
        let Some(compositor) = iskra_gpu::Compositor::headless() else {
            eprintln!("no graphics card here: the playback cache is not tried");
            return;
        };
        let renderer = egui_wgpu::Renderer::new(compositor.device(), wgpu::TextureFormat::Rgba8Unorm, egui_wgpu::RendererOptions::default());
        let mut h = Harness::new();
        h.app.viewport.cache = Some(playback::FrameCache::new(compositor, std::sync::Arc::new(egui::mutex::RwLock::new(renderer))));
        h.app.run("shot.setDuration", json!({ "frames": 12 }));
        h.drag();
        h.frame(vec![]);
        let cache = |h: &Harness| h.app.viewport.cache.as_ref().map(|cache| (cache.made, cache.kept())).unwrap();
        assert!(!h.app.viewport.from_cache && h.app.viewport.tiles_shown() > 0 && cache(&h) == (0, 0), "standing still, the shot is drawn from its tiles");

        // Playing, it is shown from the cache, which makes the frame under the playhead and
        // some of those ahead.
        h.app.switches.looping = true;
        run(&mut h, "playback.toggle");
        h.frame(vec![]);
        h.frame(vec![]);
        assert!(h.app.viewport.from_cache && h.app.viewport.tiles_shown() == 0, "no tile is drawn under a cached frame");
        assert!(cache(&h).0 >= 3 && cache(&h).0 <= 12, "{:?}", cache(&h));
        // Round the loop: every frame is made once, and never again.
        for _ in 0..80 {
            h.frame(vec![]);
        }
        assert_eq!(cache(&h), (12, 12));
        for _ in 0..80 {
            h.frame(vec![]);
        }
        assert_eq!((cache(&h), h.app.playing.is_some()), ((12, 12), true));
        // The flat view is no picture the camera takes: it plays from the tiles.
        run(&mut h, "view.flat");
        h.frame(vec![]);
        assert!(!h.app.viewport.from_cache && h.app.viewport.tiles_shown() > 0);
        run(&mut h, "view.flat");

        // Stopped, it is drawn from its tiles again, to be worked on, once the playhead has
        // rested a moment. An edit makes another shot, whose frames are made anew when it plays.
        run(&mut h, "playback.toggle");
        for _ in 0..12 {
            h.frame(vec![]);
        }
        assert!(!h.app.viewport.from_cache && h.app.viewport.tiles_shown() > 0);
        h.app.tools.frame = 0;
        h.drag_between(Pos2::new(300.0, 250.0), Pos2::new(700.0, 450.0));
        run(&mut h, "playback.toggle");
        h.frame(vec![]);
        assert!(h.app.viewport.from_cache && cache(&h).0 > 12 && cache(&h).1 < 12, "{:?}", cache(&h));
        // A shot with effect nodes plays from the card's frames too, which have the effects in
        // them: a blur that the card makes, and a kind that the reference makes for it.
        run(&mut h, "playback.toggle");
        let layer = h.app.session.project().shots[0].layers[0].id.0;
        h.app.run("effect.new", json!({ "kind": "blur", "on": { "layer": layer } }));
        h.app.run("effect.new", json!({ "kind": "transparency", "on": { "layer": layer } }));
        assert_eq!((h.app.session.project().shots[0].effects.len(), &h.app.error), (2, &None));
        let before = cache(&h).0;
        run(&mut h, "playback.toggle");
        h.frame(vec![]);
        h.frame(vec![]);
        assert!(h.app.viewport.from_cache && h.app.viewport.tiles_shown() == 0 && cache(&h).0 > before, "{:?}", cache(&h));
    }

    #[test]
    fn playing_keeps_the_drawings_textures_and_gets_the_next_frames_ready() {
        let mut h = Harness::new();
        h.app.prefs.new_drawing_hold = crate::prefs::NewDrawingHold::Frames(1);
        h.app.run("shot.setDuration", json!({ "frames": 12 }));
        // A drawing on frame 0 and another on frame 6, each a stroke over a few tiles.
        h.drag();
        h.app.tools.frame = 6;
        h.drag_between(Pos2::new(300.0, 250.0), Pos2::new(700.0, 450.0));
        h.app.tools.frame = 0;
        // Fresh textures, as after opening the project.
        h.app.viewport = Viewport::default();
        h.frame(vec![]);
        h.frame(vec![]);
        let first = h.app.viewport.tiles_shown();
        assert!(first > 0 && h.app.viewport.tiles_kept() == first, "only what frame 0 shows has been made");

        // Playing, the tiles of the drawing six frames on are made before the playhead is there.
        h.app.switches.looping = true;
        run(&mut h, "playback.toggle");
        h.frame(vec![]);
        h.frame(vec![]);
        h.frame(vec![]);
        assert!(h.app.tools.frame < 6 && h.app.viewport.tiles_kept() > first, "frame {}: {} kept", h.app.tools.frame, h.app.viewport.tiles_kept());
        // Round the loop twice: nothing more is made, and each frame was evaluated once.
        for _ in 0..40 {
            h.frame(vec![]);
        }
        let (kept, evaluated) = (h.app.viewport.tiles_kept(), h.app.viewport.frames_evaluated());
        for _ in 0..60 {
            h.frame(vec![]);
        }
        assert_eq!((h.app.viewport.tiles_kept(), h.app.viewport.frames_evaluated(), h.app.playing.is_some()), (kept, evaluated, true));
        assert!(evaluated <= 12, "{evaluated} evaluations for a shot of 12 frames");
        // An edit makes a new shot: its frames are evaluated afresh.
        run(&mut h, "playback.toggle");
        h.app.run("layer.rename", json!({ "layer": h.app.layer.unwrap().0, "name": "Ball" }));
        h.frame(vec![]);
        assert_eq!(h.app.viewport.frames_evaluated(), evaluated + 1);
    }

    #[test]
    fn dragging_with_space_held_pans_instead_of_painting() {
        let mut h = Harness::new();
        let before = h.app.viewport.view.pan;
        h.frame(vec![Event::Key { key: Key::Space, physical_key: None, pressed: true, repeat: false, modifiers: Modifiers::NONE }]);
        h.drag();
        assert_eq!(h.painted(), None);
        assert!((h.app.viewport.view.pan - before - egui::vec2(400.0, 0.0)).length() < 1.0, "{:?}", h.app.viewport.view.pan);
    }

    #[test]
    fn keys_step_the_zoom_and_reset_the_view() {
        let mut h = Harness::new();
        h.frame(vec![]);
        let fitted = h.app.viewport.view.zoom;
        // Harmony's keys: 2 in a step, 1 out a step, Shift+Z to 100%, Shift+M zoom and turn.
        press(&mut h, Modifiers::NONE, Key::Num2);
        let stepped = h.app.viewport.view.zoom;
        assert!(stepped > fitted, "{stepped} from {fitted}");
        press(&mut h, Modifiers::NONE, Key::Num1);
        press(&mut h, Modifiers::NONE, Key::Num1);
        assert!(h.app.viewport.view.zoom < fitted);
        press(&mut h, Modifiers::SHIFT, Key::Z);
        assert_eq!(h.app.viewport.view.zoom, 1.0);
        h.app.viewport.view.rotation = 0.5;
        h.app.viewport.view.pan.x += 80.0;
        press(&mut h, Modifiers::SHIFT, Key::M);
        assert_eq!(h.app.viewport.view, view::View::default());
        // Also halfway through a stroke, with the brush still down.
        let button = |pos, pressed| Event::PointerButton { pos, button: PointerButton::Primary, pressed, modifiers: Modifiers::NONE };
        let from = Pos2::new(300.0, 350.0);
        h.frame(vec![Event::PointerMoved(from)]);
        h.frame(vec![button(from, true)]);
        h.frame(vec![Event::PointerMoved(from + egui::vec2(40.0, 0.0))]);
        press(&mut h, Modifiers::NONE, Key::Num2);
        assert_eq!(h.app.viewport.view.zoom, 1.5);
        h.frame(vec![button(from + egui::vec2(40.0, 0.0), false)]);
        h.frame(vec![]);
        assert_eq!(h.app.session.history().undo_label(), Some("Brush Stroke"));
    }

    #[test]
    fn a_mouse_wheel_zooms_about_the_pointer_and_a_trackpad_pans() {
        let mut h = Harness::new();
        let pointer = Pos2::new(500.0, 300.0);
        h.frame(vec![Event::PointerMoved(pointer)]);
        let center = h.app.viewport.shown_in.expect("the viewport is shown").center();
        let (before, under) = (h.app.viewport.view, h.app.viewport.view.to_scene(center, pointer));
        let wheel = |unit, delta| Event::MouseWheel { unit, delta, phase: egui::TouchPhase::Move, modifiers: Modifiers::NONE };
        h.frame(vec![wheel(egui::MouseWheelUnit::Line, egui::vec2(0.0, 1.0))]);
        let view = h.app.viewport.view;
        assert!((view.zoom / before.zoom - 1.2).abs() < 1e-4, "a notch forward zooms in: {view:?}");
        assert!((view.to_screen(center, under) - pointer).length() < 0.01, "about the pointer");
        h.frame(vec![wheel(egui::MouseWheelUnit::Line, egui::vec2(0.0, -1.0))]);
        assert!((h.app.viewport.view.zoom - before.zoom).abs() < 1e-4, "and back out");
        let zoom = h.app.viewport.view.zoom;
        h.frame(vec![wheel(egui::MouseWheelUnit::Point, egui::vec2(0.0, -30.0))]);
        h.frame(vec![]);
        let view = h.app.viewport.view;
        assert_eq!(view.zoom, zoom, "a trackpad's scroll doesn't zoom");
        assert!((view.pan.y - before.pan.y + 30.0).abs() < 0.5, "it pans: {view:?}");
    }

    #[test]
    fn dragging_with_space_and_cmd_held_zooms_instead_of_panning() {
        let mut h = Harness::new();
        h.frame(vec![]);
        let before = h.app.viewport.view;
        let held = Modifiers::COMMAND;
        h.frame(vec![Event::ModifiersChanged(held), Event::Key { key: Key::Space, physical_key: None, pressed: true, repeat: false, modifiers: held }]);
        h.drag();
        let view = h.app.viewport.view;
        assert_eq!(h.painted(), None);
        assert!(view.zoom > before.zoom * 10.0, "dragged right, it zooms in: {view:?}");
        let center = h.app.viewport.shown_in.unwrap().center();
        let from = Pos2::new(300.0, 350.0);
        assert!((view.to_screen(center, before.to_scene(center, from)) - from).length() < 0.5, "about where the drag began");
    }

    #[test]
    fn the_zoom_tool_zooms_by_drag_click_and_box() {
        let mut h = Harness::new();
        press(&mut h, Modifiers::ALT, Key::Z);
        assert_eq!(h.app.tools.tool, Tool::Zoom);
        h.frame(vec![]);
        let center = h.app.viewport.shown_in.expect("the viewport is shown").center();
        // Pressed at `from` with `held`, dragged to `to` and let go.
        let gesture = |h: &mut Harness, held: Modifiers, from: Pos2, to: Pos2| {
            let button = |pos, pressed| Event::PointerButton { pos, button: PointerButton::Primary, pressed, modifiers: held };
            h.frame(vec![Event::ModifiersChanged(held), Event::PointerMoved(from)]);
            h.frame(vec![button(from, true)]);
            for step in 1..=10 {
                h.frame(vec![Event::PointerMoved(from + (to - from) * (step as f32 / 10.0))]);
            }
            h.frame(vec![button(to, false)]);
            h.frame(vec![Event::ModifiersChanged(Modifiers::NONE)]);
        };
        let (from, before) = (Pos2::new(300.0, 350.0), h.app.viewport.view);
        let under = before.to_scene(center, from);
        gesture(&mut h, Modifiers::NONE, from, from + egui::vec2(100.0, 0.0));
        let view = h.app.viewport.view;
        assert!(view.zoom > before.zoom * 2.0, "dragged right, it zooms in: {view:?}");
        assert!((view.to_screen(center, under) - from).length() < 0.5, "about where it was pressed");
        gesture(&mut h, Modifiers::NONE, from, from - egui::vec2(0.0, 100.0));
        assert!(h.app.viewport.view.zoom < view.zoom, "dragged up, out");
        assert_eq!(h.painted(), None, "nothing is drawn");
        // A click steps in, an Alt-click out.
        h.app.viewport.view.zoom = 1.0;
        gesture(&mut h, Modifiers::NONE, from, from);
        assert_eq!(h.app.viewport.view.zoom, 1.5);
        gesture(&mut h, Modifiers::ALT, from, from);
        gesture(&mut h, Modifiers::ALT, from, from);
        assert_eq!(h.app.viewport.view.zoom, 2.0 / 3.0);
        // With Shift a box, which fills the view once let go.
        let (corner, zoom) = (Pos2::new(400.0, 300.0), h.app.viewport.view.zoom);
        let middle = h.app.viewport.view.to_scene(center, corner + egui::vec2(25.0, 25.0));
        gesture(&mut h, Modifiers::SHIFT, corner, corner + egui::vec2(50.0, 50.0));
        let view = h.app.viewport.view;
        assert!(view.zoom > zoom * 5.0, "{view:?}");
        assert!((view.to_screen(center, middle) - center).length() < 0.5, "the box's middle is the view's");
    }

    /// The log has what was run and what went wrong, and its panel opens beside the timeline.
    #[test]
    fn the_log_says_what_was_run_and_what_went_wrong_and_opens_by_the_timeline() {
        let mut h = Harness::new();
        // The pen and the strokes are not said unless the log is to have them.
        h.app.log.clear();
        h.drag();
        assert_eq!(h.app.log.text().lines().count(), 1, "{}", h.app.log.text());
        h.app.prefs.log_strokes = true;
        h.app.log.clear();
        h.drag();
        h.app.run("no.suchCommand", json!({}));
        let failed = h.app.error.clone().expect("there is no such command");
        h.frame(vec![]);
        h.app.error = Some("The disk is full".to_string());
        h.frame(vec![]);
        h.frame(vec![]);
        let log = h.app.log.text();
        let said: Vec<&str> = log.lines().skip(1).map(|line| &line[11..]).collect();
        assert_eq!(
            said,
            ["pointer down: a mouse (no pen is reported)", "drawing.stroke", &format!("no.suchCommand: {failed}"), "The disk is full"],
            "each once: a failed command is not said again as the status bar's problem"
        );
        run(&mut h, "panel.log");
        h.frame(vec![]);
        let group = h.app.dock_drawn.1.iter().find(|group| group.showing() == Some(Panel::Log)).expect("the Log panel is shown");
        assert!(group.panels.contains(&Panel::Timeline), "{:?}", group.panels);
    }

    #[test]
    fn a_script_runs_from_the_console_or_a_file_as_one_undo_step_and_its_errors_are_logged() {
        let mut h = Harness::new();
        let layer = h.app.session.project().shots[0].layers[0].id.0;
        for frame in 0..3 {
            h.app.run("drawing.newDrawing", json!({ "layer": layer, "frame": frame, "name": format!("d{frame}") }));
        }
        let names = |h: &Harness| h.app.session.project().shots[0].layers[0].drawings.iter().map(|d| d.name.clone()).collect::<Vec<_>>();
        assert_eq!(names(&h), ["d0", "d1", "d2"]);
        let scripts = h.app.menu_bar().into_iter().find(|(menu, _)| menu == "Scripts").map(|(_, nodes)| nodes).expect("a Scripts menu");
        let titles: Vec<String> =
            scripts.iter().filter_map(|node| if let menus::MenuNode::Item(item) = node { Some(item.title.clone()) } else { None }).collect();
        assert_eq!(titles, ["Run Script File…", "Script Console", "Reload Scripts", "Show Scripts Folder"]);
        run(&mut h, "script.console");
        h.frame(vec![]);
        assert!(h.app.dock_drawn.1.iter().any(|group| group.showing() == Some(Panel::ScriptConsole)), "the console is shown");

        h.app.script_console.code = "var l = iskra.run('project.get').shots[0].layers[0];\n\
            l.drawings.forEach(function (d, i) { iskra.run('drawing.rename', { layer: l.id, drawing: d.id, name: 'pose-' + (i + 1) }); });\n\
            print('renamed', l.drawings.length); l.drawings.length"
            .to_string();
        h.app.log.clear();
        h.app.run_console();
        h.frame(vec![]);
        assert_eq!(names(&h), ["pose-1", "pose-2", "pose-3"]);
        assert_eq!(h.app.session.history().undo_label(), Some("Script Console"), "one step for the three renames");
        assert_eq!(h.app.script_console.said(), ["› Script Console", "renamed 3", "= 3"]);
        assert!(h.app.log.text().contains("Script Console: renamed 3"), "{}", h.app.log.text());
        run(&mut h, "edit.undo");
        assert_eq!(names(&h), ["d0", "d1", "d2"]);
        // A script sees what is in hand: the layer and the frame.
        h.app.tools.frame = 2;
        h.app.script_console.code = "[iskra.layer.drawingAt(iskra.frame).name, iskra.shot.name, iskra.tool]".to_string();
        h.app.run_console();
        assert_eq!(h.app.script_console.said().last().map(String::as_str), Some("= [\"d2\",\"Shot_01\",\"brush\"]"));

        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("broken.js");
        std::fs::write(&path, "print('start');\niskra.run('drawing.rename', { layer: 0, drawing: 0, name: 'x' });").unwrap();
        h.app.run_script_file(&path);
        let error = h.app.error.clone().expect("the script failed");
        assert!(error.starts_with("broken.js:2:"), "{error}");
        assert!(h.app.log.text().contains(&format!("script.run: {error}")), "{}", h.app.log.text());
        assert_eq!(h.app.script_console.said()[5..7], ["› broken.js".to_string(), "start".to_string()]);
        assert_eq!(h.app.session.history().redo_label(), Some("Script Console"), "a script that failed made no step");
        h.app.run_script_file(&dir.path().join("missing.js"));
        assert!(h.app.error.as_deref().is_some_and(|why| why.starts_with("The script ")), "{:?}", h.app.error);
    }

    #[test]
    fn the_scripts_folders_commands_are_in_the_menus_the_palette_and_the_shortcuts_table() {
        let dir = tempfile::tempdir().unwrap();
        let scripts = dir.path().join("scripts");
        std::fs::create_dir(&scripts).unwrap();
        std::fs::write(
            scripts.join("rename.js"),
            "iskra.command({ id: 'my.renameAll', title: 'Rename All Drawings', menu: 'drawing', run: () => {\n\
             iskra.layer.drawings.forEach((d, i) => d.rename('pose-' + (i + 1))); print('done'); } });",
        )
        .unwrap();
        std::fs::write(scripts.join("hello.js"), "print('hello from', iskra.shot.name)").unwrap();
        std::fs::write(scripts.join("broken.js"), "iskra.command({ id: 'nogroup', run: () => 1 })").unwrap();
        let mut h = Harness::new();
        h.app = IskraApp::new(Session::new()).with_preferences(dir.path().join("preferences.json"));
        h.frame(vec![]);
        let listed: Vec<(&str, &str, commands::Menu)> = h.app.scripts.iter().map(|s| (s.id, s.title, s.menu)).collect();
        assert_eq!(listed, [("script.hello", "hello", commands::Menu::Scripts), ("my.renameAll", "Rename All Drawings", commands::Menu::Drawing)]);
        assert!(h.app.log.text().contains("scripts: broken.js:"), "{}", h.app.log.text());
        assert!(h.app.error.as_deref().is_some_and(|why| why.contains("broken.js")), "{:?}", h.app.error);

        let items = |h: &Harness, menu: &str| {
            let nodes = h.app.menu_bar().into_iter().find(|(title, _)| title == menu).map(|(_, nodes)| nodes).unwrap_or_default();
            nodes.into_iter().filter_map(|node| if let menus::MenuNode::Item(item) = node { Some(item.title) } else { None }).collect::<Vec<_>>()
        };
        assert_eq!(items(&h, "Drawing").last().map(String::as_str), Some("Rename All Drawings"));
        assert_eq!(items(&h, "Scripts"), ["Run Script File…", "Script Console", "Reload Scripts", "Show Scripts Folder", "hello"]);
        assert_eq!(commands::Palette::scripts("drawing rename", &h.app.scripts).iter().map(|s| s.id).collect::<Vec<_>>(), ["my.renameAll"]);

        let layer = h.app.session.project().shots[0].layers[0].id;
        h.app.layer = Some(layer);
        for frame in 0..2 {
            h.app.run("drawing.newDrawing", json!({ "layer": layer.0, "frame": frame }));
        }
        let ctx = h.ctx.clone();
        h.app.run_menu_command("my.renameAll", &ctx);
        let names: Vec<String> = h.app.session.project().shots[0].layers[0].drawings.iter().map(|d| d.name.clone()).collect();
        assert_eq!(names, ["pose-1", "pose-2"]);
        assert_eq!(h.app.session.history().undo_label(), Some("Rename All Drawings"));
        h.app.run_menu_command("script.hello", &ctx);
        assert_eq!(h.app.script_console.said()[2..], ["› hello".to_string(), "hello from Shot_01".to_string()]);

        // A key given to it in the Shortcuts table runs it.
        h.app.keys.bind("script.hello", keymap::Chord::pressed(egui::Key::H, egui::Modifiers::ALT), None);
        h.frame(vec![egui::Event::Key { key: egui::Key::H, physical_key: None, pressed: true, repeat: false, modifiers: egui::Modifiers::ALT }]);
        assert_eq!(h.app.script_console.said().iter().filter(|line| *line == "› hello").count(), 2);

        // Taken out of the folder and read again, it is gone.
        std::fs::remove_file(scripts.join("hello.js")).unwrap();
        run(&mut h, "script.reload");
        assert_eq!(h.app.scripts.iter().map(|s| s.id).collect::<Vec<_>>(), ["my.renameAll"]);
    }

    #[test]
    fn a_retake_note_on_frame_42_is_written_at_the_playhead_marked_on_both_timelines_and_ticked_done() {
        let mut h = Harness::new();
        h.app.prefs.user_name = " Ana ".to_string();
        let shot = h.app.session.project().shots[0].id;
        h.app.run("shot.setDuration", json!({ "shot": shot.0, "frames": 48 }));
        let ctx = h.ctx.clone();
        h.app.run_menu_command("note.write", &ctx);
        assert!(h.app.prefs.layouts.of(h.app.page).shows(Panel::Notes) || h.app.prefs.detached.contains(&Panel::Notes));
        h.app.tools.frame = 41;
        h.app.notes_panel.writing = "The arm pops".to_string();
        h.frame(vec![]);
        let add = h.app.notes_panel.add_button.expect("the bar's button");
        click(&mut h, add.center());
        let notes = |h: &Harness| h.app.session.project().shots[0].notes.clone();
        let [note] = &notes(&h)[..] else { panic!("one note: {:?}", notes(&h)) };
        assert_eq!((note.frame, note.text.as_str(), note.author.as_str(), note.done), (41, "The arm pops", "Ana", false));
        assert!(h.app.notes_panel.writing.is_empty());

        // On the Animation page's timeline, a band over each note's frames; a click on one goes
        // to it. (Frame 42 lies past what the harness's timeline shows, so frame 6's is clicked.)
        h.app.run("note.add", json!({ "shot": shot.0, "frame": 5, "length": 2, "text": "Too slow" }));
        h.app.tools.frame = 20;
        h.frame(vec![]);
        let marked: Vec<u64> = h.app.timeline.note_marks.iter().map(|(id, _)| *id).collect();
        assert_eq!(marked, [2, 1], "in the order of their frames");
        let (_, band) = h.app.timeline.note_marks[0];
        click(&mut h, band.center());
        assert_eq!(h.app.tools.frame, 5);
        h.app.run("note.remove", json!({ "shot": shot.0, "note": 2 }));
        h.frame(vec![]);

        // Ticked done in the panel, it is listed no more, but with Show Done.
        let tick = h.app.notes_panel.tick(shot, 1).expect("listed");
        click(&mut h, tick.center());
        assert!(notes(&h)[0].done);
        assert_eq!(h.app.session.history().undo_label(), Some("Change Retake Note"));
        h.frame(vec![]);
        assert!(h.app.notes_panel.tick(shot, 1).is_none());
        h.app.notes_panel.show_done = true;
        h.frame(vec![]);
        assert!(h.app.notes_panel.tick(shot, 1).is_some());

        // On the storyboard's timeline, where the shot lies on the film from frame 0.
        run(&mut h, "page.storyboard");
        h.frame(vec![]);
        let marks: Vec<(ShotId, u64)> = h.app.storyboard_view.note_marks.iter().map(|(shot, id, _)| (*shot, *id)).collect();
        assert_eq!(marks, [(shot, 1)]);
        let band = h.app.storyboard_view.note_marks[0].2;
        assert!((band.left() - (h.app.storyboard_view.origin.x + 41.0 * 3.0)).abs() < 2.0, "{band:?}");
    }

    #[test]
    fn picked_nodes_are_deleted_by_commands_of_their_own_a_group_ungrouped_or_with_all_in_it() {
        let mut h = Harness::new();
        let ctx = h.ctx.clone();
        let made = |h: &mut Harness, name: &str| h.app.run_for("layer.new", json!({ "name": name })).and_then(|made| made["id"].as_u64()).unwrap();
        let (a, b, c, d) = (made(&mut h, "A"), made(&mut h, "B"), made(&mut h, "C"), made(&mut h, "D"));
        let peg = h.app.run_for("peg.new", json!({ "name": "P" })).and_then(|made| made["id"].as_u64()).unwrap();
        let names = |h: &Harness| h.app.session.project().shots[0].layers.iter().map(|l| l.name.clone()).collect::<Vec<_>>();
        let has = |h: &Harness, name: &str| names(h).iter().any(|n| n == name);
        let enabled = |h: &Harness, id: &str| commands::command(id).is_some_and(|c| (c.enabled)(&h.app));
        let group = |h: &mut Harness, layers: [u64; 2]| {
            h.app.run_for("group.new", json!({ "nodes": layers, "name": "G" })).and_then(|made| made["id"].as_u64()).unwrap()
        };

        // Edit ▸ Delete takes no nodes; Delete Picked Nodes takes them all, as one step.
        h.app.picked = [a, peg].into();
        assert!(!enabled(&h, "edit.delete") && enabled(&h, "node.deletePicked") && enabled(&h, "node.deletePickedWithAll"));
        let steps = h.app.session.history().entries().len();
        h.app.run_menu_command("node.deletePicked", &ctx);
        assert!(!has(&h, "A") && h.app.session.project().shots[0].peg(PegId(peg)).is_none());
        assert_eq!(h.app.session.history().entries().len(), steps + 1, "one step");
        assert!(h.app.picked.is_empty() && !enabled(&h, "node.deletePicked"));

        // A group picked: ungrouped, what is in it kept; or deleted with all in it.
        let g = group(&mut h, [b, c]);
        h.app.picked = [g].into();
        h.app.run_menu_command("node.deletePicked", &ctx);
        assert!(h.app.session.project().shots[0].groups.is_empty() && has(&h, "B") && has(&h, "C"));
        let g = group(&mut h, [b, c]);
        h.app.picked = [g, d].into();
        h.app.run_menu_command("node.deletePickedWithAll", &ctx);
        assert!(h.app.session.project().shots[0].groups.is_empty() && !has(&h, "B") && !has(&h, "C") && !has(&h, "D"), "{:?}", names(&h));

        // Both can be put on a script button: the + lists them.
        let listed: Vec<&str> = commands::Palette::matches("delete picked").iter().map(|c| c.id).collect();
        assert_eq!(listed, ["node.deletePicked", "node.deletePickedWithAll"]);
    }

    #[test]
    fn a_scripts_dialog_is_shown_and_its_answer_runs_the_script_again() {
        let dir = tempfile::tempdir().unwrap();
        let scripts = dir.path().join("scripts");
        std::fs::create_dir(&scripts).unwrap();
        std::fs::write(
            scripts.join("rename.js"),
            "iskra.command({ id: 'my.rename', title: 'Rename Drawings…', run: () => {\n\
             var got = iskra.dialog({ title: 'Rename Drawings', fields: [{ name: 'prefix', value: 'pose' }, { name: 'layer', kind: 'layer' }] });\n\
             if (got === null) { print('cancelled'); return; }\n\
             got.layer.drawings.forEach((d, i) => d.rename(got.prefix + '-' + (i + 1))); print('renamed'); } });",
        )
        .unwrap();
        let mut h = Harness::new();
        h.app = IskraApp::new(Session::new()).with_preferences(dir.path().join("preferences.json"));
        h.frame(vec![]);
        let layer = h.app.session.project().shots[0].layers[0].id;
        h.app.layer = Some(layer);
        for frame in 0..2 {
            h.app.run("drawing.newDrawing", json!({ "layer": layer.0, "frame": frame }));
        }
        let names = |h: &Harness| h.app.session.project().shots[0].layers[0].drawings.iter().map(|d| d.name.clone()).collect::<Vec<_>>();
        let steps = h.app.session.history().entries().len();

        h.app.run_script_command("my.rename");
        let asking = h.app.script_dialog.as_ref().expect("the dialog is up");
        assert_eq!(asking.values(), json!({ "prefix": "pose", "layer": layer.0 }), "the layer in hand");
        assert_eq!((h.app.session.history().entries().len(), h.app.script_console.said().len()), (steps, 0), "nothing done yet");
        // Drawn over the window, which runs no shortcut meanwhile.
        h.frame(vec![Event::Key { key: egui::Key::Z, physical_key: None, pressed: true, repeat: false, modifiers: Modifiers::COMMAND }]);
        assert_eq!(h.app.session.history().entries().len(), steps);
        assert!(h.app.script_dialog.is_some());

        let mut asking = h.app.script_dialog.take().unwrap();
        asking.set("prefix", json!("walk"));
        let values = asking.values();
        h.app.answer_script_dialog(asking, script_dialog::Answer::Given(values));
        assert_eq!(names(&h), ["walk-1", "walk-2"]);
        assert_eq!(h.app.session.history().undo_label(), Some("Rename Drawings…"));
        assert_eq!(h.app.script_console.said(), ["› Rename Drawings…", "renamed"]);

        // Escape cancels it: the script is told, and changes nothing.
        h.app.run_script_command("my.rename");
        h.frame(vec![Event::Key { key: egui::Key::Escape, physical_key: None, pressed: true, repeat: false, modifiers: Modifiers::NONE }]);
        assert!(h.app.script_dialog.is_none());
        assert_eq!(h.app.script_console.said()[2..], ["› Rename Drawings…".to_string(), "cancelled".to_string()]);
        assert_eq!(names(&h), ["walk-1", "walk-2"]);
    }

    #[test]
    fn script_buttons_are_one_row_put_in_any_bar_and_run_their_commands() {
        let dir = tempfile::tempdir().unwrap();
        let scripts = dir.path().join("scripts");
        std::fs::create_dir(&scripts).unwrap();
        std::fs::write(scripts.join("hello.js"), "print('hello')").unwrap();
        let mut icon = Vec::new();
        let pixels = [[255u8, 0, 0, 255]; 4];
        image::write_buffer_with_format(
            &mut std::io::Cursor::new(&mut icon),
            pixels.as_flattened(),
            2,
            2,
            image::ExtendedColorType::Rgba8,
            image::ImageFormat::Png,
        )
        .unwrap();
        std::fs::write(scripts.join("hello.png"), icon).unwrap();
        let mut h = Harness::new();
        h.app = IskraApp::new(Session::new()).with_preferences(dir.path().join("preferences.json"));
        // A script's command, one of the app's with a title of the user's, one with an icon and
        // one whose script is gone.
        let button = |command: &str| buttons::ScriptButton { command: command.to_string(), ..Default::default() };
        h.app.prefs.script_buttons = vec![
            button("script.hello"),
            buttons::ScriptButton { title: Some("Console".to_string()), ..button("panel.scriptConsole") },
            buttons::ScriptButton { icon: Some(scripts.join("hello.png")), ..button("script.hello") },
            button("my.gone"),
        ];
        // Put in the viewport's bar as from a tab's menu, once though asked twice.
        for _ in 0..2 {
            let mut layout = h.app.prefs.bar(Panel::Viewport);
            layout.add(Panel::Viewport, "scripts");
            h.app.prefs.set_bar(Panel::Viewport, layout);
        }
        assert_eq!(h.app.prefs.bar(Panel::Viewport).added, ["scripts"]);
        // At the bar's start, where it is not scrolled out of sight.
        let mut layout = h.app.prefs.bar(Panel::Viewport);
        layout.put(&layout.parts(Panel::Viewport), "scripts", 0);
        h.app.prefs.set_bar(Panel::Viewport, layout);
        h.frame(vec![]);
        let drawn: Vec<(String, bool)> = h.app.button_row.drawn.iter().map(|(title, _, icon)| (title.clone(), *icon)).collect();
        let titled = |title: &str, icon| (title.to_string(), icon);
        assert_eq!(drawn, [titled("hello", false), titled("Console", false), titled("hello", true), titled("my.gone", false)]);

        let at = h.app.button_row.drawn[0].1.center();
        click(&mut h, at);
        assert_eq!(h.app.script_console.said(), ["› hello", "hello"]);
        // The gone one can't be clicked.
        let at = h.app.button_row.drawn[3].1.center();
        click(&mut h, at);
        assert_eq!(h.app.script_console.said().len(), 2);

        // Kept with the preferences, the one row for every bar.
        let read: prefs::Preferences = serde_json::from_value(serde_json::to_value(&h.app.prefs).unwrap()).unwrap();
        assert_eq!(read.script_buttons, h.app.prefs.script_buttons);
    }

    #[test]
    fn with_log_timings_on_a_stroke_is_said_with_what_its_frames_took_and_what_the_project_holds() {
        let mut h = Harness::new();
        h.app.prefs.log_timings = true;
        h.frame(vec![]);
        h.app.log.clear();
        h.drag();
        let log = h.app.log.text();
        let stroke = log.lines().find(|line| line.contains("timings, a stroke of")).unwrap_or_else(|| panic!("the stroke is said: {log}"));
        assert!(stroke.contains("panel Viewport") && stroke.contains("viewport: pen input") && stroke.contains("drawing.stroke 1×"), "{stroke}");
        let state = log.lines().find(|line| line.contains("timings, as it stands:")).expect("and what the project holds");
        assert!(state.contains("1 shots, 1 layers, 1 drawings") && state.contains("undo steps") && state.contains("tile textures kept"), "{state}");
        // Off, nothing more is said.
        h.app.prefs.log_timings = false;
        h.frame(vec![]);
        h.app.log.clear();
        h.drag();
        assert!(!h.app.log.text().contains("timings"), "{}", h.app.log.text());
    }

    #[test]
    fn the_viewer_looks_through_another_display_until_another_shot_is_shown() {
        let mut h = Harness::new();
        h.frame(vec![]);
        let ctx = h.ctx.clone();
        let shot = |h: &Harness| (*h.app.session.project().shots[0]).clone();
        // One display alone: the View menu has no list of them.
        assert!(!h.app.menu_bar().iter().any(|(_, nodes)| format!("{nodes:?}").contains("display.main")));
        // The viewer has a bar of its own above it, with the display in it.
        let panel = |h: &Harness| h.app.dock_drawn.1.iter().find(|g| g.showing() == Some(Panel::Viewport)).unwrap().content;
        let under = |h: &Harness| h.app.viewport.shown_in.unwrap().top() - panel(h).top();
        assert!(Panel::Viewport.bar_parts().iter().any(|part| part.id == "display") && under(&h) > 10.0, "{}", under(&h));
        // With all its parts hidden it is a thin line with the menu that shows them again.
        let hidden = bar::BarLayout { hidden: ["display".to_string()].into(), ..Default::default() };
        h.app.prefs.panel_bars.insert(Panel::Viewport, hidden.clone());
        h.frame(vec![]);
        assert_eq!(h.app.prefs.panel_bars.get(&Panel::Viewport), Some(&hidden), "kept with the preferences");
        h.app.prefs.panel_bars.clear();
        h.frame(vec![]);
        h.app.run("display.new", json!({ "name": "Matte" }));
        let matte = shot(&h).displays[0].id;
        h.frame(vec![]);
        let listed = |h: &Harness| h.app.menu_bar().iter().any(|(_, nodes)| format!("{nodes:?}").contains("display.main"));
        // The Storyboard page shows the main one alone: no choice there, in the menu or the bar.
        let page = h.app.page;
        h.app.page = Page::Storyboard;
        assert!(!listed(&h) && !h.app.bar_part_here(Panel::Viewport, "display"));
        h.app.page = page;
        assert!(listed(&h) && h.app.bar_part_here(Panel::Viewport, "display"));
        // Looked through, the viewer shows what it shows, nothing here, and says so.
        let before = h.app.viewport.evaluated();
        h.app.run_menu_command(&format!("display.{}", matte.0), &ctx);
        h.frame(vec![]);
        assert_eq!(h.app.viewport.evaluated(), before + 1, "the shot as the matte shows it, through the cache");
        assert_eq!(h.app.viewport.viewing_said.as_deref(), Some("Matte"));
        // Its frames are kept as the main one's are: standing still, it is evaluated no more.
        let evaluated = h.app.viewport.evaluated();
        h.frame(vec![]);
        h.frame(vec![]);
        assert_eq!(h.app.viewport.evaluated(), evaluated);
        assert_eq!((h.app.viewport.posed(&shot(&h)).display, shot(&h).display.is_some()), (None, true), "the shot is as it was");
        // The Storyboard page shows the main one whatever the viewer looks through.
        h.app.viewport.work = Work::Boards;
        assert!(h.app.viewport.posed(&shot(&h)).display.is_some());
        h.app.viewport.work = Work::Whole;
        h.app.run_menu_command("display.main", &ctx);
        h.frame(vec![]);
        assert_eq!(h.app.viewport.viewing_said, None);
        // Another shot is looked at through its main one.
        h.app.run_menu_command(&format!("display.{}", matte.0), &ctx);
        h.app.run("shot.new", json!({}));
        let other = h.app.session.project().shots.iter().map(|shot| shot.id).find(|id| *id != shot(&h).id).unwrap();
        h.app.set_shot(other);
        h.frame(vec![]);
        assert_eq!((h.app.viewport.viewing, h.app.viewport.viewing_said.clone()), (None, None));
    }

    #[test]
    fn playing_every_frame_the_playhead_waits_for_a_frame_that_is_slow_to_make() {
        let mut h = Harness::new();
        h.frame(vec![]);
        assert!(h.app.prefs.play_every_frame, "on from the start");
        run(&mut h, "playback.toggle");
        h.frame(vec![]);
        let at = h.app.tools.frame;
        // A frame that took a second to make: the playhead goes on to the next frame alone.
        h.time += 1.0;
        h.frame(vec![]);
        assert_eq!(h.app.tools.frame, at + 1, "no frame is skipped");
        // And keeps time from there.
        h.frame(vec![]);
        h.frame(vec![]);
        assert!(h.app.tools.frame <= at + 2, "{}", h.app.tools.frame);
        // Off, playing keeps time, and the frames that were not ready are skipped.
        run(&mut h, "playback.everyFrame");
        let at = h.app.tools.frame;
        h.time += 0.5;
        h.frame(vec![]);
        assert!(h.app.tools.frame >= at + 10, "{} after {at}", h.app.tools.frame);
        run(&mut h, "playback.toggle");
    }

    #[test]
    fn a_shot_moved_under_the_playhead_on_the_storyboard_timeline_holds_nothing() {
        let mut h = Harness::new();
        h.app.page = Page::Storyboard;
        h.frame(vec![]);
        h.app.film_frame = 5;
        h.frame(vec![]);
        let shot = h.app.shot.unwrap();
        let button = |pos, pressed| Event::PointerButton { pos, button: PointerButton::Primary, pressed, modifiers: Modifiers::NONE };
        let aside = Pos2::new(990.0, 690.0);
        h.frame(vec![Event::PointerMoved(aside), button(aside, true)]);
        // While the button is down the shot is moved later, and the playhead goes with it, on
        // the same frame of the shot, as the storyboard timeline has it when a shot is dragged.
        let before = h.app.film_frame;
        h.app.run("storyboard.moveClip", json!({ "shot": shot.0, "start": 10 }));
        h.app.film_frame = h.app.film_frame_of(h.app.tools.frame).unwrap();
        h.frame(vec![]);
        assert!(h.app.film_frame != before && h.app.tools.frame == 5, "{} {}", h.app.film_frame, h.app.tools.frame);
        assert_eq!(h.app.held, None, "what the bars show is not held");
        h.frame(vec![button(aside, false)]);
    }

    #[test]
    fn a_key_clicked_on_a_values_row_leaves_a_held_playhead_where_it_is() {
        use iskra_model::Channel;
        use timeline::Keyed;
        let mut h = Harness::new();
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        h.app.run("peg.setKey", json!({ "peg": peg.0, "frame": 10, "channel": "rotation" }));
        h.frame(vec![]);
        let plus = h.app.timeline.openers.iter().find(|(node, _)| *node == peg.0).expect("the peg has a +").1;
        click(&mut h, plus.center());
        h.frame(vec![]);
        h.app.tools.frame = 3;
        h.app.prefs.hold_playhead = true;
        h.frame(vec![]);
        let mark =
            h.app.timeline.value_key_marks.iter().find(|(of, frame, _)| *of == Keyed::Peg(peg, Some(Channel::Rotation)) && *frame == 10).expect("its key").2;
        (0..30).for_each(|_| h.frame(vec![]));
        click(&mut h, mark.center());
        assert_eq!(h.app.timeline.picked_keys, vec![(Keyed::Peg(peg, Some(Channel::Rotation)), 10)]);
        assert_eq!(h.app.tools.frame, 3, "the playhead is held");
        // A key on the peg's own row, and an empty cell of a value's row, alike.
        let own = h.app.timeline.key_marks.iter().find(|(of, frame, _)| *of == peg && *frame == 10).map(|(.., mark)| *mark).expect("the peg's own key");
        (0..30).for_each(|_| h.frame(vec![]));
        click(&mut h, own.center());
        assert_eq!(h.app.tools.frame, 3);
        (0..30).for_each(|_| h.frame(vec![]));
        click(&mut h, mark.center() - egui::vec2(5.0 * mark.width(), 0.0));
        assert_eq!(h.app.tools.frame, 3);
        // A box pulled out from an empty cell of the value's row picks the keys it touches.
        h.app.timeline.picked_keys.clear();
        (0..30).for_each(|_| h.frame(vec![]));
        let from = mark.center() - egui::vec2(3.0 * mark.width(), 0.0);
        h.drag_between(from, mark.center() + egui::vec2(mark.width(), 0.0));
        assert_eq!(h.app.timeline.picked_keys, vec![(Keyed::Peg(peg, Some(Channel::Rotation)), 10)]);
        assert_eq!(h.app.tools.frame, 3, "and the playhead stays");
    }

    #[test]
    fn a_pegs_values_open_by_its_plus_each_on_a_row_with_its_own_keys() {
        use iskra_model::Channel;
        use timeline::Keyed;
        let mut h = Harness::new();
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        // Its place keyed on frame 0, its turn on 10.
        h.app.run("peg.setKey", json!({ "peg": peg.0, "frame": 0, "channel": "position" }));
        h.app.run("peg.setKey", json!({ "peg": peg.0, "frame": 10, "channel": "rotation" }));
        h.frame(vec![]);
        let animation = |h: &Harness| h.app.session.project().shots[0].peg(peg).unwrap().animation.clone();
        assert_eq!((animation(&h).position.keys().len(), animation(&h).rotation.keys().len(), animation(&h).scale.keys().len()), (1, 1, 0));
        assert!(h.app.timeline.value_names.is_empty(), "closed to begin with");
        // Its `+` opens a row for each of its values, with its own keys.
        let plus = h.app.timeline.openers.iter().find(|(node, _)| *node == peg.0).expect("the peg has a +").1;
        click(&mut h, plus.center());
        h.frame(vec![]);
        let named: Vec<Keyed> = h.app.timeline.value_names.iter().map(|(of, _)| *of).collect();
        assert_eq!(named, Channel::ALL.map(|channel| Keyed::Peg(peg, Some(channel))));
        let keys = |h: &Harness, channel| {
            h.app.timeline.value_key_marks.iter().filter(|(of, ..)| *of == Keyed::Peg(peg, Some(channel))).map(|(_, frame, _)| *frame).collect::<Vec<_>>()
        };
        assert_eq!((keys(&h, Channel::Position), keys(&h, Channel::Rotation), keys(&h, Channel::Scale)), (vec![0], vec![10], vec![]));
        // A key picked on a value's row is copied alone, by its value's name.
        h.app.timeline.picked_keys = vec![(Keyed::Peg(peg, Some(Channel::Rotation)), 10)];
        assert_eq!(h.app.picked_keyframes(), [json!({ "owner": { "peg": peg.0 }, "frame": 10, "value": "rotation" })]);
        // And taken away alone: the place keeps its key.
        run(&mut h, "edit.delete");
        assert_eq!((animation(&h).position.keys().len(), animation(&h).rotation.keys().len()), (1, 0));
        // Its `−` puts the rows away.
        h.frame(vec![]);
        let minus = h.app.timeline.openers.iter().find(|(node, _)| *node == peg.0).unwrap().1;
        click(&mut h, minus.center());
        h.frame(vec![]);
        assert!(h.app.timeline.value_names.is_empty());
    }

    #[test]
    fn f_shows_the_selected_node_on_the_timeline_opening_what_is_folded_over_it_and_in_the_middle_of_the_node_view() {
        let mut h = Harness::new();
        let layer = h.app.layer.unwrap();
        run(&mut h, "peg.addParent");
        let peg = h.app.peg.unwrap();
        h.app.run("peg.setFolded", json!({ "peg": peg.0, "folded": true }));
        h.app.open_panel(Panel::NodeView);
        // The layer selected, as from the node view, while its row is put away under the peg.
        (h.app.layer, h.app.peg) = (Some(layer), None);
        h.frame(vec![]);
        assert!(!h.app.timeline.names.iter().any(|(node, _)| *node == Node::Layer(layer)), "put away");
        // Its box out of the middle of the node view.
        let panel = h.app.nodes.shown_in().expect("the node view is open");
        let at = |h: &Harness| h.app.nodes.boxes.iter().find(|(item, _)| *item == nodes::Item::Layer(layer)).expect("the layer has a box").1.center();
        h.frame(vec![
            Event::PointerMoved(panel.center()),
            Event::MouseWheel { unit: egui::MouseWheelUnit::Point, delta: egui::vec2(300.0, 200.0), phase: egui::TouchPhase::Move, modifiers: Modifiers::NONE },
        ]);
        // The wheel's smoothed scroll spent.
        for _ in 0..60 {
            h.frame(vec![]);
        }
        assert!((at(&h) - panel.center()).length() > 100.0, "panned away");
        // And in a group folded in the node view, its rows folded on the timeline apart.
        let made = h.app.run_for("group.new", json!({ "nodes": [peg.0, layer.0] })).unwrap()["id"].as_u64().unwrap();
        let group = iskra_model::GroupId(made);
        h.app.run("group.set", json!({ "group": made, "folded": true }));
        h.app.run("group.set", json!({ "group": made, "rowsFolded": true }));
        (h.app.layer, h.app.peg) = (Some(layer), None);
        let key = |pressed| Event::Key { key: Key::F, physical_key: None, pressed, repeat: false, modifiers: Modifiers::NONE };
        h.frame(vec![key(true)]);
        h.frame(vec![key(false)]);
        h.frame(vec![]);
        let shot = h.app.session.project().shots[0].clone();
        assert!(!shot.folded.contains(&peg) && h.app.session.history().undo_label() == Some("Show on the Timeline"));
        assert!(shot.group(group).is_some_and(|group| !group.folded && !group.rows_folded), "both folds of the group opened");
        assert!(h.app.timeline.names.iter().any(|(node, _)| *node == Node::Layer(layer)), "its row is there");
        assert!((at(&h) - panel.center()).length() < 1.0, "its box is in the middle: {:?} {:?}", at(&h), panel.center());
    }

    #[test]
    fn a_render_of_the_boards_is_no_render_of_the_shot() {
        let mut project = iskra_model::Project::clone(Harness::new().app.session.project());
        let shot = project.shots[0].id;
        let what = iskra_model::Rendered::Shot(shot);
        let record = |work: Work, project: &iskra_model::Project| {
            let settings = iskra_export::Settings { work, ..Default::default() };
            let mark = iskra_export::mark_of(project, what, &settings).unwrap();
            iskra_model::RenderRecord {
                what,
                at: format!("/renders/{work:?}").into(),
                settings: serde_json::to_string(&settings).unwrap(),
                mark,
                when: 1,
                pass: None,
            }
        };
        // An animatic of its boards alone: the shot is not rendered, and the record says boards.
        let boards = record(Work::Boards, &project);
        project.record_render(boards);
        assert_eq!(export::rendered(&project, shot), None);
        // Its animation rendered: it is, whichever was made last.
        let animation = record(Work::Animation, &project);
        project.record_render(animation);
        let again = record(Work::Boards, &project);
        project.record_render(again);
        assert_eq!(export::rendered(&project, shot), Some(true));
    }

