        run(&mut h, "panel.new");
        let shot = h.app.shot().unwrap().clone();
        assert_eq!((shot.panels().iter().map(|panel| panel.frame).collect::<Vec<_>>(), h.app.session.history().undo_label()), (vec![0, 12], Some("New Panel")));
