    #[test]
    fn a_drawings_art_layers_are_switched_off_in_properties() {
        let mut h = Harness::new();
        press(&mut h, Modifiers::NONE, Key::K);
        h.drag();
        h.app.open_panel(Panel::Properties);
        h.frame(vec![]);
        assert_eq!(h.app.viewport.painted_art, ArtLayerKind::ALL);
        let switch = |h: &Harness, kind| h.app.art_switches.iter().find(|(k, _)| *k == kind).expect("Properties has the switch").1;
        // The colour art switched off is not drawn, and is one step.
        let at = switch(&h, ArtLayerKind::ColourArt).center();
        click(&mut h, at);
        let layer = h.app.layer.and_then(|id| h.app.session.project().layer(id)).unwrap();
        assert_eq!((layer.art_off.as_slice(), h.app.session.history().undo_label()), (&[ArtLayerKind::ColourArt][..], Some("Show Art Layer")));
        assert_eq!(h.app.viewport.painted_art, [ArtLayerKind::LineArt, ArtLayerKind::Overart]);
        let at = switch(&h, ArtLayerKind::LineArt).center();
        click(&mut h, at);
        let at = switch(&h, ArtLayerKind::Overart).center();
        click(&mut h, at);
        assert!(h.app.viewport.painted_art.is_empty());
        // The pen leaves an art layer that is switched off as it is, and says why.
        assert!(h.app.viewport.locked.is_some_and(|why| why.contains("colour art is switched off")), "{:?}", h.app.viewport.locked);
        let steps = h.app.session.history().undo_label().map(str::to_string);
        h.drag();
        assert_eq!(h.app.session.history().undo_label(), steps.as_deref(), "no stroke");
        for _ in 0..3 {
            h.app.session.undo();
        }
        h.frame(vec![]);
        assert_eq!(h.app.viewport.painted_art, ArtLayerKind::ALL);
    }

    #[test]
    fn layers_pegs_and_composites_are_found_by_the_node_search() {
        use crate::nodes::Item;
        let mut h = Harness::new();
        run(&mut h, "panel.nodeView");
        h.frame(vec![]);
        h.frame(vec![]);
        let shot = |h: &Harness| h.app.session.project().shots[0].clone();
        let at = |h: &Harness, item: Item| h.app.nodes.boxes.iter().find(|(other, _)| *other == item).expect("the node has a box").1;
        let free = at(&h, Item::Display(main_display(&h))).center() + egui::vec2(170.0, -30.0);
        let pegs: fn(&iskra_model::Shot) -> usize = |shot| shot.pegs.len();
        let composites: fn(&iskra_model::Shot) -> usize = |shot| shot.composites.len();
        for (step, (typed, count)) in [("peg", pegs), ("composite", composites)].into_iter().enumerate() {
            // Each where nothing is yet, clear of the one made before.
            let free = free + egui::vec2(0.0, 70.0 * step as f32);
            let before = count(&shot(&h));
            click(&mut h, free);
            h.frame(vec![Event::PointerMoved(free)]);
            press(&mut h, Modifiers::NONE, Key::Enter);
            h.frame(vec![Event::Text(typed.to_string())]);
            press(&mut h, Modifiers::NONE, Key::Enter);
            h.frame(vec![]);
            assert_eq!((count(&shot(&h)), &h.app.error), (before + 1, &None), "{typed}");
            // Put where the search was opened.
            let made = shot(&h).node_ids().max().unwrap();
            assert!(shot(&h).places.contains_key(&made), "{typed} is put there");
        }
    }

