    #[test]
    fn a_folded_groups_wire_is_dragged_along_a_composites_ports() {
        use crate::nodes::Item;
        let mut h = Harness::new();
        let layer = h.app.layer.unwrap();
        h.app.run("layer.new", json!({ "name": "Other" }));
        let group = iskra_model::GroupId(h.app.run_for("group.new", json!({ "nodes": [layer.0], "ports": true })).unwrap()["id"].as_u64().unwrap());
        h.app.run("group.set", json!({ "group": group.0, "folded": true }));
        run(&mut h, "panel.nodeView");
        h.frame(vec![]);
        h.frame(vec![]);
        let main = h.app.session.project().shots[0].composites[0].id;
        let inputs = |h: &Harness| h.app.session.project().shots[0].composite(main).unwrap().inputs.clone();
        let before = inputs(&h);
        let ends = |h: &Harness, from: Item| h.app.nodes.wire_ends.iter().find(|(a, b, ..)| *a == from && *b == Item::Composite(main)).map(|(.., end)| *end);
        let (folded, other) = (
            ends(&h, Item::Group(group)).expect("the folded group's wire"),
            h.app
                .nodes
                .wire_ends
                .iter()
                .find(|(a, b, ..)| *a != Item::Group(group) && *b == Item::Composite(main))
                .map(|(.., end)| *end)
                .expect("the other's wire"),
        );
        // Its end taken past the other's, the group is stacked on the other side of it.
        let past = other + egui::vec2(if folded.x < other.x { 12.0 } else { -12.0 }, 0.0);
        h.drag_between(folded, past);
        let after = inputs(&h);
        assert!(after != before && after.len() == before.len(), "{before:?} {after:?} {:?}", h.app.error);
        assert_eq!(h.app.session.history().undo_label(), Some("Connect Node"));
    }

    #[test]
    fn two_wires_out_of_one_folded_group_into_a_composite_are_dragged_each_alone() {
        use crate::nodes::Item;
        // Wired straight out of the group, not by ports, as a rig import leaves them: both
        // wires are drawn from the group's box.
        let mut h = Harness::new();
        let layers: Vec<LayerId> =
            ["A", "B"].iter().map(|name| LayerId(h.app.run_for("layer.new", json!({ "name": name })).unwrap()["id"].as_u64().unwrap())).collect();
        let group =
            iskra_model::GroupId(h.app.run_for("group.new", json!({ "nodes": [layers[0].0, layers[1].0], "ports": false })).unwrap()["id"].as_u64().unwrap());
        h.app.run("group.set", json!({ "group": group.0, "folded": true }));
        run(&mut h, "panel.nodeView");
        h.frame(vec![]);
        h.frame(vec![]);
        let main = h.app.session.project().shots[0].composites[0].id;
        let inputs = |h: &Harness| h.app.session.project().shots[0].composite(main).unwrap().inputs.clone();
        let before = inputs(&h);
        assert_eq!(before.len(), 3, "{before:?}");
        let mut ends: Vec<egui::Pos2> =
            h.app.nodes.wire_ends.iter().filter(|(from, to, ..)| *from == Item::Group(group) && *to == Item::Composite(main)).map(|(.., end)| *end).collect();
        assert_eq!(ends.len(), 2, "both drawn from the group's box");
        ends.sort_by(|a, b| a.x.total_cmp(&b.x));
        let all: Vec<egui::Pos2> = h.app.nodes.wire_ends.iter().filter(|(_, to, ..)| *to == Item::Composite(main)).map(|(.., end)| *end).collect();
        let right = all.iter().map(|end| end.x).fold(f32::MIN, f32::max);
        // The group's left wire taken past the rightmost: it alone goes to the end.
        h.drag_between(ends[0], egui::pos2(right + 12.0, ends[0].y));
        let after = inputs(&h);
        // The ports go left to right in the order of the inputs.
        let moved = before.iter().position(|input| layers.iter().any(|layer| *input == iskra_model::Source::Layer(*layer))).unwrap();
        let mut expected = before.clone();
        let input = expected.remove(moved);
        expected.push(input);
        assert_eq!(after, expected, "{:?}", h.app.error);
        assert_ne!(before, after);
    }

    #[test]
    fn nodes_are_pasted_where_the_node_view_was_clicked_in_the_group_there() {
        use crate::nodes::Item;
        let mut h = Harness::new();
        let first = h.app.layer.unwrap();
        let other = LayerId(h.app.run_for("layer.new", json!({ "name": "Other" })).unwrap()["id"].as_u64().unwrap());
        let rig = h.app.run_for("group.new", json!({ "nodes": [other.0], "name": "Rig" })).unwrap()["id"].as_u64().unwrap();
        let moves = json!([{ "node": first.0, "at": [-200.0, 0.0] }, { "node": other.0, "at": [100.0, 0.0] }]);
        h.app.run("node.place", json!({ "moves": moves }));
        run(&mut h, "panel.nodeView");
        h.frame(vec![]);
        h.frame(vec![]);
        // The first layer copied, then the background clicked inside the Rig's frame.
        h.app.picked = [first.0].into();
        h.app.copy(&h.ctx.clone(), "drawing.copy");
        assert!(h.app.copied_nodes && h.app.nodes.paste_at.is_none());
        let frame = h.app.nodes.frames[0].1;
        let inside = egui::pos2(frame.left() + 12.0, frame.bottom() - 12.0);
        click(&mut h, inside);
        assert_eq!(h.app.nodes.paste_at.map(|(_, _, group)| group), Some(Some(rig)));
        let main = h.app.session.project().shots[0].composites[0].id;
        let pasted_layer =
            |h: &Harness, before: &[LayerId]| h.app.session.project().shots[0].layers.iter().map(|layer| layer.id).find(|id| !before.contains(id)).unwrap();
        let before: Vec<LayerId> = h.app.session.project().shots[0].layers.iter().map(|layer| layer.id).collect();
        h.app.paste();
        h.frame(vec![]);
        let copy = pasted_layer(&h, &before);
        let shot = h.app.session.project().shots[0].clone();
        assert_eq!((shot.group_of(copy.0).map(|group| group.id.0), &h.app.error), (Some(rig), &None));
        assert!(!shot.composite(main).unwrap().inputs.contains(&iskra_model::Source::Layer(copy)), "wired to nothing");
        let placed = h.app.nodes.boxes.iter().find(|(item, _)| *item == Item::Layer(copy)).unwrap().1;
        assert!((placed.center() - inside).length() < 2.0, "{placed:?} at {inside:?}");
        // Pasted again with no click since, beside the first and in no group, as it is.
        assert!(h.app.nodes.paste_at.is_none());
        let before: Vec<LayerId> = h.app.session.project().shots[0].layers.iter().map(|layer| layer.id).collect();
        h.app.paste();
        let again = pasted_layer(&h, &before);
        assert_eq!(h.app.session.project().shots[0].group_of(again.0).map(|group| group.id.0), None);
    }

    #[test]
    fn what_is_under_an_open_groups_frame_is_out_of_reach_there() {
        use crate::nodes::Item;
        let mut h = Harness::new();
        let grouped = h.app.layer.unwrap();
        let other = LayerId(h.app.run_for("layer.new", json!({ "name": "Other" })).unwrap()["id"].as_u64().unwrap());
        h.app.run("group.new", json!({ "nodes": [grouped.0], "name": "Rig" }));
        // The other layer's box is half under the frame, beside the grouped one's.
        let moves = json!([{ "node": grouped.0, "at": [0.0, 0.0] }, { "node": other.0, "at": [80.0, 0.0] }]);
        h.app.run("node.place", json!({ "moves": moves }));
        run(&mut h, "panel.nodeView");
        h.frame(vec![]);
        h.frame(vec![]);
        let main = h.app.session.project().shots[0].composites[0].id;
        let at = |h: &Harness, item: Item| h.app.nodes.boxes.iter().find(|(other, _)| *other == item).map(|(_, rect)| *rect).unwrap();
        let ([(_, frame, _)], member, boxed) = (&h.app.nodes.frames[..], at(&h, Item::Layer(grouped)), at(&h, Item::Layer(other))) else {
            panic!("one frame: {:?}", h.app.nodes.frames)
        };
        let (frame, y) = (*frame, boxed.center().y);
        let (under, clear) = (egui::pos2((member.right() + frame.right()) / 2.0, y), egui::pos2((frame.right() + boxed.right()) / 2.0, y));
        assert!(boxed.contains(under) && !member.contains(under) && frame.contains(under) && boxed.contains(clear) && !frame.contains(clear));
        // Its wire leaves its box under the frame: an Alt-click on it there cuts nothing.
        let (.., start, _) = *h.app.nodes.wire_ends.iter().find(|(from, to, ..)| *from == Item::Layer(other) && *to == Item::Composite(main)).unwrap();
        let on_wire = start + egui::vec2(0.0, 12.0);
        assert!(frame.contains(on_wire) && !member.contains(on_wire));
        alt_click(&mut h, on_wire);
        let inputs = |h: &Harness| h.app.session.project().shots[0].composite(main).unwrap().inputs.clone();
        assert!(inputs(&h).contains(&iskra_model::Source::Layer(other)), "{:?}", h.app.error);
        // Its box is not taken where the frame is over it, and is where it is not. A drag near
        // the view's edge moves the view: where it is, is beside the grouped box.
        let beside = |h: &Harness| at(h, Item::Layer(other)).min - at(h, Item::Layer(grouped)).min;
        let before = beside(&h);
        h.drag_between(under, under + egui::vec2(0.0, 40.0));
        assert_eq!(beside(&h), before);
        let (frame, boxed) = (h.app.nodes.frames[0].1, at(&h, Item::Layer(other)));
        let clear = egui::pos2((frame.right() + boxed.right()) / 2.0, boxed.center().y);
        h.drag_between(clear, clear + egui::vec2(0.0, 40.0));
        assert_ne!(beside(&h), before);
    }

    #[test]
    fn egui_s_warning_of_an_id_clash_in_a_panel_is_kept_inside_it() {
        let ctx = egui::Context::default();
        ctx.options_mut(|options| options.warn_on_id_clash = true);
        let screen_rect = Some(Rect::from_min_size(Pos2::ZERO, egui::vec2(1000.0, 700.0)));
        let panel = Rect::from_min_size(egui::pos2(100.0, 100.0), egui::vec2(200.0, 150.0));
        let mut clips = Vec::new();
        let mut output = ctx.run_ui(RawInput { screen_rect, ..Default::default() }, |ui| {
            let mut inside = ui.new_child(egui::UiBuilder::new().max_rect(panel));
            let debug = egui::LayerId::debug();
            let before = ctx.graphics(|layers| layers.get(debug).map_or(0, |shapes| shapes.next_idx().0));
            debug_kept_inside(&mut inside, |ui| {
                let id = egui::Id::new("twice");
                ui.interact(Rect::from_min_size(egui::pos2(110.0, 110.0), egui::vec2(10.0, 10.0)), id, egui::Sense::click());
                ui.interact(Rect::from_min_size(egui::pos2(150.0, 110.0), egui::vec2(10.0, 10.0)), id, egui::Sense::click());
            });
            clips = ctx.graphics(|layers| {
                layers.get(debug).map(|shapes| shapes.all_entries().skip(before).map(|shape| shape.clip_rect).collect()).unwrap_or_default()
            });
        });
        output.textures_delta.clear();
        assert!(!clips.is_empty(), "egui warned of the clash");
        assert!(clips.iter().all(|clip| panel.contains_rect(*clip)), "{clips:?}");
    }

