    #[test]
    fn the_text_tool_goes_up_and_down_its_lines_and_picks_a_word_by_a_double_click() {
        let mut h = Harness::new();
        h.frame(vec![]);
        run(&mut h, "layer.newText");
        let layer = h.app.layer.unwrap();
        run(&mut h, "tool.text");
        let text = |h: &Harness| h.app.session.project().layer(layer).unwrap().drawing_at(0).unwrap().drawing.texts[0].text.clone();
        let middle = viewport_center(&h);
        click(&mut h, middle);
        h.frame(vec![Event::Text("ab".to_string())]);
        press(&mut h, Modifiers::NONE, Key::Enter);
        h.frame(vec![Event::Text("cd".to_string())]);
        h.frame(vec![]);
        // From the end of the second line, up is the end of the first.
        press(&mut h, Modifiers::NONE, Key::ArrowUp);
        h.frame(vec![Event::Text("X".to_string())]);
        h.frame(vec![]);
        assert_eq!(text(&h), "abX\ncd");
        press(&mut h, Modifiers::NONE, Key::ArrowDown);
        h.frame(vec![Event::Text("Y".to_string())]);
        h.frame(vec![]);
        assert_eq!(text(&h), "abX\ncdY");
        // A double-click on the first line picks its word, and what is typed replaces it.
        let first_line = middle + egui::vec2(3.0, 6.0);
        click(&mut h, first_line);
        click(&mut h, first_line);
        h.frame(vec![Event::Text("Z".to_string())]);
        h.frame(vec![]);
        assert_eq!(text(&h), "Z\ncdY");
    }

    #[test]
    fn the_text_panel_comes_with_the_tool_and_sets_the_box_typed_in_or_the_next() {
        let mut h = Harness::new();
        h.frame(vec![]);
        run(&mut h, "layer.newText");
        let layer = h.app.layer.unwrap();
        assert!(!h.app.prefs.layouts.of(h.app.page).shows(Panel::Text));
        run(&mut h, "tool.text");
        assert!(h.app.prefs.layouts.of(h.app.page).shows(Panel::Text), "the Text panel is shown with the tool");
        // Its list draws, previews and all, over a few frames.
        for _ in 0..5 {
            h.frame(vec![]);
        }
        assert!(!h.app.text_panel_previews().is_empty(), "previews of the fonts listed are made");
        let density = h.app.session.project().layer(layer).unwrap().density;
        let format = |h: &Harness| h.app.session.project().layer(layer).unwrap().drawing_at(0).unwrap().drawing.texts[0].clone();

        // Without a box typed in, it is the next box's format: its size in the shot's pixels.
        let changed = |fields: Value| text_panel::Changed { fields: fields.as_object().unwrap().clone(), new_step: true, ..Default::default() };
        h.app.apply_text_change(changed(json!({ "size": 30.0, "align": "centre", "font": "Inter", "style": "SemiBold" })), None, None);
        assert_eq!(h.app.viewport.text.format.size, 30.0);
        let middle = viewport_center(&h);
        click(&mut h, middle);
        let made = format(&h);
        assert_eq!((made.format.size, made.format.align, made.format.style.as_str()), (30.0 * density, iskra_model::TextAlign::Centre, "SemiBold"));
        h.frame(vec![Event::Text("Hey".to_string())]);
        h.frame(vec![]);

        // With a box typed in, it is the box's, as one step for a change dragged on.
        let editing = h.app.viewport.text.editing.expect("typing");
        let steps = h.app.session.history().entries().len();
        h.app.apply_text_change(changed(json!({ "size": 40.0 })), Some((editing, density)), None);
        h.app.apply_text_change(text_panel::Changed { new_step: false, ..changed(json!({ "size": 50.0 })) }, Some((editing, density)), None);
        assert_eq!(format(&h).format.size, 50.0 * density);
        assert_eq!(h.app.session.history().entries().len(), steps + 1, "a dragged size is one step");
        assert_eq!(h.app.session.history().undo_label(), Some("Format Text"));
        // Kerning at the cursor, before the letter after it.
        h.app.apply_text_change(text_panel::Changed { kerning: Some(80.0), ..Default::default() }, Some((editing, density)), Some(1));
        assert_eq!(format(&h).kerning.get(&1), Some(&80.0));
        assert_eq!(format(&h).text, "Hey");
    }

